// ── Online search (TorBox) ───────────────────────────────────────────────────
String _fmtBytes(int b) => b >= 1000000000
    ? '${(b / 1e9).toStringAsFixed(2)} GB'
    : b >= 1000000
        ? '${(b / 1e6).round()} MB'
        : '${(b / 1e3).round()} KB';

// Shared source-result rendering + actions (used by direct search AND browse sources).
/// Een fout die je moet kúnnen lezen, en overtypen.
///
/// Een toast van twee seconden is goed voor "opgeslagen ✓". Voor het antwoord van een server dat
/// vertelt wát er niet klopte is hij het slechtst denkbare: tegen dat je hem gelezen hebt is hij
/// weg, en dan blijft alleen "het lukte niet" over.
Future<void> _toonFout(BuildContext context, String kop, String tekst) => showDialog<void>(
      context: context,
      builder: (ctx) => AlertDialog(
        backgroundColor: _panel,
        title: Text(kop, style: kKopKlein),
        content: SizedBox(
          width: dialogWidth(ctx, 520),
          child: SingleChildScrollView(
            child: SelectableText(tekst, style: kTekstBij.copyWith(height: 1.4)),
          ),
        ),
        actions: [
          TextButton(onPressed: () => Navigator.pop(ctx), child: const Text('Sluiten')),
        ],
      ),
    );

void _srcToast(BuildContext context, String m) {
  ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(m), duration: const Duration(seconds: 2)));
}

/// A toast that offers a way out, for where the app REFUSES what was asked.
///
/// Every refusal here rests on a guess about what you already own, and that guess can be wrong —
/// two different takes can run equally long. A refusal you cannot overrule turns into a button that
/// silently does nothing, which is worse than the duplicate it was avoiding. Longer on screen than
/// a plain toast, because it asks something of the reader.
/// A message with a way to overrule it.
///
/// On a television this cannot be a toast. A SnackBarAction is technically focusable but the
/// highlight never travels there, and it is gone after eight seconds — so the button sits on
/// screen, plainly visible, and cannot be reached. That matters here more than it sounds: this is
/// the ONLY way to overrule the app when it wrongly decides a download is a duplicate you already
/// own. On a remote that whole branch of the app was dead.
void _srcToastAction(BuildContext context, String m, String label, VoidCallback onTap) {
  if (isTv) {
    showDialog<void>(
      context: context,
      builder: (ctx) => AlertDialog(
        backgroundColor: _panel,
        content: Text(m, style: const TextStyle(height: 1.4)),
        actions: [
          // The highlight starts on "leave it" — the action behind this dialog is a download the
          // app has already advised against.
          TextButton(
            autofocus: true,
            onPressed: () => Navigator.pop(ctx),
            child: const Text('Laat maar'),
          ),
          FilledButton(
            onPressed: () {
              Navigator.pop(ctx);
              onTap();
            },
            child: Text(label),
          ),
        ],
      ),
    );
    return;
  }
  ScaffoldMessenger.of(context).showSnackBar(SnackBar(
    content: Text(m),
    duration: const Duration(seconds: 8),
    action: SnackBarAction(label: label, onPressed: onTap),
  ));
}

// ── Radio / Smart Shuffle ────────────────────────────────────────────────────
// De normalisatie staat in recommend.dart als [recNorm]: hij beantwoordt overal dezelfde vraag — Radio,
// Ontdek en "Aanbevolen voor jou" — en drie kopieën van die regel zouden drie antwoorden geven.

/// Het radioplan: wat er zou moeten spelen, en wat je daarvan al hebt.
///
/// De looptijd gaat mee, en die stond er eerst niet in. Hij reist door tot in het gezag van de
/// download, en zonder hem denkt de bibliotheek op artiest + titel alleen al dat je een heropname
/// hebt — de Sting-val uit `organize.dart`.
List<Radioplek> _radioplan(List<RecTrack> recs, LibraryStore lib) {
  final index = <String, Track>{};
  for (final t in lib.tracks) {
    index.putIfAbsent('${recNorm(t.artist)}|${recNorm(t.title)}', () => t);
  }
  final bruikbaar = [
    for (final r in recs)
      if (r.title.trim().isNotEmpty && r.artist.trim().isNotEmpty) r
  ];
  // De ene weg waarlangs elke radio zijn nummers krijgt, dus de plek waar de versiekeuze hoort. Zie
  // `radiokeuze.dart`: van één liedje één uitvoering, en hoogstens twee bewerkingen per tien.
  final gekozen = kiesNummers(
      [for (final r in bruikbaar) (artiest: r.artist, titel: r.title)]);
  return [
    for (final i in gekozen)
      Radioplek(
        artiest: bruikbaar[i].artist,
        titel: bruikbaar[i].title,
        seconden: bruikbaar[i].seconds > 0 ? bruikbaar[i].seconds : null,
        eigen: index['${recNorm(bruikbaar[i].artist)}|${recNorm(bruikbaar[i].title)}'],
      ),
  ];
}

/// Een radio rond [artist].
///
/// De aanbevelingen komen nog steeds van Deezer; wat eronder veranderd is, is wat er met een nummer
/// gebeurt dat je niet hebt. Dat werd als torrent gezocht en gestreamd — een tijdelijke link die
/// nergens in je bibliotheek terechtkwam, en op een gekoppeld toestel zelfs dat niet. Nu wordt het via
/// Soulseek OPGEHAALD terwijl je luistert, en komt het pas in de rij als het bestand er werkelijk
/// staat. Zie `radio.dart`.
Future<void> startRadio(BuildContext context, String artist) async {
  final lib = context.read<LibraryStore>();
  final radio = context.read<RadioBesturing>();
  _srcToast(context, '📻 Radio starten voor $artist…');
  final rec = RecommendService();
  List<RecTrack> recs;
  try {
    recs = await rec.mixRadio(artist);
  } catch (_) {
    recs = const [];
  }
  if (!context.mounted) return;
  if (recs.isEmpty) {
    _srcToast(context, 'Geen radio gevonden voor $artist.');
    return;
  }
  final reden = await radio.start(_radioplan(recs, lib), naam: artist);
  if (!context.mounted || reden == null) return;
  // Weigeren en zeggen waarom, in plaats van stilletjes alleen eigen muziek spelen. Dat laatste is
  // precies wat de oude radio op een telefoon deed, en het is niet te onderscheiden van een radio die
  // gewoon niet veel nieuws vindt.
  _srcToast(context, reden);
}

bool _genericArtist(String s) {
  final x = s.trim().toLowerCase();
  return x.isEmpty || x == 'various' || x == 'various artists' || x == 'va' || x == 'onbekende artiest';
}

// ── Tracks (flat, all library songs) ─────────────────────────────────────────
class TracksView extends StatelessWidget {
  /// Library search + quality filter from the shell (null = show everything).
  final bool Function(Track)? match;
  final String query;
  const TracksView({super.key, this.match, this.query = ''});

  @override
  Widget build(BuildContext context) {
    final lib = context.watch<LibraryStore>();
    // `read`, niet `watch` — en dat scheelt hier meer dan waar ook in de app.
    //
    // PlayerStore meldt zich vier keer per seconde zolang er iets speelt (player.dart:606-621 remt
    // de mpv-positiestroom daarop af). Met een `watch` liep dus vier keer per seconde de HELE
    // `build` hieronder opnieuw: de bibliotheek werd opnieuw gefilterd — bij 1037 nummers duizend
    // aanroepen van [match] — en de lijst eronder werd ongeldig verklaard, terwijl er alleen een
    // spoelbalk bewoog.
    //
    // Wat dit scherm van de speler nodig heeft is tweeledig, en de twee helften horen niet bij
    // elkaar: de KNOPPEN roepen hem aan (daar is `read` genoeg, die luistert niet), en één RIJ wil
    // weten of zij het is die speelt. Dat laatste staat hieronder per rij in een `select`, precies
    // zoals `TrackRow` het al doet — met dezelfde uitleg erboven.
    final player = context.read<PlayerStore>();
    final all = lib.tracks;
    final tracks = match == null ? all : all.where(match!).toList();
    if (lib.scanning && all.isEmpty) {
      // Regels in de vorm van nummerregels, op dezelfde marges, zodat er niets verspringt zodra de
      // echte lijst er staat.
      return const SkeletLijst();
    }
    if (all.isEmpty) {
      return LeegVlak(
        teken: Icons.music_note_rounded,
        kop: 'Nog geen nummers',
        uitleg: 'Zodra er muziek in je bibliotheek staat, staat hier elk nummer los. '
            'Of zoek er zelf een op.',
        knop: 'Online zoeken',
        opKnop: () => gaNaarSectie?.call(2),
      );
    }
    if (tracks.isEmpty) {
      return LeegVlak(
        teken: Icons.filter_alt_off_rounded,
        kop: query.isEmpty ? 'Niets binnen dit filter' : 'Niets gevonden',
        uitleg: query.isEmpty
            ? 'Geen enkel nummer voldoet aan wat je hierboven hebt aangevinkt.'
            : 'Geen enkel nummer heet “$query”. Probeer een deel van de titel of de artiest.',
      );
    }
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Builder(builder: (context) {
          final narrow = isCompact(context);
          final title = Row(mainAxisSize: MainAxisSize.min, children: [
            const Text('Tracks', style: TextStyle(fontSize: 22, fontWeight: FontWeight.w700)),
            const SizedBox(width: 10),
            Text('${tracks.length}', style: const TextStyle(color: _muted, fontSize: 14)),
          ]);
          final buttons = [
            FilledButton.icon(
              style: FilledButton.styleFrom(
                  backgroundColor: _accent,
                  padding: const EdgeInsets.symmetric(horizontal: 18, vertical: 12)),
              onPressed: () => player.shuffleAll(tracks),
              icon: const Icon(Icons.shuffle_rounded, size: 18),
              label: const Text('Shuffle alles'),
            ),
            const SizedBox(width: 8),
            FilledButton.icon(
              style: FilledButton.styleFrom(
                  backgroundColor: _panel2,
                  foregroundColor: Colors.white,
                  padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 12)),
              onPressed: () => player.playQueue(tracks, 0),
              icon: const Icon(Icons.play_arrow_rounded, size: 18),
              label: const Text('Speel alles'),
            ),
          ];
          return Padding(
            padding: EdgeInsets.fromLTRB(narrow ? 18 : 28, 22, narrow ? 18 : 24, 10),
            // Title, count and two buttons. Three pixels too wide on a phone, and the count
            // vanished under the first button — so on a phone the buttons drop to their own line.
            // The Row stays everywhere else, Spacer and all, because that is where it fits.
            child: narrow
                ? Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [title, const SizedBox(height: 10), Row(children: buttons)],
                  )
                : Row(children: [title, const Spacer(), ...buttons]),
          );
        }),
        Expanded(
          child: BinnenkomstGroep(
          child: ListView.builder(
            // Zie het albumraster: waar je was blijft staan bij een wissel naar een ander scherm.
            key: const PageStorageKey('nummerlijst'),
            padding: const EdgeInsets.only(bottom: 12),
            itemCount: tracks.length,
            // Fixed height → smooth scrolling at 10k+ tracks. Taller on a television because the
            // text in the row is scaled 1.35x there and 56 would cut the second line off.
            //
            // En hoger op een telefoon, om dezelfde reden als daar: de titel mag er over twee
            // regels, want op 411 punten paste de helft van de titels niet op één. 56 draagt één
            // titelregel plus de artiest; de tweede regel kost er 20 bij.
            itemExtent: isTv || isCompact(context) ? 76 : 56,
            itemBuilder: (_, i) {
              final t = tracks[i];
              // EEN `Builder`, en dat is geen omhaal.
              //
              // De context van `itemBuilder` is de sliver zelf, en die van `build` is de HELE
              // pagina — dus hing het menu hier aan het midden van het scherm terwijl je op de derde
              // rij klikte. `findRenderObject` daalt af tot de eerste tekenende afstammeling, dus de
              // context van een `Builder` levert de RIJ. Zelfde truc als bij de drie puntjes op het
              // nu-speelt-scherm.
              return Binnenkomst(
                index: i,
                child: Builder(
                builder: (rij) {
                // Hier hoort de vraag "speel ik?" en nergens hoger. De context van `itemBuilder` is
                // de sliver zelf — daar luisteren zou de hele lijst laten hertekenen — en die van
                // `build` is de hele pagina. Deze `Builder` is de rij, en dus de enige plek waar een
                // afhankelijkheid op de speler precies één rij kost.
                //
                // `radioMode` moet mee: in de radio staat er geen enkele rij opgelicht, en zonder
                // die voorwaarde zou de rij van het nummer dat toevallig ook in de radio speelt
                // alsnog oplichten.
                // Allebei in één `select`: een record heeft structurele gelijkheid, dus deze rij
                // tekent alleen opnieuw als er werkelijk iets aan HAAR veranderd is. `playing` moet
                // mee omdat het luidsprekertje op pauze in een pijltje verandert.
                final (isCurrent, speeltHier) = rij.select<PlayerStore, (bool, bool)>((p) {
                  final ik = !p.radioMode && p.current?.path == t.path;
                  return (ik, ik && p.playing);
                });
                return InkWell(
                onTap: () => player.playQueue(tracks, i),
                onLongPress:
                    _menuOpHouden ? () => _toonItemMenu(rij, _nummerMenu(rij, t)) : null,
                onSecondaryTapDown: (d) =>
                    _toonItemMenu(rij, _nummerMenu(rij, t), bij: d.globalPosition),
                child: Container(
                  padding: const EdgeInsets.symmetric(horizontal: 24),
                  color: isCurrent ? _panel : Colors.transparent,
                  child: Row(
                    children: [
                      SizedBox(width: 22, child: Text('${i + 1}', style: const TextStyle(color: _muted, fontSize: 11))),
                      cover(lib.coverForTrack(t), size: 40, radius: 6),
                      const SizedBox(width: 12),
                      Expanded(
                        child: Column(
                          mainAxisAlignment: MainAxisAlignment.center,
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Text(t.title,
                                // TWEE hier en niet drie, anders dan in de andere nummerlijsten:
                                // deze lijst heeft een vaste rijhoogte (zie `itemExtent` hieronder)
                                // en die twee getallen horen bij elkaar. Een derde regel zonder een
                                // hogere rij loopt er gewoon uit.
                                maxLines: isCompact(context) ? 2 : 1,
                                overflow: TextOverflow.ellipsis,
                                style: TextStyle(
                                    fontSize: 14,
                                    fontWeight: FontWeight.w600,
                                    color: isCurrent ? _accent : _text)),
                            // Through displayArtist: the track's own tag may spell the artist
                            // differently from the name shown everywhere else. Split so a guest
                            // is their own name here, not part of one long unclickable string.
                            _artistLine(splitFeatured(lib.displayArtist(t.artist), t.title),
                                const TextStyle(fontSize: 12, color: _muted)),
                          ],
                        ),
                      ),
                      _echtheidMerk(t),
                      _qualityBadge(_trackQuality(t)),
                      const SizedBox(width: 4),
                      // De looptijd valt weg op een telefoon.
                      //
                      // Gezien op het toestel: "Chande…", "Elastic …", "Rolling in …" — de titels
                      // waren tot een woord teruggesnoeid terwijl er rechts een kwaliteitsmerkje van
                      // 110 punten stond, een looptijd, en twee knoppen. De looptijd is het minst
                      // dringende van die vier: hij staat op het speelscherm, op de albumpagina en
                      // in de wachtrij. Op een breder scherm blijft hij gewoon staan.
                      if (!isCompact(context)) ...[
                        Text(_fmt(t.duration),
                            style: const TextStyle(color: _muted, fontSize: 12)),
                        const SizedBox(width: 6),
                      ],
                      // Verwijderen wáár je zoekt. De prullenbak stond alleen op de albumpagina, en
                      // een los nummer terugvinden via zijn album is precies de omweg die dit scherm
                      // moet wegnemen — je filtert hier op "uit mp3" of op een naam en wil er dan
                      // meteen iets mee kunnen.
                      //
                      // Geen hover-voorwaarde zoals daar: dit is ook het scherm dat op een tablet en
                      // op de televisie draait, en daar bestaat zweven niet. Wel dezelfde bevestiging
                      // met dezelfde twee keuzes — uit de bibliotheek halen en van schijf wissen
                      // horen nooit hetzelfde te betekenen.
                      // Niet op een tv: daar is de app een speler, en een verwijderknop op elke
                      // regel is precies wat je met een afstandsbediening niet wilt tegenkomen.
                      if (!isTv)
                      SizedBox(
                        width: 34,
                        child: TvLabelled(
                                 label: 'Nummer verwijderen',
                                 child: IconButton(
                          icon: const Icon(Icons.delete_outline_rounded, size: 17),
                          color: _muted,
                          tooltip: 'Nummer verwijderen',
                          padding: EdgeInsets.zero,
                          // 48 en niet 32. Android houdt 48 aan als ondergrens voor iets dat met
                          // een vinger geraakt moet worden, en dit is een VERWIJDERKNOP die twee
                          // punten naast de afspeel-aanduiding staat in een rij van 56 hoog. Een
                          // misser hier start niet alleen het verkeerde nummer.
                          constraints: const BoxConstraints(minWidth: 48, minHeight: 48),
                          onPressed: () => _confirmDelete(context, '“${t.title}”', [t.path]),
                        ),
                               ),
                      ),
                      const SizedBox(width: 2),
                      Icon(speeltHier ? Icons.volume_up_rounded : Icons.play_arrow_rounded,
                          color: isCurrent ? _accent : _muted, size: 19),
                    ],
                  ),
                ),
              );
              },
              ),
              );
            },
          ),
          ),
        ),
      ],
    );
  }
}

// ── Ontdek (discovery feed) ──────────────────────────────────────────────────
// ── Start / welcome screen (TIDAL-style rows) ────────────────────────────────
class HomeStartView extends StatefulWidget {
  const HomeStartView({super.key});
  @override
  State<HomeStartView> createState() => _HomeStartViewState();
}

/// Wat het startscherm al opgehaald had, over een schermwissel heen.
///
/// **Zonder dit begon dit scherm elke keer opnieuw.** Wissel naar Albums en terug, en de widget
/// wordt van de grond af opgebouwd: spinner, nieuw netwerkverkeer, en een andere volgorde dan je
/// net zag. Op een telefoon is dat de hele tijd, want elke sectie zit achter de hamburgerla.
///
/// Bewust alleen de opgehaalde lijsten en niet de hele widgetboom. Dat laatste (een IndexedStack)
/// houdt verborgen schermen in de boom, en dan blijven ze meeluisteren en hertekenen — precies wat
/// er net uitgehaald is.
class _StartCache {
  static List<CatalogAlbumHit> charts = [];
  static List<CatalogAlbumHit> releases = [];
  static List<RecTrack> forYou = [];
  static bool geladen = false;
}

class _HomeStartViewState extends State<HomeStartView> {
  final _catalog = CatalogService();
  final _rec = RecommendService();
  List<CatalogAlbumHit> _charts = _StartCache.charts;
  List<CatalogAlbumHit> _releases = _StartCache.releases;
  List<RecTrack> _forYou = _StartCache.forYou;
  bool _chartsLoading = !_StartCache.geladen;
  bool _seedsRequested = false; // the library's artists have been used to load the personal rows
  bool _seedsLoading = false;

  /// Komen de persoonlijke rijen nog?
  ///
  /// Ze wachten op de bibliotheek: zolang die nog scant zijn er geen artiesten om mee te zoeken.
  /// Maar "nog niet aangevraagd" is iets anders dan "er komt niets" — en die twee waren hier
  /// hetzelfde, waardoor de secties pas verschenen op het moment dat ze gingen laden en alles
  /// eronder omlaag duwden.
  bool get _komtNog => _seedsLoading || (!_seedsRequested && _forYou.isEmpty);

  @override
  void initState() {
    super.initState();
    // Charts need no library — load them right away. Maar niet opnieuw als ze er al zijn: zie
    // [_StartCache]. Anders haalt elke terugkeer naar Start dezelfde lijst nog een keer op, met een
    // spinner en een andere volgorde dan je net zag.
    if (!_StartCache.geladen) {
      WidgetsBinding.instance.addPostFrameCallback((_) => _loadCharts());
    }
  }

  Future<void> _loadCharts() async {
    try {
      final c = await _catalog.chartAlbums();
      _StartCache.charts = c;
      if (mounted) setState(() => _charts = c);
    } catch (_) {}
    _StartCache.geladen = true;
    if (mounted) setState(() => _chartsLoading = false);
  }

  /// The personal rows depend on the scanned library. On a cold start the scan is still running
  /// when this view first builds, so we load these ONCE the library actually has artists (driven
  /// from build via context.watch) — not eagerly with an empty seed list.
  Future<void> _loadSeeds(List<String> seeds) async {
    if (mounted) setState(() => _seedsLoading = true);
    final relF = _catalog.latestFromArtists(seeds);
    final fyF = _rec.discover(seeds.take(6).toList());
    List<CatalogAlbumHit> rel = [];
    List<RecTrack> fy = [];
    try {
      rel = await relF;
    } catch (_) {}
    try {
      fy = await fyF;
    } catch (_) {}
    if (!mounted) return;
    // Wat je al hebt gaat eruit. Zonder dit stond deze rij vol met je eigen platen: hij komt via
    // verwante artiesten binnen, en de verwanten van jouw bibliotheek zijn geregeld je bibliotheek.
    // Dezelfde functie als Ontdek gebruikt, zodat de twee schermen niet elk hun eigen antwoord op
    // "heb ik dit al?" krijgen.
    final bezit = bezitSleutels(context.read<LibraryStore>().tracks);
    _StartCache.releases = rel;
    _StartCache.forYou = nogNietInBezit(fy, bezit);
    setState(() {
      _releases = _StartCache.releases;
      _forYou = _StartCache.forYou;
      _seedsLoading = false;
    });
  }

  String _greeting() {
    final h = DateTime.now().hour;
    if (h < 6) return 'Goedenacht';
    if (h < 12) return 'Goedemorgen';
    if (h < 18) return 'Goedemiddag';
    return 'Goedenavond';
  }

  Future<void> _playRec(RecTrack t) async {
    final online = context.read<OnlineService>();
    final player = context.read<PlayerStore>();
    _srcToast(context, 'Bron voorbereiden voor ${t.title}…');
    try {
      final url = await online.resolveRadio(t.artist, t.title, instantOnly: false);
      if (!mounted) return;
      if (url == null) {
        _srcToast(context, 'Geen bron gevonden — zoek het op via Online zoeken.');
        return;
      }
      player.playUrl(url, title: t.title, artist: t.artist);
    } catch (_) {
      if (mounted) _srcToast(context, 'Kan niet afspelen.');
    }
  }

  @override
  Widget build(BuildContext context) {
    final lib = context.watch<LibraryStore>();
    final artists = lib.artists.where((a) => !_genericArtist(a)).toList();
    // Fire the personal rows the first time the library actually has artists.
    // Alleen als ze er nog niet zijn — een terugkeer naar Start hoeft ze niet opnieuw te halen.
    if (!_seedsRequested && artists.isNotEmpty && _StartCache.releases.isEmpty && _StartCache.forYou.isEmpty) {
      _seedsRequested = true;
      final seeds = [...artists]..shuffle();
      WidgetsBinding.instance.addPostFrameCallback((_) => _loadSeeds(seeds));
    }
    final recent = [...lib.albums.where((a) => a.addedMs > 0)]..sort((a, b) => b.addedMs.compareTo(a.addedMs));
    final anyLoading = _chartsLoading || _seedsLoading || (!_seedsRequested && lib.scanning);
    // De balk heet NIEUWE RELEASE, dus staat er alleen iets van dit jaar in. Hij toonde albums uit 2011
    // en 2016 omdat er nergens op jaar gefilterd werd: het nieuwste dat er van een artiest te vinden is,
    // is iets anders dan nieuw.
    //
    // Eerst je eigen artiesten, dan de wereldwijde lijst — maar allebei door hetzelfde jaarfilter, want
    // een hitlijst vol evergreens hoort hier net zomin. Blijft er dan niets over, dan verdwijnt de balk;
    // dat is beter dan hem vullen met iets wat niet is wat het belooft.
    final ditJaar = DateTime.now().year;
    final eigen = uitJaar(_releases, ditJaar);
    final hero = eigen.isNotEmpty ? eigen : uitJaar(_charts, ditJaar);

    return BinnenkomstGroep(
      child: ListView(
      padding: const EdgeInsets.only(bottom: 32),
      children: [
        // 28 werd 24: alles op dit scherm staat vanaf hier op dezelfde goot als de rijen hoezen
        // eronder. Zie `ui/maten.dart`.
        Padding(
          padding: const EdgeInsets.fromLTRB(kGoot, kRuimte24, kGoot, kRuimte2),
          child: Text('${_greeting()} 👋', style: const TextStyle(fontSize: 26, fontWeight: FontWeight.w800)),
        ),
        const Padding(
          padding: EdgeInsets.fromLTRB(kGoot, 0, kGoot, kRuimte6),
          child: Text('Ontdek nieuwe muziek en pak op waar je gebleven was',
              style: TextStyle(color: _muted, fontSize: 13.5)),
        ),
        // Boven de hitlijsten, want dit is het snelste wat je hier kunt doen: één zin en er speelt
        // muziek. Alles eronder vraagt eerst dat je ergens doorheen bladert.
        const Padding(
          padding: EdgeInsets.fromLTRB(kGoot, kRuimte12, kGoot, kRuimte4),
          child: _RadioUitEenZinKaart(),
        ),
        if (hero.isNotEmpty)
          Padding(
            padding: const EdgeInsets.fromLTRB(kGoot, kRuimte12, kGoot, kRuimte4),
            child: HeroCarousel(hits: hero.take(7).toList()),
          ),
        if (recent.isNotEmpty) _section('Recent toegevoegd', _localRow(recent.take(15).toList())),
        // [_komtNog] en niet alleen _seedsLoading: die laatste gaat pas omhoog zodra de bibliotheek
        // artiesten heeft, en tot dat moment stond deze sectie er HELEMAAL NIET. Ze verscheen dus
        // midden in het lezen en duwde alles eronder omlaag — de rij is 204 punten plus zijn kop.
        // Nu staat het skelet er meteen, en het vult zich in plaats van in te schuiven.
        if (_forYou.isNotEmpty || _komtNog)
          _section('Aanbevolen voor jou',
              _forYou.isEmpty ? _loadingRow() : _recRow(_forYou.take(15).toList())),
        if (_charts.isNotEmpty || _chartsLoading)
          _section('Top van dit moment',
              _charts.isEmpty ? _loadingRow() : _catalogRow(_charts.take(20).toList())),
        if (_releases.isNotEmpty || _komtNog)
          _section('Nieuw van jouw artiesten',
              _releases.isEmpty ? _loadingRow() : _catalogRow(_releases.take(20).toList())),
        if (!anyLoading && _charts.isEmpty && _releases.isEmpty && _forYou.isEmpty && recent.isEmpty)
          LeegVlak(
            teken: Icons.library_music_rounded,
            kop: 'Nog geen muziek hier',
            uitleg: 'Zodra je pc gescand heeft, staan je platen hier. '
                'Of zoek er zelf een op.',
            knop: 'Online zoeken',
            opKnop: () => gaNaarSectie?.call(2),
            // Dit staat in een `ListView`, dus onbegrensd hoog. Zie [LeegVlak.gecentreerd].
            gecentreerd: false,
          ),
      ],
      ),
    );
  }

  Widget _section(String title, Widget row) => Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          // Stond op `fromLTRB(28, 22, 28, 12)` terwijl de rij eronder op 24 staat: vier punten
          // scheefstand tussen een kop en zijn eigen inhoud, over de hele hoogte van dit scherm.
          SectieKop(title),
          // Hoger dan de tegel zelf: een liggende `ListView` geeft zijn kinderen een STRAKKE hoogte
          // en knipt ze af, dus zonder lucht wordt de groei bij aanwijzen er boven en onder af
          // gesneden.
          //
          // Stond met de hand op 204 (236 op tv), met een commentaar erbij dat dat "maar net"
          // genoeg was. Nu berekend — inclusief de tekstschaal van het toestel, want juist die
          // maakt op een televisie het verschil. Zie `ui/tegel.dart`.
          SizedBox(height: hoogteVanTegelrij(context), child: row),
        ],
      );

  /// Een rij skelettegels in plaats van een wieltje in het midden.
  ///
  /// Het wieltje zei alleen dát er iets kwam, en het nam een andere hoogte in dan de rij die erna
  /// verscheen — dus schoof bij elke binnenkomende sectie alles eronder omlaag. Vier rijen die elk
  /// op hun eigen moment landen, en het startscherm stond te springen terwijl je las.
  Widget _loadingRow() => const SkeletRij();

  Widget _localRow(List<Album> albums) => ListView.separated(
        scrollDirection: Axis.horizontal,
        padding: const EdgeInsets.symmetric(horizontal: kGoot),
        itemCount: albums.length,
        separatorBuilder: (_, __) => const SizedBox(width: kRuimte12),
        itemBuilder: (_, i) => Binnenkomst(
          index: i,
          child: _card(
              cover(albums[i].cover, size: kTegelHoes), albums[i].title, albums[i].artist,
              () => openPagina(context, (_) => AlbumDetailPage(album: albums[i])),
              artist: albums[i].artist),
        ),
      );

  /// De artiestnaam onder een tegel, aanklikbaar.
  ///
  /// [openArtist] neemt een NAAM en zoekt de artiest zelf op, dus dit werkt net zo goed voor een naam
  /// die van Deezer komt als voor een naam uit je eigen bibliotheek — er is nergens een id voor nodig.
  /// Dat is precies waarom "overal klikbaar" haalbaar was: het enige dat ontbrak, was een plek om de
  /// widget neer te zetten.
  static Widget _naamLink(String naam) => ArtistNames(
        names: [naam],
        style: const TextStyle(color: _muted, fontSize: 12),
      );

  Widget _catalogRow(List<CatalogAlbumHit> hits) => ListView.separated(
        scrollDirection: Axis.horizontal,
        padding: const EdgeInsets.symmetric(horizontal: kGoot),
        itemCount: hits.length,
        separatorBuilder: (_, __) => const SizedBox(width: kRuimte12),
        // Deze builder voedt TWEE rijen — "Top van dit moment" en "Nieuw van jouw artiesten" — dus
        // deze ene regel maakt ze allebei klikbaar.
        itemBuilder: (_, i) => Binnenkomst(
          index: i,
          child: _card(
              _netCover(hits[i].album.cover, size: kTegelHoes), hits[i].album.title, hits[i].artist,
              () => openPagina(context, (_) => AlbumBrowsePage(hits[i].artist, hits[i].album)),
              artist: hits[i].artist),
        ),
      );

  Widget _recRow(List<RecTrack> ts) => ListView.separated(
        scrollDirection: Axis.horizontal,
        padding: const EdgeInsets.symmetric(horizontal: kGoot),
        itemCount: ts.length,
        separatorBuilder: (_, __) => const SizedBox(width: kRuimte12),
        // To the album, the same as every other row here. A tile that started playing instead was
        // the odd one out, and it gave you no way to see what the record was.
        //
        // Long-press still plays it: the quickest way to hear a recommendation should not disappear
        // because the tap now goes somewhere better.
        itemBuilder: (_, i) => Binnenkomst(
          index: i,
          child: _HoverCard(
          art: _netCover(ts[i].cover, size: kTegelHoes),
          title: ts[i].title,
          subtitle: ts[i].artist,
          // Juist hier: een aanbeveling gaat over een artiest die je NIET kent, en dan wil je als
          // eerste weten wie dat is. `RecTrack` draagt alleen een naam, en dat is genoeg.
          subtitleWidget: ts[i].artist.trim().isEmpty ? null : _naamLink(ts[i].artist),
          onTap: () => _openRec(ts[i]),
          onLongPress: () => _playRec(ts[i]),
        ),
        ),
      );

  /// Where a recommended track lives. Deezer names the album it came from; when it does not, the
  /// track itself is still worth hearing, so that falls back to playing it.
  void _openRec(RecTrack t) {
    if (!t.hasAlbum) {
      unawaited(_playRec(t));
      return;
    }
    // A positive id is a Deezer one — see CatalogAlbum.ref — and this hit came from Deezer. The
    // tracklist and the year are fetched by the page itself, so nothing is invented here.
    final album = CatalogAlbum(t.albumId, t.album, t.cover, null, 0, 'album');
    openPagina(context, (_) => AlbumBrowsePage(t.artist, album));
  }

  /// [subtitle] blijft de kale tekst voor het geval de widget niets kan; [artist] maakt hem klikbaar.
  Widget _card(Widget art, String title, String subtitle, VoidCallback onTap, {String? artist}) =>
      _HoverCard(
        art: art,
        title: title,
        subtitle: subtitle,
        subtitleWidget: artist == null || artist.trim().isEmpty ? null : _naamLink(artist),
        onTap: onTap,
      );
}

/// Een tegel in een van de rijen op Start.
///
/// Sinds `ui/tegel.dart` bestaat is dit alleen nog de naam waaronder de vier rijen hier hem
/// aanroepen. De vorm — de hoes met een schaduw eronder, de groei bij aanwijzen, de twee
/// tekstregels — staat daar, en is dezelfde als die van het raster op Albums.
class _HoverCard extends StatelessWidget {
  final Widget art;
  final String title, subtitle;

  /// De ondertitel als WIDGET, voor waar de artiestnaam aanklikbaar moet zijn.
  final Widget? subtitleWidget;
  final VoidCallback onTap;

  /// Het tweede dat deze tegel kan waar hij dat kan — een aanbeveling meteen afspelen in plaats van
  /// de plaat openen waar hij op staat. Overal elders leeg, en dan verandert er niets.
  final VoidCallback? onLongPress;

  const _HoverCard(
      {required this.art,
      required this.title,
      required this.subtitle,
      required this.onTap,
      this.subtitleWidget,
      this.onLongPress});

  @override
  Widget build(BuildContext context) => AlbumTegel(
        // De hoezen hier zijn al op maat gebouwd door de rij die ze aanlevert, dus de maat die de
        // tegel doorgeeft blijft ongebruikt.
        hoes: (_) => art,
        breedte: kTegelHoes,
        titel: title,
        ondertitel: subtitle,
        // De widget wint als hij er is. Op een afstandsbediening mag de naam GEEN eigen focusstop
        // worden: dan krijgt elke tegel in een rij er een tweede bij en pijl je twee keer zo lang.
        // Klikken blijft werken — `_maybeFocusable` haalt hem uit het pad van de highlight, niet uit
        // de app. Dezelfde afweging als bij een tracklijstrij.
        ondertitelWidget:
            subtitleWidget == null ? null : _maybeFocusable(subtitleWidget!),
        onTap: onTap,
        onLongPress: onLongPress,
      );
}

class OntdekView extends StatefulWidget {
  const OntdekView({super.key});
  @override
  State<OntdekView> createState() => _OntdekViewState();
}

class _OntdekViewState extends State<OntdekView> {
  final _rec = RecommendService();
  List<RecTrack> _tracks = [];
  bool _busy = false;
  String? _status;
  int? _expanded;
  int? _playing; // row whose source is being resolved (shows a spinner)

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addPostFrameCallback((_) => _load());
  }

  Future<void> _load() async {
    final lib = context.read<LibraryStore>();
    final seeds = lib.artists.where((a) => !_genericArtist(a)).toList()..shuffle();
    if (seeds.isEmpty) {
      setState(() => _status = 'Nog geen bibliotheek om op te ontdekken.');
      return;
    }
    setState(() {
      _busy = true;
      _tracks = [];
      _status = null;
      _expanded = null;
    });
    final owned = bezitSleutels(lib.tracks);
    List<RecTrack> recs;
    // "The lookup failed" and "your library already has everything it suggested" are different
    // answers, and they were both reported as the second one. Told that nothing new was found, the
    // obvious conclusion is that there is nothing left to discover — not that the request never
    // arrived. Refreshing then looks pointless when it is exactly the thing that would help.
    var failed = false;
    try {
      recs = await _rec.discover(seeds.take(4).toList());
    } catch (_) {
      recs = const [];
      failed = true;
    }
    final fresh = nogNietInBezit(recs, owned);
    if (mounted) {
      setState(() {
        _tracks = fresh;
        _busy = false;
        _status = fresh.isNotEmpty
            ? null
            : failed
                ? 'De suggesties konden niet worden opgehaald. Zit je online? Probeer het nog eens.'
                : 'Niets nieuws gevonden — ververs eens.';
      });
    }
  }

  Future<void> _play(int i, RecTrack t) async {
    final online = context.read<OnlineService>();
    final player = context.read<PlayerStore>();
    setState(() => _playing = i);
    _srcToast(context, 'Bron voorbereiden voor ${t.title}…');
    try {
      final url = await online.resolveRadio(t.artist, t.title, instantOnly: false);
      if (!mounted) return;
      if (url == null) {
        _srcToast(context, 'Geen bron gevonden — open de bronnen (⬇) om te downloaden.');
        return;
      }
      player.playUrl(url, title: t.title, artist: t.artist);
    } catch (e) {
      if (mounted) _srcToast(context, 'Kan niet afspelen: $e');
    } finally {
      if (mounted) setState(() => _playing = null);
    }
  }

  @override
  Widget build(BuildContext context) {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Padding(
          padding: const EdgeInsets.fromLTRB(24, 22, 24, 8),
          child: Row(
            children: [
              const Text('Ontdek', style: TextStyle(fontSize: 22, fontWeight: FontWeight.w700)),
              const SizedBox(width: 12),
              const Expanded(
                  child: Text('Nieuwe muziek op basis van je bibliotheek',
                      style: TextStyle(color: _muted, fontSize: 13))),
              TvLabelled(
                label: 'Ververs',
                child: IconButton(
                  onPressed: _busy ? null : _load,
                  icon: const Icon(Icons.refresh_rounded),
                  color: _muted,
                  tooltip: 'Ververs'),
              ),
            ],
          ),
        ),
        if (_status != null)
          Padding(padding: const EdgeInsets.all(24), child: Text(_status!, style: const TextStyle(color: _muted))),
        if (_busy)
          const Expanded(child: Center(child: CircularProgressIndicator(color: _accent)))
        else
          Expanded(
            child: ListView.builder(
              padding: const EdgeInsets.only(bottom: 24),
              itemCount: _tracks.length,
              itemBuilder: (_, i) => _row(i, _tracks[i]),
            ),
          ),
      ],
    );
  }

  Widget _row(int i, RecTrack t) {
    final open = _expanded == i;
    return Column(
      children: [
        Container(
          margin: const EdgeInsets.symmetric(horizontal: 20, vertical: 1),
          padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 8),
          decoration: BoxDecoration(color: open ? _panel : Colors.transparent, borderRadius: BorderRadius.circular(8)),
          child: Row(
            children: [
              _netCover(t.cover, size: 44, radius: 6),
              const SizedBox(width: 12),
              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(t.title, maxLines: 1, overflow: TextOverflow.ellipsis, style: const TextStyle(fontWeight: FontWeight.w600)),
                    _artistLine(splitFeatured(t.artist, t.title),
                        const TextStyle(color: _muted, fontSize: 12)),
                  ],
                ),
              ),
              _playing == i
                  ? const SizedBox(
                      width: 48,
                      height: 48,
                      child: Center(child: SizedBox(width: 20, height: 20, child: CircularProgressIndicator(strokeWidth: 2, color: _accent))))
                  : TvLabelled(label: 'Afspelen', child: IconButton(icon: const Icon(Icons.play_arrow_rounded), color: _accent, tooltip: 'Afspelen', onPressed: () => _play(i, t))),
              TvLabelled(label: 'Radio', child: IconButton(icon: const Icon(Icons.radio_rounded, size: 20), color: _muted, tooltip: 'Radio hieruit', onPressed: () => startRadio(context, t.artist))),
              // Niet op een tv: daar is dit scherm er om een aanbeveling te laten klínken, en het
              // ophalen doe je op een pc of telefoon. Afspelen en Radio hiernaast blijven staan.
              if (!isTv)
                TvLabelled(
                  label: 'Bronnen / download',
                  child: IconButton(
                    icon: Icon(open ? Icons.expand_less_rounded : Icons.download_rounded, size: 20),
                    color: _muted,
                    tooltip: 'Bronnen / download',
                    onPressed: () => setState(() => _expanded = open ? null : i)),
                ),
            ],
          ),
        ),
        if (open) Padding(padding: const EdgeInsets.only(bottom: 8), child: SourcesView(query: t.query)),
      ],
    );
  }
}

Future<void> _playTorrent(BuildContext context, SearchResult r) async {
  _srcToast(context, 'Bron voorbereiden…');
  try {
    final url = await context.read<OnlineService>().resolveStreamUrl(r);
    if (context.mounted) context.read<PlayerStore>().playUrl(url, title: r.name, artist: r.source);
  } catch (e) {
    if (context.mounted) _srcToast(context, 'Kan niet afspelen: $e');
  }
}

void _downloadTorrent(BuildContext context, SearchResult r) {
  context.read<DownloadManager>().enqueue(r);
  _srcToast(context, r.cached
      ? 'Downloaden gestart — zie de downloadlijst.'
      : 'Voorbereiden bij TorBox (kan even duren bij weinig seeders) — zie de downloadlijst.');
}

void _pickTorrentTracks(BuildContext context, SearchResult r) {
  showDialog(context: context, builder: (_) => _TrackPickerDialog(r));
}

/// Every peer in [all] offering the same track as [f] (including f itself), best-first.
/// The rule itself lives in organize.dart, where it can be tested without a live peer.
List<SoulseekFile> _slskCandidates(List<SoulseekFile> all, SoulseekFile f) {
  final out =
      all.where((o) => o.isAudio && sameRecording(f.filename, f.durationSec, o.filename, o.durationSec)).toList();
  return out.isEmpty ? [f] : out;
}

/// Ask what "delete" should mean, then do it. [what] names the thing ("het album “Bad”"), and
/// [paths] are the files it covers. Deliberately two distinct choices — removing something from
/// the library must never silently wipe the files off disk.
Future<void> _confirmDelete(BuildContext context, String what, List<String> paths) async {
  final n = paths.length;
  final choice = await showDialog<String>(
    context: context,
    builder: (ctx) => AlertDialog(
      backgroundColor: _panel,
      title: Text('$what verwijderen?', style: const TextStyle(fontSize: 17, fontWeight: FontWeight.w700)),
      content: Text(
        'Dit gaat over $n bestand${n == 1 ? "" : "en"}.\n\n'
        '• Alleen uit bibliotheek: het blijft op je pc staan, maar verdwijnt uit de app.\n'
        '• Ook van pc: de bestanden worden definitief verwijderd.',
        style: const TextStyle(color: _muted, fontSize: 13, height: 1.45),
      ),
      actions: [
        // Where the highlight starts, said out loud rather than left to whatever Flutter picks.
        //
        // "Ook van pc" deletes files from the disk and cannot be undone, and it is the last action
        // — which is exactly where a convention of "focus the primary button" would put it. On a
        // remote, one stray press of OK on a dialog you had not read yet would be gone music. So
        // the highlight starts on Cancel, and reaching the red button takes two deliberate presses.
        TextButton(
          autofocus: isTv,
          onPressed: () => Navigator.pop(ctx),
          child: const Text('Annuleren'),
        ),
        TextButton(
          onPressed: () => Navigator.pop(ctx, 'library'),
          child: const Text('Alleen uit bibliotheek'),
        ),
        FilledButton(
          style: FilledButton.styleFrom(backgroundColor: Colors.red.shade700),
          onPressed: () => Navigator.pop(ctx, 'disk'),
          child: const Text('Ook van pc'),
        ),
      ],
    ),
  );
  if (choice == null || !context.mounted) return;

  final lib = context.read<LibraryStore>();
  final fromDisk = choice == 'disk';
  final deleted = await lib.removeTracks(paths, fromDisk: fromDisk);
  if (!context.mounted) return;
  _srcToast(
      context,
      fromDisk
          ? '$what verwijderd — $deleted bestand${deleted == 1 ? "" : "en"} van je pc gewist.'
          : '$what uit je bibliotheek gehaald (bestanden staan er nog).');
}

String _slskKey(SoulseekFile f) => '${f.username}|${f.filename}';

/// Een regel uit de Soulseek-lijst downloaden — precies díé, en geen andere.
///
/// Klikken op een regel betekende tot nu toe "haal dit nummer": de klik werd verbreed tot elke kopie
/// die erop leek, en daarna won de best gerangschikte. Bij Joe Dassin was dat een ánder nummer, en
/// omdat de dubbelcontrole daarna elke tweede poging weigerde met "loopt al" viel er niets meer te
/// kiezen. De regel ís het bestand — dat was altijd al het mentale model, alleen niet de code.
///
/// Terugvallen mag nog steeds, maar alleen op peers die exact hetzelfde bestand aanbieden
/// ([zelfdeBestand]). De automatische kant blijft ongemoeid: de pijl op een nummerregel van de
/// albumpagina zoekt nog gewoon de beste kopie.
Future<void> _downloadSoulseek(BuildContext context, SoulseekFile f, List<SoulseekFile> all,
    {TrackTags? authority}) async {
  try {
    final zelfde = [
      f,
      for (final o in all)
        if (o.isAudio &&
            (o.username != f.username || o.filename != f.filename) &&
            zelfdeBestand(f.filename, f.size, f.durationSec, o.filename, o.size, o.durationSec))
          o,
    ];
    // false means it was refused — this track is already downloading. Say so; a "started" message
    // for something that never started is worse than no message.
    final started = await context
        .read<DownloadManager>()
        .enqueueSoulseekBest(zelfde, key: _slskKey(f), authority: authority, exact: f);
    if (context.mounted) {
      _srcToast(
          context,
          started
              ? '“${f.displayName}” van ${f.username} — precies dit bestand…'
              : '“${f.displayName}” loopt al — zie Mijn downloads.');
    }
  } catch (e) {
    if (context.mounted) _srcToast(context, 'Download mislukt: $e');
  }
}

/// A download button that turns into a live progress ring while THIS key's job runs — so the
/// user sees progress right on the tile/track row, without opening the download list. Shows a
/// check when done and a retry (with the failure reason as tooltip) when it failed.
/// Everything the app is downloading, in one place — the equivalent of the native Soulseek
/// transfer list. Split into what's still running and what's finished, because a track that is
/// merely WAITING for an uploader's slot is not a failure and shouldn't look like one.
/// "Plak een Tidal-link" — de hele koppeling met tiddl, in één venster.
///
/// **Waarom een venster en geen zoekscherm.** tiddl kán niet zoeken; hij neemt alleen een link of
/// een id. Een zoekscherm zou betekenen dat deze app de Tidal-API zélf gaat spreken, en dat is
/// precies het stuk dat stukgaat zodra Tidal iets verandert. Je zoekt dus in de Tidal-app, kopieert
/// de link, en plakt hem hier.
///
/// **Waarom hier en niet bij de andere twee bronnen.** Soulseek en TorBox hebben een wachtrij, een
/// voortgang en een eigen scherm. Dit is één opdracht die een bestand in je muziekmap zet, waarna de
/// bestaande scan het oppakt. Er is niets te beheren, dus er komt geen beheer bij.
class _TidalOphalen extends StatefulWidget {
  /// Het doel als het al vaststaat ('album/103805723'), omdat je hier vanaf een zoekresultaat komt.
  /// Null betekent: het venster waar je zelf een link plakt.
  final String? doel;

  /// Hoe die plaat heet — alleen om te tonen wát er straks binnenkomt.
  final String? titel;

  const _TidalOphalen({this.doel, this.titel});

  @override
  State<_TidalOphalen> createState() => _TidalOphalenState();
}

class _TidalOphalenState extends State<_TidalOphalen> {
  final _link = TextEditingController();
  String _kwaliteit = tidalKwaliteiten.first;
  bool _bezig = false;
  String? _fout;

  @override
  void dispose() {
    _link.dispose();
    super.dispose();
  }

  Future<void> _ophalen() async {
    // Eerst hier weigeren wat niet klopt. Een zin op het scherm is beter dan een stapeltrace uit
    // een proces dat je startte om een fout te ontdekken die je al kon zien.
    final doel = widget.doel ?? tidalDoel(_link.text);
    if (doel == null) {
      setState(() => _fout = 'Dat is geen Tidal-link. Plak het adres van een plaat of een nummer, '
          'bijvoorbeeld https://tidal.com/browse/album/103805723');
      return;
    }
    final map = context.read<AppSettings>().musicRoot;
    setState(() {
      _bezig = true;
      _fout = null;
    });
    final uitslag = await haalVanTidal(doel: doel, map: map, kwaliteit: _kwaliteit);
    if (!mounted) return;
    if (uitslag.fout != null) {
      setState(() {
        _bezig = false;
        _fout = uitslag.fout;
      });
      return;
    }
    Navigator.of(context).pop(uitslag.kwaliteit ?? '');
  }

  @override
  Widget build(BuildContext context) => Dialog(
        backgroundColor: _panel,
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
        child: SizedBox(
          width: dialogWidth(context, 520),
          child: Padding(
            padding: const EdgeInsets.all(20),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                const Text('Ophalen van Tidal', style: kKop),
                const SizedBox(height: kRuimte6),
                Text(
                  widget.doel == null
                      ? 'Zoek de plaat in Tidal, kopieer de link en plak hem hier. '
                          'Hij komt in je muziekmap te staan en wordt daarna vanzelf gevonden.'
                      : '“${widget.titel ?? widget.doel}” wordt met jouw Tidal-abonnement '
                          'opgehaald en komt in je muziekmap te staan.',
                  style: kTekstBij,
                ),
                const SizedBox(height: kRuimte16),
                // Komt het doel van een zoekresultaat, dan valt er niets meer te plakken.
                if (widget.doel == null) ...[
                  TextField(
                    controller: _link,
                    autofocus: true,
                    enabled: !_bezig,
                    onSubmitted: (_) => _bezig ? null : _ophalen(),
                    decoration: InputDecoration(
                      hintText: 'https://tidal.com/browse/album/…',
                      filled: true,
                      fillColor: _panel2,
                      border: OutlineInputBorder(
                          borderRadius: BorderRadius.circular(kHoek8), borderSide: BorderSide.none),
                    ),
                  ),
                  const SizedBox(height: kRuimte12),
                ],
                Row(
                  children: [
                    const Text('Kwaliteit', style: kTekstKlein),
                    const SizedBox(width: kRuimte8),
                    Container(
                      decoration: BoxDecoration(
                          color: _panel2, borderRadius: BorderRadius.circular(kHoek8)),
                      padding: const EdgeInsets.symmetric(horizontal: 10),
                      child: DropdownButtonHideUnderline(
                        child: DropdownButton<String>(
                          value: _kwaliteit,
                          dropdownColor: _panel2,
                          items: [
                            for (final k in tidalKwaliteiten)
                              DropdownMenuItem(value: k, child: Text(k)),
                          ],
                          onChanged:
                              _bezig ? null : (v) => setState(() => _kwaliteit = v ?? 'max'),
                        ),
                      ),
                    ),
                    const SizedBox(width: kRuimte8),
                    // Waarom dit erbij staat: `low` en `normal` zijn m4a van 96 en 320 kbps, en dus
                    // slechter dan wat deze bibliotheek al heeft. Wie ze kiest hoort te weten dat
                    // hij zichzelf een slechtere kopie bezorgt.
                    const Expanded(
                      child: Text('max = 24 bit tot 192 kHz · low en normal zijn m4a',
                          style: kTekstKlein),
                    ),
                  ],
                ),
                // Zonder ffmpeg kan tiddl de hi-res-stroom niet in elkaar zetten en levert hij
                // 16 bit / 44,1 kHz af terwijl je om max vroeg — met één waarschuwingsregel tussen
                // zijn voortgangsbalken door, die niemand ziet. Een mindere plaat die er goed
                // uitziet is de vervelendste soort, dus staat het hier vóórdat je op Ophalen klikt.
                if (!Ffmpeg().available) ...[
                  const SizedBox(height: kRuimte12),
                  const Text(
                    'ffmpeg staat niet op deze pc. Zonder ffmpeg komt er 16 bit / 44,1 kHz binnen, '
                    'ook op "max". Installeer hem met "winget install ffmpeg" en herstart de app.',
                    style: TextStyle(color: Color(0xFFE0B341), fontSize: 12, height: 1.35),
                  ),
                ],
                if (_fout != null) ...[
                  const SizedBox(height: kRuimte12),
                  // In het venster en niet als toast: een fout van tiddl is meerdere regels, en die
                  // wil je kunnen lezen én overtypen.
                  SelectableText(_fout!,
                      style: kTekstBij.copyWith(color: Colors.orangeAccent, height: 1.4)),
                ],
                const SizedBox(height: kRuimte16),
                Row(
                  mainAxisAlignment: MainAxisAlignment.end,
                  children: [
                    if (_bezig) ...[
                      const SizedBox(
                          width: 16,
                          height: 16,
                          child: CircularProgressIndicator(strokeWidth: 2, color: _accent)),
                      const SizedBox(width: kRuimte8),
                      // Een plaat van 24 bit is honderden megabytes; zonder deze regel lijkt het
                      // venster na een halve minuut vast te staan.
                      const Expanded(
                          child: Text('Bezig met ophalen — dit kan even duren.',
                              style: kTekstKlein)),
                    ],
                    TextButton(
                      onPressed: _bezig ? null : () => Navigator.of(context).pop(),
                      child: const Text('Annuleren'),
                    ),
                    const SizedBox(width: kRuimte8),
                    FilledButton(
                      style: FilledButton.styleFrom(backgroundColor: _accent),
                      onPressed: _bezig ? null : _ophalen,
                      child: const Text('Ophalen'),
                    ),
                  ],
                ),
              ],
            ),
          ),
        ),
      );
}

class DownloadsView extends StatelessWidget {
  const DownloadsView({super.key});

  static String statusLabel(DownloadJob j) => switch (j.status) {
        'done' => 'Klaar',
        // A download the user stopped themselves didn't fail — saying "Mislukt" makes it look
        // like something went wrong with it.
        'failed' => j.cancelled ? 'Gestopt' : 'Mislukt',
        // Niemand leverde, maar het is niet voorbij: dit nummer staat op de wenslijst en wordt
        // vanzelf opnieuw geprobeerd. "Mislukt" zou hier zeggen dat jij weer aan zet bent, en dat
        // is precies de verwarring die dit oplost.
        'later' => 'Later opnieuw',
        'waiting' => j.queuePlace > 0 ? 'Wacht op peer · plaats ${j.queuePlace}' : 'Wacht op peer',
        'queued' => 'In wachtrij',
        // Already on disk and playable; a better copy is still being chased.
        'upgrading' => 'Speelbaar · upgrade',
        'preparing' => j.progress > 0 ? 'Voorbereiden ${(j.progress * 100).round()}%' : 'Voorbereiden',
        _ => 'Bezig ${(j.progress * 100).round()}%',
      };

  static Color statusColor(DownloadJob j) => switch (j.status) {
        'done' => _accent2,
        // Rood is voor iets wat misging. Een download die jij zelf hebt afgezet ging niet mis, en
        // een rode balk met een uitroepteken erboven leest als een probleem dat je moet oplossen.
        'failed' => j.cancelled ? _muted : Colors.redAccent,
        // Amber, niet rood: er is niets kapot en er hoeft niets opgelost te worden.
        'later' => const Color(0xFFE0B341),
        'waiting' => const Color(0xFFE0B341),
        'upgrading' => _accent2, // green: you can play it, this is a bonus not a problem
        _ => _accent,
      };

  static IconData statusIcon(DownloadJob j) => switch (j.status) {
        'done' => Icons.check_circle_rounded,
        'failed' => j.cancelled ? Icons.do_not_disturb_on_outlined : Icons.error_rounded,
        'later' => Icons.update_rounded,
        'waiting' => Icons.hourglass_top_rounded,
        'queued' => Icons.schedule_rounded,
        'upgrading' => Icons.upgrade_rounded,
        _ => Icons.downloading_rounded,
      };

  @override
  Widget build(BuildContext context) {
    return Consumer<DownloadManager>(
      builder: (_, dm, __) {
        final active = dm.jobs.where((j) => j.busy).toList();
        // Drie groepen, niet twee. "Later opnieuw" stond onder AFGEROND, en dat is het niet: er
        // komt nog een poging. Daar hoorde het niet en daar werd het ook door "Wis afgeronde"
        // meegenomen — zie [DownloadManager.clearFinished].
        final later = dm.jobs.where((j) => j.status == 'later').toList();
        final finished = dm.jobs.where((j) => !j.busy && j.status != 'later').toList();
        return ListView(
          padding: const EdgeInsets.fromLTRB(28, 22, 28, 30),
          children: [
            // What is kept on THIS device, above what is being fetched onto the PC. Two different
            // things that both live under "downloads": one is music arriving into your library,
            // the other is a copy of your library travelling with you.
            const _OfflineSection(),
            // Title, a running count and a clear button. Side by side that is wider than a phone —
            // the count ran under the button and "Wis afgeronde" hung off the right edge. Wrapped,
            // so it stays one line where there is room and folds where there is not.
            Wrap(
              crossAxisAlignment: WrapCrossAlignment.center,
              spacing: 14,
              runSpacing: 4,
              children: [
                const Text('Mijn downloads',
                    style: TextStyle(fontSize: 25, fontWeight: FontWeight.w800, letterSpacing: -.4)),
                if (active.isNotEmpty)
                  // Counted from the jobs themselves: a download waiting in an uploader's queue has
                  // handed its parallel slot back, so the scheduler's counters would read 0 here.
                  Text('${active.where((j) => j.status == 'downloading' || j.status == 'preparing').length} bezig'
                      ' · ${active.where((j) => j.status == 'waiting' || j.status == 'queued').length} wachtend',
                      style: const TextStyle(color: _muted, fontSize: 12.5)),
                if (finished.isNotEmpty)
                  TextButton.icon(
                    onPressed: dm.clearFinished,
                    icon: const Icon(Icons.clear_all_rounded, size: 16),
                    label: const Text('Wis afgeronde'),
                    style: TextButton.styleFrom(foregroundColor: _muted),
                  ),
                // De derde bron. Alleen op de machine die de muziek bezit: tiddl is een programma
                // op die pc, en een telefoon heeft geen muziekmap om iets in te zetten. Hij staat
                // hier en niet tussen de bronnen op Zoeken, omdat er niets te zoeken valt — je
                // plakt een link.
                if (_isDesktop && !context.read<LibraryStore>().isRemote)
                  TextButton.icon(
                    onPressed: () async {
                      // Een string terug betekent gelukt; de inhoud is de kwaliteit die tiddl
                      // meldde. Null is geannuleerd.
                      final kwaliteit = await showDialog<String>(
                          context: context, builder: (_) => const _TidalOphalen());
                      if (kwaliteit == null || !context.mounted) return;
                      _srcToast(context, opgehaaldMelding(kwaliteit));
                      unawaited(context.read<LibraryStore>().scan());
                    },
                    icon: const Icon(Icons.link_rounded, size: 16),
                    label: const Text('Ophalen van Tidal…'),
                    style: TextButton.styleFrom(foregroundColor: _muted),
                  ),
              ],
            ),
            // Downloads die door het afsluiten zijn afgebroken. Ze starten niet meer vanzelf bij het
            // opstarten — dat is juist wat de valse wachtwoordfout veroorzaakte — dus hier staat wat
            // er klaarligt en waarom het wacht.
            if (dm.wachtendeHervattingen > 0)
              Padding(
                padding: const EdgeInsets.only(top: 10),
                child: Row(
                  children: [
                    const Icon(Icons.history_rounded, size: 16, color: _muted),
                    const SizedBox(width: 8),
                    Expanded(
                      child: Text(
                        '${dm.wachtendeHervattingen} onderbroken download'
                        '${dm.wachtendeHervattingen == 1 ? "" : "s"} — gaan vanzelf verder zodra je '
                        'Soulseek gebruikt',
                        style: const TextStyle(color: _muted, fontSize: 12.5),
                      ),
                    ),
                    TextButton(
                      onPressed: () => unawaited(dm.hervatWachtende()),
                      child: const Text('nu hervatten'),
                    ),
                  ],
                ),
              ),
            const SizedBox(height: 18),
            if (dm.jobs.isEmpty)
              LeegVlak(
                teken: Icons.download_rounded,
                kop: 'Nog geen downloads',
                uitleg: 'Start er een vanuit een album, of zoek er zelf een op.',
                knop: 'Online zoeken',
                opKnop: () => gaNaarSectie?.call(2),
                // Staat in een lijst, dus onbegrensd hoog. Zie [LeegVlak.gecentreerd].
                gecentreerd: false,
              ),
            if (active.isNotEmpty) ...[
              const _DlHeader('BEZIG'),
              ...active.map((j) => DlRow(job: j)),
              const SizedBox(height: 22),
            ],
            if (later.isNotEmpty) ...[
              const _DlHeader('LATER OPNIEUW'),
              ...later.map((j) => DlRow(job: j)),
              const SizedBox(height: 22),
            ],
            if (finished.isNotEmpty) ...[
              const _DlHeader('AFGEROND'),
              ...finished.map((j) => DlRow(job: j)),
            ],
          ],
        );
      },
    );
  }
}

class _DlHeader extends StatelessWidget {
  final String text;
  const _DlHeader(this.text);
  @override
  Widget build(BuildContext context) => Padding(
        padding: const EdgeInsets.only(bottom: 8),
        child: Text(text,
            style: const TextStyle(color: _muted, fontSize: 11, fontWeight: FontWeight.w700, letterSpacing: .8)),
      );
}

/// Eén regel in de downloadlijst: pictogram, naam, voortgang, stand.
///
/// Niet privé, omdat er een toets op staat die hem op telefoonbreedte pompt — zie
/// `test/download_regel_test.dart`. Een `_`-klasse is per bestand afgeschermd en dan kan geen enkele
/// toets erbij; die afscherming was hier het verschil tussen "gemeten" en "het lijkt te kloppen".
class DlRow extends StatelessWidget {
  final DownloadJob job;
  const DlRow({super.key, required this.job});

  @override
  Widget build(BuildContext context) {
    final color = DownloadsView.statusColor(job);
    final indeterminate = job.status == 'queued' || job.status == 'waiting';
    // Playable already: show the bar full, whatever is still running for it is a bonus.
    final filled = job.status == 'done' || job.status == 'upgrading';

    final naam = Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      mainAxisSize: MainAxisSize.min,
      children: [
        Text(job.name,
            maxLines: 1, overflow: TextOverflow.ellipsis, style: const TextStyle(fontSize: 13.5)),
        if (job.detail != null && job.detail!.isNotEmpty) ...[
          const SizedBox(height: 2),
          Text(job.detail!,
              // Bij een MISLUKKING mag deze regel niet afgekapt worden. Hij is dan het enige dat
              // zegt waarom, en juist die zinnen zijn lang: "TorBox nam deze bron niet aan — …",
              // een infohash, een pad. Op 26-08-2026 stond er "InfoHash 5bdcf1b4…" en was de reden
              // precies achter dat afkapstreepje verdwenen. Bij een lopende download blijft het één
              // regel: daar staat "12 seeders · 30 verbindingen" en dat past.
              maxLines: job.status == 'failed' ? 4 : 1,
              overflow: TextOverflow.ellipsis,
              style: TextStyle(fontSize: 11, color: job.status == 'failed' ? Colors.red.shade300 : _muted)),
        ],
      ],
    );

    final balk = LinearProgressIndicator(
      value: filled ? 1 : (indeterminate || job.progress <= 0 ? null : job.progress),
      backgroundColor: kLijn,
      color: color,
    );

    // Stop what you no longer want — a slot freed here is a slot another download gets.
    //
    // Ook op een rij die op de wenslijst staat. Die vraagt niets meer van je, maar de app zoekt op
    // de achtergrond door, en daar was geen enkele knop voor: "Wis afgeronde" haalde de rij weg en
    // liet de wens staan. Nu haalt dit kruisje allebei weg — zie [DownloadManager.stopWens].
    final opDeLijst = job.status == 'later';
    final kanStoppen = opDeLijst || (job.busy && job.canCancel);
    final stopLabel = opDeLijst ? 'Niet meer proberen' : 'Download stoppen';
    final stoppen = kanStoppen
        ? Consumer<DownloadManager>(
            builder: (_, dm, __) => TvLabelled(
              label: stopLabel,
              child: IconButton(
                icon: const Icon(Icons.close_rounded, size: 16),
                color: _muted,
                tooltip: stopLabel,
                padding: EdgeInsets.zero,
                constraints: const BoxConstraints(),
                onPressed: () =>
                    opDeLijst ? unawaited(dm.stopWens(job)) : dm.cancelJob(job),
              ),
            ),
          )
        : null;

    final stand = Text(DownloadsView.statusLabel(job),
        textAlign: TextAlign.right,
        maxLines: 1,
        overflow: TextOverflow.ellipsis,
        style: TextStyle(fontSize: 11.5, color: color, fontWeight: FontWeight.w600));

    return Container(
      margin: const EdgeInsets.only(bottom: 8),
      padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 12),
      decoration: BoxDecoration(
        color: _panel,
        borderRadius: BorderRadius.circular(12),
        border: Border.all(color: _line),
      ),
      // Op een telefoon gaat de balk ONDER de titel staan, niet ernaast.
      //
      // Naast elkaar past het daar niet, en dat viel niet op als "te krap" maar als een LEGE regel:
      // een groene balk en verder niets. Gemeten op de S26 (1440 px bij dichtheid 600 = 384 dp
      // breed): de lijst neemt 2×28 dp, de kaart 2×14 dp, en wat daarna vaststaat is
      // 19+13+16+190+14+34+74 = 360 dp — meer dan de 300 dp die overblijft. De titel kreeg dus
      // NUL breedte en "Klaar" werd het scherm afgeduwd. Een `Expanded` die op nul uitkomt geeft
      // geen overloopstreep en geen fout; hij toont gewoon niets.
      //
      // Eerder is hier het statuslabel gehalveerd (150 → 74) voor precies deze klacht. Dat hielp
      // niet, want de 190 dp brede balk was de echte vreter. Vandaar: op een smal scherm eerst de
      // regel die je wilt lezen — pictogram, titel, stand — en de balk op een eigen regel eronder.
      child: isCompact(context)
          ? Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              mainAxisSize: MainAxisSize.min,
              children: [
                Row(
                  children: [
                    Icon(DownloadsView.statusIcon(job), size: 19, color: color),
                    const SizedBox(width: 13),
                    Expanded(child: naam),
                    const SizedBox(width: 10),
                    // Vast noch flexibel: hij mag zo breed worden als hij nodig heeft, tot een
                    // grens. Zou dit een `Flexible` zijn, dan deelde hij de ruimte half om half met
                    // de titel — ook voor het woord "Klaar".
                    ConstrainedBox(constraints: const BoxConstraints(maxWidth: 132), child: stand),
                  ],
                ),
                const SizedBox(height: 10),
                Row(
                  children: [
                    Expanded(child: balk),
                    if (stoppen != null) ...[const SizedBox(width: 12), stoppen],
                  ],
                ),
              ],
            )
          : Row(
              children: [
                Icon(DownloadsView.statusIcon(job), size: 19, color: color),
                const SizedBox(width: 13),
                Expanded(child: naam),
                const SizedBox(width: 16),
                SizedBox(width: 190, child: balk),
                const SizedBox(width: 14),
                SizedBox(width: 34, child: stoppen),
                SizedBox(width: 150, child: stand),
              ],
            ),
    );
  }
}

Widget _downloadControl(BuildContext context,
    {required String jobKey, required VoidCallback onDownload, String tooltip = 'Downloaden via Soulseek'}) {
  return Consumer<DownloadManager>(
    builder: (_, dm, __) {
      final job = dm.jobByKey(jobKey);
      final status = job?.status;
      if (status == 'queued') {
        // Waiting for a download slot — show a queue clock, NOT a spinner (a spinning ring here
        // looked like a stuck download when several tracks were started at once).
        return const Padding(
          padding: EdgeInsets.all(9),
          child: Tooltip(
            message: 'In wachtrij…',
            child: Icon(Icons.schedule_rounded, color: _muted, size: 19),
          ),
        );
      }
      if (status == 'waiting') {
        // The uploader has us in its queue and will start when a slot frees — exactly what the
        // native client shows as "Queued". Not a failure, so no red: an hourglass plus the place.
        final place = job!.queuePlace;
        return Tooltip(
          message: job.detail ?? 'Wachten op peer…',
          child: SizedBox(
            width: 40,
            height: 40,
            child: Stack(alignment: Alignment.center, children: [
              const Icon(Icons.hourglass_top_rounded, color: Color(0xFFE0B341), size: 19),
              if (place > 0)
                Positioned(
                  bottom: 2,
                  child: Text('$place',
                      style: const TextStyle(fontSize: 8.5, color: _muted, fontWeight: FontWeight.w700)),
                ),
            ]),
          ),
        );
      }
      if (status == 'downloading' || status == 'preparing') {
        final pct = (job!.progress * 100).round();
        return Tooltip(
          message: job.detail ?? 'Bezig…',
          child: SizedBox(
            width: 40,
            height: 40,
            child: Stack(alignment: Alignment.center, children: [
              SizedBox(
                width: 22,
                height: 22,
                child: CircularProgressIndicator(
                    strokeWidth: 2.4,
                    value: job.progress > 0 ? job.progress : null,
                    color: _accent,
                    backgroundColor: kLijn),
              ),
              Text('$pct', style: const TextStyle(fontSize: 8.5, color: _muted, fontWeight: FontWeight.w700)),
            ]),
          ),
        );
      }
      if (status == 'upgrading') {
        // Downloaded and playable — the arrow says a better copy is still being fetched.
        return Tooltip(
          message: job?.detail ?? 'Speelbaar · betere kwaliteit onderweg',
          child: const Padding(
            padding: EdgeInsets.all(9),
            child: Icon(Icons.upgrade_rounded, color: _accent2, size: 20),
          ),
        );
      }
      if (status == 'done') {
        return const Padding(padding: EdgeInsets.all(9), child: Icon(Icons.check_circle_rounded, color: _accent2, size: 20));
      }
      // Niemand leverde, maar het staat op de wenslijst: de app klopt er vanzelf weer aan. Deze knop
      // is dan "nu meteen", niet "anders gebeurt er niets" — vandaar amber en niet rood.
      if (status == 'later') {
        final waarom = job?.detail == null
            ? 'Nog niet binnen — de app probeert het vanzelf opnieuw'
            : '${job!.detail} · nu meteen proberen';
        return TvLabelled(
          label: waarom,
          child: IconButton(
              icon: const Icon(Icons.update_rounded),
              color: const Color(0xFFE0B341),
              tooltip: waarom,
              onPressed: onDownload),
        );
      }
      if (status == 'failed') {
        return TvLabelled(
                 label: job?.detail != null ? 'Mislukt: ${job!.detail} — opnieuw' : 'Mislukt — opnieuw proberen',
                 child: IconButton(
            icon: const Icon(Icons.refresh_rounded),
            color: Colors.redAccent,
            tooltip: job?.detail != null ? 'Mislukt: ${job!.detail} — opnieuw' : 'Mislukt — opnieuw proberen',
            onPressed: onDownload),
               );
      }
      return TvLabelled(
               label: tooltip,
               child: IconButton(icon: const Icon(Icons.download_rounded), color: _accent, tooltip: tooltip, onPressed: onDownload),
             );
    },
  );
}

Future<void> _downloadSoulseekAlbum(
    BuildContext context, List<SoulseekFile> folder, List<SoulseekFile> all,
    {ReleaseAuthority? authority}) async {
  // Each folder track → its cross-peer candidates, so a busy peer for one track falls back
  // to another peer offering the same song instead of failing the whole album.
  final tracks = [for (final f in folder) _slskCandidates(all, f)];
  // Which official track each file actually is, decided by name and running time rather than by
  // the number the uploader happened to type in front of it.
  final authorities = [
    for (final f in folder) authority?.match(f.displayName, f.durationSec ?? 0)
  ];
  final n = await context
      .read<DownloadManager>()
      .enqueueSoulseekAlbum(tracks, authorities: authorities);
  if (context.mounted) {
    _srcToast(context, '$n nummer(s) via Soulseek — volg de voortgang in de downloadlijst.');
  }
}

/// De pauzemelding, en waarom dit een eigen widget is.
///
/// Saber: "altijd als ik de app open heb ik dit voor, ik wordt het echt wel beu". Terecht, en de
/// oorzaak stond hier: de melding werd getekend met `context.read<SoulseekService>()`. `read` LUISTERT
/// NIET. Deze regel kon zichzelf dus nooit opruimen — hij bleef staan tot er toevallig om een andere
/// reden hertekend werd, ook als de wachttijd allang verstreken was. En de knop "nu opnieuw proberen"
/// leek niets te doen, want er veranderde niets op het scherm.
///
/// Gemeten op 04-08-2026 om 19:25: het scherm zei "te vaak ingelogd", even later "wachtwoord klopt
/// niet, nog 10 min", terwijl `soulseek_login.log` geen enkele loginregel had en
/// `soulseek_guard.json` `blockedUntil: null`, `logins: []`, `pause: "none"` bevatte. Een herstart
/// maakte het weg. Precies wat een vastgevroren momentopname doet.
///
/// `watch` in plaats van `read` helpt hier NIET, en dat is het venijn: `SoulseekService` wordt geleverd
/// met een gewone `Provider.value` (main.dart) en is geen `ChangeNotifier`. Er is dus geen enkel
/// mechanisme waarmee een wijziging het scherm kan bereiken — luisteren kan niet naar iets wat nooit
/// iets zegt. Daarom klokt deze widget zichzelf: elke twee seconden opnieuw kijken zolang hij in beeld
/// is. Dat is goedkoop (hij bestaat alleen op de zoekpagina) en het is de enige vorm die óók klopt
/// wanneer de wachttijd vanzelf verloopt — dat is namelijk geen gebeurtenis maar een vergelijking met
/// de klok.
class _SlskPauzeStrook extends StatefulWidget {
  const _SlskPauzeStrook();

  @override
  State<_SlskPauzeStrook> createState() => _SlskPauzeStrookState();
}

class _SlskPauzeStrookState extends State<_SlskPauzeStrook> {
  Timer? _tik;

  @override
  void initState() {
    super.initState();
    _tik = Timer.periodic(const Duration(seconds: 2), (_) {
      if (mounted) setState(() {});
    });
  }

  @override
  void dispose() {
    _tik?.cancel();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final s = context.read<SoulseekService>();
    if (!s.blocked) return const SizedBox.shrink();

    final left = s.blockedFor;
    return Row(mainAxisSize: MainAxisSize.min, children: [
      const SizedBox(width: 10),
      Icon(Icons.pause_circle_outline_rounded, size: 13, color: Colors.orange.shade300),
      const SizedBox(width: 4),
      // The reason comes from the client, which knows which of the five it is. This line used
      // to say "login geweigerd" for all of them — including a login that had just worked and
      // was then kicked, and a server that never answered at all.
      Tooltip(
        message: s.whyNotLogin ?? '',
        child: Text(
            left == null
                ? 'gepauzeerd — ${s.pauseLabel}'
                : 'gepauzeerd — ${s.pauseLabel}, nog ${left.inMinutes + 1} min',
            style: TextStyle(color: Colors.orange.shade300, fontSize: 11.5)),
      ),
      const SizedBox(width: 6),
      // This wait is OUR guard, not Soulseek's. When the official client is logged in fine,
      // the account clearly isn't blocked and the user should never be stuck behind it.
      TextButton(
        style: TextButton.styleFrom(
            padding: const EdgeInsets.symmetric(horizontal: 8), minimumSize: const Size(0, 26)),
        onPressed: () {
          context.read<SoulseekService>().retryLoginNow();
          _srcToast(context, 'Soulseek opnieuw proberen…');
        },
        child: const Text('nu opnieuw proberen', style: TextStyle(fontSize: 11.5)),
      ),
    ]);
  }
}

/// Soulseek section header with a "Download album" action for the best complete folder.
/// [all] is the full (unfiltered) result set — used to find fallback peers per track.
Widget _soulseekHeader(
    BuildContext context, List<SoulseekFile> slsk, bool busy, List<SoulseekFile> all,
    {required List<SoulseekFile> folder, ReleaseAuthority? authority}) {
  return Padding(
    padding: const EdgeInsets.fromLTRB(24, 14, 18, 6),
    // Gevouwen: "SOULSEEK · P2P 7083" plus "Download album (24)" is op een telefoon breder dan het
    // scherm. Er stond een `Spacer` in, en die duwt de knop er dan gewoon af.
    child: Wrap(
      crossAxisAlignment: WrapCrossAlignment.center,
      spacing: 4,
      runSpacing: 2,
      children: [
        const Text('SOULSEEK · P2P',
            style: TextStyle(color: _muted, fontSize: 11.5, fontWeight: FontWeight.w700, letterSpacing: .6)),
        const SizedBox(width: 8),
        Text('${slsk.length}', style: const TextStyle(color: _muted, fontSize: 11.5)),
        // Back-off notice: after a refused login the app stops touching Soulseek entirely, so the
        // user knows WHY there are no results (instead of thinking the search is just empty).
        const _SlskPauzeStrook(),
        if (busy) ...const [
          SizedBox(width: 8),
          SizedBox(width: 12, height: 12, child: CircularProgressIndicator(strokeWidth: 1.6, color: _muted)),
        ],
        if (folder.length >= 2)
          TextButton.icon(
            onPressed: () => _downloadSoulseekAlbum(context, folder, all, authority: authority),
            icon: const Icon(Icons.library_add_rounded, size: 16),
            label: Text('Download album (${folder.length})'),
            style: TextButton.styleFrom(foregroundColor: _accent, padding: const EdgeInsets.symmetric(horizontal: 8)),
          ),
      ],
    ),
  );
}

Widget _qualityBadge(Quality q) {
  Color fg, bg, border;
  switch (q.tier) {
    case QTier.hires: // hi-res lossless (24-bit / >48kHz / DSD) — gold
      fg = const Color(0xFFF2C14E);
      bg = const Color(0xFF2A2413);
      border = const Color(0xFF5A4A1E);
      break;
    case QTier.lossless: // CD-quality lossless — teal
      fg = _accent2;
      bg = const Color(0xFF0F2521);
      border = const Color(0xFF24493F);
      break;
    case QTier.lossy: // MP3/AAC — blue-grey
      fg = const Color(0xFFA9B6E8);
      bg = kPaneel;
      border = const Color(0xFF2A3350);
      break;
    case QTier.unknown: // unclear — subtle grey
      fg = _muted;
      bg = kPaneel;
      border = _line;
      break;
  }
  return Container(
    margin: const EdgeInsets.symmetric(horizontal: 8),
    padding: const EdgeInsets.symmetric(horizontal: 7, vertical: 2),
    decoration: BoxDecoration(color: bg, borderRadius: BorderRadius.circular(6), border: Border.all(color: border)),
    child: Text(q.label, style: TextStyle(color: fg, fontSize: 10.5, fontWeight: FontWeight.w600)),
  );
}

/// De nummers die uit een mp3 komen, met de bronnenlijst om er zelf een betere voor te kiezen.
///
/// Waarom dit een eigen pagina is en geen venster in Instellingen: hier ga je tijd doorbrengen. Per
/// nummer een zoekopdracht, een lijst met honderden peers en een keuze. Een dialoogvenster sluit bij
/// de eerste misklik en dan ben je je plaats kwijt.
///
/// Alleen de AFGEKAPTE bestanden staan hier, niet alle betrapte. Een opgeblazen bestand is gewoon
/// cd-kwaliteit in een te grote jas — opnieuw downloaden levert exact hetzelfde geluid en die rijen
/// zouden dus alleen maar werk beloven dat niets oplevert. Zie [LibraryStore.uitMp3Bestanden].
class KwaliteitView extends StatefulWidget {
  const KwaliteitView({super.key});
  @override
  State<KwaliteitView> createState() => _KwaliteitViewState();
}

class _KwaliteitViewState extends State<KwaliteitView> {
  int? _open;
  bool _bezig = false;
  int _done = 0, _total = 0;
  String? _uitslag;

  /// Waar een nummer lag toen je zijn bronnen openklapte.
  ///
  /// Dit is hoe de rij weet dat er een nieuwe kopie geland is die het probleem NIET oplost: staat de
  /// opname er nog steeds, maar op een ander pad, dan is er iets vervangen en is de vervanger ook
  /// afgekapt. Zonder dit zou zo'n rij er precies hetzelfde uitzien als een rij waar nog niets mee
  /// gebeurd is, en zou je dezelfde slechte bron een tweede keer kunnen kiezen.
  final Map<String, String> _padBijOpenen = {};

  static String _sleutel(Track t) => '${normKey(t.artist)}|${normKey(t.title)}';

  Future<void> _meet() async {
    final lib = context.read<LibraryStore>();
    setState(() {
      _bezig = true;
      _uitslag = null;
      _done = 0;
      _total = lib.tracks.where((t) => t.isFlac).length;
    });
    try {
      final uit = await lib.meetEchtheid(onProgress: (done, total) {
        if (!mounted || (done % 20 != 0 && done != total)) return;
        setState(() {
          _done = done;
          _total = total;
        });
      });
      if (!mounted) return;
      setState(() {
        _bezig = false;
        _uitslag = '${uit.onderzocht} onderzocht · ${uit.betrapt} betrapt';
      });
    } catch (e) {
      if (!mounted) return;
      setState(() {
        _bezig = false;
        _uitslag = 'Meten mislukt: $e';
      });
    }
  }

  @override
  Widget build(BuildContext context) {
    // Beide, en om verschillende redenen. De bibliotheek verandert als een vervanger geland is (de
    // oude kopie staat dan in `_dubbel` en de scan slaat die map over, dus de rij verdwijnt vanzelf);
    // de downloadlijst verandert al tijdens het binnenhalen, en dat is wat de voortgangsringetjes op
    // de bronregels laat lopen.
    final lib = context.watch<LibraryStore>();
    context.watch<DownloadManager>();
    final rijen = lib.uitMp3Bestanden();

    return ListView(
      padding: const EdgeInsets.fromLTRB(28, 22, 28, 30),
      children: [
        Wrap(
          crossAxisAlignment: WrapCrossAlignment.center,
          spacing: 14,
          runSpacing: 4,
          children: [
            const Text('Kwaliteit',
                style: TextStyle(fontSize: 25, fontWeight: FontWeight.w800, letterSpacing: -.4)),
            if (_bezig)
              Text('Luisteren… $_done van $_total', style: const TextStyle(color: _muted, fontSize: 12.5))
            else
              TextButton.icon(
                onPressed: _meet,
                icon: const Icon(Icons.verified_outlined, size: 16),
                label: const Text('Opnieuw meten'),
                style: TextButton.styleFrom(foregroundColor: _muted),
              ),
            if (_uitslag != null)
              Text(_uitslag!, style: const TextStyle(color: _muted, fontSize: 12.5)),
          ],
        ),
        const SizedBox(height: 6),
        Text(
          rijen.isEmpty
              ? 'Niets afgekapt gevonden — of er is nog niet gemeten.'
              : '${rijen.length} nummer(s) komen uit een mp3 en zitten dus ónder cd-kwaliteit. '
                  'Het ergste staat bovenaan. Klap er een open om te zien wat er te halen valt, en '
                  'kies zelf een vervanger — de oude kopie gaat naar _dubbel, nooit weg.',
          style: const TextStyle(color: _muted, fontSize: 12.5, height: 1.4),
        ),
        const SizedBox(height: 16),
        for (var i = 0; i < rijen.length; i++) _rij(rijen[i], i),
      ],
    );
  }

  Widget _rij(({Track track, Echtheidsoordeel oordeel}) r, int i) {
    final t = r.track;
    final open = _open == i;
    final sleutel = _sleutel(t);
    final vorig = _padBijOpenen[sleutel];
    final nogSteeds = vorig != null && vorig != t.path;
    final hz = r.oordeel.afkapHz;

    return Container(
      margin: const EdgeInsets.only(bottom: 6),
      decoration: BoxDecoration(color: _panel, borderRadius: BorderRadius.circular(10)),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          InkWell(
            borderRadius: BorderRadius.circular(10),
            onTap: () => setState(() {
              _open = open ? null : i;
              if (!open) _padBijOpenen[sleutel] = t.path;
            }),
            child: Padding(
              padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 11),
              child: Row(
                children: [
                  Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text('${t.artist} — ${t.title}',
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                            style: const TextStyle(fontWeight: FontWeight.w600, fontSize: 13.5)),
                        const SizedBox(height: 2),
                        Text(t.album, style: const TextStyle(color: _muted, fontSize: 11.5)),
                        const SizedBox(height: 3),
                        // `waaromAfkap` en niet `waarom`: op deze lijst staat een rij ALTIJD om
                        // zijn afkap, en die hoort dus vooraan te staan. Zie de docstring daar.
                        Text(waaromAfkap(r.oordeel),
                            style: TextStyle(color: Colors.orange.shade300, fontSize: 11.5)),
                        if (nogSteeds) ...[
                          const SizedBox(height: 3),
                          const Text('de nieuwe kopie is óók afgekapt — probeer een andere bron',
                              style: TextStyle(
                                  color: Color(0xFFE8913A), fontSize: 11.5, fontWeight: FontWeight.w600)),
                        ],
                      ],
                    ),
                  ),
                  if (hz != null) ...[
                    // De hoogte van de muur in één getal, want dat is wat de rijen onderling
                    // ordent: 15,6k is een heel ander bestand dan 21,0k.
                    Container(
                      margin: const EdgeInsets.only(right: 10),
                      padding: const EdgeInsets.symmetric(horizontal: 7, vertical: 2),
                      decoration: BoxDecoration(
                        color: const Color(0x33FF9800),
                        borderRadius: BorderRadius.circular(6),
                        border: Border.all(color: Colors.orange.shade300),
                      ),
                      child: Text('${(hz / 1000).toStringAsFixed(1)} kHz',
                          style: TextStyle(
                              color: Colors.orange.shade300, fontSize: 10.5, fontWeight: FontWeight.w600)),
                    ),
                  ],
                  Icon(open ? Icons.expand_less_rounded : Icons.travel_explore_rounded,
                      size: 18, color: open ? _accent : _muted),
                ],
              ),
            ),
          ),
          // Dezelfde bronnenlijst als op de albumpagina — torrents en Soulseek, met per regel een
          // downloadknop. Wat jij daar aanklikt gaat als `exact` de wachtrij in en wint dus van wat
          // er ligt, ook als het kleiner is.
          //
          // De tags komen van het bestand dat vervangen wordt en niet van de peer. Zie
          // [LibraryStore.tagsVoorVervanger].
          if (open)
            Padding(
              padding: const EdgeInsets.only(bottom: 8),
              child: SourcesView(
                query: '${t.artist} ${t.title}',
                tags: context.read<LibraryStore>().tagsVoorVervanger(t),
              ),
            ),
        ],
      ),
    );
  }
}

/// Alles wat de echtheidsproef niet doorstond, op een rij.
///
/// Zelfde vorm als [SoundDuplicatesDialog]: per regel wat het is en waaróm, in de bewoording van
/// [waarom] zodat het scherm nooit iets anders zegt dan de meting. Alleen de betrapten — een vinkje bij
/// de vijfhonderd die in orde zijn is ruis, en het totaal staat al onder de knop.
class EchtheidDialog extends StatelessWidget {
  const EchtheidDialog({super.key, required this.items});
  final List<({Track track, Echtheidsoordeel oordeel})> items;

  @override
  Widget build(BuildContext context) {
    return AlertDialog(
      backgroundColor: _panel,
      title: Text('${items.length} bestand(en) zijn niet wat ze zeggen'),
      content: SizedBox(
        width: dialogWidth(context, 720),
        height: 460,
        child: items.isEmpty
            ? const Center(child: Text('Niets gevonden.', style: TextStyle(color: _muted)))
            : ListView.separated(
                itemCount: items.length,
                separatorBuilder: (_, __) => const Divider(height: 1, color: _line),
                itemBuilder: (_, i) {
                  final it = items[i];
                  return Padding(
                    padding: const EdgeInsets.symmetric(vertical: 8),
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text('${it.track.artist} — ${it.track.title}',
                            style: const TextStyle(fontWeight: FontWeight.w600, fontSize: 13)),
                        const SizedBox(height: 2),
                        Text(it.track.album, style: const TextStyle(color: _muted, fontSize: 11.5)),
                        const SizedBox(height: 3),
                        Text(waarom(it.oordeel),
                            style: TextStyle(color: Colors.orange.shade300, fontSize: 11.5)),
                      ],
                    ),
                  );
                },
              ),
      ),
      actions: [
        // Bewust geen knop die iets weggooit. Zelfs de dubbelveger, die op 10.231 gemeten paren werkt,
        // wist niets — deze meting is aantoonbaar zwakker en verdient dus zeker niet meer bevoegdheid.
        TextButton(onPressed: () => Navigator.pop(context), child: const Text('Sluiten')),
      ],
    );
  }
}

/// Is dit bestand écht wat de badge ernaast beweert?
///
/// Saber: "hoe weet ik dat ik echt lossless of hi-res binnenhaal?" De kwaliteitsbadge hiernaast toont
/// wat het BESTAND zegt — dat is een bewering, geen feit. Deze toont wat er gemeten is.
///
/// Alleen zichtbaar als er iets te melden valt: een bestand dat de proef doorstaat krijgt niets, want
/// een vinkje bij 536 van de 672 nummers is ruis. Een ongemeten bestand krijgt óók niets — zwijgen is
/// hier eerlijker dan een vraagteken bij alles wat nog niet aan de beurt is geweest.
/// Twee bevindingen, twee heel verschillende gewichten — en dus twee vormen.
///
/// **Uit een mp3** is een verlies dat je niet terugkrijgt: die bestanden moeten eruit. Dat merkje mag
/// in de weg zitten, en blijft daarom precies zoals het was.
///
/// **Opgeschaald** is iets anders. Zo'n bestand IS cd-kwaliteit; het draagt alleen een te grote jas.
/// Er valt niets aan te verbeteren door het opnieuw te halen — je krijgt exact hetzelfde geluid terug.
/// Een even luide waarschuwing als bij een echte transcode zette 89 nummers in het rood voor iets wat
/// alleen ruimte kost. Vandaar een bolletje: aanwezig, maar het schreeuwt niet.
///
/// De uitleg gaat niet verloren, want de tooltip blijft eronder hangen — één beweging ver, met
/// dezelfde zin uit [waarom] die de badge ook toonde.
Widget _echtheidMerk(Track? t) {
  final pad = t?.path;
  if (t == null || pad == null || pad.isEmpty) return const SizedBox.shrink();
  final sr = t.sampleRate, bits = t.bitsPerSample;
  final o = gemeten(pad);
  if (o == null || !o.isNep) return const SizedBox.shrink();

  // ZEGGEN WAT HET DAN WEL IS, in plaats van alleen dat het niet klopt.
  //
  // Hier stond een bolletje van zeven bij zeven. Dat was een eerlijke keuze -- een even luide
  // waarschuwing als bij een echte transcode zette negenentachtig nummers in het rood voor iets wat
  // alleen ruimte kost -- maar het beantwoordde de verkeerde vraag. Ernaast staat `FLAC · 24/192`,
  // wat het bestand BEWEERT, en het bolletje zei dat dat gelogen was zonder te zeggen wat het dan
  // wél was. Precies het getal dat je wilt weten stond nergens.
  //
  // Nu staat de gemeten waarheid er: `16/44,1`, of `tot 17,2 kHz` als er een muur in het spectrum
  // zit. Even rustig als het bolletje -- gedempt amber, geen kader, geen pictogram -- en het zegt
  // iets.
  //
  // En met ruimte aan BEIDE kanten. De marge stond alleen rechts, dus het plakte tegen de
  // artiestennaam aan.
  final echt = echteResolutie(o, kopSampleRate: sr, kopBits: bits);
  if (echt == null) return const SizedBox.shrink();
  return Tooltip(
    message: waarom(o),
    child: Padding(
      padding: const EdgeInsets.symmetric(horizontal: 8),
      child: Text(echt, style: kLabel.copyWith(color: const Color(0xFFB98A4A))),
    ),
  );
}

/// Quality of a LOCAL library track (real bitrate from size÷duration, so a 16/44 FLAC and a
/// 24-bit hi-res FLAC read differently).
/// De kwaliteit van een nummer uit de eigen bibliotheek.
///
/// Het label komt uit de bitrate -- "FLAC · 2788k" zegt meer dan "FLAC" -- maar of het hi-res IS wordt
/// bepaald door de sample rate en de bitdiepte, want die staan in het bestand. De bitrate is daar maar
/// een benadering van: een druk gemasterd nummer van 44,1 kHz haalt ook 1500 kbit/s.
Quality _trackQuality(Track t) {
  final basis = qualityFromFile(
    name: t.title,
    ext: t.ext,
    isFlac: t.isFlac,
    durationSec: t.duration?.inSeconds,
    size: t.sizeBytes,
  );
  // Het formaat zelf in plaats van de bitrate, en bij ELKE lossless -- ook bij 16/44.1. Een bitrate is
  // de uitkomst van de muziek en de compressie samen en verschilt per nummer; dit zegt wat het bestand
  // is. En één notatie voor de hele lijst leest rustiger dan de ene rij "1433k" en de volgende "24/96".
  if (t.isFlac && t.sampleRate > 0 && t.bitsPerSample > 0) {
    // GEMETEN gaat vóór wat de kop beweert.
    //
    // Zonder deze regel kreeg een opgeblazen bestand het gouden hi-res-merk op grond van getallen
    // waarvan de meting had aangetoond dat ze niet kloppen — en dan filtert "Hi-Res" precies de
    // nepbestanden naar voren. De meting spreekt alleen het NEGATIEVE uit (zie echtheid.dart), dus
    // dit kan de badge alleen omlaag halen, nooit omhoog.
    final o = gemeten(t.path);
    final echtHiRes = isHiRes(sampleRate: t.sampleRate, bitsPerSample: t.bitsPerSample) &&
        !(o?.isNep ?? false);
    return Quality(
      'FLAC · ${depthRateLabel(sampleRate: t.sampleRate, bitsPerSample: t.bitsPerSample)}',
      echtHiRes ? QTier.hires : QTier.lossless,
    );
  }
  // Bij een lossy bestand is bitdiepte betekenisloos en is de bitrate juist wél waar het om gaat. Toch
  // met hetzelfde streepje ertussen, want anders staat er in dezelfde kolom één rij zonder enig getal
  // en dat is precies waar de lijn breekt.
  //
  // Berekend uit grootte en duur, want de app leest geen MP3-framekop. Voor 320, 192 en 160 komt dat
  // exact uit; bij VBR is het het echte gemiddelde, en bij een dikke ingesloten hoes kan het er een
  // paar procent boven schieten -- die telt mee in de grootte.
  final k = t.bitrateKbps;
  if (!t.isFlac && k != null && k > 0 && t.ext.isNotEmpty) {
    return Quality('${t.ext.toUpperCase()} · ${k}k', QTier.lossy);
  }
  return basis;
}

/// De kwaliteitsrang van één Soulseek-bestand, als één plat getal.
///
/// De resultaten stonden in de volgorde waarin de peers toevallig antwoordden, en dat is geen
/// volgorde: een bestand van 212 MB kon onder een van 30 MB staan. Lossless boven lossy, daarbinnen
/// op capaciteit; zie [kwaliteitsRang]. Wat er bij gelijke rang gebeurt staat in [vergelijkNaRang]:
/// eerst een vrije plek, dan de kortste wachtrij, dan de grootste — want het beste bestand van
/// iemand die niets uitdeelt heb je nog steeds niet, en "per grote boven" was letterlijk de vraag.
///
/// Een functie per BESTAND en niet een vergelijker, en dat is niet cosmetisch: [rangschikSoulseek]
/// en [groepeerSoulseek] roepen hem allebei één keer per bestand aan in plaats van twee keer per
/// vergelijking. Bij zevenduizend treffers scheelt dat een factor twintig, en dat is precies het
/// verschil tussen soepel en haperend scrollen.
int _slskRang(SoulseekFile f) {
  final kbps = effectieveBitrate(bitrate: f.bitrate, durationSec: f.durationSec, size: f.size);
  final lossless = f.isFlac || const {'alac', 'ape', 'wav', 'aiff'}.contains(f.ext);
  return kwaliteitsRang(
    lossless: lossless,
    // Het formaat dat de peer meldt gaat vóór de gemeten bitrate. Twee ripjes van dezelfde 24/96
    // verschillen een paar procent in bitrate zonder dat er iets beters aan is; hun sample rate maal
    // bitdiepte is identiek, en dát is waar het om gaat. Meldt de peer niets, dan rekent
    // [capaciteitOpEenSchaal] de gemeten bitrate terug naar diezelfde maat — anders vergelijk je een
    // ruwe capaciteit met een ingepakte en staat elk onbekend bestand een derde te hoog.
    kbps: capaciteitOpEenSchaal(
        sampleRate: f.sampleRate, bitDepth: f.bitDepth, kbps: kbps, lossless: lossless),
    // Twee wegen: de som bewijst het, de naam vangt de peers die geen sample rate sturen. Op de hele
    // naam en niet alleen het bestandsnaampje — uploaders zetten "5.1" net zo vaak in de mapnaam.
    stereo: !meerDanStereo(sampleRate: f.sampleRate, bitDepth: f.bitDepth, kbps: kbps) &&
        surroundLabel(f.filename) == null,
  );
}

/// Wat er als waarschuwing op de rij komt, of null bij gewoon stereo.
///
/// De naam gaat vóór als hij iets zegt — "5.1" is duidelijker dan "meerkanaals". Zegt de naam niets,
/// dan beslist de som: een bestand dat boven zijn eigen onbewerkte stereogrootte uitkomt heeft meer
/// kanalen, en dat is precies het geval dat de naam laat lopen.
String? _surroundMerk(SoulseekFile f) {
  final uitNaam = surroundLabel(f.filename);
  if (uitNaam != null) return uitNaam;
  final kbps = effectieveBitrate(bitrate: f.bitrate, durationSec: f.durationSec, size: f.size);
  return meerDanStereo(sampleRate: f.sampleRate, bitDepth: f.bitDepth, kbps: kbps)
      ? 'meerkanaals'
      : null;
}

/// Het etiket op een zoekresultaat, met het formaat dat de peer zélf meldt.
///
/// Sinds de sample rate en de bitdiepte bewaard worden, staat hier `FLAC · 24/192` in plaats van een
/// bitrate die de app zelf uit grootte en duur moest afleiden. Dezelfde notatie als in de bibliotheek —
/// dan is een zoekresultaat rechtstreeks te vergelijken met wat je al hebt, en dat is de hele vraag.
///
/// Zonder die twee getallen blijft het de oude weg: bij mp3 zegt bitdiepte niets, en een peer die niets
/// meldt heeft nog steeds een bitrate die uit te rekenen valt.
Quality _slskQuality(SoulseekFile f) {
  final sr = f.sampleRate, bits = f.bitDepth;
  if (f.isFlac && sr != null && bits != null && sr > 0 && bits > 0) {
    return Quality(
      'FLAC · ${depthRateLabel(sampleRate: sr, bitsPerSample: bits)}',
      isHiRes(sampleRate: sr, bitsPerSample: bits) ? QTier.hires : QTier.lossless,
    );
  }
  return _slskQualityUitGrootte(f);
}

Quality _slskQualityUitGrootte(SoulseekFile f) => qualityFromFile(
      name: f.displayName,
      ext: f.ext,
      isFlac: f.isFlac,
      bitrate: f.bitrate,
      durationSec: f.durationSec,
      size: f.size,
      isVbr: f.isVbr,
    );

/// A row of quality-filter chips (Alles / Lossless / Hi-Res / MP3), shared by the
/// direct-search results and the browse "Bronnen" panel.
Widget _filterChipsRow(QFilter current, ValueChanged<QFilter> onChanged) => Padding(
      padding: const EdgeInsets.fromLTRB(22, 6, 20, 2),
      // Gevouwen en niet op één rij: vier chips plus het icoontje passen op 360 punten net niet,
      // en een `Row` die niet past geeft de gele overloopbalk — iets wat geen enkele toets ziet en
      // alleen op het toestel opvalt.
      child: Wrap(
        crossAxisAlignment: WrapCrossAlignment.center,
        runSpacing: 6,
        children: [
          const Icon(Icons.tune_rounded, size: 15, color: _muted),
          const SizedBox(width: 8),
          ...QFilter.values.map((f) {
            final sel = current == f;
            return Padding(
              padding: const EdgeInsets.only(right: 6),
              child: InkWell(
                onTap: () => onChanged(f),
                borderRadius: BorderRadius.circular(20),
                child: Container(
                  padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 5),
                  decoration: BoxDecoration(
                    color: sel ? _accent : _panel,
                    borderRadius: BorderRadius.circular(20),
                    border: Border.all(color: sel ? _accent : _line),
                  ),
                  child: Text(f.label,
                      style: TextStyle(
                          color: sel ? Colors.white : _muted, fontSize: 12, fontWeight: FontWeight.w600)),
                ),
              ),
            );
          }),
        ],
      ),
    );

/// Knoppen om op BRON te zeven: alleen RuTracker, alleen Knaben, enzovoort.
///
/// Naast de kwaliteitsknoppen en niet ertussen: het zijn twee losse vragen ("wat voor bestand" en
/// "van wie"), en ze werken over elkaar heen. Zie [bronnenInResultaten] voor waarom deze rij uit de
/// resultaten zelf komt en niet uit een vaste lijst.
///
/// Niets bij één bron. Een keuze uit één is geen keuze, en een rij knoppen die niets kan veranderen
/// is precies de ruimte die op een telefoon nergens vandaan komt.
Widget _bronChipsRow(
  List<({String bron, int aantal})> bronnen,
  String? gekozen,
  ValueChanged<String?> onChanged,
) {
  if (bronnen.length < 2) return const SizedBox.shrink();
  Widget chip(String label, int? aantal, bool sel, VoidCallback doen) => Padding(
        padding: const EdgeInsets.only(right: 6),
        child: InkWell(
          onTap: doen,
          borderRadius: BorderRadius.circular(20),
          child: Container(
            padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 5),
            decoration: BoxDecoration(
              color: sel ? _accent2.withValues(alpha: .22) : _panel,
              borderRadius: BorderRadius.circular(20),
              border: Border.all(color: sel ? _accent2 : _line),
            ),
            child: Text(aantal == null ? label : '$label $aantal',
                style: TextStyle(
                    color: sel ? Colors.white : _muted,
                    fontSize: 12,
                    fontWeight: sel ? FontWeight.w600 : FontWeight.w400)),
          ),
        ),
      );
  return Padding(
    padding: const EdgeInsets.fromLTRB(22, 2, 20, 2),
    // `Wrap` om dezelfde reden als bij de kwaliteitsknoppen: vijf bronnen met hun aantal passen op
    // een staande telefoon niet op één regel, en een `Row` die niet past tekent gewoon door.
    child: Wrap(
      crossAxisAlignment: WrapCrossAlignment.center,
      runSpacing: 6,
      children: [
        const Icon(Icons.travel_explore_rounded, size: 15, color: _muted),
        const SizedBox(width: 8),
        chip('Alle bronnen', null, gekozen == null, () => onChanged(null)),
        for (final b in bronnen)
          chip(b.bron, b.aantal, gekozen == b.bron, () => onChanged(b.bron)),
      ],
    ),
  );
}

Widget _sourceHeader(String title, int count, bool loading) => Padding(
      padding: const EdgeInsets.fromLTRB(24, 14, 24, 6),
      child: Row(
        children: [
          Text(title.toUpperCase(),
              style: const TextStyle(color: _muted, fontSize: 11.5, fontWeight: FontWeight.w700, letterSpacing: .6)),
          const SizedBox(width: 8),
          Text('$count', style: const TextStyle(color: _muted, fontSize: 11.5)),
          if (loading) ...const [
            SizedBox(width: 8),
            SizedBox(width: 12, height: 12, child: CircularProgressIndicator(strokeWidth: 1.6, color: _muted)),
          ],
        ],
      ),
    );

/// Eén torrenttreffer.
///
/// **Waarom deze rij op een telefoon een kaart is en geen regel.** Hij was een `Row` met rechts drie
/// `IconButton`s (samen zo'n 130 punten) en een keurmerk, en links wat er dan nog overbleef. Op 360
/// punten breed hield de titel er nog geen 150 over: op het scherm stond "(Pop) [CDM] Backstre…" en
/// "Backstreet Boys - Bac…" — vier treffers onder elkaar die er allemaal precies hetzelfde uitzien,
/// terwijl juist het weggevallen stuk (welke persing, welk jaar, welke uitgave) het verschil is waar
/// je op kiest. Ook de tweede regel was op één regel gesnoerd, dus daar stond "BitS… · 2 se…".
///
/// Op een telefoon staat nu alles onder elkaar: de titel over [titelRegels] regels, daaronder de
/// gegevens die mogen omlopen, en de drie knoppen op hun eigen regel — mét hun naam erbij, want als
/// ze toch ruimte krijgen kun je net zo goed zien wat ze doen. Op een breed scherm blijft het de
/// rij die het was: daar past het ruim, en rijen van gelijke hoogte lezen sneller.
Widget _torrentTile(BuildContext context, SearchResult r) {
  final q = qualityFromName(r.name);
  final smal = isCompact(context);
  final meta = '${r.source} · ${r.seeders} seeders · ${_fmtBytes(r.size)}';
  final acties = <({IconData icoon, String naam, String uitleg, Color kleur, VoidCallback doen})>[
    (
      icoon: Icons.play_arrow_rounded,
      naam: 'Beste nummer',
      uitleg: 'Beste nummer afspelen',
      kleur: _accent,
      doen: () => _playTorrent(context, r)
    ),
    (
      icoon: Icons.queue_music_rounded,
      naam: 'Kies nummer',
      uitleg: 'Kies nummer',
      kleur: _muted,
      doen: () => _pickTorrentTracks(context, r)
    ),
    (
      icoon: Icons.download_rounded,
      naam: 'Alles',
      uitleg: 'Alles downloaden',
      kleur: _muted,
      doen: () => _downloadTorrent(context, r)
    ),
  ];
  final kaart = Container(
    margin: const EdgeInsets.symmetric(horizontal: 20, vertical: 1),
    padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 10),
    decoration: BoxDecoration(color: _panel, borderRadius: BorderRadius.circular(8)),
    child: smal
        ? Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Text(r.name,
                  maxLines: titelRegels(context),
                  overflow: TextOverflow.ellipsis,
                  style: const TextStyle(fontWeight: FontWeight.w600)),
              const SizedBox(height: 6),
              // Gevouwen en niet gesnoerd: staat er een bron met een lange naam of een grote
              // seedersstand, dan zakt het keurmerk naar de volgende regel in plaats van dat de
              // tekst achter puntjes verdwijnt.
              Wrap(
                spacing: 8,
                runSpacing: 4,
                crossAxisAlignment: WrapCrossAlignment.center,
                children: [
                  Text(meta, style: const TextStyle(color: _muted, fontSize: 12)),
                  if (r.cached)
                    const Text('⚡ Instant', style: TextStyle(color: _accent2, fontSize: 12)),
                  _qualityBadge(q),
                ],
              ),
              const SizedBox(height: 2),
              Wrap(
                children: [
                  // Geen [TvLabelled] hier: die zet een naam ónder een icoon voor de
                  // afstandsbediening, en op een scherm dat hier binnenkomt (smaller dan 600 punten)
                  // is dat nooit een tv. De naam staat bovendien al op de knop.
                  for (final a in acties)
                    TextButton.icon(
                      onPressed: a.doen,
                      icon: Icon(a.icoon, size: 19),
                      label: Text(a.naam),
                      style: TextButton.styleFrom(
                        foregroundColor: a.kleur,
                        padding: const EdgeInsets.symmetric(horizontal: 8),
                        visualDensity: VisualDensity.compact,
                      ),
                    ),
                ],
              ),
            ],
          )
        : Row(
            children: [
              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(r.name,
                        maxLines: titelRegels(context),
                        overflow: TextOverflow.ellipsis,
                        style: const TextStyle(fontWeight: FontWeight.w600)),
                    const SizedBox(height: 2),
                    Row(
                      children: [
                        // Ingesnoerd, want deze regel liep ONDER de badge door. Een `Text` los in
                        // een `Row` krijgt geen bovengrens en tekent gewoon door tot buiten zijn vak.
                        Flexible(
                          child: Text(meta,
                              maxLines: 1,
                              overflow: TextOverflow.ellipsis,
                              style: const TextStyle(color: _muted, fontSize: 12)),
                        ),
                        if (r.cached)
                          const Padding(
                              padding: EdgeInsets.only(left: 8),
                              child:
                                  Text('⚡ Instant', style: TextStyle(color: _accent2, fontSize: 12))),
                      ],
                    ),
                  ],
                ),
              ),
              _qualityBadge(q),
              for (final a in acties)
                TvLabelled(
                  label: a.naam,
                  child: IconButton(
                      icon: Icon(a.icoon), color: a.kleur, tooltip: a.uitleg, onPressed: a.doen),
                ),
            ],
          ),
  );
  // Eigen tekenlaag per rij. Zonder dit tekent een beweging van één punt de hele lijst opnieuw —
  // ook de rijen die niet veranderen en de rijen die je niet ziet. Met een [RepaintBoundary] wordt
  // een rij één keer getekend en daarna alleen nog verschoven, en dát is wat scrollen soepel maakt.
  return RepaintBoundary(child: kaart);
}

/// Eén Soulseek-bestand.
///
/// De gebruikersnaam staat hier NIET meer: die hoort in de kop van zijn groep, één keer, in plaats
/// van op elk van de zevenduizend regels. Dat was ook precies de ruimte die de titel tekortkwam.
/// [toonGebruiker] zet hem terug voor een lijst die niet gegroepeerd is.
///
/// Op een telefoon zakken de merken (meerkanaals, "verdacht klein", het keurmerk) naar een eigen
/// regel onder de tekst. Naast de titel vraten ze de laatste ruimte op die de naam nog had — en een
/// naam als "Backstreet Boys - …" zonder de rest zegt niets, want dat staat op álle treffers.
Widget _soulseekTile(BuildContext context, SoulseekFile f, List<SoulseekFile> all,
    {TrackTags? authority,
    bool toonGebruiker = true,
    bool past = false,
    String pastMerk = 'dit nummer',
    EdgeInsets? marge}) {
  final status = f.freeSlots ? 'vrij' : 'wachtrij ${f.queueLength}';
  final q = _slskQuality(f);
  final smal = isCompact(context);
  final meta = [
    status,
    if (toonGebruiker) f.username,
    _fmtBytes(f.size),
    if (f.durationSec != null && f.durationSec! > 0) _fmt(Duration(seconds: f.durationSec!)),
  ].join(' · ');
  // Het kanaalaantal, als de naam het prijsgeeft. Zonder dit was een 5.1-bestand niet van een
  // stereobestand te onderscheiden behalve aan zijn verdachte grootte — en die grootte leest
  // juist als "beter", terwijl het op een stereo-installatie minder is.
  //
  // Oranje en niet groen: dit is een waarschuwing, geen keurmerk.
  Widget merk(String tekst, {String? uitleg}) {
    final blok = Container(
      padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 2),
      decoration: BoxDecoration(
        color: const Color(0xFFE8913A).withValues(alpha: .16),
        borderRadius: BorderRadius.circular(5),
        border: Border.all(color: const Color(0xFFE8913A).withValues(alpha: .45)),
      ),
      child: Text(tekst,
          style: const TextStyle(
              fontSize: 10, fontWeight: FontWeight.w700, color: Color(0xFFE8913A))),
    );
    return uitleg == null ? blok : Tooltip(message: uitleg, child: blok);
  }

  final merken = <Widget>[
    // GROEN, en als enige groen tussen de oranje waarschuwingen: dit is geen twijfel maar een
    // bevestiging. Het zegt dat de naam én de looptijd van dit bestand kloppen met het nummer dat
    // je aantikte — inclusief de versie, waarbij de map van de peer als bewijs meetelt. Zie
    // [versieVolgtUitMap]. Deze bestanden staan bovendien bovenaan; zie [_pastBonus].
    if (past)
      Container(
        padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 2),
        decoration: BoxDecoration(
          color: _accent2.withValues(alpha: .16),
          borderRadius: BorderRadius.circular(5),
          border: Border.all(color: _accent2.withValues(alpha: .45)),
        ),
        child: Text(pastMerk,
            style: const TextStyle(fontSize: 10, fontWeight: FontWeight.w700, color: _accent2)),
      ),
    if (_surroundMerk(f) != null) merk(_surroundMerk(f)!),
    // TE KLEIN VOOR WAT HET BEWEERT. Meten kan hier niet: je kunt niet in het bestand van een
    // vreemde kijken zonder het eerst binnen te halen. Wat wél kan is de getallen tegen elkaar
    // wegstrepen die de peer zelf meestuurt — een 24/96 die uit een 44,1-bron is opgetild pakt veel
    // kleiner in dan een echte. Zie [verdachtKleinVoorHiRes].
    //
    // Bewust dezelfde oranje vorm als het surroundmerk, en om dezelfde reden: dit is een
    // waarschuwing, geen keurmerk en geen oordeel. Het staat ook NIET in de rangschikking — een
    // vermoeden hoort de gebruiker te informeren, niet voor hem te beslissen.
    if (verdachtKleinVoorHiRes(
        sampleRate: f.sampleRate, bitDepth: f.bitDepth, kbps: f.bitrate ?? 0))
      merk('verdacht klein',
          uitleg: 'Zegt ${f.bitDepth}/${f.sampleRate} maar is daar veel te klein voor — '
              'waarschijnlijk opgeschaald. Zeker weten kan pas na het binnenhalen.'),
    _qualityBadge(q),
  ];
  final kaart = Container(
    margin: marge ?? const EdgeInsets.symmetric(horizontal: 20, vertical: 1),
    padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 10),
    decoration: BoxDecoration(color: _panel, borderRadius: BorderRadius.circular(8)),
    child: Row(
      crossAxisAlignment: smal ? CrossAxisAlignment.start : CrossAxisAlignment.center,
      children: [
        Padding(
          padding: EdgeInsets.only(top: smal ? 5 : 0),
          child: Icon(f.freeSlots ? Icons.circle : Icons.schedule_rounded,
              size: 10, color: f.freeSlots ? _accent2 : _muted),
        ),
        const SizedBox(width: 10),
        Expanded(
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Text(f.displayName,
                  maxLines: titelRegels(context),
                  overflow: TextOverflow.ellipsis,
                  style: const TextStyle(fontWeight: FontWeight.w600)),
              const SizedBox(height: 2),
              Text(meta, style: const TextStyle(color: _muted, fontSize: 12)),
              if (smal) ...[
                const SizedBox(height: 6),
                Wrap(spacing: 6, runSpacing: 4, children: merken),
              ],
            ],
          ),
        ),
        if (!smal)
          for (final m in merken) Padding(padding: const EdgeInsets.only(left: 6), child: m),
        _downloadControl(context,
            jobKey: _slskKey(f),
            onDownload: () => _downloadSoulseek(context, f, all, authority: authority)),
      ],
    ),
  );
  // Eigen tekenlaag, om dezelfde reden als bij [_torrentTile].
  return RepaintBoundary(child: kaart);
}

/// Network cover with a graceful placeholder (album browse / artist photos from Deezer).
Widget _netCover(String? url, {double size = 160, double radius = 12, bool circle = false}) {
  final shape = circle ? BoxShape.circle : BoxShape.rectangle;
  final br = circle ? null : BorderRadius.circular(radius);
  final placeholder = Container(
    width: size,
    height: size,
    decoration: BoxDecoration(
      shape: shape,
      borderRadius: br,
      gradient: const LinearGradient(colors: [kPaneelHoog, kPaneel]),
    ),
    child: Icon(circle ? Icons.person_rounded : Icons.album_rounded, color: _muted.withValues(alpha: .4), size: size * .34),
  );
  if (url == null || url.isEmpty) return placeholder;
  final beeld = Image.network(url,
      width: size,
      height: size,
      fit: BoxFit.cover,
      cacheWidth: decodeWidth(size),
      errorBuilder: (_, __, ___) => placeholder,
      loadingBuilder: (c, w, p) => p == null ? w : placeholder,
      // Invaden in plaats van inploppen. Zonder dit springt een tegel in één beeld van de grijze
      // verloop naar het volle plaatje; met vier rijen op het startscherm is dat een minutenlang
      // mozaïek dat staat te knipperen. `wasSynchronouslyLoaded` sluit de tweede keer uit: een
      // plaatje dat al in de cache zat hoort er meteen te staan, niet opnieuw te komen opzetten.
      frameBuilder: (c, kind, frame, gesynchroniseerd) => gesynchroniseerd
          ? kind
          : AnimatedOpacity(
              opacity: frame == null ? 0 : 1,
              duration: const Duration(milliseconds: 220),
              curve: Curves.easeOut,
              child: kind,
            ));
  // ClipRRect/ClipOval en niet `Container(clipBehavior:)` — zie de uitleg bij `cover()`.
  return SizedBox(
    width: size,
    height: size,
    child: circle ? ClipOval(child: beeld) : ClipRRect(borderRadius: br!, child: beeld),
  );
}

/// Combined torrent + Soulseek sources for one query — the "streams" list under a track/album.
class SourcesView extends StatefulWidget {
  final String query;

  /// The official release this list of sources belongs to, when it was opened from an album page.
  ///
  /// Soulseek serves one song under a dozen names and each carries its own tags. Without this the
  /// peer decides what track it is; with it, the record does and Soulseek only supplies the audio.
  /// Null when the sources were opened from a loose search, where there is no release to appeal to.
  final ReleaseAuthority? authority;

  /// The one track these sources are for, when this list is under a track row.
  final ChoiceTrack? track;

  /// De tags die de binnengehaalde kopie moet krijgen, al klaar.
  ///
  /// [authority] + [track] leiden ze af uit een officiële uitgave, en dat is de juiste weg zolang je
  /// van een albumpagina komt. Vanuit de Kwaliteit-lijst is er geen uitgave: daar staat een bestand
  /// dat AL in de bibliotheek ligt, met de tags die de gebruiker er zelf op heeft gezet. Die zijn
  /// beter dan wat een nieuwe opzoeking zou opleveren, en ze per rij ophalen zou bovendien een
  /// MusicBrainz-zoekopdracht per nummer kosten. Zie [LibraryStore.tagsVoorVervanger].
  ///
  /// Gaat vóór op [authority] + [track] wanneer beide gegeven zijn.
  final TrackTags? tags;
  const SourcesView({super.key, required this.query, this.authority, this.track, this.tags});
  @override
  State<SourcesView> createState() => _SourcesViewState();
}

class _SourcesViewState extends State<SourcesView> {
  List<SearchResult> _torrents = [];
  List<SoulseekFile> _slsk = [];

  bool _tBusy = true, _sBusy = false;
  QFilter _filter = QFilter.all;

  /// Op welke bron gezeefd wordt, of null voor alles. Zie [bronnenInResultaten].
  String? _bron;

  /// Zie [_tekenRem]: één per bron, zodat torrents en Soulseek elkaar niet in de weg zitten.
  final _slskRem = _Tekenrem(), _torrentRem = _Tekenrem();

  /// De vraag waarop Soulseek uiteindelijk gezocht heeft. Wijkt hij af van [SourcesView.query], dan
  /// staat er een regel bij die dat zegt.
  String? _gezochtOp;

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addPostFrameCallback((_) => _run());
  }

  Future<void> _run() async {
    final online = context.read<OnlineService>();
    final soulseek = context.read<SoulseekService>();
    if (mounted) {
      setState(() {
        _tBusy = true;
        _sBusy = soulseek.available;
        _gezochtOp = null;
      });
    }
    if (soulseek.available) {
      soulseek.search(widget.query, gebruikteVraag: (v) {
        // Zodra er op een ruimere trede gezocht wordt, gaat deze lijst over een ándere vraag dan je
        // stelde. Dat hoort erbij te staan — zie [zoekLadder].
        if (mounted && v != _gezochtOp) setState(() => _gezochtOp = v);
      }, onPartial: (p) {
        // Zie [_tekenRem]: niet elk stukje hoeft het scherm opnieuw te laten tekenen.
        if (mounted && _slskRem.mag()) setState(() => _slsk = p);
      }).then((r) {
        if (mounted) setState(() { _slsk = r; _sBusy = false; });
      }).catchError((_) { if (mounted) setState(() => _sBusy = false); });
    }
    try {
      final r = await online.search(widget.query, onPartial: (p) {
        if (mounted && _torrentRem.mag()) setState(() => _torrents = p);
      });
      if (mounted) setState(() => _torrents = r);
    } catch (_) {}
    if (mounted) setState(() => _tBusy = false);
  }

  /// Het geheugen van één: zie [_SlskKlaar]. Zonder dit werd er bij elke tik en elk deelresultaat
  /// opnieuw gefilterd, gerangschikt en gegroepeerd over duizenden bestanden.
  _SlskKlaar? _klaar;
  _SlskKlaar get _bronnen {
    final k = _klaar;
    if (k != null && k.geldigVoor(_slsk, _filter, null)) return k;
    return _klaar = _SlskKlaar.van(_slsk, _filter,
        past: _pastBijNummer, hergebruik: k?.hergebruikVoor(_slsk, null));
  }

  /// Of een aangeboden bestand bewijsbaar het nummer is dat onder deze lijst hangt.
  ///
  /// Alleen vanaf een albumpagina, want alleen daar weet de app wat er gevraagd is: de titel mét
  /// zijn versie-aanduiding, en de officiële looptijd. [fileOffersTitle] neemt de MAP van de peer
  /// als bewijs mee — zie [versieVolgtUitMap] — en dat is precies waarom "Fields of Gold (My Songs
  /// Version)" nu wél te vinden is in een map die "My Songs" heet.
  bool Function(SoulseekFile)? get _pastBijNummer {
    final a = widget.authority, t = widget.track;
    if (a == null || t == null) return null;
    return (f) => fileOffersTitle(t.title, t.seconds, a.artist, f.filename, f.durationSec);
  }

  @override
  Widget build(BuildContext context) {
    final ready = context.read<SoulseekService>().available;
    // De bronknoppen komen uit de resultaten die de KWALITEITSzeef al doorstonden, zodat het aantal
    // achter elke bron klopt met wat je te zien krijgt als je erop tikt.
    final naKwaliteit =
        _torrents.where((r) => _filter.matches(qualityFromName(r.name))).toList();
    final bronKeuzes = bronnenInResultaten(naKwaliteit);
    final bron = geldigeKeuze(_bron, bronKeuzes);
    final torrents = [for (final r in naKwaliteit) if (pastBijBron(r, bron)) r];
    final bronnen = _bronnen;
    final slsk = bronnen.gefilterd;
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        if (_torrents.isNotEmpty || _slsk.isNotEmpty)
          _filterChipsRow(_filter, (f) => setState(() => _filter = f)),
        _bronChipsRow(bronKeuzes, bron, (b) => setState(() => _bron = b)),
        _sourceHeader('Torrents · TorBox', torrents.length, _tBusy),
        if (!_tBusy) _waaromGeenTorrents(context, leeg: torrents.isEmpty),
        ...torrents.map((r) => _torrentTile(context, r)),
        if (ready)
          _soulseekHeader(context, slsk, _sBusy, slsk,
              folder: bronnen.besteMap, authority: widget.authority)
        else
          const Padding(
              padding: EdgeInsets.fromLTRB(24, 14, 24, 6),
              child: Text('SOULSEEK · log in via Instellingen',
                  style: TextStyle(color: _muted, fontSize: 11.5, fontWeight: FontWeight.w700, letterSpacing: .6))),
        if (ready && slsk.isEmpty && !_sBusy)
          const Padding(
              padding: EdgeInsets.fromLTRB(24, 2, 24, 6),
              child: Text('Geen Soulseek-bronnen.', style: TextStyle(color: _muted, fontSize: 12.5))),
        // Eerlijk zeggen waar deze lijst over gaat. Zonder deze regel stond je naar bronnen voor een
        // ándere vraag te kijken zonder dat er iets over gezegd werd — zie [zoekLadder].
        if (ready && _gezochtOp != null && ruimerGezocht(widget.query, _gezochtOp!))
          Padding(
            padding: const EdgeInsets.fromLTRB(24, 2, 24, 6),
            child: Text(
                'Niets gevonden voor “${widget.query}”. Dit zijn de bronnen voor “$_gezochtOp” — '
                'kijk dus na of het de juiste versie is.',
                style: const TextStyle(color: Color(0xFFE8913A), fontSize: 12.5)),
          ),
        // Whichever copy the user picks, the record decides what it is. That is the whole point:
        // this same song is offered as "13 …", "19. …" and "…The Essential … - 01 - …".
        // De boom houdt zijn eigen openstand en venster bij; [sleutel] is wat hem terugzet als er
        // een nieuwe zoekopdracht onder komt te staan.
        _SoulseekGroepen(
            gebruikers: bronnen.gebruikers,
            slsk: slsk,
            passend: bronnen.passend,
            sleutel: widget.query,
            authority: _trackAuthority,
            uitgave: widget.authority),
      ],
    );
  }

  /// What the track under this list IS, when it was opened from an album page.
  TrackTags? get _trackAuthority {
    // Al klaargelegd door de aanroeper — dan valt er niets af te leiden. Zie [SourcesView.tags].
    if (widget.tags != null) return widget.tags;
    final a = widget.authority, t = widget.track;
    if (a == null || t == null) return null;
    // The position IS the number: this tracklist came from the official release. Never indexOf on
    // the track — ChoiceTrack has no equality, so it would miss every time and fall back to
    // something that is not a track number at all.
    final stated = int.tryParse(t.position) ?? 0;
    if (stated > 0) return a.forTrack(t, stated);
    final at = a.tracks.indexWhere((x) => normKey(x.title) == normKey(t.title));
    return at < 0 ? null : a.forTrack(t, at + 1);
  }
}

/// Hoeveel BRONNEN er in één keer op het scherm komen, en hoeveel erbij per tik.
///
/// Rows are built eagerly inside a plain ListView, so a broad query (3500+ hits is normal for a
/// popular track) would build every one of them on every rebuild and lock the UI. Vandaar een
/// venster in plaats van alles — maar het is nu een venster dat OPENGAAT.
///
/// Sinds de lijst per gebruiker gegroepeerd is, telt dit BRONNEN en geen bestanden — en daarom mag
/// het getal veel lager. Tweehonderd kaarten tegelijk zijn tweehonderd rijen die allemaal echt
/// bestaan en bij elke beweging meegetekend worden, ook de honderdtachtig die je niet ziet; dat was
/// te voelen als haperend scrollen. Vijftig bronnen is ruim genoeg om te kiezen, en de knop staat
/// eronder.
///
/// **Niet privé, en dat is met opzet.** Dit getal stond in `bron_venster_test.dart` nog eens als
/// `200` uitgeschreven, dus toen het hier veranderde brak die toets — op het getal, niet op de
/// rekensom die hij hoort te bewaken. Nu leest de toets het hier, en mag het getal veranderen
/// zonder dat er iets stuk hoeft.
const bronStap = 50;

/// Wat er van een gerangschikte bronnenlijst getoond wordt, en wat er nog wacht.
///
/// Apart en zuiver omdat dit precies het soort rekensom is dat er goed uitziet en er één naast
/// zit: een [limiet] die groter is dan de lijst mag niet uit `sublist` vallen, en de laatste tik
/// moet "Nog 35 tonen" zeggen en niet "Nog 200 tonen".
({int tot, int rest, int volgende}) bronVenster(int aantal, int limiet) {
  final tot = limiet < 0
      ? 0
      : limiet > aantal
          ? aantal
          : limiet;
  final rest = aantal - tot;
  return (tot: tot, rest: rest, volgende: rest < bronStap ? rest : bronStap);
}

/// Hoeveel een bestand erbij krijgt als het bewijsbaar het GEVRAAGDE nummer is.
///
/// Groot genoeg om alles te overstemmen: [kwaliteitsRang] komt niet boven de honderd miljoen, dus
/// een passende MP3 staat hier boven een 24/96 van iets anders. Dat is met opzet de goede kant op.
/// Bij "Fields of Gold (My Songs Version)" stonden er honderden kopieën van de plaat uit 1993
/// bovenaan, allemaal in prachtige kwaliteit, en de heropname uit 2019 lag ergens onderin — als hij
/// er al bij zat. De béste kopie van het verkeerde nummer is geen goede kopie.
///
/// Alleen als de app WEET wat er gevraagd is, dus als er een uitgave onder de lijst hangt. Bij een
/// los zoekscherm gebeurt er niets en blijft de volgorde precies wat hij was.
const _pastBonus = 1000000000;

/// Eén trede DEKKING: hoeveel van je getypte woorden er in dit pad voorkomen.
///
/// De hoogste trap van alle, want dit is letterlijk "hoeveel van mijn vraag zit hierin". Twintig
/// treden, dus één woord meer van een vraag van vier telt vijf treden.
const _dekkingStap = 1000000000000;

/// Eén trede REEKS: hoeveel van je woorden er ACHTER ELKAAR in de bestandsnaam staan.
///
/// Onder de dekking en boven de kwaliteit. Zie [reeksScore]: op "mackenzie you all i need" haalt
/// `YORK feat. Ginger Mackenzie - I Need You` dekking 0,75 en reeks 0,25, terwijl
/// `Mackenzie - You're All I Need` op 1,00 en 0,50 komt. Bij gelijke dekking is dít wat een
/// treffer van een toevalstreffer scheidt.
const _reeksStap = 10000000000;

/// De bronnenlijst voorgekauwd: gefilterd, gerangschikt en gegroepeerd, in één keer.
///
/// **Waarom hier een geheugen zit.** Dit rekenwerk stond gewoon in `build()`, en `build()` draait
/// veel vaker dan er iets verandert: elke driehonderd milliseconden komt er een deelresultaat
/// binnen, en elke tik op een groep is er ook één. Bij zevenduizend treffers is dat per keer een
/// filter, een sortering en een groepering over alles — terwijl je aan het scrollen bent.
///
/// Eén uitkomst onthouden is genoeg: hij is alleen ongeldig als er nieuwe treffers zijn (dan is het
/// een ándere lijst, vandaar [identical] en geen inhoudelijke vergelijking) of als je een ander
/// filter aantikt.
/// Hoe vaak binnenstromende zoekresultaten het scherm opnieuw mogen laten tekenen.
///
/// **Waarom hier een rem op moet.** Soulseek levert zijn treffers in tientallen tot honderden
/// stukjes aan. De laag eronder bundelt die al tot één melding per 300 ms, en elke melding zette
/// tot nu toe rechtstreeks de hele lijst opnieuw: zeven, rangschikken, groeperen, en dan het hele
/// blok opnieuw tekenen. Bij duizenden treffers kost die ronde op een telefoon méér dan 300 ms, dus
/// het scherm liep permanent achter de resultaten aan — en dat is precies wat je voelt als je
/// probeert te scrollen terwijl er gezocht wordt.
///
/// Eén keer per seconde is genoeg om te zien dát er iets binnenkomt. Er gaat niets verloren: de
/// volledige lijst wordt sowieso in één keer gezet zodra de ronde klaar is.
const _tekenRem = Duration(milliseconds: 900);

/// Laat hoogstens één keer per [_tekenRem] iets door, maar de eerste keer altijd meteen.
///
/// Die eerste doorlaat is met opzet: anders blijft het scherm een seconde op "Zoeken…" staan
/// terwijl de treffers er al zijn.
class _Tekenrem {
  DateTime? _vorige;

  bool mag() {
    final nu = DateTime.now();
    if (_vorige != null && nu.difference(_vorige!) < _tekenRem) return false;
    _vorige = nu;
    return true;
  }

  void herbegin() => _vorige = null;
}

class _SlskKlaar {
  final List<SoulseekFile> ruw;
  final QFilter filter;

  /// De overgebleven bestanden, beste eerst. Gaat als kandidatenpoel mee naar elke rij: een
  /// download die bij de eerste peer strandt valt terug op alle andere.
  final List<SoulseekFile> gefilterd;

  /// Diezelfde bestanden als boom: gebruiker → map → nummers.
  final List<SlskGebruiker> gebruikers;

  /// De meest complete map van één peer, voor de knop "Download album" in de kop.
  ///
  /// Die had zijn eigen doorloop over alle treffers (`_bestSoulseekFolder`), met een padsplitsing
  /// per bestand — een tweede keer precies het werk dat [gebruikers] al gedaan heeft. Nu is het een
  /// keuze uit de mappen die er al liggen. Dezelfde regel als voorheen: de meeste nummers wint, en
  /// bij gelijk aantal de peer die nú uitdeelt.
  final List<SoulseekFile> besteMap;

  const _SlskKlaar._(this.ruw, this.filter, this.gefilterd, this.gebruikers, this.besteMap,
      this.passend, this.vraag, this.besteDekking, this.rangen, this.zeef);

  /// De rangen die voor deze ronde al uitgerekend zijn, om aan de volgende door te geven.
  ///
  /// Tijdens één zoekopdracht groeit de lijst in stukjes, en tot nu toe werd bij elk stukje de rang
  /// van élk bestand opnieuw bepaald — inclusief de bestanden die er de vorige keer ook al in
  /// zaten. Dat is het werk dat het scrollen deed haperen. Nu kost een stukje alleen nog de rang
  /// van wat er nieuw bij kwam.
  final Map<SoulseekFile, int> rangen;

  /// Wat de ZEEF van elk bestand vond: hoort het bij de vraag, ja of nee.
  ///
  /// **De rangen kregen dit geheugen wel en de zeef niet.** [volslagenAnders] roept [vraagScore]
  /// aan, en die doet drie keer `fileWords` plus een `baseName` — per bestand. Bij elk stukje dat
  /// binnenkwam liep dat opnieuw over ÁLLE ruwe treffers, ook over de honderden die er de vorige
  /// keer ook al in zaten. Dat is precies het werk waar de rangen twee regels hierboven al vanaf
  /// geholpen zijn.
  ///
  /// Alleen de vraag-helft zit erin, NIET het filter. Dat filter kun je aanpassen terwijl je vraag
  /// gelijk blijft — een kwaliteitsknop omzetten — en dan zou een onthouden uitkomst hem doodleggen.
  /// Het filter is bovendien goedkoop: een paar veldvergelijkingen.
  final Map<SoulseekFile, bool> zeef;

  /// Die rangen en die zeefuitslag, maar alleen als ze voor deze nieuwe lijst nog gelden.
  ///
  /// Alleen bij dezelfde vraag (de vraag zit ín allebei) en bij een lijst die alleen maar gegroeid
  /// is. Wordt de lijst korter, dan is er een nieuwe zoekopdracht begonnen en beginnen we schoon —
  /// anders blijft het geheugen van elke zoekopdracht van vandaag hangen.
  ({Map<SoulseekFile, int> rangen, Map<SoulseekFile, bool> zeef})? hergebruikVoor(
          List<SoulseekFile> nieuw, String? v) =>
      v == vraag && nieuw.length >= ruw.length ? (rangen: rangen, zeef: zeef) : null;

  /// Welke bestanden echt het gevraagde nummer zijn — leeg als er geen uitgave bekend is.
  ///
  /// Zie [_pastBonus]: die staan bovenaan, hoe goed de rest ook is.
  final Set<SoulseekFile> passend;

  /// [vraag] is de tekst die de gebruiker LETTERLIJK intikte, en alleen bij direct zoeken gevuld.
  ///
  /// Daar zat tot nu toe geen enkele zeef tussen de bronnen en het scherm, en de volgorde keek
  /// alleen naar geluidskwaliteit: wat je typte kwam in de rangschikking helemaal niet voor. Met
  /// [vraag] erbij gaat wat je vroeg vóór, en valt wat er niets mee te maken heeft weg. Zie
  /// [vraagScore] en [volslagenAnders].
  factory _SlskKlaar.van(List<SoulseekFile> ruw, QFilter filter,
      {bool Function(SoulseekFile)? past,
      String? vraag,
      ({Map<SoulseekFile, int> rangen, Map<SoulseekFile, bool> zeef})? hergebruik}) {
    // De rang van een bestand wordt hier één keer uitgerekend en daarna hergebruikt, door zowel de
    // rangschikking als de groepering. Zie [rangschikSoulseek] voor waarom dat het verschil maakt.
    // Met [hergebruik] loopt dat geheugen door over de stukjes van één zoekopdracht heen — zie
    // [hergebruikVoor].
    final onthouden = hergebruik?.rangen ?? Map<SoulseekFile, int>.identity();
    final zeefUitslag = hergebruik?.zeef ?? Map<SoulseekFile, bool>.identity();
    final passend = Set<SoulseekFile>.identity();
    // Wat je vroeg gaat vóór wat goed klinkt. Twintig treden, zodat "alles in de bestandsnaam"
    // ruim boven "alleen de artiest in de mapnaam" staat en de kwaliteit binnen één trede beslist.
    int bonus(SoulseekFile f) => vraag == null
        ? 0
        : (vraagScore(vraag, f.filename) * 20).round() * _dekkingStap +
            (reeksScore(vraag, f.filename) * 10).round() * _reeksStap;
    int rang(SoulseekFile f) =>
        onthouden[f] ??= _slskRang(f) + (passend.contains(f) ? _pastBonus : 0) + bonus(f);

    // Score nul betekent: geen enkel woord uit je vraag komt ergens in dit pad voor. Bij Soulseek
    // kan dat niet van een echte treffer komen — de server eist elk woord ergens in het pad — dus
    // dit is de ruis van de jokervariant `*ain` voor "Rain". Zie [volslagenAnders].
    // Het filter ELKE keer opnieuw, de vraag maar één keer per bestand. Zie [zeef] voor waarom die
    // twee niet samen in het geheugen mogen: het filter verandert terwijl de vraag gelijk blijft.
    bool hoortBijDeVraag(SoulseekFile f) =>
        vraag == null || (zeefUitslag[f] ??= !volslagenAnders(vraag, f.filename));
    final over =
        ruw.where((f) => _filterLaatDoor(filter, f) && hoortBijDeVraag(f)).toList();
    if (past != null) {
      for (final f in over) {
        if (past(f)) passend.add(f);
      }
    }
    final gefilterd = rangschikSoulseek(over, rang: rang);
    final gebruikers = groepeerSoulseek(gefilterd, rang: rang);

    List<SoulseekFile> beste = const [];
    var meeste = 0;
    var besteVrij = false;
    for (final g in gebruikers) {
      for (final m in g.mappen) {
        if (m.aantal > meeste || (m.aantal == meeste && g.vrij && !besteVrij)) {
          beste = m.nummers;
          meeste = m.aantal;
          besteVrij = g.vrij;
        }
      }
    }
    // De bovenste is per definitie de best dekkende — daar is de rangschikking op gebouwd.
    final dekking = vraag == null || gefilterd.isEmpty
        ? -1
        : gedekteWoorden(vraag, gefilterd.first.filename);
    return _SlskKlaar._(ruw, filter, gefilterd, gebruikers, beste, passend, vraag, dekking,
        onthouden, zeefUitslag);
  }

  /// De vraag waarop dit gebaseerd is, zodat het geheugen ongeldig wordt als je iets anders typt.
  final String? vraag;

  /// Hoeveel van je getypte woorden de BESTE treffer dekt. -1 als er geen vraag is.
  ///
  /// Dit is het getal dat op het scherm hoort. Zonder dat moet je zelf bestandsnamen ontcijferen om
  /// te zien dat de bovenste treffer maar drie van je vier woorden heeft — en dan zoek je door
  /// terwijl je denkt dat je gevonden hebt.
  final int besteDekking;

  bool geldigVoor(List<SoulseekFile> r, QFilter f, String? v) =>
      identical(r, ruw) && f == filter && v == vraag;
}

/// Of dit bestand door het gekozen kwaliteitsfilter komt.
bool _filterLaatDoor(QFilter filter, SoulseekFile f) =>
    filter == QFilter.all || filter.matches(_slskQuality(f));

/// Hoeveel gebruikers er standaard opengeklapt staan.
///
/// Niet nul: een scherm vol dichte namen is nog steeds niets waar je uit kunt maken wat er te halen
/// valt. Niet alles: de rijen worden gretig gebouwd (zie [bronStap]), en van zevenduizend
/// treffers alles tegelijk tekenen zet de app vast. Drie is waar het beste resultaat meteen te zien
/// is terwijl er hooguit een paar tientallen rijen staan.
const _slskOpenVanZelf = 3;

/// De Soulseek-treffers als boom: gebruiker → eventueel album → de liedjes.
///
/// **Waarom niet meer één platte lijst.** Er stonden zevenduizend losse regels onder elkaar, met
/// dezelfde gebruiker twintig keer, zijn naam op elke regel opnieuw, en zonder enige aanwijzing dat
/// vijf van die regels bij één album van één persoon horen. Het Soulseek-programma zelf toont het
/// als een boom, en dat is niet toevallig: bij P2P kies je een BRON, niet een bestand — wat die
/// bron verder heeft en of hij een plek vrij heeft, bepaalt of je het ooit krijgt.
///
/// **Waarom een widget met eigen staat.** Wat opengeklapt is en hoeveel gebruikers er getoond
/// worden, hoort bij deze lijst en niet bij het scherm eromheen. Beide schermen die hem gebruiken
/// (het bronnenpaneel van een album en het losse zoekscherm) krijgen daarmee vanzelf dezelfde
/// lijst, zonder dat ze allebei hun eigen teller moeten bijhouden.
class _SoulseekGroepen extends StatefulWidget {
  /// De boom, al gerangschikt. Komt uit [_SlskKlaar], dat hem onthoudt tussen twee keer tekenen.
  final List<SlskGebruiker> gebruikers;

  /// Alle overgebleven bestanden, als kandidatenpoel voor een download die bij één peer strandt.
  final List<SoulseekFile> slsk;

  /// De bestanden die bewijsbaar het gevraagde nummer zijn. Leeg als er geen uitgave bekend is.
  final Set<SoulseekFile> passend;

  /// Wat er op het groene merkje staat. Op een albumpagina "dit nummer"; bij direct zoeken slaat
  /// het op de getypte tekst en niet op een nummer, dus dan hoort er iets anders te staan.
  final String pastMerk;

  /// De zoekterm. Wisselt die, dan klapt alles weer dicht en begint het venster opnieuw — anders
  /// zou een nieuwe zoekopdracht de openstand van de vorige erven.
  final String sleutel;

  final TrackTags? authority;

  /// Voor de "Download album"-knop per map; komt van de albumpagina waar dit paneel onder hangt.
  final ReleaseAuthority? uitgave;

  /// Waar de open- en dichtstand bewaard blijft, als hij een schermwissel moet overleven.
  ///
  /// Bij direct zoeken wijzen deze naar [ZoekGeheugen]: wie naar de speler loopt en terugkomt, vindt
  /// dezelfde gebruiker nog opengeklapt. Op een albumpagina blijft dit null — die pagina staat op de
  /// navigator en wordt sowieso niet weggegooid, dus daar valt niets te bewaren.
  final Set<String>? open;
  final Set<String>? dicht;

  const _SoulseekGroepen(
      {required this.gebruikers,
      required this.slsk,
      required this.passend,
      required this.sleutel,
      this.pastMerk = 'dit nummer',
      this.authority,
      this.uitgave,
      this.open,
      this.dicht});

  @override
  State<_SoulseekGroepen> createState() => _SoulseekGroepenState();
}

class _SoulseekGroepenState extends State<_SoulseekGroepen> {
  /// Hoeveel GEBRUIKERS er nu getoond worden — niet hoeveel bestanden. Door het groeperen zakt een
  /// resultaat van zevenduizend bestanden meestal naar een paar honderd bronnen, en dan is er in de
  /// praktijk geen tik meer nodig.
  int _limiet = bronStap;

  /// Wie de gebruiker zelf heeft opengeklapt, en wie hij heeft dichtgeklapt. Twee verzamelingen en
  /// geen enkele `bool`: de eerste [_slskOpenVanZelf] staan vanzelf open, en die moeten óók dicht
  /// kunnen — met één verzameling was "niet opengeklapt" niet te onderscheiden van "dichtgeklapt".
  ///
  /// Krijgt dit paneel er twee mee, dan zijn dat DEZELFDE verzamelingen als in [ZoekGeheugen] — niet
  /// een kopie. Wat je hier openklapt staat daarmee meteen ook in het geheugen, zonder dat er ergens
  /// een moment van wegschrijven bedacht hoeft te worden.
  late final Set<String> _open = widget.open ?? <String>{};
  late final Set<String> _dicht = widget.dicht ?? <String>{};

  @override
  void didUpdateWidget(_SoulseekGroepen oud) {
    super.didUpdateWidget(oud);
    if (oud.sleutel != widget.sleutel) {
      _limiet = bronStap;
      _open.clear();
      _dicht.clear();
    }
  }

  bool _staatOpen(int i, String naam) =>
      _open.contains(naam) || (i < _slskOpenVanZelf && !_dicht.contains(naam));

  void _klap(int i, String naam) {
    setState(() {
      if (_staatOpen(i, naam)) {
        _open.remove(naam);
        _dicht.add(naam);
      } else {
        _dicht.remove(naam);
        _open.add(naam);
      }
    });
  }

  @override
  Widget build(BuildContext context) {
    final gebruikers = widget.gebruikers;
    final venster = bronVenster(gebruikers.length, _limiet);
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        for (var i = 0; i < venster.tot; i++) ..._gebruikerRijen(i, gebruikers[i]),
        if (venster.rest > 0)
          Padding(
            padding: const EdgeInsets.fromLTRB(24, 10, 24, 16),
            // Gevouwen, want naast elkaar is dit breder dan een telefoon.
            child: Wrap(
              crossAxisAlignment: WrapCrossAlignment.center,
              spacing: 12,
              runSpacing: 8,
              children: [
                FilledButton.icon(
                  style: FilledButton.styleFrom(
                    backgroundColor: _panel2,
                    foregroundColor: Colors.white,
                    padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 12),
                  ),
                  onPressed: () => setState(() => _limiet += bronStap),
                  icon: const Icon(Icons.expand_more_rounded, size: 19),
                  label: Text('Nog ${venster.volgende} tonen'),
                ),
                Text('nog ${venster.rest} bronnen · de beste staan bovenaan',
                    style: const TextStyle(color: _muted, fontSize: 12)),
              ],
            ),
          ),
      ],
    );
  }

  List<Widget> _gebruikerRijen(int i, SlskGebruiker g) {
    final open = _staatOpen(i, g.naam);
    final rijen = <Widget>[_gebruikerKop(g, open, () => _klap(i, g.naam))];
    if (!open) return rijen;
    // Eén map met één nummer: geen albumkop, want er is geen album. "Gebruiker, EVENTUEEL album,
    // en daar de liedjes." Een kop boven één regel is geen indeling maar ruis.
    if (g.losNummer) {
      rijen.add(_nummer(g.mappen.first.nummers.first));
      return rijen;
    }
    for (final m in g.mappen) {
      rijen.add(_mapKop(m));
      rijen.addAll(m.nummers.map(_nummer));
    }
    return rijen;
  }

  /// De kop van een gebruiker: wie het is, hoeveel hij heeft, en of hij nú uitdeelt.
  Widget _gebruikerKop(SlskGebruiker g, bool open, VoidCallback klap) => RepaintBoundary(
        child: Padding(
        padding: const EdgeInsets.fromLTRB(20, 6, 20, 1),
        child: Material(
          color: _panel2,
          borderRadius: BorderRadius.circular(8),
          child: InkWell(
            onTap: klap,
            borderRadius: BorderRadius.circular(8),
            child: Padding(
              padding: const EdgeInsets.fromLTRB(12, 10, 12, 10),
              child: Row(
                children: [
                  Icon(open ? Icons.expand_more_rounded : Icons.chevron_right_rounded,
                      size: 20, color: _muted),
                  const SizedBox(width: 6),
                  Icon(g.vrij ? Icons.circle : Icons.schedule_rounded,
                      size: 10, color: g.vrij ? _accent2 : _muted),
                  const SizedBox(width: 8),
                  Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text(g.naam,
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                            style: const TextStyle(fontWeight: FontWeight.w700)),
                        const SizedBox(height: 2),
                        Text(
                            '${g.vrij ? "vrij" : "wachtrij ${g.wachtrij}"} · '
                            '${g.aantal} ${g.aantal == 1 ? "nummer" : "nummers"}'
                            '${g.mappen.length > 1 ? " in ${g.mappen.length} mappen" : ""} · '
                            '${_fmtBytes(g.totaal)}',
                            maxLines: 2,
                            style: const TextStyle(color: _muted, fontSize: 12)),
                      ],
                    ),
                  ),
                  const SizedBox(width: 8),
                  // Het keurmerk van zijn BESTE bestand. Dat is waar je op kiest zonder open te
                  // klappen, en het is ook waarop deze hele lijst gerangschikt staat.
                  _qualityBadge(_slskQuality(g.beste)),
                ],
              ),
            ),
          ),
        ),
        ),
      );

  /// De albumregel onder een gebruiker, met de knop die de hele map in één keer binnenhaalt.
  Widget _mapKop(SlskMap m) => Padding(
        padding: const EdgeInsets.fromLTRB(34, 8, 20, 2),
        // Gevouwen: een mapnaam plus een knop is op een telefoon breder dan het scherm, en een
        // `Row` die niet past geeft de gele overloopbalk die geen enkele toets ziet.
        child: Wrap(
          crossAxisAlignment: WrapCrossAlignment.center,
          spacing: 10,
          runSpacing: 2,
          children: [
            const Icon(Icons.folder_rounded, size: 15, color: _muted),
            ConstrainedBox(
              constraints: const BoxConstraints(maxWidth: 260),
              child: Text(m.naam.isEmpty ? 'losse nummers' : m.naam,
                  maxLines: 2,
                  overflow: TextOverflow.ellipsis,
                  style: const TextStyle(fontSize: 12.5, fontWeight: FontWeight.w600)),
            ),
            Text('${m.aantal} · ${_fmtBytes(m.totaal)}',
                style: const TextStyle(color: _muted, fontSize: 12)),
            if (m.aantal >= 2)
              TextButton.icon(
                // De volledige lijst gaat als kandidatenpoel mee: een download die bij deze peer
                // strandt valt terug op alle andere, niet alleen op wat er in deze map staat.
                onPressed: () => _downloadSoulseekAlbum(context, m.nummers, widget.slsk,
                    authority: widget.uitgave),
                icon: const Icon(Icons.library_add_rounded, size: 15),
                label: Text('Album (${m.aantal})'),
                style: TextButton.styleFrom(
                    foregroundColor: _accent,
                    padding: const EdgeInsets.symmetric(horizontal: 8),
                    visualDensity: VisualDensity.compact),
              ),
          ],
        ),
      );

  /// Eén nummer, ingesprongen onder zijn gebruiker. De volledige lijst gaat als kandidatenpoel mee,
  /// ook wat niet getoond wordt — zie [_slskCandidates].
  Widget _nummer(SoulseekFile f) => _soulseekTile(context, f, widget.slsk,
      authority: widget.authority,
      toonGebruiker: false,
      past: widget.passend.contains(f),
      pastMerk: widget.pastMerk,
      marge: const EdgeInsets.fromLTRB(34, 1, 20, 1));
}

class OnlineSearchScreen extends StatefulWidget {
  const OnlineSearchScreen({super.key});
  @override
  State<OnlineSearchScreen> createState() => _OnlineSearchScreenState();
}

class _OnlineSearchScreenState extends State<OnlineSearchScreen> {
  final _c = TextEditingController();

  /// Skipped when arrowing on a television, for the same reason as the library search: focus opens
  /// the leanback keyboard, and the keyboard then swallows every arrow press — so the whole tab
  /// below it becomes unreachable. OK on the field is what opens it.
  final _searchFocus = FocusNode(skipTraversal: isTv, debugLabel: 'online search');
  final _catalog = CatalogService();
  // Elk veld hieronder begint bij wat er de vorige keer stond — zie [ZoekGeheugen]. Zonder dat
  // opende dit scherm na elke sectiewissel leeg, en moest je "rihanna" opnieuw intikken en opnieuw
  // afwachten omdat je even naar de speler was.
  int _mode = ZoekGeheugen.tab; // 0 = Bladeren, 1 = Direct, 2 = TIDAL
  // browse (artists + albums + tracks)
  List<CatalogArtist> _artists = ZoekGeheugen.artiesten;
  List<CatalogAlbumHit> _albumHits = ZoekGeheugen.albums;
  List<CatalogTrackHit> _trackHits = ZoekGeheugen.nummers;
  bool _browseBusy = false;
  int? _trackExpanded = ZoekGeheugen.nummerOpen;
  // direct
  List<SearchResult> _torrents = ZoekGeheugen.torrents;
  List<SoulseekFile> _slsk = ZoekGeheugen.slsk;

  /// Bewust NIET onthouden. Een molentje dat blijft draaien voor een zoekopdracht die allang klaar
  /// is, is erger dan geen molentje — en of er nog iets loopt weet dit scherm na een wissel niet.
  bool _busy = false, _slskBusy = false;

  /// Zie [_tekenRem]: één per bron, zodat torrents en Soulseek elkaar niet in de weg zitten.
  final _slskRem = _Tekenrem(), _torrentRem = _Tekenrem();

  /// Wat er letterlijk getypt is bij direct zoeken. Zie [_SlskKlaar.vraag]: dit is het enige wat
  /// dit scherm heeft om "past dit bij wat ik zocht?" mee te beantwoorden.
  String? _getypt = ZoekGeheugen.getypt;

  /// De vraag waarop Soulseek uiteindelijk gezocht heeft — zie [zoekLadder]. Wijkt hij af van
  /// [_getypt], dan hoort dat erbij te staan; anders sta je naar een ander nummer te kijken.
  String? _gezochtDirect = ZoekGeheugen.gezochtDirect;

  String? _status = ZoekGeheugen.status;
  QFilter _filter = ZoekGeheugen.filter;

  /// Op welke bron gezeefd wordt, of null voor alles. Zie [bronnenInResultaten].
  ///
  /// Niet in [ZoekGeheugen], en dat is met opzet: de kwaliteitskeuze geldt voor élke zoekopdracht
  /// ("ik wil lossless"), maar een bron kiezen is iets wat je bij één lijst doet. Zou hij blijven
  /// staan, dan kom je bij de volgende zoekopdracht terug op een lijst die stilletjes ingekort is.
  String? _bron;
  // tidal
  List<TidalTrack> _tidalTracks = ZoekGeheugen.tidalNummers;
  List<TidalAlbum> _tidalAlbums = ZoekGeheugen.tidalAlbums;
  bool _tidalBusy = false, _tidalConnecting = false;
  int? _tidalExpanded = ZoekGeheugen.tidalNummerOpen,
      _tidalAlbumExpanded = ZoekGeheugen.tidalAlbumOpen;

  @override
  void initState() {
    super.initState();
    _c.text = ZoekGeheugen.vraag;
  }

  Future<void> _search() async {
    final q = _c.text.trim();
    if (q.isEmpty) return;
    if (_mode == 0) {
      await _searchBrowse(q);
    } else if (_mode == 1) {
      await _searchDirect(q);
    } else {
      await _searchTidal(q);
    }
  }

  Future<void> _searchTidal(String q) async {
    final tidal = context.read<TidalService>();
    if (!tidal.connected) return;
    final gen = ZoekGeheugen.nieuweRonde();
    bool geldig() => ZoekGeheugen.geldig(gen);
    setState(() {
      _tidalBusy = true;
      _tidalTracks = [];
      _tidalAlbums = [];
      _tidalExpanded = null;
      _tidalAlbumExpanded = null;
      _status = null;
    });
    ZoekGeheugen.tidalNummers = const [];
    ZoekGeheugen.tidalAlbums = const [];
    ZoekGeheugen.tidalNummerOpen = null;
    ZoekGeheugen.tidalAlbumOpen = null;
    ZoekGeheugen.status = null;
    try {
      final r = await tidal.search(q);
      if (!geldig()) return;
      _tidalAlbums = r.albums;
      _tidalTracks = r.tracks;
      _status = r.leeg ? 'Geen TIDAL-resultaten.' : null;
      ZoekGeheugen.tidalAlbums = _tidalAlbums;
      ZoekGeheugen.tidalNummers = _tidalTracks;
      ZoekGeheugen.status = _status;
      if (mounted) setState(() {});
    } catch (e) {
      if (!geldig()) return;
      _status = 'TIDAL-zoeken mislukt: $e';
      ZoekGeheugen.status = _status;
      if (mounted) setState(() {});
    } finally {
      if (geldig() && mounted) setState(() => _tidalBusy = false);
    }
  }

  Future<void> _connectTidal() async {
    final tidal = context.read<TidalService>();
    setState(() => _tidalConnecting = true);
    try {
      await tidal.login();
      if (mounted) _srcToast(context, 'TIDAL verbonden ✓');
    } catch (e) {
      if (mounted) _srcToast(context, 'TIDAL-login mislukt: $e');
    } finally {
      if (mounted) setState(() => _tidalConnecting = false);
    }
  }

  Future<void> _manualTidal() async {
    final tidal = context.read<TidalService>();

    // Eerst het klembord zelf lezen, en pas als daar niets bruikbaars in staat een tekstvak tonen.
    //
    // **Waarom.** Je hebt dat adres net gekopieerd — het staat al op je klembord. Er is dus geen
    // reden om jou te laten plakken in een veld dat vierhonderd tekens moet slikken. Dat scheelt
    // een handeling, en het omzeilt de plek waar het inloggen vastliep: precies op het moment van
    // plakken, nog vóór er ook maar één regel van dit inlogwerk draaide. Wat daar misgaat weet ik
    // nog niet; deze weg komt er niet langs.
    try {
      final klembord = await Clipboard.getData(Clipboard.kTextPlain);
      final tekst = klembord?.text ?? '';
      if (tekst.isNotEmpty && TidalService.extractCode(tekst) != null) {
        await _verbindMetGeplakt(tidal, tekst);
        return;
      }
    } catch (_) {/* geen klembord? dan gewoon het venster hieronder */}

    final ctrl = TextEditingController();
    final pasted = await showDialog<String>(
      context: context,
      builder: (_) => AlertDialog(
        backgroundColor: _panel,
        title: const Text('Adres uit je browser plakken', style: kKopKlein),
        content: SizedBox(
          width: dialogWidth(context, 460),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              const Text('Plak het hele adres waar je browser op uitkwam — dat begint met '
                  'https://tidal.com/?code= en is lang. Enkel de code mag ook.',
                  style: kTekstKlein),
              const SizedBox(height: 10),
              TextField(
                controller: ctrl,
                autofocus: !isTv,
                style: const TextStyle(fontSize: 13),
                decoration: InputDecoration(
                  isDense: true,
                  filled: true,
                  fillColor: kVerzonken,
                  border: OutlineInputBorder(borderRadius: BorderRadius.circular(9), borderSide: const BorderSide(color: _line)),
                  enabledBorder: OutlineInputBorder(borderRadius: BorderRadius.circular(9), borderSide: const BorderSide(color: _line)),
                ),
              ),
            ],
          ),
        ),
        actions: [
          TextButton(onPressed: () => Navigator.pop(context), child: const Text('Annuleren')),
          FilledButton(
            style: FilledButton.styleFrom(backgroundColor: _accent),
            onPressed: () => Navigator.pop(context, ctrl.text.trim()),
            child: const Text('Verbind'),
          ),
        ],
      ),
    );
    // Bewust NIET ctrl.dispose() hier: het venster is aan het wegschuiven en zijn TextField leeft
    // nog een paar beelden door. Een controller die dan al opgeruimd is gooit tijdens het tekenen,
    // en dan verdwijnt de halve pagina — erger dan één controller die blijft hangen in een venster
    // dat je één keer in je leven opent.
    if (pasted == null || pasted.isEmpty) return;
    await _verbindMetGeplakt(tidal, pasted);
  }

  /// De code inwisselen, of het nu uit het klembord kwam of uit het tekstvak.
  Future<void> _verbindMetGeplakt(TidalService tidal, String tekst) async {
    setState(() => _tidalConnecting = true);
    try {
      await tidal.completeManual(tekst);
      if (mounted) _srcToast(context, 'TIDAL verbonden ✓');
    } catch (e) {
      // In een venster en niet als toast: het antwoord van TIDAL is meerdere regels en zegt wélk
      // stuk niet klopte. Dat in twee seconden laten wegglijden is precies waardoor deze fout
      // vanmorgen niet te onderzoeken was.
      if (mounted) await _toonFout(context, 'Verbinden met TIDAL mislukt', '$e');
    } finally {
      if (mounted) setState(() => _tidalConnecting = false);
    }
  }

  /// Eén resultaat uit de TIDAL-lijst binnenhalen met tiddl.
  ///
  /// Hetzelfde venster als "Ophalen van Tidal…" bij Mijn downloads, alleen met het doel al
  /// ingevuld: er valt hier niets meer te plakken. Daarna dezelfde scan, want het bestand staat dan
  /// in de muziekmap en moet nog gevonden worden.
  Future<void> _ophalenVanTidal(String? doel, String naam) async {
    if (doel == null) {
      // Kan alleen als TIDAL een id teruggeeft dat niet op een id lijkt. Beter een zin dan een
      // proces starten om een fout te ontdekken die hier al zichtbaar was.
      _srcToast(context, 'Dit resultaat heeft geen bruikbaar Tidal-id.');
      return;
    }
    final kwaliteit = await showDialog<String>(
        context: context, builder: (_) => _TidalOphalen(doel: doel, titel: naam));
    if (kwaliteit == null || !mounted) return;
    _srcToast(context, opgehaaldMelding(kwaliteit));
    unawaited(context.read<LibraryStore>().scan());
  }

  /// Append what Discogs has that Deezer does not.
  ///
  /// Deezer catalogues what streams and is the faster, cleaner search, so it stays first and the
  /// list is usable before Discogs answers at all. Discogs is where the editions, the promos and
  /// the regional issues live — the versions Deezer has no entry for.
  ///
  /// Deduped on artist + title, so the same record never appears twice; a different EDITION of it
  /// carries a different title and still comes through, which is the whole reason to add it.
  /// [geldig] in plaats van `mounted`: deze aanvulling hoort ook binnen te komen als je intussen naar
  /// de speler bent, want de lijst wordt bewaard — zie [ZoekGeheugen].
  Future<void> _addDiscogsAlbums(String q, bool Function() geldig) async {
    try {
      final extra = await DiscogsService(context.read<AppSettings>()).searchAlbums(q);
      if (!geldig() || extra.isEmpty) return;
      String key(CatalogAlbumHit h) => '${artistKey(h.artist)}|${normKey(h.album.title)}';
      final seen = {for (final h in _albumHits) key(h)};
      final add = [
        for (final h in extra)
          if (seen.add(key(h))) h
      ];
      if (add.isEmpty) return;
      _albumHits = [..._albumHits, ...add];
      _status = null;
      _onthoudBladeren();
      if (mounted) setState(() {});
    } catch (_) {/* Deezer on its own is still a working search */}
  }

  /// Add what MusicBrainz knows: albums, tracks and artists.
  ///
  /// Runs AFTER Deezer, never inside its Future.wait — MusicBrainz spaces its requests 1100 ms
  /// apart, and putting it in the same wait would hold the fast results hostage to the slow one.
  ///
  /// Every query is scoped to an artist first. MusicBrainz ranks on text alone with no popularity
  /// signal at all: bare "thriller" returns Part Chimp and Swoop before Michael Jackson, and bare
  /// "quit playing games" returns Mar.Ko before the Backstreet Boys. Scoped, both are exact.
  Future<void> _addMusicBrainzHits(String q, bool Function() geldig) async {
    final mb = context.read<MusicBrainzService>();
    try {
      // "Artist - Album" first, then the whole query as an artist name, then whatever the Deezer
      // pass already decided the artist was. Any of the three gives the scoping that makes this work.
      var artist = '', rest = q.trim();
      final dash = q.indexOf(' - ');
      if (dash > 0) {
        artist = q.substring(0, dash).trim();
        rest = q.substring(dash + 3).trim();
      } else if (_artists.isNotEmpty) {
        artist = _artists.first.name;
      }

      final found = await mb.searchArtists(q, max: 8);
      if (!geldig()) return;
      if (found.isNotEmpty) {
        final have = {for (final a in _artists) artistKey(a.name)};
        final add = [
          for (final a in found)
            if (have.add(artistKey(a.name)))
              CatalogArtist(0, a.name, null, 0,
                  origin: CatalogRef.musicbrainz(a.mbid), detail: a.line)
        ];
        if (add.isNotEmpty) {
          _artists = [..._artists, ...add];
          _onthoudBladeren();
          if (mounted) setState(() {});
        }
        if (artist.isEmpty) artist = found.first.name;
      }

      // Records, not pressings — otherwise twenty CDs of one album are twenty cards.
      final groups = await mb.searchReleaseGroups(rest, artist: artist);
      if (!geldig()) return;
      if (groups.isNotEmpty) {
        final have = {
          for (final h in _albumHits) '${artistKey(h.artist)}|${normKey(h.album.title)}'
        };
        final add = <CatalogAlbumHit>[];
        for (final g in groups) {
          if (!have.add('${artistKey(g.artist)}|${normKey(g.title)}')) continue;
          add.add(CatalogAlbumHit(
            CatalogAlbum(0, g.title, null, g.firstDate, 0,
                g.primaryType.toLowerCase().isEmpty ? 'album' : g.primaryType.toLowerCase(),
                // A GROUP, not a release. Opening it resolves a pressing first — only a pressing
                // has a tracklist, and handing a group id to the release endpoint loads nothing.
                origin: CatalogRef.musicbrainzGroup(g.mbid)),
            g.artist,
          ));
          if (add.length >= 12) break;
        }
        if (add.isNotEmpty) {
          _albumHits = [..._albumHits, ...add];
          _onthoudBladeren();
          if (mounted) setState(() {});
        }
      }

      final recs = await mb.searchRecordings(rest, artist: artist);
      if (!geldig() || recs.isEmpty) return;
      // MusicBrainz returns one row per release a recording appears on, so a popular song comes
      // back twenty-five times. Without this the track list is one title repeated.
      final have = {for (final t in _trackHits) '${artistKey(t.artist)}|${normKey(t.title)}'};
      final add = [
        for (final r in recs)
          if (have.add('${artistKey(r.artist)}|${normKey(r.title)}'))
            CatalogTrackHit(r.title, r.artist, null)
      ];
      if (add.isNotEmpty) {
        _trackHits = [..._trackHits, ...add.take(12)];
        _onthoudBladeren();
        if (mounted) setState(() {});
      }
    } catch (_) {/* Deezer and Discogs on their own are still a working search */}
  }

  /// Waarom er niets gevonden is — als er een betere reden voor is dan "het bestaat niet".
  ///
  /// **Waarom dit nodig is.** Een time-out, een geweigerd verzoek, een storing bij Discogs en een
  /// zoekterm die werkelijk nergens voorkomt geven hier allemaal een lege lijst, en dus allemaal
  /// "Niets gevonden." Zonder Discogs-token faalt daar bovendien élke aanroep stil. Dat is precies
  /// de reden dat taggen "soms niet lukt" zonder dat er iets te onderzoeken valt: het scherm zegt
  /// dat de plaat niet bestaat, terwijl er in werkelijkheid niemand geantwoord heeft.
  ///
  /// De tellers waren er al — `transportErrors` telt op beide diensten alles wat GEEN 404 is, juist
  /// om dit onderscheid mogelijk te maken. Ze werden hier alleen niet gelezen.
  String? _waaromLeeg(int dgVoor, int mbVoor) {
    final dgStuk = DiscogsService.transportErrors > dgVoor;
    final mbStuk = MusicBrainzService.transportErrors > mbVoor;
    if (dgStuk && mbStuk) {
      return 'Geen van de catalogi antwoordde. Dat is iets anders dan "niet gevonden" — '
          'controleer je verbinding en probeer het zo nog eens.';
    }
    if (dgStuk) {
      return 'Discogs antwoordde niet: een time-out, te veel verzoeken achter elkaar, of een '
          'storing daar. Wat je zoekt kan er dus wél zijn.';
    }
    if (mbStuk) {
      return 'MusicBrainz antwoordde niet. Wat je zoekt kan er dus wél zijn; probeer het zo nog '
          'eens.';
    }
    if (context.read<AppSettings>().discogsToken.trim().isEmpty) {
      return 'Niets gevonden — maar er is ook geen Discogs-token ingevuld, dus er is alleen bij '
          'Deezer en MusicBrainz gekeken. Discogs kent juist de persingen en verzamelaars.';
    }
    return null;
  }

  Future<void> _searchBrowse(String q) async {
    // Zelfde volgnummer als bij direct zoeken — één zoekveld, één lopende vraag. Zie [ZoekGeheugen].
    final gen = ZoekGeheugen.nieuweRonde();
    bool geldig() => ZoekGeheugen.geldig(gen);
    setState(() {
      _browseBusy = true;
      _artists = [];
      _albumHits = [];
      _trackHits = [];
      _trackExpanded = null;
      _status = null;
    });
    ZoekGeheugen.artiesten = const [];
    ZoekGeheugen.albums = const [];
    ZoekGeheugen.nummers = const [];
    ZoekGeheugen.nummerOpen = null;
    ZoekGeheugen.status = null;
    // Vóór het zoeken opnemen, want deze tellers zijn statisch en lopen ook door van andere
    // zoekopdrachten. Alleen het VERSCHIL over deze zoekopdracht zegt iets.
    final dgVoor = DiscogsService.transportErrors;
    final mbVoor = MusicBrainzService.transportErrors;
    try {
      final res = await Future.wait([
        _catalog.searchArtists(q),
        _catalog.searchAlbums(q),
        _catalog.searchTracks(q),
      ]);
      if (!geldig()) return;
      _artists = res[0] as List<CatalogArtist>;
      _albumHits = res[1] as List<CatalogAlbumHit>;
      _trackHits = res[2] as List<CatalogTrackHit>;
      // Nog geen reden geven: Discogs en MusicBrainz zijn hieronder nog aan het werk, en een
      // oordeel over "waarom leeg" is pas te vellen als iedereen geantwoord heeft.
      _status = (_artists.isEmpty && _albumHits.isEmpty && _trackHits.isEmpty)
          ? 'Niets gevonden.'
          : null;
      _onthoudBladeren();
      if (mounted) setState(() {});
      await _addDiscogsAlbums(q, geldig);
      await _addMusicBrainzHits(q, geldig);
      if (geldig() && _artists.isEmpty && _albumHits.isEmpty && _trackHits.isEmpty) {
        _status = _waaromLeeg(dgVoor, mbVoor) ?? 'Niets gevonden.';
        ZoekGeheugen.status = _status;
        if (mounted) setState(() {});
      }
    } catch (e) {
      if (!geldig()) return;
      _status = 'Zoeken mislukt: $e';
      ZoekGeheugen.status = _status;
      if (mounted) setState(() {});
    } finally {
      if (geldig() && mounted) setState(() => _browseBusy = false);
    }
  }

  /// De drie bladerlijsten en de stand wegschrijven, zodat ze een schermwissel overleven.
  void _onthoudBladeren() {
    ZoekGeheugen.artiesten = _artists;
    ZoekGeheugen.albums = _albumHits;
    ZoekGeheugen.nummers = _trackHits;
    ZoekGeheugen.status = _status;
  }

  Future<void> _searchDirect(String q) async {
    final online = context.read<OnlineService>();
    final soulseek = context.read<SoulseekService>();
    // Het volgnummer staat in [ZoekGeheugen] en niet meer hier. Dat is een reparatie op zichzelf:
    // als veld van dit scherm begon het bij elke sectiewissel weer bij nul, en dan werd een oudere,
    // nog lopende zoekopdracht per ongeluk weer geldig verklaard.
    final gen = ZoekGeheugen.nieuweRonde();
    // ALLEEN over de vraag, niet meer over het scherm. Wie wegloopt naar de speler terwijl Soulseek
    // nog bezig is, kwam vroeger terug bij een leeg scherm: de resultaten kwamen wél binnen, maar
    // `mounted` was onwaar en er was niemand meer die ze aannam. Nu worden ze altijd bewaard en
    // alleen getekend als er iemand kijkt.
    bool geldig() => ZoekGeheugen.geldig(gen);
    setState(() {
      _busy = true;
      _slskBusy = soulseek.available;
      _torrents = [];
      _slsk = [];
      _getypt = q;
      _gezochtDirect = null;
      _status = 'Zoeken…';
    });
    ZoekGeheugen.torrents = const [];
    ZoekGeheugen.slsk = const [];
    ZoekGeheugen.getypt = q;
    ZoekGeheugen.gezochtDirect = null;
    ZoekGeheugen.status = null;
    ZoekGeheugen.slskOpen.clear();
    ZoekGeheugen.slskDicht.clear();
    // Een nieuwe zoekopdracht mag meteen weer iets tonen — zie [_Tekenrem].
    _slskRem.herbegin();
    _torrentRem.herbegin();
    if (soulseek.available) {
      soulseek.search(q, gebruikteVraag: (v) {
        if (!geldig()) return;
        ZoekGeheugen.gezochtDirect = v;
        if (mounted && v != _gezochtDirect) setState(() => _gezochtDirect = v);
      }, onPartial: (p) {
        // Stream results as peers respond — maar geremd, zie [_tekenRem].
        if (!geldig()) return;
        ZoekGeheugen.slsk = p;
        if (mounted && _slskRem.mag()) setState(() => _slsk = p);
      }).then((r) {
        if (!geldig()) return;
        ZoekGeheugen.slsk = r;
        if (mounted) setState(() { _slsk = r; _slskBusy = false; });
      }).catchError((_) {
        if (geldig() && mounted) setState(() => _slskBusy = false);
      });
    }
    try {
      final r = await online.search(q, onPartial: (p) {
        // fast sources show first — de eerste komt er altijd meteen door, zie [_Tekenrem]
        if (!geldig()) return;
        ZoekGeheugen.torrents = p;
        ZoekGeheugen.status = null;
        if (mounted && _torrentRem.mag()) setState(() { _torrents = p; _status = null; });
      });
      if (!geldig()) return;
      ZoekGeheugen.torrents = r;
      ZoekGeheugen.status = null;
      if (mounted) setState(() { _torrents = r; _status = null; });
    } catch (e) {
      if (!geldig()) return;
      ZoekGeheugen.status = 'Torrent-zoeken mislukt: $e';
      if (mounted) setState(() => _status = ZoekGeheugen.status);
    } finally {
      if (geldig() && mounted) setState(() => _busy = false);
    }
  }

  void _setMode(int m) {
    if (m == _mode) return;
    setState(() { _mode = m; _status = null; });
  }

  @override
  void dispose() {
    // De bedieningsstand, niet de resultaten: die schrijven de zoekfuncties zelf al weg, ook als dit
    // scherm er niet meer is. Zie [ZoekGeheugen] en `_searchDirect`.
    ZoekGeheugen.tab = _mode;
    ZoekGeheugen.vraag = _c.text;
    ZoekGeheugen.filter = _filter;
    ZoekGeheugen.nummerOpen = _trackExpanded;
    ZoekGeheugen.tidalNummerOpen = _tidalExpanded;
    ZoekGeheugen.tidalAlbumOpen = _tidalAlbumExpanded;
    _c.dispose();
    _searchFocus.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final soulseekReady = context.read<SoulseekService>().available;
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        const Padding(
          padding: EdgeInsets.fromLTRB(24, 22, 24, 8),
          child: Text('Online zoeken', style: kKop),
        ),
        Padding(
          padding: const EdgeInsets.fromLTRB(24, 0, 24, 10),
          // Wrap en geen Row: drie chips passen op een telefoon van 360 punten net niet naast
          // elkaar, en een overloop is een gele balk op het toestel die geen enkele toets ziet.
          child: Wrap(spacing: 8, runSpacing: 8, children: [
            _modeChip('Bladeren', 0),
            _modeChip('Direct zoeken', 1),
            // Altijd zichtbaar, ook zonder Client ID. Verstoppen zou betekenen dat de chip pas ná
            // een herstart verschijnt: dit scherm luistert niet naar de instellingen. Het paneel
            // eronder legt zelf uit wat er nog ontbreekt — dat stond er al, maar was tot nu toe
            // onbereikbaar omdat deze chip nooit gebouwd werd.
            _modeChip('TIDAL', 2),
          ]),
        ),
        Padding(
          padding: const EdgeInsets.fromLTRB(24, 0, 24, 12),
          child: Row(
            children: [
              Expanded(
                child: MaybePressable(
                  enabled: isTv,
                  onPressed: _searchFocus.requestFocus,
                  borderRadius: BorderRadius.circular(11),
                  child: TextField(
                  controller: _c,
                  focusNode: _searchFocus,
                  onSubmitted: (_) => _search(),
                  decoration: InputDecoration(
                    hintText: _mode == 0
                        ? 'Zoek artiest, album of nummer…'
                        : (_mode == 2 ? 'Zoek in TIDAL…' : 'Artiest, album of nummer…'),
                    filled: true,
                    fillColor: _panel,
                    prefixIcon: const Icon(Icons.search_rounded, size: 20),
                    border: OutlineInputBorder(
                        borderRadius: BorderRadius.circular(11), borderSide: const BorderSide(color: _line)),
                    enabledBorder: OutlineInputBorder(
                        borderRadius: BorderRadius.circular(11), borderSide: const BorderSide(color: _line)),
                  ),
                ),
                ),
              ),
              const SizedBox(width: 10),
              FilledButton(
                style: FilledButton.styleFrom(
                    backgroundColor: _accent, padding: const EdgeInsets.symmetric(horizontal: 22, vertical: 18)),
                // Guarded on a television, disabled everywhere else.
                //
                // Disabling it is right under a mouse — the button greys out and the cursor says
                // so. On a TV it is wrong: a disabled button leaves the traversal order, and while
                // a search runs this was the only thing next to a field that is skipped, so the
                // highlight had nowhere to be. Guarding it on BOTH would have quietly taken the
                // grey away from Windows and the iPad, where nothing was broken.
                onPressed: (!isTv && (_busy || _browseBusy || _tidalBusy))
                    ? null
                    : () {
                        if (_busy || _browseBusy || _tidalBusy) return;
                        _search();
                      },
                autofocus: isTv,
                child: const Text('Zoek'),
              ),
            ],
          ),
        ),
        Consumer<DownloadManager>(
          builder: (_, dm, __) {
            // Wat lóópt eerst, en niet meer dan een handvol.
            //
            // Deze strook stond boven de zoekresultaten en toonde gewoon de eerste vijf uit de
            // lijst. Op een telefoon waren dat vier afgeronde downloads van gisteren, samen een
            // half scherm, en de resultaten begonnen pas daaronder. Draait er niets, dan zijn twee
            // regels genoeg als bewijs dat het gelukt is; de volledige lijst staat in "Mijn
            // downloads".
            final actief = dm.jobs.where((j) => j.busy).toList();
            final rest = dm.jobs.where((j) => !j.busy).toList();
            final recent = [...actief, ...rest].take(actief.isEmpty ? 2 : 5).toList();
            if (recent.isEmpty) return const SizedBox.shrink();
            // GEEN 'later' meer: die rijen laat "Wis afgeronde" sinds kort staan, dus de knop zou
            // hier iets beloven wat niet gebeurt als er alleen zulke rijen zijn.
            final hasFinished =
                dm.jobs.any((j) => j.status == 'done' || j.status == 'failed');
            return Padding(
              padding: const EdgeInsets.fromLTRB(24, 0, 24, 8),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.stretch,
                children: [
                  Row(
                    children: [
                      const Text('DOWNLOADS', style: kOpschrift),
                      const Spacer(),
                      if (hasFinished)
                        TextButton.icon(
                          onPressed: () => dm.clearFinished(),
                          icon: const Icon(Icons.clear_all_rounded, size: 15),
                          label: const Text('Wis afgeronde'),
                          style: TextButton.styleFrom(
                              foregroundColor: _muted,
                              padding: const EdgeInsets.symmetric(horizontal: 8),
                              textStyle: const TextStyle(fontSize: 12)),
                        ),
                    ],
                  ),
                  ...recent
                    .map((j) => Padding(
                          padding: const EdgeInsets.symmetric(vertical: 3),
                          child: Row(
                            children: [
                              Expanded(
                                  child: Column(
                                    crossAxisAlignment: CrossAxisAlignment.start,
                                    mainAxisSize: MainAxisSize.min,
                                    children: [
                                      Text(j.name,
                                          maxLines: 1,
                                          overflow: TextOverflow.ellipsis,
                                          style: kTekstBij.copyWith(color: kTekst)),
                                      if (j.detail != null && j.detail!.isNotEmpty)
                                        Text(j.detail!,
                                            // Zie `_DlRow`: een mislukking mag zijn reden niet
                                            // kwijtraken aan een afkapstreepje.
                                            maxLines: j.status == 'failed' ? 4 : 1,
                                            overflow: TextOverflow.ellipsis,
                                            style: kLabel.copyWith(
                                                fontWeight: FontWeight.w400,
                                                color: j.status == 'failed' ? Colors.red.shade300 : null)),
                                    ],
                                  )),
                              SizedBox(
                                // Zelfde rekensom als bij _DlRow: op 384 dp vreet een balk van 160
                                // plus een label van 70 de titel weg. Hier past het stapelen niet
                                // (dit zijn vijf regels in een zoekscherm), dus krimpt de balk.
                                width: isCompact(context) ? 80 : 160,
                                child: LinearProgressIndicator(
                                  value: j.status == 'done'
                                      ? 1
                                      : (j.status == 'preparing' && j.progress <= 0 ? null : j.progress),
                                  backgroundColor: kLijn,
                                  color: j.status == 'failed'
                                      ? Colors.red
                                      : (j.status == 'done' ? _accent2 : _accent),
                                ),
                              ),
                              const SizedBox(width: 10),
                              SizedBox(
                                width: isCompact(context) ? 62 : 70,
                                child: Text(
                                  j.status == 'done'
                                      ? 'klaar'
                                      : (j.status == 'failed'
                                          ? (j.cancelled ? 'gestopt' : 'mislukt')
                                          : (j.status == 'queued'
                                              ? 'wachtrij'
                                              : (j.status == 'preparing'
                                                  ? (j.progress > 0 ? 'TorBox ${(j.progress * 100).round()}%' : 'voorbereiden')
                                                  : '${(j.progress * 100).round()}%'))),
                                  textAlign: TextAlign.right,
                                  style: kLabel.copyWith(fontWeight: FontWeight.w400),
                                ),
                              ),
                            ],
                          ),
                        )),
                ],
              ),
            );
          },
        ),
        if (_status != null)
          Padding(padding: const EdgeInsets.all(24), child: Text(_status!, style: const TextStyle(color: _muted))),
        Expanded(
            child: _mode == 0
                ? _browseResults()
                : (_mode == 1 ? _directResults(soulseekReady) : _tidalResults())),
      ],
    );
  }

  Widget _tidalResults() {
    final tidal = context.read<TidalService>();
    if (!tidal.configured) {
      return const Center(
        child: Padding(
          padding: EdgeInsets.all(24),
          child: Text('Stel je TIDAL Client ID + Secret in via Instellingen (⚙) om TIDAL te gebruiken.',
              textAlign: TextAlign.center, style: TextStyle(color: _muted)),
        ),
      );
    }
    if (!tidal.connected) {
      return Center(
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            // Twee stappen, en de tweede is geen noodgreep. TIDAL zet je na het inloggen op
            // tidal.com — een pagina die niet van ons is, dus er kan niets vanzelf terugkomen. Dat
            // stond hier eerder als "lukt het automatisch niet?", en dat is precies de zin die je
            // laat wachten op iets wat nooit gaat gebeuren.
            const Padding(
              padding: EdgeInsets.symmetric(horizontal: 24),
              child: Text('Verbind je TIDAL-account om de catalogus te doorzoeken.\n'
                  'Je logt in op TIDAL zelf — DebridMusic ziet je wachtwoord niet.',
                  textAlign: TextAlign.center, style: TextStyle(color: _muted)),
            ),
            const SizedBox(height: 16),
            FilledButton.icon(
              style: FilledButton.styleFrom(backgroundColor: _accent, padding: const EdgeInsets.symmetric(horizontal: 22, vertical: 14)),
              icon: _tidalConnecting
                  ? const SizedBox(width: 16, height: 16, child: CircularProgressIndicator(strokeWidth: 2, color: Colors.white))
                  : const Icon(Icons.open_in_browser_rounded, size: 18),
              label: Text(_tidalConnecting ? 'Bezig…' : 'Stap 1 · Inloggen bij TIDAL'),
              onPressed: _tidalConnecting ? null : _connectTidal,
            ),
            const SizedBox(height: 14),
            const Padding(
              padding: EdgeInsets.symmetric(horizontal: 24),
              child: Text('Na het inloggen kom je uit op tidal.com. Kopieer daar het hele adres uit '
                  'de adresbalk van je browser — er staat ?code= in — en klik dan hieronder. De app '
                  'haalt het van je klembord; je hoeft nergens te plakken.',
                  textAlign: TextAlign.center, style: kTekstKlein),
            ),
            const SizedBox(height: 8),
            OutlinedButton.icon(
              onPressed: _tidalConnecting ? null : _manualTidal,
              icon: const Icon(Icons.content_paste_rounded, size: 16),
              label: const Text('Stap 2 · Adres van klembord halen'),
            ),
          ],
        ),
      );
    }
    if (_tidalBusy) return const Center(child: CircularProgressIndicator(color: _accent));
    if (_tidalAlbums.isEmpty && _tidalTracks.isEmpty) {
      return const Center(
        child: Padding(
          padding: EdgeInsets.all(24),
          child: Text('Verbonden met TIDAL ✓  — zoek een plaat of een nummer. Ophalen gaat met je '
              'eigen abonnement; klap een regel uit voor torrent en Soulseek.',
              textAlign: TextAlign.center, style: TextStyle(color: _muted)),
        ),
      );
    }
    // tiddl staat op de machine die de muziek bezit. Een telefoon, de Shield en een op afstand
    // gekoppeld toestel hebben geen muziekmap om iets in te zetten — daar blijft dit precies wat
    // het was: een zoekscherm dat torrents en Soulseek voedt.
    final kanOphalen = _isDesktop && !context.read<LibraryStore>().isRemote;
    return ListView(
      // Waar je gebleven was blijft staan als je even naar de speler gaat. De route eronder
      // overleeft de sectiewissel, dus die bewaart de scrolstand — zelfde truc als bij het
      // albumraster en de nummerlijst.
      key: const PageStorageKey('online-tidal'),
      padding: const EdgeInsets.only(bottom: 24),
      children: [
        if (_tidalAlbums.isNotEmpty) ...[
          _browseHeader('Albums', _tidalAlbums.length),
          for (var i = 0; i < _tidalAlbums.length; i++)
            _tidalAlbumRow(i, _tidalAlbums[i], kanOphalen),
        ],
        if (_tidalTracks.isNotEmpty) ...[
          _browseHeader('Nummers', _tidalTracks.length),
          for (var i = 0; i < _tidalTracks.length; i++)
            _tidalTrackRow(i, _tidalTracks[i], kanOphalen),
        ],
      ],
    );
  }

  /// Eén plaat uit de TIDAL-lijst.
  ///
  /// Dezelfde vorm als [_tidalTrackRow], met twee verschillen: het jaar staat achter de artiest
  /// (heruitgaven dragen dezelfde titel) en de artiestnaam gaat er zonder [splitFeatured] in — een
  /// plaat heeft geen gastartiest in zijn titel, en dat raden levert alleen maar rare afbrekingen.
  Widget _tidalAlbumRow(int i, TidalAlbum a, bool kanOphalen) {
    final open = _tidalAlbumExpanded == i;
    return Column(
      children: [
        InkWell(
          onTap: () => setState(() => _tidalAlbumExpanded = open ? null : i),
          child: Container(
            margin: const EdgeInsets.symmetric(horizontal: 20, vertical: 1),
            padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 11),
            decoration: BoxDecoration(
                color: open ? _panel : Colors.transparent, borderRadius: BorderRadius.circular(8)),
            child: Row(
              children: [
                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(a.title,
                          maxLines: titelRegels(context),
                          overflow: TextOverflow.ellipsis,
                          style: kTekstNormaal),
                      if (a.artist.isNotEmpty || a.jaar.isNotEmpty)
                        Text(a.jaar.isEmpty ? a.artist : '${a.artist} · ${a.jaar}',
                            maxLines: 1, overflow: TextOverflow.ellipsis, style: kTekstKlein),
                    ],
                  ),
                ),
                if (kanOphalen) _ophaalKnop(tidalDoelVanId('album', a.id), a.label),
                Icon(open ? Icons.expand_less_rounded : Icons.travel_explore_rounded,
                    size: 18, color: open ? _accent : _muted),
              ],
            ),
          ),
        ),
        if (open)
          Padding(padding: const EdgeInsets.only(bottom: 8), child: SourcesView(query: a.sourceQuery)),
      ],
    );
  }

  /// De knop die één resultaat binnenhaalt.
  ///
  /// Een knop binnen de `InkWell` van de regel wint de aanraking, dus ophalen klapt de regel niet
  /// óók nog open.
  Widget _ophaalKnop(String? doel, String naam) => TextButton.icon(
        onPressed: () => _ophalenVanTidal(doel, naam),
        icon: const Icon(Icons.download_rounded, size: 15),
        label: const Text('Ophalen'),
        style: TextButton.styleFrom(
            foregroundColor: _accent2, textStyle: const TextStyle(fontSize: 12)),
      );

  Widget _tidalTrackRow(int i, TidalTrack t, bool kanOphalen) {
    final open = _tidalExpanded == i;
    return Column(
      children: [
        InkWell(
          onTap: () => setState(() => _tidalExpanded = open ? null : i),
          child: Container(
            margin: const EdgeInsets.symmetric(horizontal: 20, vertical: 1),
            padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 11),
            decoration: BoxDecoration(color: open ? _panel : Colors.transparent, borderRadius: BorderRadius.circular(8)),
            child: Row(
              children: [
                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(t.title,
                          maxLines: titelRegels(context),
                          overflow: TextOverflow.ellipsis,
                          style: kTekstNormaal),
                      if (t.artist.isNotEmpty)
                        _artistLine(splitFeatured(t.artist, t.title), kTekstKlein),
                    ],
                  ),
                ),
                if (kanOphalen) _ophaalKnop(tidalDoelVanId('track', t.id), t.label),
                Icon(open ? Icons.expand_less_rounded : Icons.travel_explore_rounded, size: 18, color: open ? _accent : _muted),
              ],
            ),
          ),
        ),
        if (open) Padding(padding: const EdgeInsets.only(bottom: 8), child: SourcesView(query: t.sourceQuery)),
      ],
    );
  }

  Widget _modeChip(String label, int m) {
    final sel = _mode == m;
    return Pressable(
      onPressed: () => _setMode(m),
      borderRadius: BorderRadius.circular(999),
      scaleOnFocus: false,
      child: Container(
        padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 8),
        decoration: BoxDecoration(
          color: sel ? _accent : _panel,
          borderRadius: BorderRadius.circular(9),
          border: Border.all(color: sel ? _accent : _line),
        ),
        child: Text(label, style: TextStyle(color: sel ? Colors.white : _muted, fontSize: 13, fontWeight: FontWeight.w600)),
      ),
    );
  }

  Widget _browseResults() {
    if (_browseBusy) return const Center(child: CircularProgressIndicator(color: _accent));
    if (_artists.isEmpty && _albumHits.isEmpty && _trackHits.isEmpty) {
      return const Center(
        child: Padding(
          padding: EdgeInsets.all(24),
          child: Text('Zoek een artiest, album of nummer — bronnen (torrent/Soulseek) verschijnen eronder.',
              textAlign: TextAlign.center, style: TextStyle(color: _muted)),
        ),
      );
    }
    return ListView(
      // Waar je gebleven was blijft staan als je even naar de speler gaat. De route eronder
      // overleeft de sectiewissel, dus die bewaart de scrolstand — zelfde truc als bij het
      // albumraster en de nummerlijst.
      key: const PageStorageKey('online-bladeren'),
      padding: const EdgeInsets.only(bottom: 24),
      children: [
        if (_artists.isNotEmpty) ...[
          _browseHeader('Artiesten', _artists.length),
          SizedBox(
            height: 158,
            child: ListView.separated(
              scrollDirection: Axis.horizontal,
              padding: const EdgeInsets.symmetric(horizontal: 20),
              itemCount: _artists.length,
              separatorBuilder: (_, __) => const SizedBox(width: 12),
              itemBuilder: (_, i) {
                final a = _artists[i];
                return InkWell(
                  onTap: () =>
                      openPagina(context, (_) => ArtistBrowsePage(a)),
                  borderRadius: BorderRadius.circular(12),
                  child: SizedBox(
                    width: 116,
                    child: Column(
                      children: [
                        _netCover(a.picture, size: 116, circle: true),
                        const SizedBox(height: 6),
                        Text(a.name,
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                            textAlign: TextAlign.center,
                            style: kTegelTitel),
                      ],
                    ),
                  ),
                );
              },
            ),
          ),
        ],
        if (_albumHits.isNotEmpty) ...[
          _browseHeader('Albums', _albumHits.length),
          SizedBox(
            height: 186,
            child: ListView.separated(
              scrollDirection: Axis.horizontal,
              padding: const EdgeInsets.symmetric(horizontal: 20),
              itemCount: _albumHits.length,
              separatorBuilder: (_, __) => const SizedBox(width: 12),
              itemBuilder: (_, i) {
                final h = _albumHits[i];
                return InkWell(
                  onTap: () => openPagina(context, (_) => AlbumBrowsePage(h.artist, h.album)),
                  borderRadius: BorderRadius.circular(12),
                  child: SizedBox(
                    width: 132,
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        _netCover(h.album.cover, size: 132, radius: 10),
                        const SizedBox(height: 6),
                        Text(h.album.title,
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                            style: kTegelTitel),
                        _maybeFocusable(Align(
                          alignment: Alignment.centerLeft,
                          child: ArtistNames(names: [h.artist], style: kTegelOnder),
                        )),
                      ],
                    ),
                  ),
                );
              },
            ),
          ),
        ],
        if (_trackHits.isNotEmpty) ...[
          _browseHeader('Nummers', _trackHits.length),
          ..._trackHits.asMap().entries.map((e) => _browseTrackRow(e.key, e.value)),
        ],
      ],
    );
  }

  Widget _browseHeader(String title, int count) => Padding(
        padding: const EdgeInsets.fromLTRB(24, 14, 24, 8),
        child: Text('${title.toUpperCase()}  ·  $count', style: kOpschrift),
      );

  Widget _browseTrackRow(int i, CatalogTrackHit t) {
    final open = _trackExpanded == i;
    return Column(
      children: [
        InkWell(
          onTap: () => setState(() => _trackExpanded = open ? null : i),
          child: Container(
            margin: const EdgeInsets.symmetric(horizontal: 20, vertical: 1),
            padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 9),
            decoration:
                BoxDecoration(color: open ? _panel : Colors.transparent, borderRadius: BorderRadius.circular(8)),
            child: Row(
              children: [
                _netCover(t.cover, size: 42, radius: 6),
                const SizedBox(width: 12),
                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(t.title,
                          maxLines: 1,
                          overflow: TextOverflow.ellipsis,
                          style: kTekstNormaal),
                      _artistLine(splitFeatured(t.artist, t.title), kTekstKlein),
                    ],
                  ),
                ),
                Icon(open ? Icons.expand_less_rounded : Icons.chevron_right_rounded, color: _muted),
              ],
            ),
          ),
        ),
        if (open) Padding(padding: const EdgeInsets.only(bottom: 8), child: SourcesView(query: t.query)),
      ],
    );
  }

  /// Zelfde geheugen van één als bij [SourcesView] — zie [_SlskKlaar].
  ///
  /// Met één verschil dat het hele punt is: hier gaat de LETTERLIJK getypte tekst mee. Dit scherm
  /// heeft geen uitgave om aan te toetsen, dus is de vraag zelf het enige wat "past dit bij wat ik
  /// zocht?" kan beantwoorden — en die werd tot nu toe nergens gebruikt.
  _SlskKlaar? _klaar;
  _SlskKlaar get _bronnen {
    final k = _klaar;
    if (k != null && k.geldigVoor(_slsk, _filter, _getypt)) return k;
    // Volledige dekking krijgt het groene merkje: alles wat je typte staat in dit bestand. Dat is
    // hier de enige maat die er is — er hangt geen uitgave onder dit scherm.
    final v = _getypt;
    return _klaar = _SlskKlaar.van(_slsk, _filter,
        vraag: v,
        past: v == null || v.isEmpty
            ? null
            : (f) => gedekteWoorden(v, f.filename) >= telbareWoorden(v),
        hergebruik: k?.hergebruikVoor(_slsk, v));
  }

  Widget _directResults(bool soulseekReady) {
    final vraag = _getypt;
    // Zeven op bron gebeurt NA de kwaliteitszeef en VOOR het rangschikken: dan klopt het aantal
    // achter elke bronknop met wat je te zien krijgt, en blijft "wat je typte bovenaan" gelden
    // binnen de bron die je koos. Zie [bronnenInResultaten].
    final naKwaliteit =
        _torrents.where((r) => _filter.matches(qualityFromName(r.name))).toList();
    final bronKeuzes = bronnenInResultaten(naKwaliteit);
    final bron = geldigeKeuze(_bron, bronKeuzes);
    final torrents = [for (final r in naKwaliteit) if (pastBijBron(r, bron)) r];
    // WAT JE TYPTE BOVENAAN. De torrentlijst kwam binnen op "gecacht, dan seeders" en verder
    // niets: een torrent die de indexer om een los woord teruggaf stond zomaar boven de plaat die
    // je bedoelde. Hier wordt niets weggegooid — een indexer mag best iets anders spellen — maar
    // wat je vroeg staat nu wel voorop. Zie [vraagScore].
    if (vraag != null && vraag.isNotEmpty) {
      final score = {for (final r in torrents) r: vraagScore(vraag, r.name)};
      torrents.sort((a, b) {
        final v = score[b]!.compareTo(score[a]!);
        if (v != 0) return v;
        if (a.cached != b.cached) return a.cached ? -1 : 1;
        return b.seeders.compareTo(a.seeders);
      });
    }
    final bronnen = _bronnen;
    final slsk = bronnen.gefilterd;
    return ListView(
      // Waar je gebleven was blijft staan als je even naar de speler gaat. De route eronder
      // overleeft de sectiewissel, dus die bewaart de scrolstand — zelfde truc als bij het
      // albumraster en de nummerlijst.
      key: const PageStorageKey('online-direct'),
      padding: const EdgeInsets.only(bottom: 24),
      children: [
        if (_torrents.isNotEmpty || _slsk.isNotEmpty)
          _filterChipsRow(_filter, (f) => setState(() => _filter = f)),
        _bronChipsRow(bronKeuzes, bron, (b) => setState(() => _bron = b)),
        // Dezelfde eerlijkheid als in het bronnenscherm: is er ruimer gezocht, dan gaat deze lijst
        // over een ándere vraag dan die je stelde, en dat hoort er te staan.
        if (vraag != null && _gezochtDirect != null && ruimerGezocht(vraag, _gezochtDirect!))
          Padding(
            padding: const EdgeInsets.fromLTRB(24, 6, 24, 2),
            child: Text(
                'Niets gevonden voor “$vraag”. Dit zijn de treffers voor “$_gezochtDirect”.',
                style: const TextStyle(color: Color(0xFFE8913A), fontSize: 12.5)),
          ),
        // HOE GOED DEKT DE BESTE TREFFER JE VRAAG? Zonder dit moest je zelf bestandsnamen
        // ontcijferen om te zien dat de bovenste maar drie van je vier woorden had — en dan zoek je
        // door terwijl je denkt dat je gevonden hebt. Gemeld op "mackenzie you all i need": 1867
        // treffers, geen enkele met alle vier de woorden, en niets op het scherm dat dat zei.
        if (vraag != null && bronnen.besteDekking >= 0 && slsk.isNotEmpty)
          Builder(builder: (_) {
            final totaal = telbareWoorden(vraag);
            final volledig = bronnen.besteDekking >= totaal;
            return Padding(
              padding: const EdgeInsets.fromLTRB(24, 6, 24, 2),
              child: Text(
                  volledig
                      ? 'Beste treffer heeft al je woorden.'
                      : 'Beste treffer heeft ${bronnen.besteDekking} van je $totaal woorden — '
                          'waarschijnlijk staat wat je zoekt er niet bij.',
                  style: TextStyle(
                      color: volledig ? _accent2 : const Color(0xFFE8913A), fontSize: 12.5)),
            );
          }),
        if (torrents.isNotEmpty) _sourceHeader('Torrents · TorBox', torrents.length, _busy),
        // Stond hier helemaal niet: waren er geen torrents, dan was er ook geen kop en geen woord.
        if (!_busy && _getypt != null) _waaromGeenTorrents(context, leeg: torrents.isEmpty),
        ...torrents.map((r) => _torrentTile(context, r)),
        if (_status == null || _slsk.isNotEmpty || _slskBusy)
          (soulseekReady
              ? _soulseekHeader(context, slsk, _slskBusy, slsk, folder: bronnen.besteMap)
              : const Padding(
                  padding: EdgeInsets.fromLTRB(24, 16, 24, 6),
                  child: Text('SOULSEEK · log in via Instellingen om P2P mee te zoeken',
                      style: kOpschrift))),
        // Het volgnummer telt op bij elke nieuwe zoekopdracht — precies het teken dat de boom nodig
        // heeft om zijn openstand en venster terug te zetten. De open- en dichtstand wijst naar
        // [ZoekGeheugen], zodat een gebruiker die je openklapte ook na een schermwissel open staat.
        _SoulseekGroepen(
            gebruikers: bronnen.gebruikers,
            slsk: slsk,
            passend: bronnen.passend,
            pastMerk: 'alles wat je typte',
            open: ZoekGeheugen.slskOpen,
            dicht: ZoekGeheugen.slskDicht,
            sleutel: '${ZoekGeheugen.gen}'),
      ],
    );
  }
}

/// Resolves a torrent's audio files and lets the user play or download any single track.
class _TrackPickerDialog extends StatefulWidget {
  final SearchResult result;
  const _TrackPickerDialog(this.result);
  @override
  State<_TrackPickerDialog> createState() => _TrackPickerDialogState();
}

class _TrackPickerDialogState extends State<_TrackPickerDialog> {
  bool _loading = true;
  String? _error;
  TbTorrent? _torrent;
  List<TbFile> _files = [];
  double _prep = 0;

  /// Wat TorBox op dit moment doet, in zijn eigen woorden. Zie `torbox_stand.dart`.
  ///
  /// Deze zin kwam altijd al binnen en werd weggegooid; op het scherm stond in plaats daarvan een
  /// vaste regel over "weinig seeders", ook bij een torrent met er veertig.
  String _stand = '';

  @override
  void initState() {
    super.initState();
    _load();
  }

  Future<void> _load() async {
    try {
      final (t, f) = await context.read<OnlineService>().tracklist(widget.result, onProgress: (p, s) {
        if (mounted) {
          setState(() {
            _prep = p;
            _stand = s;
          });
        }
      });
      if (!mounted) return;
      setState(() {
        _torrent = t;
        _files = f;
        _loading = false;
      });
    } catch (e) {
      if (mounted) setState(() { _error = '$e'; _loading = false; });
    }
  }

  Future<void> _play(TbFile f) async {
    try {
      final url = await context.read<OnlineService>().resolveTrackUrl(_torrent!.id, f.id);
      if (!mounted) return;
      context.read<PlayerStore>().playUrl(url, title: f.label, artist: widget.result.source);
      Navigator.pop(context);
    } catch (e) {
      _snack('Afspelen mislukt: $e');
    }
  }

  void _download(TbFile f) {
    // De torrent die dit venster al heeft laten voorbereiden gaat mee. Zonder dat begon het
    // downloaden met precies hetzelfde wachten er nog een keer overheen.
    context.read<DownloadManager>().enqueue(widget.result, fileId: f.id, klaar: _torrent);
    _snack('“${f.label}” naar downloads');
  }

  void _snack(String m) {
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(m), duration: const Duration(seconds: 2)));
  }

  @override
  Widget build(BuildContext context) {
    return Dialog(
      backgroundColor: _bg,
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(14)),
      child: Container(
        width: dialogWidth(context, 560),
        constraints: const BoxConstraints(maxHeight: 560),
        padding: const EdgeInsets.all(20),
        child: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text(widget.result.name,
                maxLines: 2, overflow: TextOverflow.ellipsis, style: const TextStyle(fontSize: 15, fontWeight: FontWeight.w700)),
            const SizedBox(height: 4),
            const Text('Kies een nummer om af te spelen of los te downloaden',
                style: TextStyle(color: _muted, fontSize: 12)),
            const SizedBox(height: 14),
            if (_loading)
              Padding(
                padding: const EdgeInsets.symmetric(vertical: 36, horizontal: 20),
                child: Center(
                  child: Column(children: [
                    const CircularProgressIndicator(color: _accent),
                    const SizedBox(height: 16),
                    Text(
                        _stand.isNotEmpty ? _stand : 'Bron voorbereiden bij TorBox…',
                        textAlign: TextAlign.center,
                        style: const TextStyle(color: _muted, fontSize: 12.5)),
                    if (_prep > 0) ...[
                      const SizedBox(height: 10),
                      ClipRRect(
                        borderRadius: BorderRadius.circular(3),
                        child: LinearProgressIndicator(
                            value: _prep, minHeight: 4, backgroundColor: _panel2, color: _accent),
                      ),
                    ],
                    // Waaróm je hierop wacht. Hier stond "niet-gecachte torrents met weinig seeders
                    // kunnen even duren" — een vaste zin, ook bij veertig seeders. Nu staat er wat
                    // er werkelijk gebeurt, en geen woord over een aantal dat niet gemeten is.
                    if (torboxWaarom(gecacht: widget.result.cached).isNotEmpty) ...[
                      const SizedBox(height: 10),
                      Text(torboxWaarom(gecacht: widget.result.cached),
                          textAlign: TextAlign.center,
                          style: const TextStyle(color: _muted, fontSize: 11)),
                    ],
                  ]),
                ),
              )
            else if (_error != null)
              Padding(
                padding: const EdgeInsets.symmetric(vertical: 24),
                child: Text(_error!, style: const TextStyle(color: Colors.redAccent)),
              )
            else
              Flexible(
                child: ListView.builder(
                  shrinkWrap: true,
                  itemCount: _files.length,
                  itemBuilder: (_, i) {
                    final f = _files[i];
                    return Padding(
                      padding: const EdgeInsets.symmetric(vertical: 2),
                      child: Row(
                        children: [
                          Expanded(
                            child: Column(
                              crossAxisAlignment: CrossAxisAlignment.start,
                              children: [
                                Text(f.label, maxLines: 1, overflow: TextOverflow.ellipsis, style: const TextStyle(fontSize: 13.5)),
                                Text('${_fmtBytes(f.size)}${f.isFlac ? " · FLAC" : ""}',
                                    style: const TextStyle(color: _muted, fontSize: 11.5)),
                              ],
                            ),
                          ),
                          TvLabelled(
                            label: 'Afspelen',
                            child: IconButton(
                              icon: const Icon(Icons.play_arrow_rounded, size: 22),
                              color: _accent,
                              tooltip: 'Afspelen',
                              onPressed: () => _play(f)),
                          ),
                          TvLabelled(
                            label: 'Download dit nummer',
                            child: IconButton(
                              icon: const Icon(Icons.download_rounded, size: 20),
                              color: _muted,
                              tooltip: 'Download dit nummer',
                              onPressed: () => _download(f)),
                          ),
                        ],
                      ),
                    );
                  },
                ),
              ),
            const SizedBox(height: 10),
            Align(
              alignment: Alignment.centerRight,
              child: TextButton(onPressed: () => Navigator.pop(context), child: const Text('Sluiten')),
            ),
          ],
        ),
      ),
    );
  }
}

/// Collapsed artist bio (3 lines) that opens the full text in a dialog on tap.
class BioText extends StatelessWidget {
  final String artist;
  final String text;
  const BioText(this.artist, this.text, {super.key});
  @override
  Widget build(BuildContext context) {
    // Capped where the long text actually lives, so artist bios and album blurbs both get it.
    // Align is load-bearing: a list hands its children a TIGHT width and a bare ConstrainedBox
    // cannot shrink below that — without it the cap silently does nothing.
    //
    // The Align sits OUTSIDE the Pressable, not inside it. Inside, the opaque hit test claimed the
    // Align's full row width, so on Windows a hand cursor appeared and a click landed hundreds of
    // pixels to the right of any text — over empty background. The press target is the paragraph.
    return Align(
      alignment: Alignment.topLeft,
      child: Pressable(
        onPressed: () => showDialog(
          context: context,
          builder: (_) => AlertDialog(
            backgroundColor: _panel,
            title: Text(artist, style: const TextStyle(fontSize: 18, fontWeight: FontWeight.w700)),
            content: SizedBox(
              width: dialogWidth(context, 540),
              child: SingleChildScrollView(
                child: Text(text, style: const TextStyle(color: Color(0xFFC7CBDA), fontSize: 13.5, height: 1.5)),
              ),
            ),
            actions: [TextButton(onPressed: () => Navigator.pop(context), child: const Text('Sluiten'))],
          ),
        ),
        child: ConstrainedBox(
          constraints: const BoxConstraints(maxWidth: 820),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Text(text,
                  maxLines: 3,
                  overflow: TextOverflow.ellipsis,
                  style: const TextStyle(color: _muted, fontSize: 13, height: 1.45)),
              const Padding(
                padding: EdgeInsets.only(top: 3),
                child: Text('Lees meer',
                    style: TextStyle(color: _accent, fontSize: 12.5, fontWeight: FontWeight.w600)),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

/// The banner at the top of the start page: the newest releases, one at a time, large.
///
/// The cover doubles as the backdrop — blurred, darkened and bled to the edges — because an album
/// has no separate wide artwork the way a film has a still. Auto-advances, but stops the moment
/// the pointer is on it so it can't slide away mid-read.
class HeroCarousel extends StatefulWidget {
  final List<CatalogAlbumHit> hits;
  const HeroCarousel({super.key, required this.hits});

  @override
  State<HeroCarousel> createState() => _HeroCarouselState();
}

class _HeroCarouselState extends State<HeroCarousel> {
  final _page = PageController();
  Timer? _timer;
  int _index = 0;
  bool _hover = false;

  @override
  void initState() {
    super.initState();
    _restart();
  }

  @override
  void dispose() {
    _timer?.cancel();
    _page.dispose();
    super.dispose();
  }

  void _restart() {
    _timer?.cancel();
    if (widget.hits.length < 2) return;
    // Never on a television, and this is not a performance decision — it is a correctness one.
    //
    // A PageView builds only the visible page. When the slide changes, the button you had the
    // highlight on is unmounted: the ring vanishes and OK does nothing, mid-read, on the first
    // screen the app shows. The mouse escape hatch does not apply, because `_hover` is only ever
    // set by a MouseRegion and a remote has no pointer.
    //
    // It happens to also stop two full-screen 28-sigma blurs sliding across a Tegra X1 every seven
    // seconds, which is the most expensive thing the home screen does. But the reason is the focus.
    if (isTv) return;
    _timer = Timer.periodic(const Duration(seconds: 7), (_) {
      if (!mounted || _hover || !_page.hasClients) return;
      _page.animateToPage((_index + 1) % widget.hits.length,
          duration: const Duration(milliseconds: 550), curve: Curves.easeInOutCubic);
    });
  }

  void _go(int delta) {
    if (!_page.hasClients) return;
    final n = widget.hits.length;
    _page.animateToPage((_index + delta + n) % n,
        duration: const Duration(milliseconds: 380), curve: Curves.easeOutCubic);
  }

  @override
  Widget build(BuildContext context) {
    return MouseRegion(
      onEnter: (_) => setState(() => _hover = true),
      onExit: (_) => setState(() => _hover = false),
      child: ClipRRect(
        borderRadius: BorderRadius.circular(18),
        child: SizedBox(
          // The banner lays a cover beside a title, a year and a button. On a phone that column is
          // narrow enough that the title takes two lines and the button fell one pixel past the
          // bottom — so the banner is taller there, not shorter.
          height: isCompact(context) ? 300 : 260,
          child: Stack(
            children: [
              PageView.builder(
                controller: _page,
                itemCount: widget.hits.length,
                onPageChanged: (i) => setState(() => _index = i),
                itemBuilder: (_, i) => _slide(widget.hits[i]),
              ),
              if (widget.hits.length > 1) ...[
                _arrow(Alignment.centerLeft, Icons.chevron_left_rounded, -1),
                _arrow(Alignment.centerRight, Icons.chevron_right_rounded, 1),
                Align(
                  alignment: Alignment.bottomCenter,
                  child: Padding(
                    padding: const EdgeInsets.only(bottom: 12),
                    child: Row(
                      mainAxisSize: MainAxisSize.min,
                      children: [
                        for (var i = 0; i < widget.hits.length; i++)
                          AnimatedContainer(
                            duration: const Duration(milliseconds: 260),
                            margin: const EdgeInsets.symmetric(horizontal: 3),
                            width: i == _index ? 18 : 6,
                            height: 6,
                            decoration: BoxDecoration(
                              color: i == _index ? Colors.white : Colors.white.withValues(alpha: .38),
                              borderRadius: BorderRadius.circular(999),
                            ),
                          ),
                      ],
                    ),
                  ),
                ),
              ],
            ],
          ),
        ),
      ),
    );
  }

  Widget _arrow(Alignment side, IconData icon, int delta) => Align(
        alignment: side,
        // Invisible is not the same as absent. Opacity 0 leaves the InkWell in the traversal, and
        // the focus ring is drawn inside that same Opacity — so on a television pressing right from
        // "Bekijken" sent the highlight into a transparent circle and OK then paged the carousel
        // for no visible reason. Nothing to see, nothing to land on.
        child: ExcludeFocus(
          excluding: !_hover,
          child: AnimatedOpacity(
          opacity: _hover ? 1 : 0,
          duration: const Duration(milliseconds: 180),
          child: Padding(
            padding: const EdgeInsets.symmetric(horizontal: 8),
            child: Material(
              color: Colors.black.withValues(alpha: .45),
              shape: const CircleBorder(),
              child: InkWell(
                customBorder: const CircleBorder(),
                onTap: () => _go(delta),
                child: Padding(padding: const EdgeInsets.all(6), child: Icon(icon, size: 26, color: Colors.white)),
              ),
            ),
          ),
        )),
      );

  Widget _slide(CatalogAlbumHit hit) {
    final cover = hit.album.cover;
    // The whole banner is clickable AND carries a "Bekijken" button that does the same thing. For a
    // mouse that is a convenience; for a remote it is two stops with one outcome, and a ring drawn
    // around 260 points of artwork.
    //
    // So on a television the banner is not pressable and the button is. NOT ExcludeFocus, which was
    // the first attempt and was simply wrong: it excludes the whole subtree, so it took the
    // "Bekijken" button out of the highlight's path as well and left the entire carousel
    // unreachable — the opposite of what the comment claimed.
    return Pressable(
      onPressed: isTv
          ? null
          : () => openPagina(context, (_) => AlbumBrowsePage(hit.artist, hit.album)),
      borderRadius: BorderRadius.circular(12),
      scaleOnFocus: false,
      child: MouseRegion(
        cursor: SystemMouseCursors.click,
        child: Stack(
          fit: StackFit.expand,
          children: [
            if (cover != null)
              ImageFiltered(
                imageFilter: ImageFilter.blur(sigmaX: 28, sigmaY: 28),
                // Decoded at 64 and blown up, not decoded at 1000 and blurred. At sigma 28 the two
                // are indistinguishable — the blur throws away everything a bigger decode bought —
                // but one costs 16 kB and the other 4 MB, seven slides at a time.
                child: Image.network(cover,
                    fit: BoxFit.cover,
                    cacheWidth: 64,
                    filterQuality: FilterQuality.low,
                    errorBuilder: (_, __, ___) => const SizedBox()),
              ),
            // Without this the blurred art is too busy to read white text on. Kept dark even at
            // the far edge: a mostly-white sleeve blurs to near-white and washed the banner out.
            DecoratedBox(
              decoration: BoxDecoration(
                gradient: LinearGradient(
                  begin: Alignment.centerLeft,
                  end: Alignment.centerRight,
                  colors: [Colors.black.withValues(alpha: .88), Colors.black.withValues(alpha: .62)],
                ),
              ),
            ),
            Padding(
              // 28 a side plus a 168 cover plus a 24 gap is 248 of a phone's 411 points, and the
              // 163 left over is not enough for the button beside it — "Bekijken" broke in half.
              padding: EdgeInsets.fromLTRB(
                  isCompact(context) ? 16 : 28, 24, isCompact(context) ? 16 : 28, 28),
              child: Row(
                children: [
                  ClipRRect(
                    borderRadius: BorderRadius.circular(10),
                    child: SizedBox(
                      width: isCompact(context) ? 118 : 168,
                      height: isCompact(context) ? 118 : 168,
                      child: cover == null
                          ? Container(color: _panel2)
                          : Image.network(cover,
                              fit: BoxFit.cover,
                              cacheWidth: decodeWidth(isCompact(context) ? 118 : 168),
                              errorBuilder: (_, __, ___) => Container(color: _panel2)),
                    ),
                  ),
                  SizedBox(width: isCompact(context) ? 14 : 24),
                  Expanded(
                    child: Column(
                      mainAxisAlignment: MainAxisAlignment.center,
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        const Text('NIEUWE RELEASE',
                            style: TextStyle(
                                color: _accent2, fontSize: 11, fontWeight: FontWeight.w800, letterSpacing: 1.2)),
                        const SizedBox(height: 8),
                        Text(hit.album.title,
                            maxLines: 2,
                            overflow: TextOverflow.ellipsis,
                            style: const TextStyle(fontSize: 27, fontWeight: FontWeight.w800, height: 1.1)),
                        const SizedBox(height: 6),
                        _maybeFocusable(Align(
                          alignment: Alignment.centerLeft,
                          child: ArtistNames(
                              names: [hit.artist],
                              style: const TextStyle(fontSize: 15, color: Color(0xFFC7CBDA))),
                        )),
                        if (hit.album.year != null) ...[
                          const SizedBox(height: 2),
                          Text('${hit.album.year}', style: const TextStyle(fontSize: 12.5, color: _muted)),
                        ],
                        const SizedBox(height: 14),
                        FilledButton.icon(
                          style: FilledButton.styleFrom(
                              backgroundColor: _accent, padding: const EdgeInsets.symmetric(horizontal: 20, vertical: 12)),
                          onPressed: () =>
                              openPagina(context, (_) => AlbumBrowsePage(hit.artist, hit.album)),
                          icon: const Icon(Icons.playlist_add_rounded, size: 18),
                          label: const Text('Bekijken'),
                        ),
                      ],
                    ),
                  ),
                ],
              ),
            ),
          ],
        ),
      ),
    );
  }
}

/// A cinematic banner for an artist: wide backdrop, and the act's OWN wordmark rather than their
/// name set in the app's typeface.
///
/// The wordmark is the point. There is no way to render text in an artist's official lettering —
/// those fonts aren't distributed — but the logo itself is an image of exactly that lettering, so
/// showing it is the real thing instead of an imitation. Falls back to plain text for the acts
/// that have no logo (about one in four).
/// The artist's own photo, blurred, standing behind a WHOLE page rather than behind a banner.
///
/// It does not scroll: the records and tracks move over a wash that stays put, so the page reads
/// as one thing about one artist instead of a strip of atmosphere with a list bolted under it.
/// The scrim is light at the top, where the portrait and wordmark are, and settles to near-solid
/// below that — album titles and track rows have to stay readable over it.
class ArtistBackdrop extends StatefulWidget {
  final String name;
  final Uint8List? fallbackImage;
  final Widget child;
  const ArtistBackdrop({super.key, required this.name, this.fallbackImage, required this.child});

  @override
  State<ArtistBackdrop> createState() => _ArtistBackdropState();
}

class _ArtistBackdropState extends State<ArtistBackdrop> {
  ArtistArt? _art;

  @override
  void initState() {
    super.initState();
    _load();
  }

  @override
  void didUpdateWidget(ArtistBackdrop old) {
    super.didUpdateWidget(old);
    if (old.name != widget.name) {
      setState(() => _art = null);
      _load();
    }
  }

  Uint8List? _chosenBackdrop;
  String? _loadedUrl;

  Future<void> _load() async {
    final name = widget.name;
    final settings = context.read<AppSettings>();
    final art = await CoverEnricher(settings).artistArt(name);
    if (!mounted || name != widget.name) return;
    setState(() => _art = art);
    // A picture the user picked outranks anything the shape heuristic chose. Fetched here rather
    // than stored as bytes, so the choice survives independently of any cache being cleared.
    final lib = context.read<LibraryStore>();
    for (final kind in const ['backdrop']) {
      final url = lib.chosenArtistArt(name, kind);
      if (url == null) continue;
      final bytes = await CoverEnricher(settings).downloadImage(url);
      if (!mounted || name != widget.name || bytes == null) continue;
      if (kind == 'backdrop') setState(() => _chosenBackdrop = bytes);
    }
  }

  @override
  Widget build(BuildContext context) {
    // Same as the hero: a fresh pick has to show without leaving the page and coming back.
    final chosen = context.watch<LibraryStore>().chosenArtistArt(widget.name, 'backdrop');
    if (chosen != _loadedUrl) {
      _loadedUrl = chosen;
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted) _load();
      });
    }
    final img = _chosenBackdrop ?? _art?.backdropBytes ?? _art?.thumbBytes ?? widget.fallbackImage;
    return Stack(
      fit: StackFit.expand,
      children: [
        if (img != null)
          ClipRect(
            child: ImageFiltered(
              imageFilter: ImageFilter.blur(sigmaX: 60, sigmaY: 60),
              // Overscanned, or the blur samples past the image and the edges fade to nothing.
              child: Transform.scale(
                scale: 1.25,
                // Same argument as the hero backdrop: at sigma 60 nothing survives that a 96-point
                // decode did not already have, and a full-resolution artist portrait behind a
                // screen-filling blur is the most expensive thing on this page.
                child: Image.memory(img,
                    fit: BoxFit.cover,
                    cacheWidth: 96,
                    filterQuality: FilterQuality.low,
                    alignment: Alignment.topCenter,
                    errorBuilder: (_, __, ___) => const SizedBox()),
              ),
            ),
          ),
        DecoratedBox(
          decoration: BoxDecoration(
            gradient: LinearGradient(
              begin: Alignment.topCenter,
              end: Alignment.bottomCenter,
              // The hero fills roughly the top third, so the scrim stays light that far down and
              // only closes in below it, where the records and tracks have to stay readable.
              colors: [
                Colors.black.withValues(alpha: .26),
                Colors.black.withValues(alpha: .40),
                kAchtergrond.withValues(alpha: .86),
                kAchtergrond.withValues(alpha: .92),
              ],
              stops: const [0, .30, .58, 1],
            ),
          ),
        ),
        widget.child,
      ],
    );
  }
}

class ArtistHero extends StatefulWidget {
  final String name;
  final String? subtitle;
  final Uint8List? fallbackImage;
  final List<Widget> actions;

  /// False when an [ArtistBackdrop] is already washing the whole page — the hero then contributes
  /// only the portrait and the wordmark, and doesn't paint a second, differently-cropped copy.
  final bool ownBackdrop;
  const ArtistHero({
    super.key,
    required this.name,
    this.subtitle,
    this.fallbackImage,
    this.actions = const [],
    this.ownBackdrop = true,
  });

  @override
  State<ArtistHero> createState() => _ArtistHeroState();
}

class _ArtistHeroState extends State<ArtistHero> {
  ArtistArt? _art;

  @override
  void initState() {
    super.initState();
    _load();
  }

  @override
  void didUpdateWidget(ArtistHero old) {
    super.didUpdateWidget(old);
    if (old.name != widget.name) {
      setState(() => _art = null);
      _load();
    }
  }

  /// The URLs this hero last fetched, so a fresh pick can be spotted while the page stays open.
  String? _loadedPortraitUrl, _loadedBackdropUrl;

  /// Re-fetch when the user picks a different photo. Without this the choice was saved and simply
  /// not shown until you left the page and came back — a setting that appears to do nothing.
  void _syncChoice() {
    final lib = context.watch<LibraryStore>();
    final p = lib.chosenArtistArt(widget.name, 'portrait');
    final b = lib.chosenArtistArt(widget.name, 'backdrop');
    if (p == _loadedPortraitUrl && b == _loadedBackdropUrl) return;
    _loadedPortraitUrl = p;
    _loadedBackdropUrl = b;
    // After this frame: build must not kick off a setState of its own.
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (mounted) _load();
    });
  }

  Future<void> _load() async {
    final name = widget.name;
    final settings = context.read<AppSettings>();
    final art = await CoverEnricher(settings).artistArt(name);
    if (!mounted || name != widget.name) return;
    setState(() => _art = art);
    // Same as the page backdrop: a picture the user picked outranks the shape heuristic.
    final lib = context.read<LibraryStore>();
    for (final kind in const ['portrait', 'backdrop']) {
      final url = lib.chosenArtistArt(name, kind);
      if (url == null) continue;
      final bytes = await CoverEnricher(settings).downloadImage(url);
      if (!mounted || name != widget.name || bytes == null) continue;
      setState(() => kind == 'portrait' ? _chosenPortrait = bytes : _chosenBackdrop = bytes);
    }
  }

  Uint8List? _chosenPortrait, _chosenBackdrop;

  @override
  Widget build(BuildContext context) {
    _syncChoice();
    final logo = _art?.logoBytes;
    final portrait = _chosenPortrait ?? _art?.thumbBytes ?? widget.fallbackImage;
    final backdrop = _chosenBackdrop ?? _art?.backdropBytes ?? widget.fallbackImage;

    // Op een telefoon staat de portretfoto BOVEN de naam en de knoppen, niet ernaast. Die vaste
    // 400 is de hoogte voor naast elkaar, en onder elkaar past het er niet in.
    //
    // **Dit is waarom "Foto kiezen" en "Radio" op de telefoon niets deden.** De knoppenrij viel
    // ~30 dp buiten dat vak, en wat buiten zijn eigen vak getekend wordt, tekent in Flutter nog wél
    // maar vángt geen tik: `RenderBox.hitTest` slaat een positie buiten `size` over. Je zag dus
    // twee knoppen staan die aantoonbaar niets deden — ook de Radio-knop ernaast niet. Gemeten op
    // de S26: de rij eindigde 12 px onder de onderrand van de kop.
    //
    // Op een telefoon wordt die hoogte niet meer BEGROOT maar GEMETEN. De vorige versie rekende
    // `portret + 230`, en 230 was precies genoeg voor de naam, de telling en ÉÉN regel knoppen.
    // Toen er een derde knop bij kwam zakte die naar een tweede regel, en stond hij weer buiten het
    // vak: half afgesneden en niet aan te tikken — exact dezelfde fout, één knop later. Elk vast
    // getal hier is een fout die op zijn volgende knop wacht, dus de inhoud bepaalt de hoogte nu
    // zelf en er valt niets meer te schatten.
    final smal = isCompact(context);
    final marge = smal ? 18.0 : 28.0;
    final portretMaat =
        smal ? (MediaQuery.sizeOf(context).width - marge * 2).clamp(120.0, 220.0) : 270.0;

    // De achtergrond en de waas zijn `Positioned.fill`: zo vullen ze het vak zonder het te MAKEN.
    // Op een telefoon (`StackFit.loose`) is de inhoud het enige kind dat de hoogte bepaalt; op een
    // groot scherm blijft het vaste vak van 400 eromheen staan.
    final vak = Stack(
        fit: smal ? StackFit.loose : StackFit.expand,
        children: [
          // Blurred on purpose. Every artist image any database has is 16:9 — fanart, widethumb,
          // all of it — and a banner this wide can only show a quarter of one. Sharp, that quarter
          // was a gamble: it framed Michael Jackson but gave Stromae a band of forehead, because his
          // photo is a close-up that no crop can survive. So the backdrop is atmosphere drawn from
          // the artist's own colours, and the portrait beside it is what you actually recognise.
          if (backdrop != null && widget.ownBackdrop)
            Positioned.fill(
              child: ImageFiltered(
                imageFilter: ImageFilter.blur(sigmaX: 26, sigmaY: 26),
                // Overscanned: a blur samples past the edges, and at 1.0 the sides faded out.
                child: Transform.scale(
                  scale: 1.15,
                  // Klein gedecodeerd en dan uitvergroot. Deze gaat er tóch doorheen met een blur van
                  // sigma 26 — er is geen enkel detail dat de decodeergrootte rechtvaardigt, en een
                  // artiestachtergrond van 1920x1080 is 8,3 MB als bitmap. Dezelfde afweging staat
                  // 300 regels hierboven al uitgeschreven bij de andere achtergrond; deze was
                  // overgeslagen.
                  child: Image.memory(backdrop,
                      fit: BoxFit.cover,
                      cacheWidth: 64,
                      alignment: const Alignment(0, -.3),
                      errorBuilder: (_, __, ___) => const SizedBox()),
                ),
              ),
            ),
          // Dark enough at the bottom that the wordmark and buttons always read. Skipped when the
          // page already carries the wash — a second gradient on top of it just muddies the top.
          if (widget.ownBackdrop)
            Positioned.fill(
              child: DecoratedBox(
                decoration: BoxDecoration(
                  gradient: LinearGradient(
                    begin: Alignment.topCenter,
                    end: Alignment.bottomCenter,
                    colors: [
                      Colors.black.withValues(alpha: .30),
                      Colors.black.withValues(alpha: .38),
                      Colors.black.withValues(alpha: .82),
                      kAchtergrond,
                    ],
                    stops: const [0, .40, .82, 1],
                  ),
                ),
              ),
            ),
          Builder(builder: (context) {
            // Dezelfde drie waarden als waarmee de hoogte hierboven gerekend is. Eén bron, want
            // gingen die uit elkaar lopen, dan is de kop precies weer te klein voor wat erin staat
            // — en dat is de fout die de knoppen onaanraakbaar maakte.
            // 270 points of portrait plus a 26 gap leaves about ninety of a phone's 411 for the
            // column beside it, and "61 albums" came out one word per line. Stacked there, and the
            // portrait sized from the width that exists.
            final narrow = smal;
            final pad = marge;
            final portraitSize = portretMaat;

            final photo = portrait == null
                ? null
                : DecoratedBox(
                    decoration: BoxDecoration(
                      borderRadius: BorderRadius.circular(14),
                      // Lifts it off a backdrop that is, by design, the same photo's colours.
                      boxShadow: [BoxShadow(color: Colors.black.withValues(alpha: .55), blurRadius: 28, offset: const Offset(0, 10))],
                    ),
                    child: ClipRRect(
                      borderRadius: BorderRadius.circular(14),
                      child: Image.memory(portrait,
                          width: portraitSize,
                          height: portraitSize,
                          fit: BoxFit.cover,
                          alignment: const Alignment(0, -.25),
                          errorBuilder: (_, __, ___) => const SizedBox()),
                    ),
                  );

            final details = Column(
                    // Op een telefoon MEET deze kolom de kop op; dan mag hij niet naar de volle
                    // hoogte willen rekken, want de kop staat in een scroller en die is naar
                    // beneden onbegrensd. Naast de foto (groot scherm) blijft hij wél rekken —
                    // daar duwt `end` de naam en de knoppen naar de onderrand van het vak.
                    mainAxisSize: smal ? MainAxisSize.min : MainAxisSize.max,
                    mainAxisAlignment: MainAxisAlignment.end,
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      if (logo != null)
                        ConstrainedBox(
                          constraints: const BoxConstraints(maxHeight: 96, maxWidth: 460),
                          child: Image.memory(logo,
                              fit: BoxFit.contain,
                              // De HOOGTE begrenst hier, niet de breedte: een woordmerk is breed en
                              // laag, en het vak eromheen is 96 hoog. `cacheHeight` is dus de wenk die
                              // past — met `cacheWidth` zou een breed logo alsnog op volle hoogte
                              // gedecodeerd worden.
                              cacheHeight: decodeWidth(96),
                              alignment: Alignment.centerLeft,
                              errorBuilder: (_, __, ___) => _plainName()),
                        )
                      else
                        _plainName(),
                      if (widget.subtitle != null) ...[
                        const SizedBox(height: 8),
                        Text(widget.subtitle!, style: const TextStyle(color: Color(0xFFC7CBDA), fontSize: 13.5)),
                      ],
                      if (widget.actions.isNotEmpty) ...[
                        const SizedBox(height: 12),
                        // Een Wrap en geen Row. Drie knoppen naast elkaar vragen zo'n 445 punten en
                        // een telefoon heeft er 411, dus de derde liep van het scherm af; nu zakt
                        // hij naar een eigen regel. De tussenruimte zit in `spacing`, dus de
                        // aanroepers geven geen SizedBox meer mee.
                        Wrap(spacing: 10, runSpacing: 10, children: widget.actions),
                      ],
                    ],
                  );

            return Padding(
              padding: EdgeInsets.fromLTRB(pad, 0, pad, 22),
              child: narrow
                  ? Column(
                      mainAxisSize: MainAxisSize.min,
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        if (photo != null) ...[photo, const SizedBox(height: 14)],
                        details,
                      ],
                    )
                  : Row(
                      crossAxisAlignment: CrossAxisAlignment.end,
                      children: [
                        // The portrait is what makes this a page about a PERSON. A wide backdrop
                        // cropped to a banner shows a horizontal slice, and whether the face is in
                        // it is luck.
                        if (photo != null) ...[photo, const SizedBox(width: 26)],
                        Expanded(child: details),
                      ],
                    ),
            );
          }),
        ],
    );

    // A blur paints outside its child's bounds, and the overscan pushes it further still — without
    // this the wash ran on down the page and the biography underneath was hard to read.
    return ClipRect(
      // Room for a 270px portrait with the wordmark and buttons beside it. The backdrop is very
      // wide, so every extra pixel of height is another band of it that isn't cropped away. Alleen
      // op een groot scherm: op een telefoon meet de inhoud zichzelf op.
      child: smal ? vak : SizedBox(height: 400, child: vak),
    );
  }

  Widget _plainName() => Text(widget.name,
      maxLines: 2,
      overflow: TextOverflow.ellipsis,
      style: const TextStyle(fontSize: 34, fontWeight: FontWeight.w800, letterSpacing: -.5));
}

/// De naam van een artiest in zijn eigen lettering, of anders gewoon in letters.
///
/// **Waarom dit los van [ArtistHero] staat.** Die kop is een heel vak: achtergrond, portret, waas,
/// knoppen, tellingen. Op het speelscherm is daar geen plaats voor en hoort er maar één ding boven
/// de hoes: van wie is deze plaat. Het logo is precies dat — een afbeelding van de officiële
/// lettering van de act, en dat is de enige manier om die lettering te tonen, want die letterfonts
/// worden niet uitgegeven.
///
/// Ongeveer één op de vier artiesten heeft er geen. Dan komt de naam als tekst op diezelfde plek —
/// niet niets, want dan zou de hoes per plaat op een andere hoogte springen.
///
/// Dezelfde bron als de artiestenpagina: [CoverEnricher.artistArt] bewaart de bytes op schijf, dus
/// dit haalt niet bij elk nummer opnieuw iets op.
class ArtiestKop extends StatefulWidget {
  const ArtiestKop({
    super.key,
    required this.naam,
    this.hoogte = 64,
    this.breedte = 320,
    this.gecentreerd = true,
  });

  final String naam;

  /// Hoe hoog het logo hoogstens mag worden. De artiestenpagina gunt het 96; hier staat er een hoes
  /// onder die de hoogte al opeist.
  final double hoogte;
  final double breedte;
  final bool gecentreerd;

  @override
  State<ArtiestKop> createState() => _ArtiestKopState();
}

class _ArtiestKopState extends State<ArtiestKop> {
  Uint8List? _logo;

  @override
  void initState() {
    super.initState();
    _laad();
  }

  @override
  void didUpdateWidget(ArtiestKop oud) {
    super.didUpdateWidget(oud);
    if (oud.naam != widget.naam) {
      setState(() => _logo = null);
      _laad();
    }
  }

  Future<void> _laad() async {
    final naam = widget.naam;
    if (naam.trim().isEmpty) return;
    final art = await CoverEnricher(context.read<AppSettings>()).artistArt(naam);
    if (!mounted || naam != widget.naam) return;
    setState(() => _logo = art?.logoBytes);
  }

  Widget _alsTekst() => Text(
        widget.naam,
        maxLines: 2,
        overflow: TextOverflow.ellipsis,
        textAlign: widget.gecentreerd ? TextAlign.center : TextAlign.left,
        style: const TextStyle(fontSize: 22, fontWeight: FontWeight.w800, letterSpacing: -.3),
      );

  @override
  Widget build(BuildContext context) {
    if (widget.naam.trim().isEmpty) return const SizedBox.shrink();
    final logo = _logo;
    return Pressable(
      onPressed: () => openArtist(context, widget.naam),
      borderRadius: BorderRadius.circular(8),
      scaleOnFocus: false,
      child: ConstrainedBox(
        constraints: BoxConstraints(maxWidth: widget.breedte),
        child: logo == null
            ? _alsTekst()
            : ConstrainedBox(
                constraints: BoxConstraints(maxHeight: widget.hoogte),
                child: Image.memory(
                  logo,
                  fit: BoxFit.contain,
                  // Zelfde wenk als bij de artiestenkop, en hier telt hij dubbel: dit staat op het
                  // speelscherm, dat bij elk nieuw album opnieuw opgebouwd wordt.
                  cacheHeight: decodeWidth(widget.hoogte),
                  alignment: widget.gecentreerd ? Alignment.center : Alignment.centerLeft,
                  // Een kapot of half binnengehaald bestand mag geen leeg gat geven; dan de naam.
                  errorBuilder: (_, __, ___) => _alsTekst(),
                ),
              ),
      ),
    );
  }
}

/// What this release IS: the official blurb plus year, genre, label and rating — the album
/// equivalent of a film's synopsis panel. Silent when nothing is known, so a page never shows
/// an empty box.
class AlbumInfoPanel extends StatefulWidget {
  final String artist, album;

  /// How many tracks the library holds for this album — used to reject a Discogs pressing that
  /// is really a single or a sampler filed under the same master.
  final int trackCount;

  /// Is [trackCount] de HELE plaat, of alleen wat de bibliotheek er toevallig van heeft?
  ///
  /// Dat verschil beslist of een uitgave mag afvallen omdat hij te LANG is. Alleen de bladerpagina
  /// weet het zeker — die telt de tracklijst van precies deze uitgave. De albumpagina telt wat er op
  /// schijf staat, en dat is routinematig een deel: vier nummers van Demon Days zijn nog steeds
  /// Demon Days, en een bovengrens op dat viertal zou elke echte persing van vijftien afwijzen. Dat
  /// is precies waarom [DiscogsService.edition] alleen op "te weinig" toetst.
  ///
  /// Met een volledige tracklijst is de andere richting wél te vertrouwen, en die is nodig: Sia /
  /// "Titans" is één nummer, en de tekstzoektocht bij Discogs leverde een soundtrack van Waxwork
  /// Records met negenentwintig — jaartal, label, genres en credits van een plaat die niet van haar
  /// is, boven een tracklijst die dat wel is.
  final bool completeTracklist;

  /// The Discogs release the user pinned to this album, if any.
  final int? pinned;

  /// Or the MusicBrainz one, when they pinned there instead.
  final String? pinnedMbid;

  /// Images the user assigned by hand — the back cover shown here is one of them.
  final Map<String, String> roles;

  const AlbumInfoPanel(
      {super.key,
      required this.artist,
      required this.album,
      this.trackCount = 0,
      this.completeTracklist = false,
      this.pinned,
      this.pinnedMbid,
      this.roles = const {}});

  @override
  State<AlbumInfoPanel> createState() => _AlbumInfoPanelState();
}

class _AlbumInfoPanelState extends State<AlbumInfoPanel> {
  AlbumInfo? _info;
  DiscogsEdition? _edition;
  Uint8List? _back;

  /// The pressing the user pinned on MusicBrainz, when that is where they pinned it.
  ///
  /// Without this the line below described a Discogs pressing nobody chose. Pick the French CD in
  /// the gallery and it still read "Uitgave: cd · 88725453152 · Canada" — the pin was on disk and
  /// correct, but this panel only ever asked Discogs, so the one sentence naming your copy of the
  /// record contradicted the choice you had just made.
  MbRelease? _mbEdition;

  @override
  void initState() {
    super.initState();
    _load();
  }

  @override
  void didUpdateWidget(AlbumInfoPanel old) {
    super.didUpdateWidget(old);
    // The PIN counts as a change too. Without it, picking a different release of the same record
    // changed nothing here: the name stays "Adele – 30", so this saw no difference and never
    // refetched. The front cover did change, because that comes down a different path entirely —
    // which is exactly what it looked like from the outside.
    if (old.artist != widget.artist ||
        old.album != widget.album ||
        old.pinned != widget.pinned ||
        old.pinnedMbid != widget.pinnedMbid ||
        !mapEquals(old.roles, widget.roles)) {
      // Not cleared first: the year, label and catalogue number of the pressing you just left are
      // a better thing to look at for one network round trip than an empty panel that collapses
      // the page and pushes the tracklist up under your cursor.
      _load();
    }
  }

  /// Which load is current — see the same field on [_AlbumArtState].
  int _gen = 0;

  Future<void> _load() async {
    final artist = widget.artist, album = widget.album;
    final mine = ++_gen;
    final settings = context.read<AppSettings>();
    final mbService = context.read<MusicBrainzService>();
    final store = context.read<LibraryStore>();
    final discogs = DiscogsService(settings);

    /// Still looking at the same record? Read before every setState: each of these lands on its own
    /// schedule now, so any of them can come back after the page has moved on.
    bool stillHere() =>
        mounted && mine == _gen && artist == widget.artist && album == widget.album;

    // Four independent questions, asked at the same time instead of in a queue.
    //
    // They used to be four awaits in a row, and the scans were last. Measured on ANTI: the pressing
    // line landed after thirteen seconds and the back and the disc were still not there after
    // thirty, because their request had not been SENT yet — it was waiting behind TheAudioDB,
    // MusicBrainz and the Discogs edition. Nothing in the artwork chain needs any of those three:
    // every argument it takes comes from the widget. See DiscogsService.edition's in-flight table
    // for why asking for the edition twice at once costs one fetch, not two.
    final blurb = CoverEnricher(settings).albumInfo(artist, album).catchError((_) => null);

    final mbid = widget.pinnedMbid;
    final pressing = (mbid != null && mbid.isNotEmpty)
        ? mbService.release(mbid).catchError((_) => null)
        : Future.value(null);

    final release = discogs
        .edition(artist, album, expectedTracks: widget.trackCount, pinned: widget.pinned)
        .catchError((_) => null);

    final scans = discogs
        .releaseArt(artist, album,
            expectedTracks: widget.trackCount,
            pinned: widget.pinned,
            pinnedMbid: widget.pinnedMbid,
            roles: widget.roles)
        .catchError((_) => null);

    // The blurb comes from TheAudioDB, which is the only one of these that writes one.
    unawaited(blurb.then((info) {
      if (info != null && stillHere()) setState(() => _info = info);
    }));

    unawaited(pressing.then((mb) {
      if (!stillHere()) return;
      if (mb != null) {
        setState(() => _mbEdition = mb);
      } else if (mbid == null || mbid.isEmpty) {
        if (_mbEdition != null) setState(() => _mbEdition = null);
      }
    }));

    // Discogs knows what the record IS: which pressing, on whose label, under what catalogue number.
    unawaited(release.then((ed) {
      if (ed == null || !stillHere()) return;
      // …maar alleen als het over DEZE plaat gaat. De zoektocht hierboven is op tekst en de laatste
      // uitweg in `_editionFresh` geeft bewust de dichtstbijzijnde persing terug in plaats van
      // niets — goed genoeg voor een album dat echt bestaat, fout voor een titel die Discogs niet
      // kent. Zie `completeTracklist` voor waarom alleen de bladerpagina dit mag toetsen.
      if (widget.completeTracklist &&
          widget.trackCount > 0 &&
          ed.tracklist.isNotEmpty &&
          !DiscogsService.fitsTrackCount(ed.tracklist.length, widget.trackCount)) {
        return;
      }
      setState(() => _edition = ed);
      // Remember what this record sounds like. The map fills in as albums are opened, which is what
      // makes browsing by style possible without sweeping the whole library up front.
      unawaited(store.rememberStyles(artist, album, [...ed.genres, ...ed.styles]));
    }));

    unawaited(scans.then((art) {
      if (art?.back != null && stillHere()) setState(() => _back = art!.back);
    }));
  }

  /// "CD" reads oddly next to a year; "File" reads as nothing at all.
  static String _formatLabel(String f) => switch (f.toLowerCase()) {
        'file' => 'digitaal',
        'vinyl' => 'vinyl',
        'cd' => 'cd',
        'cdr' => 'cd-r',
        'cassette' => 'cassette',
        _ => f.toLowerCase(),
      };

  @override
  Widget build(BuildContext context) {
    final info = _info;
    final ed = _edition;
    final mb = _mbEdition;
    if (info == null && ed == null && mb == null) return const SizedBox.shrink();
    // Discogs describes one specific pressing, so where the two disagree its year and label are
    // the ones that belong to the record in front of you.
    final genres = <String>{...ed?.genres ?? const [], ...ed?.styles ?? const []};
    if (genres.isEmpty) {
      if (info?.genre != null) genres.add(info!.genre!);
      if (info?.style != null) genres.add(info!.style!);
    }
    // The RECORD's year leads, not the pressing's: Demon Days is a 2005 album, even when the copy
    // being described is the 2014 digital reissue.
    final year = ed?.albumYear ?? ed?.year ?? info?.year;
    final facts = <String>[
      if (year != null) '$year',
      ...genres.take(4),
      // Same reason as the pressing line: the label that pressed YOUR copy, when you named it.
      if ((mb?.label ?? ed?.label ?? info?.label) != null) (mb?.label ?? ed?.label ?? info?.label)!,
    ];
    // The pressing itself, kept apart from the genre soup: this is the line that says WHICH copy
    // of the record the page is describing. The precedence rule lives in pressingFacts, where it
    // can be held to it — see editions.dart.
    final pressing = pressingFacts(
      pinned: mb == null
          ? null
          : (format: mb.format, catno: mb.catno, country: mb.country, year: mb.year),
      guessed: ed == null
          ? null
          : (format: ed.format, catno: ed.catno, country: ed.country, year: ed.year),
      recordYear: year,
      formatLabel: _formatLabel,
    );
    final text = info?.text;

    return Padding(
      padding: const EdgeInsets.fromLTRB(24, 4, 24, 14),
      // Capped: on a maximised window the blurb would otherwise run the full 1400px, and a line
      // that long is genuinely hard to read back to the next line.
      //
      // Align first, and that is not decoration: a list hands its children a TIGHT width, and a
      // bare ConstrainedBox cannot shrink below a tight constraint — the cap silently did nothing
      // until this was added. Align loosens the constraint so the cap can take effect.
      child: Align(
        alignment: Alignment.topLeft,
        child: ConstrainedBox(
        constraints: const BoxConstraints(maxWidth: 820),
        child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              if (info?.score != null) ...[
                const Icon(Icons.star_rounded, size: 16, color: Color(0xFFE0B341)),
                const SizedBox(width: 4),
                Text(info!.score!.toStringAsFixed(1),
                    style: const TextStyle(fontSize: 12.5, fontWeight: FontWeight.w700)),
                const SizedBox(width: 12),
              ],
              Flexible(
                // Every style is a door. Clicking "Synth-pop" is the difference between a label on
                // a page and a way into the rest of the music that sounds like this.
                child: Wrap(spacing: 5, runSpacing: 2, children: [
                  for (var i = 0; i < facts.length; i++) ...[
                    if (i > 0) const Text('·', style: TextStyle(color: _muted, fontSize: 12.5)),
                    if (genres.contains(facts[i]))
                      InkWell(
                        onTap: () => openPagina(context, (_) => StylePage(facts[i])),
                        borderRadius: BorderRadius.circular(4),
                        child: Text(facts[i],
                            style: const TextStyle(color: _accent2, fontSize: 12.5)),
                      )
                    else
                      Text(facts[i], style: const TextStyle(color: _muted, fontSize: 12.5)),
                  ],
                ]),
              ),
            ],
          ),
          if (pressing.isNotEmpty) ...[
            const SizedBox(height: 6),
            Row(children: [
              const Icon(Icons.album_outlined, size: 13, color: _muted),
              const SizedBox(width: 5),
              Flexible(
                child: Text(
                    // Named, so it is always plain whether the page is describing the release YOU
                    // chose or the one the app picked for itself.
                    // "Jouw" means the user pinned this, on EITHER catalogue — saying "Uitgave" after
                    // they chose one reads as the app ignoring them, which is what it was doing.
                    '${widget.pinned != null || (widget.pinnedMbid ?? '').isNotEmpty ? "Jouw uitgave" : "Uitgave"}'
                    ': ${pressing.join(' · ')}',
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    style: const TextStyle(color: _muted, fontSize: 12)),
              ),
            ]),
          ],
          // The back of the sleeve, next to the line describing the pressing it belongs to. Click
          // to see it full size — the track list and the small print are the reason to look.
          if (_back != null) ...[
            const SizedBox(height: 10),
            InkWell(
              onTap: () => showDialog<void>(
                context: context,
                builder: (_) => Dialog(
                  backgroundColor: Colors.transparent,
                  insetPadding: const EdgeInsets.all(40),
                  child: InteractiveViewer(child: Image.memory(_back!)),
                ),
              ),
              borderRadius: BorderRadius.circular(6),
              child: ClipRRect(
                borderRadius: BorderRadius.circular(6),
                child: Image.memory(_back!,
                    height: 116, fit: BoxFit.contain, cacheWidth: decodeWidth(200)),
              ),
            ),
          ],
          if (text != null && text.isNotEmpty) ...[
            const SizedBox(height: 8),
            BioText('${widget.artist} — ${widget.album}', text),
          ],
        ],
        ),
        ),
      ),
    );
  }
}

// ── Stremio-style online browse: artist → albums → tracks → sources ──────────
class ArtistBrowsePage extends StatefulWidget {
  final CatalogArtist artist;
  const ArtistBrowsePage(this.artist, {super.key});
  @override
  State<ArtistBrowsePage> createState() => _ArtistBrowsePageState();
}

class _ArtistBrowsePageState extends State<ArtistBrowsePage> {
  final _catalog = CatalogService();

  /// De drie bronnen APART, en pas samengevoegd bij het tekenen.
  ///
  /// Eén gedeelde lijst zou betekenen dat de uitkomst afhangt van wie het eerst binnenkwam, en dan
  /// verspringt de lijst terwijl je ernaar kijkt. Zo geeft elke hertekening hetzelfde antwoord — en is
  /// dat antwoord precies wat `mergeDiscography` in de test oplevert.
  List<DiscoRelease> _dz = const [], _mb = const [], _dg = const [];
  BronStatus? _dzStatus, _mbStatus, _dgStatus;

  /// Hoezen die Discogs' zoeksweep kent voor platen die hij zelf niet als regel oplevert.
  Map<String, String> _hoezen = const {};

  /// De [discoKey]s van regels die in werkelijkheid andermans plaat zijn.
  ///
  /// Saber wees "Pavarotti & Friends for Cambodia and Tibet" aan tussen de albums van Enrique
  /// Iglesias — een plaat van Luciano Pavarotti waar Enrique op één nummer meezingt. Komt na het
  /// laden binnen, want het kost één verzoek per regel die alleen Deezer kent.
  Set<String> _gasten = const {};

  DiscoSort _sort = DiscoSort.datum;
  String? _bio;
  bool _busy = true;

  /// "Klinkt als" — overgenomen van de oude, tweede artiestpagina.
  ///
  /// Die pagina kreeg je via Bibliotheek → Artiesten en had als enige dit blok én "Foto kiezen";
  /// deze had als enige de biografie, MusicBrainz en Discogs. Welk scherm je zag hing dus af van
  /// waar je vandaan kwam. Nu is er één pagina en staat alles erop.
  List<CatalogArtist> _related = const [];

  @override
  void initState() {
    super.initState();
    _load();
    _loadBio();
    _loadRelated();
  }

  DiscographyService get _disco => DiscographyService(
        _catalog,
        context.read<MusicBrainzService>(),
        DiscogsService(context.read<AppSettings>()),
      );

  /// Drie bronnen, elk zodra hij klaar is.
  ///
  /// Dit was een OF/OF: een MusicBrainz-artiest kreeg alleen MusicBrainz, alle anderen alleen Deezer.
  /// Daardoor miste je bij een gewone artiest elke regionale uitgave en elke compilatie die een
  /// streamingcatalogus nooit heeft gekend, en bij een MusicBrainz-artiest élke hoes.
  ///
  /// Nu alle drie, in volgorde van snelheid: Deezer heeft geen rem en staat er meteen, MusicBrainz
  /// kost één verzoek op een baan van 1100 ms, Discogs twee op een baan van zestig per minuut. De
  /// pagina is dus bruikbaar voordat de trage bronnen binnen zijn, en groeit daarna.
  Future<void> _load() async {
    final ref = widget.artist.ref;
    final naam = widget.artist.name;
    final svc = _disco;

    // De cache eerst, zodat een tweede bezoek niet leeg begint. Wat daarna binnenkomt overschrijft
    // hem gewoon — samenvoegen is idempotent, dus dat kan geen kwaad.
    final bewaard = await svc.lees(naam);
    if (mounted && bewaard != null && bewaard.releases.isNotEmpty) {
      setState(() {
        _dz = bewaard.releases;
        _busy = false;
      });
    }

    Future<void> pak(Future<BronUitkomst> f, void Function(BronUitkomst) zet) async {
      final u = await f;
      if (!mounted) return;
      setState(() {
        zet(u);
        _busy = false;
      });
    }

    // Niet awaited op elkaar: de drie lopen naast elkaar en elke setState tekent wat er dán is.
    await Future.wait([
      pak(svc.vanDeezer(naam, bekendId: ref.isMb ? null : widget.artist.id),
          (u) { _dz = u.releases; _dzStatus = u.status; }),
      pak(svc.vanMusicBrainz(naam, bekendeMbid: ref.isMb ? ref.id : null),
          (u) { _mb = u.releases; _mbStatus = u.status; }),
      pak(svc.vanDiscogs(naam),
          (u) { _dg = u.releases; _dgStatus = u.status; _hoezen = u.hoezen; }),
    ]);

    if (!mounted) return;
    final alles = vulHoezenAan(mergeDiscography([_dz, _mb, _dg]), _hoezen);
    if (alles.isNotEmpty) unawaited(svc.schrijf(naam, alles));

    // Pas NA de drie bronnen, want wat MusicBrainz of Discogs ook kent hoeft niet nagevraagd — die
    // twee laten een gastoptreden al vallen. En pas nadat de pagina staat: dit kost een verzoek per
    // regel die alleen Deezer kent, voor Enrique Iglesias zijn dat er 47.
    final gasten = await svc.gastoptredens(naam, alles);
    if (!mounted || gasten.isEmpty) return;
    setState(() => _gasten = gasten);
    // Opnieuw wegschrijven, zodat een tweede bezoek ze niet eerst weer laat opflitsen.
    unawaited(svc.schrijf(naam, alles.where((r) => !gasten.contains(r.key)).toList()));
  }

  Future<void> _loadBio() async {
    final enricher = CoverEnricher(context.read<AppSettings>());
    var bio = await enricher.cachedBio(widget.artist.name);
    bio ??= await enricher.fetchArtistBio(widget.artist.name);
    if (mounted && bio != null) setState(() => _bio = bio);
  }

  /// Verwante artiesten. Alleen Deezer kent die, en alleen op nummer.
  ///
  /// Een pagina die vanuit MusicBrainz of vanuit een kale naam is geopend draagt geen Deezer-id, dus
  /// die wordt hier alsnog opgezocht — met dezelfde naamcontrole als de discografie, want een
  /// naamgenoot levert een rij "klinkt als" op die nergens op slaat.
  Future<void> _loadRelated() async {
    try {
      final naam = widget.artist.name;
      var id = widget.artist.ref.isMb ? 0 : widget.artist.id;
      if (id == 0) {
        final hits = await _catalog.searchArtists(naam);
        id = hits.where((a) => artistKey(a.name) == artistKey(naam)).firstOrNull?.id ?? 0;
      }
      if (id == 0) return;
      final r = await _catalog.relatedArtists(id);
      if (mounted && naam == widget.artist.name) setState(() => _related = r);
    } catch (_) {/* een pagina zonder "klinkt als" is nog steeds een goede pagina */}
  }

  @override
  Widget build(BuildContext context) {
    // The records of this artist you actually hold. Matched on the normalised artist name, the same
    // key the library groups by, so a stray capital or accent doesn't hide your own albums.
    final lib = context.watch<LibraryStore>();
    final mine = lib.albums
        .where((a) => artistKey(a.artist) == artistKey(widget.artist.name))
        .toList()
      ..sort((a, b) => (b.year ?? 0).compareTo(a.year ?? 0));

    // Samenvoegen gebeurt HIER, bij het tekenen, en niet in `_load`. Zo geeft elke hertekening
    // hetzelfde antwoord ongeacht welke bron het eerst binnenkwam — zie de test daarop.
    //
    // Bezit langs dezelfde sleutel als de rest, want anders is "heb ik dit" een andere vraag dan "is
    // dit dezelfde plaat" en vink je twee regels af voor één album.
    final bezit = {for (final a in mine) discoKey(a.title)};
    // Hoezen aanvullen vóór het sorteren, gastoptredens eruit: allebei op de samengevoegde lijst,
    // zodat elke hertekening hetzelfde antwoord geeft ongeacht wat er wanneer binnenkwam.
    final alles = vulHoezenAan(mergeDiscography([_dz, _mb, _dg]), _hoezen)
        .where((r) => !_gasten.contains(r.key))
        .toList();
    final blokken = inBlokken(alles, _sort, bezit);
    final rijen = alles;

    return Scaffold(
      backgroundColor: _bg,
      // De spelerbalk hoort op ELKE pagina, niet alleen in de shell.
      //
      // Hij stond op precies twee plekken: het hoofdscherm en de albumpagina. Op de artiest-,
      // persoon-, afspeellijst-, stijl- en online-albumpagina was er dus geen speler in beeld —
      // en omdat de hoes in die balk de ENIGE ingang naar "Nu speelt" is, was dat scherm daar
      // helemaal onbereikbaar. Op de Shield gemeten: negen drukken vanaf Start, en vanaf een
      // gepushte pagina geen enkele weg.
      //
      // In de `bottomNavigationBar`-sleuf en niet als Column: Scaffold legt de body er dan
      // vanzelf boven, en de balk blijft binnen deze route — dus `Navigator.of(context)` in de
      // wachtrij- en speakerknop wijst nog naar de goede plek.
      // GEEN eigen spelerbalk meer. De schil tekent hem, en die staat sinds de binnennavigator
      // ónder deze pagina in plaats van erachter — twee balken zouden er twee zijn.
      body: ArtistBackdrop(
        name: widget.artist.name,
        // Same as the album browse page: this draws its own hero rather than an AppBar, so the
        // status bar had nothing keeping it clear. The backdrop stays behind it — only the
        // content is inset.
        child: SafeArea(
            // A television reports no insets, so SafeArea alone is a no-op there; this is the
            // margin that keeps the back arrow off the part of the picture a set cuts away.
            minimum: tvOverscan,
        bottom: false,
        child: CustomScrollView(
        slivers: [
          SliverToBoxAdapter(
            child: Stack(
              children: [
                ArtistHero(
                  name: widget.artist.name,
                  ownBackdrop: false,
                  subtitle: _busy
                      ? 'Albums laden…'
                      : [
                          if (mine.isNotEmpty) '${mine.length} in je bibliotheek',
                          '${rijen.length} albums',
                        ].join(' · '),
                  actions: [
                    FilledButton.icon(
                      style: FilledButton.styleFrom(
                          backgroundColor: _accent,
                          padding: const EdgeInsets.symmetric(horizontal: 18, vertical: 10)),
                      onPressed: () => startRadio(context, widget.artist.name),
                      icon: const Icon(Icons.radio_rounded, size: 18),
                      label: const Text('Radio'),
                    ),
                    // De app raadt portret-of-achtergrond uit de vorm van een plaatje, en juist een
                    // gok hoor je te kunnen overrulen.
                    FilledButton.icon(
                      style: FilledButton.styleFrom(
                          backgroundColor: _panel2,
                          foregroundColor: Colors.white,
                          padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 10)),
                      onPressed: () => showDialog<void>(
                          context: context, builder: (_) => ArtistArtGallery(widget.artist.name)),
                      icon: const Icon(Icons.photo_library_outlined, size: 18),
                      label: const Text('Foto kiezen'),
                    ),
                    // Alleen waar er iets te hernoemen valt: een artiest uit de catalogus waarvan
                    // je niets hebt, heeft geen tags om te corrigeren.
                    if (mine.isNotEmpty) ...[
                      // Waar een in tweeën gevallen discografie weer één wordt. De naam is het
                      // enige waar groeperen op af kan gaan, dus één album getagd als “Enrique”
                      // tussen een plank “Enrique Iglesias” zijn twee artiesten wat deze app
                      // betreft — en deze pagina, die er dan de helft van toont, is waar je het ziet.
                      FilledButton.icon(
                        style: FilledButton.styleFrom(
                            backgroundColor: _panel2,
                            foregroundColor: Colors.white,
                            padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 10)),
                        onPressed: () async {
                          final r = await showDialog<({String naam, int geschreven, int mislukt})>(
                              context: context,
                              builder: (_) => ArtistRenameDialog(widget.artist.name));
                          if (r == null || !context.mounted) return;
                          _srcToast(
                              context,
                              r.mislukt > 0
                                  ? 'Staat nu onder “${r.naam}” — ${r.mislukt} bestand'
                                      '${r.mislukt == 1 ? '' : 'en'} kon niet geschreven worden.'
                                  : 'Staat nu onder “${r.naam}”.');
                          // Deze pagina gaat over een naam waar niets meer onder staat.
                          Navigator.pop(context);
                        },
                        icon: const Icon(Icons.drive_file_rename_outline_rounded, size: 18),
                        label: const Text('Naam corrigeren'),
                      ),
                    ],
                  ],
                ),
                Padding(
                  padding: const EdgeInsets.fromLTRB(10, 8, 0, 0),
                  child: IconButton(
                    icon: const Icon(Icons.arrow_back_rounded),
                    onPressed: () => Navigator.pop(context),
                  ),
                ),
              ],
            ),
          ),
          if (_bio != null)
            SliverToBoxAdapter(
              child: Padding(
                padding: const EdgeInsets.fromLTRB(20, 0, 20, 14),
                child: BioText(widget.artist.name, _bio!),
              ),
            ),
          // What you already own by this artist, first. Reaching an artist from an album used to
          // show only the online discography, so the records sitting on your own disk were the one
          // thing this page would not tell you about.
          if (mine.isNotEmpty) ...[
            SliverToBoxAdapter(child: _sectionTitle('In mijn bibliotheek', '${mine.length}')),
            SliverPadding(
              padding: const EdgeInsets.fromLTRB(20, 0, 20, 18),
              sliver: SliverGrid(
                gridDelegate: const SliverGridDelegateWithMaxCrossAxisExtent(
                    maxCrossAxisExtent: 180, mainAxisSpacing: 14, crossAxisSpacing: 14, childAspectRatio: .74),
                delegate:
                    SliverChildBuilderDelegate((_, i) => AlbumCard(album: mine[i]), childCount: mine.length),
              ),
            ),
          ],
          if (_busy)
            const SliverToBoxAdapter(
                child: Padding(padding: EdgeInsets.all(40), child: Center(child: CircularProgressIndicator(color: _accent))))
          else ...[
            SliverToBoxAdapter(
              child: Builder(builder: (context) {
                final kop = _sectionTitle(
                    mine.isEmpty ? 'Discografie' : 'Volledige discografie',
                    '${rijen.length} in ${blokken.length} blokken');
                // Op een telefoon gaat de sorteerpil ONDER de kop staan. Samen vragen ze zo'n 500
                // punten en een telefoon heeft er 411; naast elkaar bleef er voor de kop te weinig
                // over en liep hij dwars door de pil heen. Een eigen regel kost 30 punten en is het
                // enige dat de twee uit elkaar houdt.
                if (isCompact(context)) {
                  return Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      kop,
                      Padding(
                        padding: const EdgeInsets.fromLTRB(24, 0, 20, 10),
                        child: _sorteerPil(),
                      ),
                    ],
                  );
                }
                return Row(
                  children: [
                    Expanded(child: kop),
                    Padding(
                      padding: const EdgeInsets.only(right: 20),
                      child: _sorteerPil(),
                    ),
                  ],
                );
              }),
            ),
            if (_bronRegel() case final regel?)
              SliverToBoxAdapter(
                child: Padding(
                  padding: const EdgeInsets.fromLTRB(24, 0, 24, 8),
                  child: Text(regel, style: const TextStyle(color: _muted, fontSize: 11.5)),
                ),
              ),
            // Per soort een eigen blok met een eigen kop. Zonder die scheiding staat een deluxe naast
            // het gewone album met bijna dezelfde naam, en tussen tweehonderd singles zie je niet meer
            // welke platen er eigenlijk zijn.
            for (final blok in blokken) ...[
              SliverToBoxAdapter(
                  child: _sectionTitle(blokTitel(blok.soort), '${blok.rijen.length}')),
              SliverPadding(
                padding: const EdgeInsets.fromLTRB(20, 0, 20, 24),
                sliver: SliverGrid(
                  gridDelegate: const SliverGridDelegateWithMaxCrossAxisExtent(
                      maxCrossAxisExtent: 180, mainAxisSpacing: 14, crossAxisSpacing: 14, childAspectRatio: .74),
                  delegate: SliverChildBuilderDelegate(
                      (_, i) => _discoCard(blok.rijen[i], bezit.contains(blok.rijen[i].key)),
                      childCount: blok.rijen.length),
                ),
              ),
            ],
          ],
          // Onder de discografie, want dit is de uitgang van de pagina: als je hier niets vond, is de
          // volgende vraag "wie klinkt hier dan op".
          if (_related.isNotEmpty) ...[
            SliverToBoxAdapter(child: _sectionTitle('Klinkt als', '${_related.length}')),
            SliverToBoxAdapter(
              child: SizedBox(
                height: 176,
                child: ListView.separated(
                  scrollDirection: Axis.horizontal,
                  padding: const EdgeInsets.symmetric(horizontal: 20),
                  itemCount: _related.length,
                  separatorBuilder: (_, __) => const SizedBox(width: kRuimte12),
                  itemBuilder: (_, i) {
                    final r = _related[i];
                    return _RelatedArtistCard(
                      artist: r,
                      inLibrary: lib.hasArtist(r.name),
                      // Eén bestemming, ook hier: iemand die je zelf hebt en iemand die je niet hebt
                      // openen dezelfde pagina. Dat verschil was juist de reden dat er twee waren.
                      onTap: () => openArtist(
                          context, lib.hasArtist(r.name) ? lib.displayArtist(r.name) : r.name),
                    );
                  },
                ),
              ),
            ),
          ],
          const SliverToBoxAdapter(child: SizedBox(height: 24)),
        ],
        ),
        ),
      ),
    );
  }

  /// Dezelfde pil als op de Albums-pagina, zodat sorteren overal hetzelfde ding is.
  Widget _sorteerPil() => Container(
        decoration: BoxDecoration(
          color: Colors.white.withValues(alpha: .06),
          borderRadius: BorderRadius.circular(999),
          border: Border.all(color: Colors.white.withValues(alpha: .12)),
        ),
        padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 2),
        child: PopupMenuButton<DiscoSort>(
          tooltip: 'Sorteren',
          initialValue: _sort,
          onSelected: (s) => setState(() => _sort = s),
          itemBuilder: (_) => [
            for (final s in DiscoSort.values) PopupMenuItem(value: s, child: Text(s.label)),
          ],
          child: Row(mainAxisSize: MainAxisSize.min, children: [
            const Icon(Icons.sort_rounded, size: 15, color: _muted),
            const SizedBox(width: 6),
            Text(_sort.label, style: const TextStyle(fontSize: 12, color: _muted)),
            const Icon(Icons.arrow_drop_down_rounded, size: 18, color: _muted),
          ]),
        ),
      );

  /// Wat de bronnen deden — alleen als er iets te melden valt.
  ///
  /// "Geen token", "niet bereikbaar" en "niets gevonden" zien er op een lege lijst hetzelfde uit, en
  /// zonder Discogs-token faalt daar élke aanroep stil. Dat verschil hoort op het scherm te staan.
  String? _bronRegel() {
    final meldingen = <String>[];
    if (_dgStatus == BronStatus.geenToken) meldingen.add('Discogs: geen token in Instellingen');
    if (_dgStatus == BronStatus.onbereikbaar) meldingen.add('Discogs niet bereikbaar');
    if (_mbStatus == BronStatus.onbereikbaar) meldingen.add('MusicBrainz niet bereikbaar');
    if (_dzStatus == BronStatus.onbereikbaar) meldingen.add('Deezer niet bereikbaar');
    for (final e in {
      'Deezer': _dzStatus,
      'MusicBrainz': _mbStatus,
      'Discogs': _dgStatus,
    }.entries) {
      if (e.value == BronStatus.andereArtiest) {
        meldingen.add('${e.key} kende alleen een naamgenoot — overgeslagen');
      }
    }
    return meldingen.isEmpty ? null : meldingen.join(' · ');
  }

  /// Eén plaat uit de samengevoegde discografie.
  Widget _discoCard(DiscoRelease r, bool owned) {
    final al = r.toCatalogAlbum();
    // Het merkje: welke catalogi deze plaat kennen. Alleen tonen als het iets toevoegt — bij één bron
    // zegt het niets, en drie letters onder elke tegel is ruis.
    final merk = r.sources.length > 1
        ? r.sources.map((s) => switch (s) {
              DiscoSource.deezer => 'D',
              DiscoSource.musicbrainz => 'MB',
              DiscoSource.discogs => 'DG',
            }).join('·')
        : null;
    return Stack(children: [
      _albumCard(al, owned),
      if (merk != null)
        Positioned(
          left: 6,
          top: 6,
          child: Container(
            padding: const EdgeInsets.symmetric(horizontal: 5, vertical: 1),
            decoration: BoxDecoration(
              color: Colors.black.withValues(alpha: .55),
              borderRadius: BorderRadius.circular(5),
            ),
            child: Text(merk, style: const TextStyle(fontSize: 9, color: Colors.white70)),
          ),
        ),
    ]);
  }

  Widget _albumCard(CatalogAlbum al, [bool owned = false]) {
    final sub = [
      if (al.year != null) al.year!,
      if (al.isSingle) 'Single' else if (al.trackCount > 0) '${al.trackCount} nummers',
    ].join(' · ');
    return InkWell(
      onTap: () => openPagina(context, (_) => AlbumBrowsePage(widget.artist.name, al)),
      borderRadius: BorderRadius.circular(12),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Expanded(
            child: LayoutBuilder(
              builder: (_, c) => Stack(children: [
                _netCover(al.cover, size: c.maxWidth),
                // Which of the discography you already hold — so the gap in the collection is the
                // thing you can see, rather than something to work out by comparing two lists.
                if (owned)
                  Positioned(
                    right: 5,
                    top: 5,
                    child: Container(
                      padding: const EdgeInsets.all(3),
                      decoration: BoxDecoration(
                        color: _bg.withValues(alpha: .72),
                        shape: BoxShape.circle,
                      ),
                      child: const Icon(Icons.check_circle_rounded, size: 15, color: _accent2),
                    ),
                  ),
              ]),
            ),
          ),
          const SizedBox(height: 6),
          Text(al.title, maxLines: 1, overflow: TextOverflow.ellipsis, style: const TextStyle(fontSize: 12.5, fontWeight: FontWeight.w600)),
          Text(sub, maxLines: 1, overflow: TextOverflow.ellipsis, style: const TextStyle(color: _muted, fontSize: 11)),
        ],
      ),
    );
  }

  Widget _sectionTitle(String title, String count) => Padding(
        padding: const EdgeInsets.fromLTRB(24, 10, 24, 10),
        child: Row(children: [
          // Flexible, want een Row die niet past tekent gewoon door over wat ernaast staat — geen
          // melding, geen streepjes, in een release-bouw alleen twee teksten over elkaar heen.
          // Zo stond "Volledige discografie" op een telefoon dwars door de sorteerpil.
          Flexible(
            child: Text(title,
                maxLines: 1,
                overflow: TextOverflow.ellipsis,
                style: const TextStyle(fontSize: 17, fontWeight: FontWeight.w700)),
          ),
          const SizedBox(width: 8),
          Text(count, style: const TextStyle(color: _muted, fontSize: 13)),
        ]),
      );
}

class AlbumBrowsePage extends StatefulWidget {
  final String artistName;
  final CatalogAlbum album;
  const AlbumBrowsePage(this.artistName, this.album, {super.key});
  @override
  State<AlbumBrowsePage> createState() => _AlbumBrowsePageState();
}

class _AlbumBrowsePageState extends State<AlbumBrowsePage> {
  static const _albumLevel = -1;
  final _catalog = CatalogService();
  List<CatalogTrack> _tracks = [];
  bool _busy = true;
  int? _expanded; // track index whose sources are shown; -1 = whole album

  // Soulseek sources for the WHOLE album, pre-loaded in the background with ONE search when the
  // page opens — so tapping a track's download button is instant (no per-track search). Kept to
  // one search per album-open on purpose (never a per-track burst) so we don't trip the login block.
  List<SoulseekFile> _albumSlsk = [];
  bool _slskBusy = false;

  @override
  void initState() {
    super.initState();
    _load();
    WidgetsBinding.instance.addPostFrameCallback((_) => _preloadSoulseek());
  }

  Future<void> _load() async {
    // Where this album came from decides who can describe it. The sign of the id used to say, and
    // it had run out of values — it also meant two different things at once, since a negative id
    // was a Discogs RELEASE from search but a Discogs MASTER from a style page. Feeding a master
    // to the release endpoint is why an album opened from a style page had no tracklist at all.
    final ref = widget.album.ref;
    switch (ref.source) {
      case CatalogSource.musicbrainz:
        if (!await _loadMusicBrainzRelease(ref.id)) _geenTracklijst();
        return;
      case CatalogSource.musicbrainzGroup:
        await _loadMusicBrainzGroup(ref.id);
        return;
      case CatalogSource.discogsRelease:
        if (!await _loadDiscogsRelease(ref.intId)) _geenTracklijst();
        return;
      case CatalogSource.discogsMaster:
        await _loadDiscogsMaster(ref.intId);
        return;
      case CatalogSource.deezer:
        break;
    }
    try {
      final (_, tracks) = await _catalog.albumTracks(widget.album.id);
      if (mounted) setState(() { _tracks = tracks; _busy = false; });
    } catch (_) {
      if (mounted) setState(() => _busy = false);
    }
    await _preferOfficialTracklist();
  }

  /// De pagina is uitgeladen en heeft geen nummers gevonden.
  void _geenTracklijst() {
    if (mounted) setState(() => _busy = false);
  }

  /// A record, not a pressing — so resolve its best pressing first. Only a pressing has a
  /// tracklist, and this is the single easiest way to ship a page that loads nothing.
  ///
  /// Doorlopen tot er één persing nummers oplevert, in plaats van bij de best gerangschikte te
  /// stoppen. GEMETEN op Sia / "Titans": de releasegroep heeft drie persingen, de best gerangschikte
  /// levert helemaal niets op en de twee erachter allebei het ene nummer dat erop staat. Stoppen bij
  /// de eerste gaf dus een lege pagina voor een plaat waarvan MusicBrainz de tracklijst gewoon heeft.
  Future<void> _loadMusicBrainzGroup(String groupMbid) async {
    try {
      final mb = context.read<MusicBrainzService>();
      final editions = MusicBrainzService.orderByPreference(await mb.editionsOf(groupMbid));
      // Hooguit een handvol: elke persing is een eigen verzoek op een baan van 1100 ms, en een
      // releasegroep als Thriller heeft er vijfentachtig.
      for (final e in editions.take(4)) {
        if (await _loadMusicBrainzRelease(e.mbid)) return;
      }
    } catch (_) {/* valt door naar de lege pagina */}
    _geenTracklijst();
  }

  /// True zodra deze persing nummers opleverde. False betekent "vraag de volgende" — en dus
  /// nadrukkelijk NIET dat de pagina klaar is met laden.
  Future<bool> _loadMusicBrainzRelease(String mbid) async {
    if (!mounted) return false;
    try {
      final e = await context.read<MusicBrainzService>().release(mbid);
      if (!mounted || e == null || e.tracks.isEmpty) return false;
      setState(() {
        _tracks = [
          for (var i = 0; i < e.tracks.length; i++)
            CatalogTrack(
              // No Deezer id exists for these; the index keys the row and Soulseek is searched by
              // name anyway, which is all this page does with it.
              -(i + 1),
              e.tracks[i].title,
              widget.artistName,
              e.tracks[i].seconds ?? 0,
              i + 1,
            )
        ];
        _busy = false;
      });
      return true;
    } catch (_) {
      return false;
    }
  }

  /// A Discogs MASTER groups every pressing of a record and has no tracklist of its own; the style
  /// page hands these out, and they were being read as releases.
  Future<void> _loadDiscogsMaster(int masterId) async {
    try {
      final dg = DiscogsService(context.read<AppSettings>());
      final versions = DiscogsService.orderByPreference(await dg.versionsOf(masterId));
      // Zelfde reden als bij MusicBrainz: de best gerangschikte persing is niet gegarandeerd de
      // persing die nummers oplevert, en dan is de pagina leeg terwijl de plaat wél beschreven is.
      // Drie, want elke persing kost een verzoek uit zestig per minuut.
      for (final v in versions.take(3)) {
        if (await _loadDiscogsRelease(v.id)) return;
      }
    } catch (_) {/* valt door naar de lege pagina */}
    _geenTracklijst();
  }

  /// True zodra deze persing nummers opleverde — zie [_loadMusicBrainzRelease].
  Future<bool> _loadDiscogsRelease(int releaseId) async {
    if (!mounted) return false;
    try {
      final e = await DiscogsService(context.read<AppSettings>()).release(releaseId);
      if (!mounted || e == null || e.tracklist.isEmpty) return false;
      setState(() {
        _tracks = [
          for (var i = 0; i < e.tracklist.length; i++)
            CatalogTrack(
              // No Deezer id exists for these; the index is enough to key a row and to search
              // Soulseek with, which is all this page does with it.
              -(i + 1),
              e.tracklist[i].title,
              widget.artistName,
              e.tracklist[i].seconds ?? 0,
              i + 1,
            )
        ];
        _busy = false;
      });
      return true;
    } catch (_) {
      return false;
    }
  }

  /// Replace Deezer's tracklist with the one from the pressing itself.
  ///
  /// Deezer catalogues the streaming edition, and it names tracks after whichever recording it
  /// licensed: on *Off the Wall* it lists "Rock with You (Single Version)", while the record simply
  /// has "Rock with You". Discogs describes an actual pressing, so its tracklist is the album's.
  ///
  /// Only swapped when the two agree about the SHAPE of the record — same number of tracks. A
  /// different count means a different edition, and renaming your tracks from the wrong one would
  /// be worse than leaving Deezer's names alone.
  Future<void> _preferOfficialTracklist() async {
    if (_tracks.isEmpty || !mounted) return;
    // MusicBrainz first, Discogs as the supplement. MusicBrainz needs no token, so for anyone who
    // has not entered a Discogs one this stops being a guaranteed no-op.
    var titles = <String>[], secs = <int>[];
    // Both read before the first await: after one, this widget may be gone and its context with it.
    final mb = context.read<MusicBrainzService>();
    final settings = context.read<AppSettings>();
    try {
      final hits = await mb.searchReleases(
          widget.artistName, DiscogsService.plainTitle(widget.album.title),
          expectedTracks: _tracks.length);
      if (hits.isNotEmpty) {
        final full = await mb.release(hits.first.mbid);
        final ts = full?.tracks ?? const <MbTrack>[];
        if (ts.length == _tracks.length) {
          titles = [for (final t in ts) t.title];
          secs = [for (final t in ts) t.seconds ?? 0];
          // When the RECORD came out, not when this pressing did — a 2009 reissue of a 1996 album
          // is still a 1996 album. Kept because a download has to be stamped with it, and the
          // search hit this page was opened from carries no date at all.
          _officialYear = full?.albumYear ?? full?.year;
        }
      }
    } catch (_) {/* fall through to Discogs */}

    if (titles.isEmpty) {
      try {
        final e = await DiscogsService(settings)
            .edition(widget.artistName, widget.album.title, expectedTracks: _tracks.length);
        final dg = e?.tracklist ?? const <DiscogsTrack>[];
        if (dg.length == _tracks.length) {
          titles = [for (final t in dg) t.title];
          secs = [for (final t in dg) t.seconds ?? 0];
          _officialYear = e?.albumYear ?? e?.year;
        }
      } catch (_) {/* the Deezer list is a fine fallback */}
    }
    if (!mounted || titles.length != _tracks.length) return;

    // Index-aligned, so a pressing that agrees on the COUNT but not the order would rename every
    // track after the first difference. The running times are the check that they are the same
    // record in the same order; a couple of disagreements is normal, wholesale is not.
    var wrong = 0;
    for (var i = 0; i < titles.length; i++) {
      final a = _tracks[i].durationSec, b = secs[i];
      if (a > 0 && b > 0 && (a - b).abs() > 15) wrong++;
    }
    if (wrong > titles.length / 3) return;

    setState(() {
      _tracks = [
        for (var i = 0; i < _tracks.length; i++)
          CatalogTrack(
            _tracks[i].id,
            _behoudTitel(_tracks[i].title, titles[i]),
            _tracks[i].artist,
            // Keep Deezer's running time when the pressing doesn't state one.
            secs[i] > 0 ? secs[i] : _tracks[i].durationSec,
            _tracks[i].position,
          )
      ];
    });
  }

  /// Welke van de twee titels blijft staan: die van de catalogus of die van de persing?
  ///
  /// **Waarom dit niet altijd de persing is.** Dat wás het, en dat wiste een verschil dat er echt
  /// toe doet. Op *My Songs* van Sting heet elk nummer bij Deezer "… (My Songs Version)" — het zijn
  /// heropnames uit 2019. De persing noemt ze kaal, want bínnen dat album valt er niets te
  /// onderscheiden. Door de persing te volgen stond er "Fields Of Gold" op het scherm, werd daarop
  /// gezocht, en kwamen er honderden kopieën van de plaat uit 1993 terug. De heropname was
  /// onbereikbaar geworden, en niemand kon zien waaróm.
  ///
  /// Het merk blijft staan als het de PLAAT noemt — zie [versieNoemtDeUitgave]. "(My Songs Version)"
  /// op *My Songs* noemt de plaat en is dus identiteit; "(Single Version)" op *Off the Wall* noemt
  /// hem niet en is de ruis waar deze hele vervanging voor bedoeld was. Die blijft dus verdwijnen.
  String _behoudTitel(String vanCatalogus, String vanPersing) {
    if (vanPersing.isEmpty) return vanCatalogus;
    if (versieNoemtDeUitgave(vanCatalogus, widget.album.title)) return vanCatalogus;
    // Noemt de catalogus gasten en de persing niet, dan blijven die gasten staan — zie [featStaart].
    // "Lose Control (feat. Ciara and Fat Man Scoop)" werd hier anders "Lose Control", en dan is niet
    // meer te zien wie er meedoet.
    final gasten = featStaart(vanCatalogus);
    if (gasten.isNotEmpty && featStaart(vanPersing).isEmpty) return '$vanPersing $gasten';
    return vanPersing;
  }

  Future<void> _preloadSoulseek() async {
    if (!mounted) return;
    final soulseek = context.read<SoulseekService>();
    if (!soulseek.available) return;
    setState(() => _slskBusy = true);
    try {
      final r = await soulseek.search('${widget.artistName} ${widget.album.title}', onPartial: (p) {
        if (mounted) setState(() => _albumSlsk = p);
      });
      if (mounted) setState(() { _albumSlsk = r; _slskBusy = false; });
    } catch (_) {
      if (mounted) setState(() => _slskBusy = false);
    }
  }

  /// Pre-loaded Soulseek copies of one track. Empty if the album-wide search didn't cover it.
  /// Deezer's running time is passed along because the title alone can't tell a track from a
  /// medley that contains it, nor from a remix of about the same length.
  List<SoulseekFile> _slskForTitle(CatalogTrack t) => _albumSlsk
      .where((f) => f.isAudio && fileOffersTitle(t.title, t.durationSec, widget.artistName, f.filename, f.durationSec))
      .toList();

  /// The copy of this track already in the library (null if we don't have it). Version markers
  /// are part of the identity, so a Live/Radio-Edit/compilation cut still counts as NOT owned.
  Track? _owned(CatalogTrack t) => context.read<LibraryStore>().ownedTrack(widget.artistName, t.title);

  /// What year the RECORD is from, according to whichever catalogue described it.
  ///
  /// Not from widget.album: a search hit carries no release date, so leaving it out meant DATE was
  /// never written and each downloaded file kept whatever year its uploader had put in — one album
  /// came out of three peers stamped 1996, 1998 and 1999.
  int? _officialYear;

  /// This album, as the official release the sources should be judged against.
  ///
  /// The tracklist here has already been through [_preferOfficialTracklist], so it is MusicBrainz's
  /// or Discogs's idea of the record rather than a streaming catalogue's — and emphatically rather
  /// than a Soulseek uploader's.
  ReleaseAuthority get _release => ReleaseAuthority(
        artist: widget.artistName,
        album: widget.album.title,
        albumArtist: widget.artistName,
        year: _officialYear ?? int.tryParse(widget.album.year ?? ''),
        tracks: [
          for (var i = 0; i < _tracks.length; i++)
            ChoiceTrack('${_numberOf(_tracks[i], i)}', _tracks[i].title, _tracks[i].durationSec)
        ],
      );

  /// This track's number on the record.
  ///
  /// Deezer's album endpoint does not return `track_position` at all — it only exists on the
  /// per-track endpoint — so every position here is 0 and the numbers on screen are really just row
  /// indexes. Taking `position` at face value filed a download as "We've Got It Goin' On.flac"
  /// with no number in front of it. The list is in release order either way, so the index IS the
  /// number whenever the catalogue declines to say.
  int _numberOf(CatalogTrack t, int i) => t.position > 0 ? t.position : i + 1;

  /// What this track IS, from the page the user is looking at.
  ///
  /// This tracklist has already been through _preferOfficialTracklist, so its titles and order come
  /// from MusicBrainz or Discogs rather than from a streaming catalogue — and certainly rather than
  /// from whichever peer serves the file. Soulseek offers this same song as "13 Anywhere for You",
  /// "19. Backstreet Boys - Anywhere For You" and "…The Essential Backstreet Boys - 01 - …";
  /// downloading any of them must still produce track 2 of this album.
  TrackTags _authorityFor(CatalogTrack t, int i) => TrackTags(
        title: t.title,
        artist: widget.artistName,
        album: widget.album.title,
        albumArtist: widget.artistName,
        trackNo: _numberOf(t, i),
        trackTotal: _tracks.length,
        year: _officialYear ?? int.tryParse(widget.album.year ?? ''),
        // De looptijd gaat mee tot in de filer. Zie [TrackTags.seconds].
        seconds: t.durationSec,
      );

  /// Every peer copy of this track worth trying — the preload's, plus a fresh targeted search.
  ///
  /// The album-wide preload often lists a track's copies only from peers that are now offline, so
  /// a download built on it alone can report "no source" while a live copy plainly exists. A search
  /// aimed at this one track finds those live peers. Both sets are filtered to this exact title and
  /// running time, so the pool can never fill with a different song from the same user — which is
  /// what happened when the old path took every audio result the search returned and, after the
  /// query broadened to just the artist, would have downloaded the wrong song under this one's tags.
  Future<List<SoulseekFile>> _slskCandidatesForTrack(CatalogTrack t) async {
    final soulseek = context.read<SoulseekService>();
    final pool = <String, SoulseekFile>{
      for (final f in _slskForTitle(t)) '${f.username}|${f.filename}': f
    };
    try {
      final r = await soulseek.search(soulseekQuery(widget.artistName, t.title));
      for (final f in r) {
        if (!f.isAudio) continue;
        if (!fileOffersTitle(t.title, t.durationSec, widget.artistName, f.filename, f.durationSec)) {
          continue;
        }
        pool.putIfAbsent('${f.username}|${f.filename}', () => f);
      }
    } catch (_) {/* the preload's copies are still worth a try on their own */}
    return pool.values.toList();
  }

  Future<void> _downloadTrack(CatalogTrack t, int i) async {
    final dm = context.read<DownloadManager>();
    final soulseek = context.read<SoulseekService>();
    if (_owned(t) != null) {
      _srcToast(context, '“${t.title}” heb je al — niet opnieuw gedownload.');
      return;
    }
    if (!soulseek.available) {
      _srcToast(context, 'Stel je Soulseek-login in (Instellingen).');
      return;
    }
    if (mounted) _srcToast(context, 'Bron zoeken voor “${t.title}”…');
    final cands = await _slskCandidatesForTrack(t);
    if (!mounted) return;
    if (cands.isEmpty) {
      _srcToast(context, 'Geen Soulseek-bron gevonden voor “${t.title}”.');
      return;
    }
    try {
      final started = await dm.enqueueSoulseekBest(cands,
          key: 'alb:${widget.album.ref.keyPart}:$i', authority: _authorityFor(t, i));
      if (mounted) {
        _srcToast(context, started ? '“${t.title}” via Soulseek…' : '“${t.title}” loopt al — zie Mijn downloads.');
      }
    } catch (e) {
      if (mounted) _srcToast(context, 'Download mislukt: $e');
    }
  }

  void _toggle(int i) => setState(() => _expanded = _expanded == i ? null : i);

  @override
  Widget build(BuildContext context) {
    final al = widget.album;
    return Scaffold(
      backgroundColor: _bg,
      // De spelerbalk hoort op ELKE pagina, niet alleen in de shell.
      //
      // Hij stond op precies twee plekken: het hoofdscherm en de albumpagina. Op de artiest-,
      // persoon-, afspeellijst-, stijl- en online-albumpagina was er dus geen speler in beeld —
      // en omdat de hoes in die balk de ENIGE ingang naar "Nu speelt" is, was dat scherm daar
      // helemaal onbereikbaar. Op de Shield gemeten: negen drukken vanaf Start, en vanaf een
      // gepushte pagina geen enkele weg.
      //
      // In de `bottomNavigationBar`-sleuf en niet als Column: Scaffold legt de body er dan
      // vanzelf boven, en de balk blijft binnen deze route — dus `Navigator.of(context)` in de
      // wachtrij- en speakerknop wijst nog naar de goede plek.
      // GEEN eigen spelerbalk meer. De schil tekent hem, en die staat sinds de binnennavigator
      // ónder deze pagina in plaats van erachter — twee balken zouden er twee zijn.
      // Its own header rather than an AppBar, so nothing was adding the status bar's height —
      // the cover and the title were drawn UNDER the clock and the wifi icons. The album page
      // escaped this only because a SliverAppBar puts that inset in by itself.
      body: SafeArea(
          // A television reports no insets, so SafeArea alone is a no-op there; this is the
          // margin that keeps the back arrow off the part of the picture a set cuts away.
          minimum: tvOverscan,
        bottom: false,
        child: ListView(
        padding: const EdgeInsets.only(bottom: 40),
        children: [
          Padding(
            padding: const EdgeInsets.fromLTRB(16, 16, 20, 8),
            child: Row(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                IconButton(icon: const Icon(Icons.arrow_back_rounded), onPressed: () => Navigator.pop(context)),
                const SizedBox(width: 4),
                _netCover(al.cover, size: 128),
                const SizedBox(width: 16),
                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      const SizedBox(height: 6),
                      Text(al.title, style: const TextStyle(fontSize: 22, fontWeight: FontWeight.w800)),
                      const SizedBox(height: 4),
                      // De naam los van de rest, zodat je van een online album naar de artiest kunt.
                      // Zelfde vorm als de kop van je eigen albumpagina.
                      _maybeFocusable(Row(mainAxisSize: MainAxisSize.min, children: [
                        Flexible(
                            child: ArtistNames(
                                names: [widget.artistName],
                                style: const TextStyle(color: _muted, fontSize: 13))),
                        Flexible(
                          child: Text(
                              '${al.year != null ? " · ${al.year}" : ""}'
                              '${_tracks.isNotEmpty ? " · ${_tracks.length} nummers" : ""}',
                              maxLines: 1,
                              overflow: TextOverflow.ellipsis,
                              style: const TextStyle(color: _muted, fontSize: 13)),
                        ),
                      ])),
                      const SizedBox(height: 12),
                      FilledButton.icon(
                        // The one action of this page, and where the highlight starts on a
                        // television — otherwise the first arrow press finds the back arrow and OK
                        // leaves the record you just opened.
                        autofocus: isTv,
                        style: FilledButton.styleFrom(backgroundColor: _panel2, foregroundColor: Colors.white),
                        icon: Icon(_expanded == _albumLevel ? Icons.expand_less_rounded : Icons.travel_explore_rounded, size: 18),
                        label: const Text('Bronnen voor album'),
                        onPressed: () => _toggle(_albumLevel),
                      ),
                    ],
                  ),
                ),
              ],
            ),
          ),
          if (_expanded == _albumLevel)
            Padding(
              padding: const EdgeInsets.only(bottom: 8),
              child: SourcesView(query: '${widget.artistName} ${al.title}', authority: _release),
            ),
          // Geen beschrijving bij een plaat die deze pagina niet heeft kunnen identificeren.
          //
          // Deze twee zoeken op TEKST — artiest plus titel — terwijl de tracklijst op verwijzing
          // zoekt. Bij Sia / "Titans" leverde de verwijzing niets en de tekstzoektocht een
          // soundtrack van Waxwork Records: je kreeg een lege tracklijst met daarboven het jaartal,
          // het label en de filmcomponisten van een plaat die niet van haar is. Liever niets dan
          // het verkeerde — dat was de klacht.
          if (!_busy && _tracks.isNotEmpty) ...[
            AlbumInfoPanel(
                artist: widget.artistName,
                album: al.title,
                // Zonder dit stond de vormcontrole UIT: DiscogsService.edition weegt alleen op
                // aantal als expectedTracks > 0, en deze pagina gaf altijd nul door.
                trackCount: _tracks.length,
                // En dit aantal is de HELE plaat — het is de tracklijst die hieronder staat, niet
                // wat er van op schijf staat. Alleen daarom mag een te lange uitgave hier afvallen.
                completeTracklist: true),
            CreditsPanel(
                artist: widget.artistName, album: al.title, volledigAantal: _tracks.length),
          ],
          if (_busy)
            const Padding(padding: EdgeInsets.all(30), child: Center(child: CircularProgressIndicator(color: _accent)))
          else if (_tracks.isEmpty)
            const Padding(
                padding: EdgeInsets.all(24),
                child: Text('Geen tracklijst gevonden voor deze uitgave.',
                    style: TextStyle(color: _muted)))
          else
            ..._tracks.asMap().entries.map((e) => _trackRow(e.key, e.value)),
        ],
        ),
      ),
    );
  }

  Widget _trackRow(int i, CatalogTrack t) {
    final open = _expanded == i;
    final soulseekReady = context.read<SoulseekService>().available;
    final srcCount = soulseekReady ? _slskForTitle(t).length : 0;
    return Column(
      children: [
        InkWell(
          onTap: () => _toggle(i),
          child: Container(
            padding: const EdgeInsets.symmetric(horizontal: 24, vertical: 11),
            color: open ? _panel : Colors.transparent,
            child: Row(
              children: [
                SizedBox(
                    width: 26,
                    child: Text('${_numberOf(t, i)}',
                        style: const TextStyle(color: _muted, fontSize: 13))),
                // Which tracks of this record you already have — the gap in the album, at a glance.
                Builder(builder: (context) {
                  final have = context.watch<LibraryStore>().ownedTrack(widget.artistName, t.title) != null;
                  return SizedBox(
                    width: 22,
                    child: have
                        ? const Icon(Icons.check_circle_rounded, size: 14, color: _accent2)
                        : const SizedBox.shrink(),
                  );
                }),
                Expanded(
                    child: Text(t.title,
                        maxLines: titelRegels(context), overflow: TextOverflow.ellipsis,
                        style: const TextStyle(fontSize: 14, fontWeight: FontWeight.w500))),
                // "N bronnen klaar" hint (or a tiny spinner while the album search is still running).
                if (soulseekReady && srcCount > 0)
                  Padding(
                    padding: const EdgeInsets.only(right: 8),
                    child: Text('$srcCount ⌄',
                        style: const TextStyle(color: _accent2, fontSize: 11, fontWeight: FontWeight.w600)),
                  )
                else if (soulseekReady && _slskBusy)
                  const Padding(
                    padding: EdgeInsets.only(right: 8),
                    child: SizedBox(width: 11, height: 11, child: CircularProgressIndicator(strokeWidth: 1.6, color: _muted)),
                  ),
                Text(t.durationLabel, style: const TextStyle(color: _muted, fontSize: 12)),
                if (_owned(t) != null)
                  const Padding(
                    padding: EdgeInsets.all(9),
                    child: Tooltip(
                      message: 'Al in je bibliotheek',
                      child: Icon(Icons.library_add_check_rounded, color: _accent2, size: 19),
                    ),
                  )
                else if (soulseekReady)
                  _downloadControl(context,
                      jobKey: 'alb:${widget.album.ref.keyPart}:$i',
                      onDownload: () => _downloadTrack(t, i),
                      tooltip: 'Download via Soulseek'),
                const SizedBox(width: 2),
                Icon(open ? Icons.expand_less_rounded : Icons.travel_explore_rounded,
                    size: 18, color: open ? _accent : _muted),
              ],
            ),
          ),
        ),
        if (open)
          Padding(
            padding: const EdgeInsets.only(bottom: 8),
            child: SourcesView(
                query: '${widget.artistName} ${t.title}',
                authority: _release,
                track: ChoiceTrack('${_numberOf(t, i)}', t.title, t.durationSec)),
          ),
      ],
    );
  }
}

// ── Settings dialog ──────────────────────────────────────────────────────────
/// Which build is this, and where is it running from?
///
/// Read from the RUNNING executable rather than a constant in the source: a hand-maintained
/// number drifts the moment someone forgets to bump it, and the whole point here is to stop
/// guessing. The install path is shown for the same reason — a second copy left behind
/// elsewhere on disk looks identical until you can see which one you actually opened.
class _AboutSection extends StatefulWidget {
  const _AboutSection();

  @override
  State<_AboutSection> createState() => _AboutSectionState();
}

class _AboutSectionState extends State<_AboutSection> {
  String _version = '…';
  String _path = '';

  @override
  void initState() {
    super.initState();
    _load();
  }

  Future<void> _load() async {
    var version = '?';
    try {
      final info = await PackageInfo.fromPlatform();
      version = info.buildNumber.isEmpty ? info.version : '${info.version}+${info.buildNumber}';
    } catch (_) {/* fall through to the placeholder */}
    if (!mounted) return;
    setState(() {
      _version = version;
      _path = Platform.resolvedExecutable;
    });
  }

  @override
  Widget build(BuildContext context) {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        const Text('Info', style: TextStyle(fontSize: 14, fontWeight: FontWeight.w700)),
        const SizedBox(height: 8),
        Row(
          children: [
            Container(
              padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 5),
              decoration: BoxDecoration(
                color: _accent.withValues(alpha: .16),
                borderRadius: BorderRadius.circular(999),
                border: Border.all(color: _accent.withValues(alpha: .35)),
              ),
              child: Text('DebridMusic $_version',
                  style: const TextStyle(fontSize: 13, fontWeight: FontWeight.w700, color: Colors.white)),
            ),
            const SizedBox(width: 10),
            TvLabelled(
              label: 'Versie kopiëren',
              child: IconButton(
              icon: const Icon(Icons.copy_rounded, size: 15),
              color: _muted,
              tooltip: 'Versie kopiëren',
              onPressed: () {
                Clipboard.setData(ClipboardData(text: 'DebridMusic $_version'));
                ScaffoldMessenger.of(context).showSnackBar(
                  const SnackBar(content: Text('Versie gekopieerd'), duration: Duration(seconds: 2)),
                );
              },
            ),
            ),
          ],
        ),
        if (_path.isNotEmpty) ...[
          const SizedBox(height: 6),
          // Zero-width spaces after each separator: a path has no spaces, so Flutter would
          // otherwise break it after the "C:" and the rest reads as if it started at \Users.
          // Plain Text on a television. SelectableText builds an EditableText, and that takes the
          // four arrows for selection without opening a keyboard to explain why the highlight
          // stopped moving — the worst kind of dead end, at the bottom of Settings where you were
          // heading for "Opslaan". There is nothing to copy a path to on a TV anyway.
          isTv
              ? Text(_path.replaceAll(r'\', '\\\u200B'),
                  style: const TextStyle(color: _muted, fontSize: 11, height: 1.35))
              : SelectableText(_path.replaceAll(r'\', '\\\u200B'),
                  style: const TextStyle(color: _muted, fontSize: 11, height: 1.35)),
        ],
        // Zelf kijken, naast de controle die bij het opstarten loopt.
        //
        // Die eerste slaat een versie over als je daarop geklikt hebt, en biedt hem daarna niet
        // meer aan. Zonder deze knop is er dan geen weg terug \u2014 daarom negeert hij dat expres.
        if (Updater.kanHier) ...[
          const SizedBox(height: 10),
          Row(children: [
            OutlinedButton.icon(
              onPressed: _zoeken ? null : _zoekUpdate,
              icon: _zoeken
                  ? const SizedBox(
                      width: 14, height: 14, child: CircularProgressIndicator(strokeWidth: 2))
                  : const Icon(Icons.system_update_alt_rounded, size: 16),
              label: Text(_zoeken ? 'Bezig met kijken\u2026' : 'Controleer op updates'),
            ),
          ]),
        ],
      ],
    );
  }

  bool _zoeken = false;

  Future<void> _zoekUpdate() async {
    setState(() => _zoeken = true);
    final uitgave = await const Updater().zoek(negeerOvergeslagen: true);
    if (!mounted) return;
    setState(() => _zoeken = false);
    if (uitgave == null) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Je hebt de nieuwste versie.'), duration: Duration(seconds: 3)),
      );
      return;
    }
    await toonUpdate(context, uitgave);
  }
}

/// Sharing this library with the Mac, the iPad and the Shield.
///
/// The address and the token are the whole pairing story, so they are shown plainly and can be
/// copied — and offered as a QR code, because typing a 32-character token on a TV remote is not
/// something anyone should be asked to do.
class _SharingSection extends StatefulWidget {
  const _SharingSection();

  @override
  State<_SharingSection> createState() => _SharingSectionState();
}

class _SharingSectionState extends State<_SharingSection> {
  late final TextEditingController _root;
  bool _showToken = false;

  // Signing this PC in to the account. The same two fields as LoginScreen, but a different job: a
  // Mac signs in to FIND the music, this machine signs in to be findable.
  final _email = TextEditingController();
  final _password = TextEditingController();
  bool _cloudBusy = false;
  bool _cloudRegister = false;
  String? _cloudError;

  @override
  void initState() {
    super.initState();
    _root = TextEditingController(text: context.read<LibraryStore>().rootPath);
  }

  @override
  void dispose() {
    _root.dispose();
    _email.dispose();
    _password.dispose();
    super.dispose();
  }

  /// Sign in (or register) and start publishing straight away.
  ///
  /// The publish is not left to the next launch: the reason to sign in here is so a Mac or an iPad
  /// can find this PC, and "restart the app first" is not an answer to that.
  Future<void> _cloudSubmit() async {
    final email = _email.text.trim();
    final password = _password.text;
    if (email.isEmpty || password.isEmpty) {
      setState(() => _cloudError = 'Vul je e-mailadres en wachtwoord in.');
      return;
    }
    setState(() {
      _cloudBusy = true;
      _cloudError = null;
    });
    final cloud = context.read<CloudSession>();
    try {
      if (_cloudRegister) {
        await cloud.register(email, password);
      } else {
        await cloud.signIn(email, password);
      }
      if (!mounted) return;
      await publishAsOwner(cloud, context.read<AppSettings>(), context.read<LanSharing>(),
          context.read<LibraryStore>(), context.read<DownloadManager>());
      if (!mounted) return;
      // Not kept in memory a moment longer than the request needs them.
      _email.clear();
      _password.clear();
      setState(() => _cloudBusy = false);
    } catch (e) {
      if (!mounted) return;
      setState(() {
        _cloudBusy = false;
        _cloudError = '$e';
      });
    }
  }

  /// This PC's account: signed in, or the form to sign in with.
  Widget _cloudPanel(CloudSession cloud) {
    // A build with no Firebase project configured cannot sign in to anything, and saying so is
    // better than a form that always fails. The pairing code below still works.
    if (cloud.state == CloudState.disabled) {
      return const Padding(
        padding: EdgeInsets.only(bottom: 14),
        child: Text(
          'Deze build heeft geen cloud-project, dus inloggen kan niet. '
          'Je apparaten koppelen met de code hieronder werkt gewoon.',
          style: TextStyle(color: _muted, fontSize: 11.5, height: 1.35),
        ),
      );
    }

    final title = Row(
      children: [
        const Icon(Icons.cloud_outlined, size: 16, color: _muted),
        const SizedBox(width: 6),
        const Text('Account', style: TextStyle(fontSize: 14, fontWeight: FontWeight.w700)),
        if (cloud.state == CloudState.restoring) ...[
          const SizedBox(width: 8),
          const SizedBox(width: 11, height: 11, child: CircularProgressIndicator(strokeWidth: 1.6)),
        ],
      ],
    );

    if (cloud.isSignedIn) {
      return Padding(
        padding: const EdgeInsets.only(bottom: 16),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            title,
            const SizedBox(height: 6),
            Text(cloud.user?.email ?? 'Ingelogd',
                style: const TextStyle(fontSize: 13, fontWeight: FontWeight.w600)),
            const SizedBox(height: 2),
            Text(
              cloud.lastError != null
                  ? 'Deze pc kon zich niet aanmelden: ${cloud.lastError}'
                  : 'Deze pc meldt zich aan onder dit account. Log op je Mac, iPad of Shield in met '
                      'hetzelfde account — dan vinden ze hem zonder code.',
              style: TextStyle(
                  color: cloud.lastError != null ? const Color(0xFFFF6B6B) : _muted,
                  fontSize: 11.5,
                  height: 1.35),
            ),
            const SizedBox(height: 8),
            OutlinedButton.icon(
              onPressed: () async {
                final serverId = context.read<AppSettings>().serverId;
                // Tell the account this PC is going away before forgetting the account, or the
                // devices keep seeing a server that will never answer again.
                if (serverId.isNotEmpty) {
                  try {
                    await cloud.goOffline(serverId);
                  } catch (_) {/* signing out matters more than the last word */}
                }
                await cloud.signOut();
              },
              icon: const Icon(Icons.logout_rounded, size: 16),
              label: const Text('Uitloggen'),
            ),
          ],
        ),
      );
    }

    return Padding(
      padding: const EdgeInsets.only(bottom: 16),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          title,
          const SizedBox(height: 4),
          const Text(
            'Log in en je Mac, iPad en Shield vinden deze pc zonder code — ook op een netwerk '
            'dat automatisch zoeken blokkeert. Begin hier: een apparaat kan pas verbinden als '
            'deze pc onder het account bekend is.',
            style: TextStyle(color: _muted, fontSize: 11.5, height: 1.35),
          ),
          const SizedBox(height: 10),
          Row(
            children: [
              Expanded(
                child: TextField(
                  controller: _email,
                  enabled: !_cloudBusy,
                  autofillHints: const [AutofillHints.email],
                  keyboardType: TextInputType.emailAddress,
                  decoration: const InputDecoration(
                    labelText: 'E-mailadres',
                    isDense: true,
                    border: OutlineInputBorder(),
                  ),
                ),
              ),
              const SizedBox(width: 8),
              Expanded(
                child: TextField(
                  controller: _password,
                  enabled: !_cloudBusy,
                  obscureText: true,
                  autofillHints: [_cloudRegister ? AutofillHints.newPassword : AutofillHints.password],
                  onSubmitted: (_) => _cloudBusy ? null : _cloudSubmit(),
                  decoration: const InputDecoration(
                    labelText: 'Wachtwoord',
                    isDense: true,
                    border: OutlineInputBorder(),
                  ),
                ),
              ),
            ],
          ),
          if (_cloudError != null) ...[
            const SizedBox(height: 8),
            Text(_cloudError!,
                style: const TextStyle(color: Color(0xFFFF6B6B), fontSize: 12, height: 1.35)),
          ],
          const SizedBox(height: 10),
          Row(
            children: [
              FilledButton(
                style: FilledButton.styleFrom(backgroundColor: _accent),
                onPressed: _cloudBusy ? null : _cloudSubmit,
                child: Text(_cloudBusy
                    ? 'Bezig…'
                    : (_cloudRegister ? 'Account aanmaken' : 'Inloggen')),
              ),
              const SizedBox(width: 8),
              TextButton(
                onPressed: _cloudBusy
                    ? null
                    : () => setState(() {
                          _cloudRegister = !_cloudRegister;
                          _cloudError = null;
                        }),
                child: Text(_cloudRegister
                    ? 'Ik heb al een account'
                    : 'Nog geen account? Maak er een'),
              ),
            ],
          ),
          const Divider(height: 26),
        ],
      ),
    );
  }

  void _copy(String value, String what) {
    Clipboard.setData(ClipboardData(text: value));
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(content: Text('$what gekopieerd'), duration: const Duration(seconds: 2)),
    );
  }

  /// What this panel says on a device that reads someone else's library: which PC, whether it is
  /// answering, and the way back out.
  Widget _connectedPanel(ClientSession session) {
    final endpoint = session.endpoint;
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        const Text('Verbonden met je pc',
            style: TextStyle(fontSize: 14, fontWeight: FontWeight.w700)),
        const SizedBox(height: 12),
        Container(
          padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 12),
          decoration: BoxDecoration(color: _panel2, borderRadius: BorderRadius.circular(12)),
          child: Row(children: [
            Icon(Icons.computer_rounded,
                color: session.lastError == null ? _accent2 : Colors.orangeAccent, size: 20),
            const SizedBox(width: 12),
            Expanded(
              child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                Text(session.serverName,
                    style: const TextStyle(fontWeight: FontWeight.w600, fontSize: 13.5)),
                Text(
                  // Deliberately verbatim: a port is a number you type, not one to be shown as
                  // "47.820" by whatever the device's locale thinks a thousands separator is.
                  //
                  // **HET ADRES OP ZIJN EIGEN REGEL**, en dat is geen opmaak maar een reparatie.
                  // Alles achter elkaar is een kleine vijftig tekens, en dat past niet naast de
                  // knop "Ververs". Flutter breekt een woord dat niet past dan op een willekeurig
                  // teken — en dat viel op 28-08-2026 middenin het poortnummer: er stond
                  // "100.97.101.113:4782" en op de volgende regel "0 · 1056 nummers". Een adres
                  // dat je moet kunnen overtikken mag nooit half op een regel eindigen.
                  endpoint == null
                      ? ''
                      : '${endpoint.baseUrl.host}:${endpoint.baseUrl.port}\n'
                          '${session.library.tracks.length} nummers'
                          // DE VERSIE VAN DE PC, en dat is geen sieraad.
                          //
                          // Bij een koppeling doet de pc het zoeken en het downloaden. Wat je hier
                          // ziet zijn zíjn taken en zíjn foutmeldingen; de versie bovenaan dit
                          // scherm is die van DIT toestel en zegt daar niets over. Op 27-08-2026
                          // stond op de Mac 3.9.223 — mét de reparatie — en verscheen toch een
                          // melding die in die versie niet meer bestaat. Hij kwam van de pc.
                          '${session.serverVersie.isEmpty ? '' : ' · ${session.serverVersie}'}',
                  style: const TextStyle(color: _muted, fontSize: 12),
                ),
              ]),
            ),
            TextButton(
              onPressed: () => session.refreshNow(),
              child: const Text('Ververs', style: TextStyle(color: _muted)),
            ),
          ]),
        ),
        if (session.lastError != null) ...[
          const SizedBox(height: 10),
          Text(session.lastError!,
              style: const TextStyle(color: Colors.orangeAccent, fontSize: 12)),
        ],
        const SizedBox(height: 14),
        // Meteen onder de versie van de pc, want dat is waar dit over gaat. Zie [PcBijwerkenKnop]
        // — hij tekent niets zolang er niets te melden valt.
        PcBijwerkenKnop(session: session),
        const SizedBox(height: 14),
        Text(
          'Je bibliotheek, je covers en je bewerkingen komen van je pc. Aanpassen doe je daar; '
          'hier zie je het resultaat vanzelf terug.',
          style: TextStyle(color: _muted.withValues(alpha: .85), fontSize: 12, height: 1.45),
        ),
        // Alleen hier: dit gaat over wat er over de lijn komt, en een gekoppeld toestel is het
        // enige dat een lijn heeft. De Shield hangt aan een kabel of aan de wifi thuis en heeft
        // geen databundel — daar zou de keuze alleen maar in de weg staan.
        if (!isTv) ...[
          const SizedBox(height: 18),
          const Divider(height: 1, color: _panel2),
          const SizedBox(height: 14),
          const StroomkwaliteitKeuze(),
        ],
        const SizedBox(height: 14),
        OutlinedButton.icon(
          onPressed: () async {
            final yes = await showDialog<bool>(
              context: context,
              builder: (c) => AlertDialog(
                backgroundColor: _panel,
                title: const Text('Koppeling verbreken?'),
                content: const Text(
                    'Dit apparaat vergeet je pc. Je muziek blijft gewoon op de pc staan.'),
                actions: [
                  TextButton(
                      onPressed: () => Navigator.pop(c, false), child: const Text('Annuleer')),
                  FilledButton(
                      onPressed: () => Navigator.pop(c, true), child: const Text('Verbreken')),
                ],
              ),
            );
            if (yes == true) await session.unpair();
          },
          icon: const Icon(Icons.link_off_rounded, size: 18),
          label: const Text('Koppeling verbreken'),
        ),
      ],
    );
  }

  /// Een adres met erbij waar het toe dient. De uitleg staat er altijd, ook bij het thuisadres:
  /// "192.168.0.117" zegt uit zichzelf niets over of je gsm er onderweg mee verder kan.
  Widget _adresRegel(String url, String uitleg, {bool hoofdzaak = false}) => InkWell(
        onTap: () => _copy(url, 'Adres'),
        child: Padding(
          padding: const EdgeInsets.symmetric(vertical: 3),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Row(
                mainAxisSize: MainAxisSize.min,
                children: [
                  if (hoofdzaak) ...[
                    const Icon(Icons.public_rounded, size: 13, color: Color(0xFF6BCB8B)),
                    const SizedBox(width: 5),
                  ],
                  Text(url,
                      style: TextStyle(
                          fontSize: 13,
                          fontWeight: FontWeight.w600,
                          color: hoofdzaak ? const Color(0xFF6BCB8B) : null)),
                  const SizedBox(width: 6),
                  const Icon(Icons.copy_rounded, size: 13, color: _muted),
                ],
              ),
              Text(uitleg, style: const TextStyle(color: _muted, fontSize: 10.5)),
            ],
          ),
        ),
      );

  @override
  Widget build(BuildContext context) {
    final sharing = context.watch<LanSharing>();
    final settings = context.read<AppSettings>();
    final session = context.watch<ClientSession>();

    // On a Mac or an iPad this panel is the other way round: this device does not share a library,
    // it reads one. Offering a server switch here would let you turn on a server with nothing
    // behind it.
    if (!session.owner) return _connectedPanel(session);

    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        // The account comes first: it is what a device uses to find this PC, and the code below is
        // the fallback for when it cannot.
        _cloudPanel(context.watch<CloudSession>()),
        Row(
          children: [
            const Expanded(
              child: Text('Delen met andere apparaten',
                  style: TextStyle(fontSize: 14, fontWeight: FontWeight.w700)),
            ),
            Switch(
              value: settings.lanEnabled,
              activeThumbColor: _accent,
              onChanged: (on) async {
                settings.lanEnabled = on;
                await settings.save();
                await sharing.applySettings();
              },
            ),
          ],
        ),
        const Text(
          'Zet dit aan en je Mac, iPad en Shield zien dezelfde bibliotheek — '
          'inclusief je eigen covers en persingen.',
          style: TextStyle(color: _muted, fontSize: 11.5, height: 1.35),
        ),
        const SizedBox(height: 14),
        Row(
          children: [
            const Expanded(
              child: Text('Albuminfo vooraf ophalen',
                  style: TextStyle(fontSize: 14, fontWeight: FontWeight.w700)),
            ),
            Switch(
              value: settings.warmFacts,
              activeThumbColor: _accent,
              onChanged: (on) async {
                settings.warmFacts = on;
                await settings.save();
                // The warmer reads the setting before every album, so switching off stops the
                // sweep where it is rather than at the end of the library.
              },
            ),
          ],
        ),
        const Text(
          'Deze pc zoekt van elke plaat de persing en de officiële tracklijst op vóórdat je hem '
          'opent, zodat een album nooit meer laat wachten. Eén keer per plaat, en elk toestel in '
          'huis heeft er wat aan. Hij schrijft bij elk album een klein bestandje in die albummap, '
          'zodat je metadata meeverhuist met je muziek.',
          style: TextStyle(color: _muted, fontSize: 11.5, height: 1.35),
        ),
        if (settings.lanEnabled) ...[
          const SizedBox(height: 10),
          if (sharing.error != null)
            Text(sharing.error!, style: const TextStyle(color: Color(0xFFFF6B6B), fontSize: 12))
          else if (!sharing.running)
            const Text('Starten…', style: TextStyle(color: _muted, fontSize: 12))
          else ...[
            Row(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      const Text('Adres', style: TextStyle(color: _muted, fontSize: 11.5)),
                      // Twee soorten adres, en het verschil is niet klein: het ene stopt aan de
                      // voordeur, het andere gaat mee op 5G. Ze door elkaar in een lijstje zetten
                      // is precies hoe je een gsm koppelt aan een adres dat buitenshuis zwijgt.
                      if (sharing.remoteUrl != null)
                        _adresRegel(sharing.remoteUrl!, 'werkt overal, ook op mobiele data',
                            hoofdzaak: true),
                      for (final url in sharing.homeAddresses)
                        _adresRegel(url, 'alleen thuis op dit netwerk'),
                      if (sharing.remoteUrl == null)
                        const Padding(
                          padding: EdgeInsets.only(top: 4),
                          child: Text(
                            'Van buitenshuis is deze pc nu niet bereikbaar. Zet Tailscale aan op '
                            'de pc én op je gsm — dan verschijnt hier het adres dat overal werkt.',
                            style: TextStyle(color: Color(0xFFE0A44A), fontSize: 11, height: 1.35),
                          ),
                        ),
                      const SizedBox(height: 8),
                      const Text('Toegangscode', style: TextStyle(color: _muted, fontSize: 11.5)),
                      Row(
                        children: [
                          Flexible(
                            child: Text(
                              _showToken ? sharing.token : '•' * 16,
                              style: const TextStyle(fontSize: 13, fontFamily: 'monospace'),
                              overflow: TextOverflow.ellipsis,
                            ),
                          ),
                          TvLabelled(
                            label: _showToken ? 'Verbergen' : 'Tonen',
                            child: IconButton(
                            icon: Icon(_showToken ? Icons.visibility_off_rounded : Icons.visibility_rounded,
                                size: 15),
                            color: _muted,
                            tooltip: _showToken ? 'Verbergen' : 'Tonen',
                            onPressed: () => setState(() => _showToken = !_showToken),
                          ),
                          ),
                          TvLabelled(
                            label: 'Code kopiëren',
                            child: IconButton(
                            icon: const Icon(Icons.copy_rounded, size: 15),
                            color: _muted,
                            tooltip: 'Code kopiëren',
                            onPressed: () => _copy(sharing.token, 'Toegangscode'),
                          ),
                          ),
                        ],
                      ),
                      Text(
                        sharing.discoverable
                            ? 'Je apparaten vinden deze pc vanzelf.'
                            : 'Automatisch vinden lukt niet — vul het adres hierboven met de hand in.',
                        style: const TextStyle(color: _muted, fontSize: 11, height: 1.35),
                      ),
                    ],
                  ),
                ),
                if (sharing.pairingCode != null) ...[
                  const SizedBox(width: 14),
                  // White backing on purpose: a QR on a dark panel is unreadable to most scanners.
                  Container(
                    padding: const EdgeInsets.all(6),
                    decoration: BoxDecoration(
                      color: Colors.white,
                      borderRadius: BorderRadius.circular(8),
                    ),
                    child: QrImageView(
                      data: sharing.pairingCode!,
                      size: 96,
                      padding: EdgeInsets.zero,
                    ),
                  ),
                ],
              ],
            ),
            const SizedBox(height: 10),
            // Pairing by six digits, because the alternative is typing 32 hex characters on a
            // TV remote with an on-screen keyboard.
            if (sharing.pairingCodeDigits != null)
              Row(
                children: [
                  for (final digit in sharing.pairingCodeDigits!.split(''))
                    Container(
                      margin: const EdgeInsets.only(right: 6),
                      padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 7),
                      decoration: BoxDecoration(
                        color: _accent.withValues(alpha: .16),
                        borderRadius: BorderRadius.circular(7),
                        border: Border.all(color: _accent.withValues(alpha: .35)),
                      ),
                      child: Text(digit,
                          style: const TextStyle(
                              fontSize: 18, fontWeight: FontWeight.w700, color: Colors.white)),
                    ),
                  const SizedBox(width: 6),
                  TextButton(
                    onPressed: sharing.stopPairing,
                    style: TextButton.styleFrom(
                        foregroundColor: _muted, textStyle: const TextStyle(fontSize: 12)),
                    child: const Text('Klaar'),
                  ),
                ],
              )
            else
              Row(
                children: [
                  FilledButton.icon(
                    style: FilledButton.styleFrom(
                        backgroundColor: _accent, textStyle: const TextStyle(fontSize: 12.5)),
                    onPressed: sharing.startPairing,
                    icon: const Icon(Icons.add_link_rounded, size: 16),
                    label: const Text('Apparaat koppelen'),
                  ),
                  const SizedBox(width: 8),
                  TextButton.icon(
                    onPressed: () async {
                      final ok = await _confirmRotate();
                      if (ok) await sharing.rotateToken();
                    },
                    icon: const Icon(Icons.autorenew_rounded, size: 15),
                    label: const Text('Nieuwe toegangscode'),
                    style: TextButton.styleFrom(
                        foregroundColor: _muted, textStyle: const TextStyle(fontSize: 12)),
                  ),
                ],
              ),
            if (sharing.pairingCodeDigits != null)
              const Padding(
                padding: EdgeInsets.only(top: 4),
                child: Text('Typ deze zes cijfers op je Shield of iPad. Vijf minuten geldig.',
                    style: TextStyle(color: _muted, fontSize: 11, height: 1.35)),
              ),
          ],
        ],
        const SizedBox(height: 12),
        const Text('Muziekmap', style: TextStyle(color: _muted, fontSize: 12.5)),
        const SizedBox(height: 5),
        Row(
          children: [
            Expanded(
              child: TextField(
                controller: _root,
                style: const TextStyle(fontSize: 13),
                decoration: InputDecoration(
                  isDense: true,
                  filled: true,
                  fillColor: kVerzonken,
                  border: OutlineInputBorder(
                      borderRadius: BorderRadius.circular(9),
                      borderSide: const BorderSide(color: _line)),
                  enabledBorder: OutlineInputBorder(
                      borderRadius: BorderRadius.circular(9),
                      borderSide: const BorderSide(color: _line)),
                  focusedBorder: OutlineInputBorder(
                      borderRadius: BorderRadius.circular(9),
                      borderSide: const BorderSide(color: _accent)),
                ),
              ),
            ),
            const SizedBox(width: 8),
            TextButton(
              onPressed: () async {
                final path = _root.text.trim();
                if (path.isEmpty) return;
                final lib = context.read<LibraryStore>();
                settings.musicRoot = path;
                await settings.save();
                lib.rootPath = path;
                await lib.scan();
              },
              style: TextButton.styleFrom(foregroundColor: _accent),
              child: const Text('Opnieuw scannen'),
            ),
          ],
        ),
      ],
    );
  }

  Future<bool> _confirmRotate() async {
    final ok = await showDialog<bool>(
      context: context,
      builder: (_) => AlertDialog(
        backgroundColor: _panel,
        title: const Text('Nieuwe toegangscode?',
            style: TextStyle(fontSize: 16, fontWeight: FontWeight.w700)),
        content: const Text(
          'Je Mac, iPad en Shield verliezen de verbinding en moeten opnieuw gekoppeld worden.',
          style: TextStyle(fontSize: 13, height: 1.4),
        ),
        actions: [
          TextButton(
              autofocus: isTv,
              onPressed: () => Navigator.pop(context, false),
              child: const Text('Annuleren')),
          FilledButton(
            style: FilledButton.styleFrom(backgroundColor: _accent),
            onPressed: () => Navigator.pop(context, true),
            child: const Text('Vervangen'),
          ),
        ],
      ),
    );
    return ok ?? false;
  }
}

class SettingsDialog extends StatefulWidget {
  const SettingsDialog({super.key});
  @override
  State<SettingsDialog> createState() => _SettingsDialogState();
}

class _SettingsDialogState extends State<SettingsDialog> {
  late final TextEditingController _discogs, _torbox, _slskUser, _slskPass, _lastfm, _anthropic, _anthropicWs, _rtUser, _rtPass, _slskPort, _acoustid, _tidalId, _tidalSecret, _torznabUrl, _torznabKey, _redacted;

  @override
  void initState() {
    super.initState();
    final s = context.read<AppSettings>();
    _discogs = TextEditingController(text: s.discogsToken);
    _torbox = TextEditingController(text: s.torboxToken);
    _slskUser = TextEditingController(text: s.soulseekUser);
    _slskPass = TextEditingController(text: s.soulseekPass);
    _slskPort = TextEditingController(text: s.soulseekPort > 0 ? s.soulseekPort.toString() : "");
    _lastfm = TextEditingController(text: s.lastfmKey);
    _anthropic = TextEditingController(text: s.anthropicKey);
    _anthropicWs = TextEditingController(text: s.anthropicWorkspace);
    _acoustid = TextEditingController(text: s.acoustidKey);
    _tidalId = TextEditingController(text: s.tidalClientId);
    _tidalSecret = TextEditingController(text: s.tidalClientSecret);
    _rtUser = TextEditingController(text: s.rutrackerUser);
    _rtPass = TextEditingController(text: s.rutrackerPass);
    _torznabUrl = TextEditingController(text: s.torznabUrl);
    _torznabKey = TextEditingController(text: s.torznabKey);
    _redacted = TextEditingController(text: s.redactedKey);
  }

  bool _testing = false;
  bool _rtBusy = false;

  /// De uitkomst van "Verbinding proberen" bij de eigen indexers.
  ///
  /// Meteen proberen in plaats van bij de eerstvolgende zoekopdracht: een adres dat je bewaart
  /// zonder het te proberen is een instelling waarvan je pas veel later hoort dat hij niets deed.
  bool _fsBezig = false;

  /// Een vers Cloudflare-koekje halen zonder plakwerk.
  ///
  /// De uitkomst komt als melding onderin, want dit is precies het soort knop waarvan je anders niet
  /// weet of hij iets deed: het koekje is onzichtbaar, en "het werkt weer" merk je pas een
  /// zoekopdracht later.
  Future<void> _versKoekjeViaFlareSolverr() async {
    setState(() => _fsBezig = true);
    final rt = context.read<OnlineService>().rutracker;
    final uit = await rt.ververViaFlareSolverr();
    if (!mounted) return;
    setState(() => _fsBezig = false);
    ScaffoldMessenger.of(context).showSnackBar(SnackBar(
      content: Text(uit.ok
          ? 'Vers koekje opgehaald en getoetst — RuTracker doet het weer.'
          : (uit.error ?? 'Het lukte niet.')),
      duration: const Duration(seconds: 6),
    ));
  }

  bool _torznabBusy = false;
  bool _torznabOk = false;
  String _torznabUit = '';

  /// Het adres en de sleutel uit de VELDEN proberen, niet uit de bewaarde instellingen.
  ///
  /// Anders moet je eerst opslaan om te kunnen proberen, en dan staat er een adres bewaard waarvan
  /// je nog niet weet of het klopt.
  bool _redBusy = false;
  bool _redOk = false;
  String _redUit = '';

  /// De sleutel van Redacted proberen, en bij succes meteen bewaren.
  ///
  /// Zelfde vorm als de proef hierboven, en om dezelfde reden: een sleutel die je invult zonder hem
  /// te proberen is een instelling waarvan je pas bij de volgende zoekopdracht hoort dat hij niets
  /// deed — en bij een besloten tracker weet je dan nog steeds niet of het aan de sleutel lag of aan
  /// zijn rechten.
  Future<void> _proefRedacted() async {
    final echte = context.read<AppSettings>();
    final sleutel = _redacted.text.trim();
    setState(() {
      _redBusy = true;
      _redUit = '';
    });
    try {
      final uit = await RedactedApi(() => sleutel).proef();
      if (!mounted) return;
      setState(() {
        _redOk = uit.ok;
        _redUit = uit.reden;
      });
      if (uit.ok) {
        echte.redactedKey = sleutel;
        await echte.save();
      }
    } finally {
      if (mounted) setState(() => _redBusy = false);
    }
  }

  Future<void> _proefTorznab() async {
    final echte = context.read<AppSettings>();
    final proef = AppSettings()
      ..torznabUrl = _torznabUrl.text.trim()
      ..torznabKey = _torznabKey.text.trim();
    setState(() {
      _torznabBusy = true;
      _torznabUit = '';
    });
    try {
      final uit = await TorznabSource(proef).proef();
      if (!mounted) return;
      setState(() {
        _torznabOk = uit.ok;
        _torznabUit = uit.reden;
      });
      // Klopt het, dan meteen bewaren: dan doet hij mee aan je volgende zoekopdracht zonder dat je
      // eerst nog op Opslaan moet denken.
      if (uit.ok) {
        echte.torznabUrl = proef.torznabUrl;
        echte.torznabKey = proef.torznabKey;
        await echte.save();
      }
    } finally {
      if (mounted) setState(() => _torznabBusy = false);
    }
  }

  /// De echtheidsveegbeurt: draait hij, hoe ver, en wat kwam eruit.
  bool _echtBusy = false;
  int _echtDone = 0, _echtTotal = 0;
  String? _echtResult;

  Future<void> _meetEchtheid() async {
    final lib = context.read<LibraryStore>();
    setState(() {
      _echtBusy = true;
      _echtResult = null;
      _echtDone = 0;
      _echtTotal = lib.tracks.where((t) => t.isFlac).length;
    });
    ({int betrapt, int onbeoordeelbaar, int onderzocht}) uit;
    try {
      uit = await lib.meetEchtheid(onProgress: (done, total) {
        // Eén hertekening per bestand zou de lijst laten stotteren; elke twintig is genoeg om het
        // getal te laten lopen. Zelfde afweging als bij de dubbelveger hierboven.
        if (!mounted || (done % 20 != 0 && done != total)) return;
        setState(() {
          _echtDone = done;
          _echtTotal = total;
        });
      });
    } catch (e) {
      if (!mounted) return;
      setState(() {
        _echtBusy = false;
        _echtResult = 'Meten mislukt: $e';
      });
      return;
    }
    if (!mounted) return;
    setState(() => _echtBusy = false);
    if (uit.onderzocht == 0) {
      setState(() => _echtResult =
          'ffmpeg ontbreekt — zet ffmpeg.exe in C:\\ffmpeg\\bin of naast de app om dit te gebruiken.');
      return;
    }
    // Het totaal hoort erbij, ook het deel dat niet te beoordelen was. Alleen de betrapten tonen zou
    // suggereren dat de rest onderzocht én goedgekeurd is, en dat is niet hetzelfde.
    setState(() => _echtResult = '${uit.onderzocht} onderzocht · ${uit.betrapt} betrapt · '
        '${uit.onbeoordeelbaar} niet te beoordelen (te kort, te stil of geen 44,1 kHz)');
    if (uit.betrapt > 0 && mounted) {
      await showDialog<void>(
          context: context,
          builder: (_) => EchtheidDialog(items: context.read<LibraryStore>().betrapteBestanden()));
    }
  }

  /// The listen-for-duplicates pass: whether it is running, how far, and what it came to.
  bool _dupeBusy = false;
  int _dupeDone = 0, _dupeTotal = 0;
  String? _dupeResult;

  Future<void> _findSoundDupes() async {
    final lib = context.read<LibraryStore>();
    setState(() {
      _dupeBusy = true;
      _dupeResult = null;
      _dupeDone = 0;
      _dupeTotal = lib.tracks.length;
    });
    List<SameRecordingPair> paren;
    try {
      paren = await lib.duplicatesEverywhere(onProgress: (done, total) {
        // Every file would be a rebuild per fingerprint; a tenth of the library is enough for the
        // number to move and cheap enough not to matter.
        if (!mounted || (done % 20 != 0 && done != total)) return;
        setState(() {
          _dupeDone = done;
          _dupeTotal = total;
        });
      });
    } catch (e) {
      if (!mounted) return;
      setState(() {
        _dupeBusy = false;
        _dupeResult = 'Zoeken mislukt: $e';
      });
      return;
    }
    if (!mounted) return;
    setState(() => _dupeBusy = false);
    if (paren.isEmpty && !Fingerprinter().available) {
      setState(() => _dupeResult = 'fpcalc ontbreekt — herinstalleer de app om dit te gebruiken.');
      return;
    }
    final done = await showDialog<bool>(
        context: context, builder: (_) => SoundDuplicatesDialog(pairs: paren));
    if (!mounted) return;
    setState(() => _dupeResult = done == true
        ? 'Opgeruimd — kijk in $dupeFolder als je iets terug wil.'
        : '${paren.length} ${paren.length == 1 ? 'paar' : 'paren'} gevonden');
  }
  bool _tidying = false;
  String? _tidyResult;
  final Map<String, ConnResult> _conn = {};

  /// One focus node per field, made on demand by [_field].
  ///
  /// Eight text fields on one screen, and on a television every one of them opens the leanback
  /// keyboard the moment it takes focus — after which the keyboard owns all four arrows and the
  /// only way out is BACK, which closes the settings and discards everything typed. So they are
  /// skipped when arrowing and entered on purpose, and the nodes have to be kept somewhere.
  final _fieldFocus = <TextEditingController, FocusNode>{};

  /// De scroller van het middenstuk, alleen zodat de balk ernaast altijd te zien is — en daarvoor
  /// wil `Scrollbar` een controller die hij zeker kent.
  final _rol = ScrollController();

  @override
  void dispose() {
    _rol.dispose();
    _discogs.dispose();
    _torbox.dispose();
    _slskUser.dispose();
    _slskPass.dispose();
    _slskPort.dispose();
    _lastfm.dispose();
    _anthropic.dispose();
    _anthropicWs.dispose();
    _acoustid.dispose();
    _tidalId.dispose();
    _tidalSecret.dispose();
    _rtUser.dispose();
    _rtPass.dispose();
    for (final n in _fieldFocus.values) {
      n.dispose();
    }
    super.dispose();
  }

  /// Sort the app's download folder into Albums/Singles/Compilaties per artist and drop exact
  /// duplicate tracks (best format/size wins). Never touches the user's own collection.
  Future<void> _tidyDownloads() async {
    final lib = context.read<LibraryStore>();
    setState(() {
      _tidying = true;
      _tidyResult = null;
    });
    try {
      final root = '${lib.rootPath}${Platform.pathSeparator}DebridMusic Downloads';
      final report = await tidyDownloads(root);
      await lib.scan();
      if (mounted) setState(() => _tidyResult = 'Klaar — $report');
    } catch (e) {
      if (mounted) setState(() => _tidyResult = 'Opruimen mislukt: $e');
    } finally {
      if (mounted) setState(() => _tidying = false);
    }
  }

  /// Test the credentials as currently typed (without saving to disk).
  Future<void> _testAll() async {
    final real = context.read<AppSettings>();
    final probe = AppSettings()
      // A throwaway that must never reach the disk. It has never seen the TIDAL tokens, the LAN
      // token, the server id or the music folder, so one save() from anywhere down this path would
      // write those away as empty. Today nothing on this path saves; this is so that stays true.
      ..readOnly = true
      ..torboxToken = _torbox.text.trim()
      ..discogsToken = _discogs.text.trim()
      ..soulseekUser = _slskUser.text.trim()
      ..soulseekPass = _slskPass.text.trim()
      ..soulseekPort = int.tryParse(_slskPort.text.trim()) ?? 0
      ..rutrackerUser = _rtUser.text.trim()
      ..rutrackerPass = _rtPass.text
      ..acoustidKey = _acoustid.text.trim()
      ..rutrackerCookie = real.rutrackerCookie; // RuTracker validity depends on the live session
    // Soulseek deliberately uses the app's REAL service, not a probe copy: a probe would have its
    // own client, so testing the connection would open a SECOND login on an account that allows
    // one — kicking the live session and provoking a re-login. It also wouldn't see the app's
    // back-off, so "Test" could keep hammering an account that is already blocked.
    final checker = ConnectionChecker(probe, TorBox(() => probe.torboxToken),
        context.read<SoulseekService>(), RuTrackerService(probe));
    setState(() {
      _testing = true;
      for (final k in ['torbox', 'discogs', 'soulseek', 'rutracker', 'acoustid']) {
        _conn[k] = const ConnResult(ConnState.checking);
      }
    });
    Future<void> run(String key, Future<ConnResult> Function() f) async {
      final r = await f();
      if (mounted) setState(() => _conn[key] = r);
    }

    await Future.wait([
      run('torbox', checker.torboxCheck),
      run('discogs', checker.discogsCheck),
      run('soulseek', checker.soulseekCheck),
      run('rutracker', checker.rutrackerCheck),
      run('acoustid', checker.acoustidCheck),
    ]);
    if (mounted) setState(() => _testing = false);
  }

  /// Aanmelden bij RuTracker in een echt browservenster — zie `rutracker_login.dart`.
  ///
  /// **Waarom dit de eerste weg is en niet de tweede.** Het koekje, de Cloudflare-doorgang en het
  /// browserkenmerk komen hier uit één venster op één IP-adres, en die drie horen onlosmakelijk bij
  /// elkaar: `cf_clearance` zit vast aan het IP-adres én aan de User-Agent die hem gekregen heeft.
  /// Bij plakken moet je die met de hand laten kloppen, en klopt er één niet, dan krijg je een 403
  /// zonder dat iets uitlegt waarom.
  ///
  /// Meteen naneuzen met `verify()`: een sessie die je bewaart zonder hem te proberen is een
  /// instelling waarvan je pas bij de volgende zoekopdracht hoort dat hij niets deed.
  Future<void> _meldAanInVenster() async {
    final settings = context.read<AppSettings>();
    final rt = context.read<OnlineService>().rutracker;
    final sessie = await meldAanBijRutracker(context);
    if (!mounted) return;
    if (sessie == null) {
      setState(() => _conn['rutracker'] =
          const ConnResult(ConnState.fail, 'Aanmelden afgebroken — er kwam niets binnen'));
      return;
    }
    if (!sessie.heeftSessie) {
      // Wél door Cloudflare, niet ingelogd. Dat verschil hoort gezegd te worden, anders zoek je het
      // in je wachtwoord terwijl je gewoon het venster te vroeg dichtdeed.
      setState(() => _conn['rutracker'] = ConnResult(
          ConnState.fail,
          sessie.heeftClearance
              ? 'Cloudflare doorlopen, maar nog niet ingelogd — log in het venster echt in'
              : 'Geen koekje opgehaald'));
      return;
    }
    settings.rutrackerCookie = sessie.cookie;
    if (sessie.ua.isNotEmpty) settings.rutrackerUa = sessie.ua;
    await settings.save();
    // Meteen het onzichtbare venster opbouwen, zodat je eerste zoekopdracht niet op die opbouw hoeft
    // te wachten. Zie rutracker_venster.dart.
    if (RutrackerVenster.kan) unawaited(RutrackerVenster.instantie.warmOp());

    // **En doorgeven aan de pc, want dáár wordt gezocht.** Dit was het gat waar drie uitgaven in
    // verdwenen: je meldt je op je telefoon aan, maar zodra die aan je pc gekoppeld is loopt het
    // zoeken en het downloaden over de pc — en die had geen sessie, dus vroeg hij RuTracker niet
    // eens. Op het scherm stond dan "RuTracker: niet bevraagd", en dat was waar, alleen ging het
    // over de verkeerde machine.
    final online = context.read<OnlineService>();
    if (online is RemoteOnlineService) {
      final pc = await online.stuurRutrackerSessie(sessie.cookie, sessie.ua);
      if (!mounted) return;
      final zin = pc.ok
          ? 'Aangemeld — ook op de pc, die het zoeken doet.'
          : 'Op dit toestel aangemeld, maar de pc niet: ${pc.reden}';
      setState(() =>
          _conn['rutracker'] = ConnResult(pc.ok ? ConnState.ok : ConnState.fail, zin));
      // Ook hier zichtbaar, en niet alleen in de verbindingsregel die buiten beeld kan staan.
      ScaffoldMessenger.of(context)
          .showSnackBar(SnackBar(content: Text(zin), duration: const Duration(seconds: 6)));
      return;
    }
    if (!mounted) return;
    setState(() {
      _rtBusy = true;
      _conn['rutracker'] = const ConnResult(ConnState.checking);
    });
    try {
      final werkt = await rt.verify();
      if (!mounted) return;
      setState(() => _conn['rutracker'] = werkt
          ? const ConnResult(ConnState.ok, 'Aangemeld — RuTracker antwoordt')
          : const ConnResult(ConnState.fail, 'Koekje opgehaald, maar RuTracker weigert het nog'));
    } finally {
      if (mounted) setState(() => _rtBusy = false);
    }
  }

  /// De aanmelding die al op dit toestel staat alsnog naar de pc sturen.
  ///
  /// Voor wie zich eerder aanmeldde toen die weg er nog niet was. Zie `_meldAanInVenster` voor
  /// waarom dit moet: gekoppeld aan een pc gebeurt het zoeken daar, en een sessie die hier blijft
  /// staan doet niets.
  Future<void> _stuurRtNaarPc() async {
    final online = context.read<OnlineService>();
    if (online is! RemoteOnlineService) return;
    final settings = context.read<AppSettings>();
    setState(() {
      _rtBusy = true;
      _conn['rutracker'] = const ConnResult(ConnState.checking);
    });
    try {
      final pc = await online.stuurRutrackerSessie(
          settings.rutrackerCookie, settings.rutrackerUa);
      if (!mounted) return;
      setState(() => _conn['rutracker'] = ConnResult(
          pc.ok ? ConnState.ok : ConnState.fail, pc.reden));
      // **En het meteen zeggen, op de plek waar je kijkt.** De uitkomst belandde in de
      // verbindingsregel bovenaan het RuTracker-blok, en die staat bij een uitgeklapte
      // instellingenlijst buiten beeld. Een knop die je indrukt en waarna er niets gebeurt is een
      // knop die stuk lijkt — ook als hij precies deed wat hij moest doen.
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(SnackBar(
        content: Text(pc.reden),
        duration: const Duration(seconds: 6),
      ));
    } finally {
      if (mounted) setState(() => _rtBusy = false);
    }
  }

  /// Log in to RuTracker (persisting the typed creds first), solving a CAPTCHA if asked.
  Future<void> _rtLogin() async {
    final settings = context.read<AppSettings>();
    final rt = context.read<OnlineService>().rutracker;
    settings.rutrackerUser = _rtUser.text.trim();
    settings.rutrackerPass = _rtPass.text;
    await settings.save();
    setState(() {
      _rtBusy = true;
      _conn['rutracker'] = const ConnResult(ConnState.checking);
    });
    try {
      var result = await rt.login();
      while (result.captcha != null && mounted) {
        final answer = await _captchaDialog(result.captcha!);
        if (answer == null || answer.isEmpty) {
          if (mounted) setState(() => _conn['rutracker'] = const ConnResult(ConnState.fail, 'Login geannuleerd'));
          return;
        }
        result = await rt.login(captchaAnswer: answer, captcha: result.captcha);
      }
      if (!mounted) return;
      setState(() => _conn['rutracker'] = result.ok
          ? ConnResult(ConnState.ok, 'Ingelogd als ${settings.rutrackerUser}')
          : ConnResult(ConnState.fail, result.error ?? 'Login mislukt'));
    } finally {
      if (mounted) setState(() => _rtBusy = false);
    }
  }

  Future<String?> _captchaDialog(RtCaptcha cap) {
    final ctrl = TextEditingController();
    return showDialog<String>(
      context: context,
      builder: (_) => AlertDialog(
        backgroundColor: _panel,
        title: const Text('RuTracker CAPTCHA', style: TextStyle(fontSize: 16, fontWeight: FontWeight.w700)),
        content: SizedBox(
          width: 320,
          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              const Text('Typ de tekens uit de afbeelding over.',
                  style: TextStyle(color: _muted, fontSize: 12.5)),
              const SizedBox(height: 10),
              Container(
                padding: const EdgeInsets.all(6),
                color: Colors.white,
                child: Image.network(cap.imageUrl,
                    height: 72,
                    errorBuilder: (_, __, ___) =>
                        const Text('Afbeelding kon niet laden', style: TextStyle(color: Colors.black54))),
              ),
              const SizedBox(height: 10),
              TextField(
                controller: ctrl,
                autofocus: !isTv,
                onSubmitted: (v) => Navigator.pop(context, v.trim()),
                decoration: InputDecoration(
                  isDense: true,
                  filled: true,
                  fillColor: kVerzonken,
                  border: OutlineInputBorder(borderRadius: BorderRadius.circular(9), borderSide: const BorderSide(color: _line)),
                  enabledBorder: OutlineInputBorder(borderRadius: BorderRadius.circular(9), borderSide: const BorderSide(color: _line)),
                ),
              ),
            ],
          ),
        ),
        actions: [
          TextButton(onPressed: () => Navigator.pop(context), child: const Text('Annuleren')),
          FilledButton(
            style: FilledButton.styleFrom(backgroundColor: _accent),
            onPressed: () => Navigator.pop(context, ctrl.text.trim()),
            child: const Text('Verstuur'),
          ),
        ],
      ),
    );
  }

  Widget _statusRow(String label, String key, {Widget? trailing}) {
    final r = _conn[key];
    IconData icon;
    Color color;
    String text;
    switch (r?.state) {
      case ConnState.ok:
        icon = Icons.check_circle_rounded;
        color = _accent2;
        text = r!.detail;
        break;
      case ConnState.fail:
        icon = Icons.cancel_rounded;
        color = Colors.redAccent;
        text = r!.detail;
        break;
      case ConnState.absent:
        icon = Icons.remove_circle_outline_rounded;
        color = _muted;
        text = r!.detail;
        break;
      case ConnState.checking:
        icon = Icons.hourglass_top_rounded;
        color = _muted;
        text = 'Testen…';
        break;
      default:
        icon = Icons.circle_outlined;
        color = _muted;
        text = 'Nog niet getest';
    }
    return Padding(
      padding: const EdgeInsets.symmetric(vertical: 4),
      child: Row(
        children: [
          r?.state == ConnState.checking
              ? const SizedBox(
                  width: 16, height: 16, child: CircularProgressIndicator(strokeWidth: 2, color: _muted))
              : Icon(icon, size: 18, color: color),
          const SizedBox(width: 10),
          SizedBox(
              width: 84,
              child: Text(label, style: const TextStyle(fontSize: 13, fontWeight: FontWeight.w600))),
          Expanded(child: Text(text, style: TextStyle(fontSize: 12.5, color: color))),
          if (trailing != null) trailing,
        ],
      ),
    );
  }

  Widget _field(String label, TextEditingController c, {bool obscure = false}) {
    return Padding(
      padding: const EdgeInsets.only(bottom: 12),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(label, style: const TextStyle(color: _muted, fontSize: 12.5)),
          const SizedBox(height: 5),
          MaybePressable(
            enabled: isTv,
            onPressed: () => _focusFor(c).requestFocus(),
            borderRadius: BorderRadius.circular(9),
            child: TextField(
            controller: c,
            focusNode: _focusFor(c),
            obscureText: obscure,
            style: const TextStyle(fontSize: 14),
            decoration: InputDecoration(
              isDense: true,
              filled: true,
              fillColor: kVerzonken,
              border: OutlineInputBorder(
                  borderRadius: BorderRadius.circular(9), borderSide: const BorderSide(color: _line)),
              enabledBorder: OutlineInputBorder(
                  borderRadius: BorderRadius.circular(9), borderSide: const BorderSide(color: _line)),
              focusedBorder: OutlineInputBorder(
                  borderRadius: BorderRadius.circular(9), borderSide: const BorderSide(color: _accent)),
            ),
            ),
          ),
        ],
      ),
    );
  }

  /// The node for this field, made once and kept. Keyed by the controller because that is what
  /// [_field] is handed — there is no id, and eight call sites should not have to invent one.
  FocusNode _focusFor(TextEditingController c) => _fieldFocus.putIfAbsent(
        c,
        () => FocusNode(skipTraversal: isTv),
      );

