String _fmt(Duration? d) {
  if (d == null) return '0:00';
  final m = d.inMinutes;
  final s = d.inSeconds % 60;
  return '$m:${s.toString().padLeft(2, '0')}';
}

/// The album sleeve, with the disc sliding out from behind it while the record plays.
///
/// Both scans come from Discogs, which does not label them — see artwork.dart for how the disc is
/// told apart from a back cover. When there is no disc scan the sleeve simply sits there, which is
/// what every album looked like before.
class AlbumArt extends StatefulWidget {
  final String artist, album;
  final Uint8List? fallback;

  /// A sleeve the user picked by hand. It outranks anything Discogs offers — an automatic source
  /// correcting a deliberate choice is the app arguing with its owner.
  final Uint8List? chosen;
  final double size;

  /// Which RECORD this is, when the caller knows (the album uid). Only used to tell "the same
  /// record under a new name" apart from "a different record altogether": scans are kept on screen
  /// through the first, and must not be through the second.
  final String identity;

  final int trackCount;
  final bool playing;

  /// The Discogs release the user pinned, if any — see LibraryStore.pinnedRelease.
  final int? pinned;

  /// Or the MusicBrainz one — see LibraryStore.pinnedMbid.
  final String? pinnedMbid;

  /// The sleeve this widget ended up drawing, handed back as it resolves.
  ///
  /// For the screens that show the art AND let you open it: the enlarged view has to be the same
  /// image as the thumbnail, and only this widget knows which pressing's scan won.
  final ValueChanged<Uint8List?>? onFront;

  /// Het label waarmee de hoes van de tegel hierheen vliegt. Null = geen vlucht.
  ///
  /// Alleen om de SLEEVE heen, niet om het geheel: staat er een cd naast, dan is deze widget
  /// `s + travel` breed en zou er een rechthoek met lege ruimte door het scherm zweven.
  final String? heroTag;

  /// Images the user assigned by hand — see LibraryStore.albumArtRoles. They outrank every guess.
  final Map<String, String> roles;
  const AlbumArt({
    super.key,
    required this.artist,
    required this.album,
    required this.size,
    this.identity = '',
    this.fallback,
    this.chosen,
    this.trackCount = 0,
    this.playing = false,
    this.pinned,
    this.pinnedMbid,
    this.onFront,
    this.roles = const {},
    this.heroTag,
  });

  @override
  State<AlbumArt> createState() => _AlbumArtState();
}

/// How far the disc stays out when nothing is playing.
///
/// Enough to see that there IS one, and to check the scan you just chose; not so much that pressing
/// play has nothing left to show. A quarter of the travel leaves the label behind the sleeve, so it
/// still reads as a disc tucked into a card rather than one lying beside it.
const _discRest = 0.26;

/// A disc with a hole in it, the way a CD has one.
///
/// Two circles in one path with [PathFillType.evenOdd]: the outer one keeps, the inner one gives
/// back. The sleeve behind shows through the hole, which is what makes it read as a disc lying on
/// top rather than as a printed circle.
///
/// Still one clip, so the [RepaintBoundary] above it does its job exactly as before: the mask is
/// rasterised once and each frame only turns an existing layer. Doing this with a second widget
/// stacked on top — a hole painted in the background colour — would have looked right on the album
/// page and wrong everywhere the background is not that colour.
class _DiscClipper extends CustomClipper<Path> {
  const _DiscClipper();

  /// A CD is 120 mm across with a 15 mm hole: an eighth. Measured rather than eyeballed, because
  /// slightly too big reads as a vinyl label and slightly too small as a smudge.
  static const _holeFraction = 15 / 120;

  @override
  Path getClip(Size size) {
    final centre = Offset(size.width / 2, size.height / 2);
    final radius = size.shortestSide / 2;
    return Path()
      ..fillType = PathFillType.evenOdd
      ..addOval(Rect.fromCircle(center: centre, radius: radius))
      ..addOval(Rect.fromCircle(center: centre, radius: radius * _holeFraction));
  }

  @override
  bool shouldReclip(_DiscClipper oldClipper) => false;
}

class _AlbumArtState extends State<AlbumArt> with TickerProviderStateMixin {
  ReleaseArt? _art;
  late final AnimationController _slide = AnimationController(
    vsync: this,
    duration: const Duration(milliseconds: 750),
    reverseDuration: const Duration(milliseconds: 450),
  );
  // Roughly a third of an RPM on screen — enough to read as turning, slow enough not to nag.
  late final AnimationController _spin =
      AnimationController(vsync: this, duration: const Duration(seconds: 9));

  /// Wat het scherm haalt zolang de plaat draait.
  ///
  /// Apart bestand, niet ui.log: die schrijft per hoes een paar regels en zou hierdoor binnen een
  /// minuut zijn eigen kop afkappen. En niet weggelaten na de reparatie — dit is het enige punt waar
  /// "de plaat hapert" van "de plaat is traag" te onderscheiden valt, en dat komt terug.
  late final FpsProbe _fps = FpsProbe(WarmLog('$appDir${Platform.pathSeparator}fps.log'));

  @override
  void initState() {
    super.initState();
    _load();
    _sync();
  }

  @override
  void didUpdateWidget(AlbumArt old) {
    super.didUpdateWidget(old);
    // Same as the info panel: a new pin is a new set of scans, even when the album's name is
    // unchanged. This is why the disc never followed the release you picked.
    if (old.artist != widget.artist ||
        old.album != widget.album ||
        old.pinned != widget.pinned ||
        old.pinnedMbid != widget.pinnedMbid ||
        !mapEquals(old.roles, widget.roles)) {
      // A DIFFERENT record: drop what is up. Keeping it would put one album's sleeve and disc on
      // another album's page for the length of a round trip, which is not a smaller lie than a gap.
      if (widget.identity.isNotEmpty && old.identity.isNotEmpty &&
          old.identity != widget.identity) {
        setState(() => _art = null);
      }
      // Otherwise the old scans stay up until the new ones arrive — renaming a record does not
      // change its sleeve. Clearing here left a gap the length of a network round trip, in which
      // the disc vanished and the sleeve fell back to the file's own cover, which read as the app
      // losing the choice that was just made.
      _load();
    }
    if (old.playing != widget.playing) _sync();
  }

  void _sync() {
    if (widget.playing) {
      _slide.forward();
      if (!_spin.isAnimating) {
        _spin.repeat();
        // Alleen meten zolang er iets te meten valt. Een stilstaande plaat vraagt geen frames aan,
        // dus dan zou de teller alleen ruis van de rest van het scherm optellen.
        _fps.start('draaiende cd ${widget.size.round()}px');
      }
    } else {
      _slide.reverse();
      // Left where it stopped rather than snapped back to zero: a record that stops turning
      // stops where it is.
      _spin.stop();
      _fps.stop();
    }
  }

  /// Which load is the current one. A pin can be changed twice before the first fetch returns, and
  /// without this the slower answer would land last and win — showing scans nobody asked for.
  int _gen = 0;

  Future<void> _load() async {
    final artist = widget.artist, album = widget.album;
    final mine = ++_gen;
    try {
      final art = await DiscogsService(context.read<AppSettings>()).releaseArt(artist, album,
          expectedTracks: widget.trackCount,
          pinned: widget.pinned,
          pinnedMbid: widget.pinnedMbid,
          roles: widget.roles);
      if (!mounted || mine != _gen || artist != widget.artist || album != widget.album) return;
      // Nothing found leaves what is on screen alone: an empty answer is not a better answer than
      // the sleeve already showing.
      if (art != null) setState(() => _art = art);
      // Hand it to the library too. Without this the correction lived only on the open page: the
      // album showed the right sleeve, and going back to the grid showed the wrong one again.
      //
      // `from` is what makes that actually true now. With a pressing pinned or matched, this is the
      // art OF that release and outranks whatever the files carry; without one it is a search by
      // name, which is a guess and stays below the embedded cover.
      final front = art?.front;
      if (front != null && mounted) {
        // **De persing die de hoes WERKELIJK leverde gaat vóór de gepinde.**
        //
        // Hier stond alleen de pin, en dat was te weinig. Zonder pin — het gewone geval — kwam er
        // `null` uit, en dan landt de hoes in `enriched`, dat het verliest van de hoes die in de
        // bestanden zit. Gevolg: de albumpagina tekende de gevonden hoes en Start bleef de oude
        // tonen. Twee schermen, twee antwoorden, één plaat — precies de klacht.
        //
        // De keten weet inmiddels wél van welke persing de voorkant is; zie [ReleaseArt.bron]. De
        // pin blijft als terugval staan voor het geval de hoes uit de cache van vóór deze versie
        // komt, want daar staat nog geen herkomst bij.
        final from = hoesHerkomst(
            artBron: art?.bron, pinnedMbid: widget.pinnedMbid, pinned: widget.pinned);
        // With the settings, a traced sleeve is written down and survives the next start; the
        // correction used to live only for as long as the window stayed open.
        context
            .read<LibraryStore>()
            .adoptAlbumCover(artist, album, front, from: from, settings: context.read<AppSettings>());
      }
      widget.onFront?.call(widget.chosen ?? front ?? widget.fallback);
    } catch (_) {/* no artwork is not an error worth showing */}
  }

  @override
  void dispose() {
    // Vóór de controllers: de haak hangt aan de SchedulerBinding en die leeft door als deze widget
    // weg is. Blijft hij hangen, dan telt hij het hele scherm mee en klopt de volgende meting niet.
    _fps.stop();
    _slide.dispose();
    _spin.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final s = widget.size;
    final front = widget.chosen ?? _art?.front ?? widget.fallback;
    final disc = _art?.disc;
    // How far the disc comes out. Started at .42 — enough to see it, not enough to enjoy it — so
    // it now clears the sleeve by a good margin while the label still sits behind the card.
    //
    // Less of it in portrait on a phone. The travel is reserved WIDTH, so on 411 points every
    // percent of it is taken off the sleeve and off whatever sits beside it — and on the player
    // screen that is the row of transport buttons, which has to be there. Sideways and on the TV
    // there is width to spare, so the disc gets its full stride.
    final travel = s * discTravelFactor(context);

    final sleeve = ClipRRect(
      borderRadius: BorderRadius.circular(10),
      child: front == null
          ? Container(width: s, height: s, color: _panel2, child: const Icon(Icons.album, color: _muted))
          : Image.memory(front,
              width: s, height: s, fit: BoxFit.cover, cacheWidth: decodeWidth(s)),
    );

    final vliegend =
        widget.heroTag == null ? sleeve : Hero(tag: widget.heroTag!, child: sleeve);

    if (disc == null) return vliegend;

    // Built once and handed to the animation as a child, so none of this is rebuilt per frame.
    //
    // The order is load-bearing. ClipOval forces a saveLayer — Flutter renders into an offscreen
    // buffer, masks it, then composites — which is the most expensive thing in the raster pipeline.
    // Written the obvious way, that saveLayer sat INSIDE the rotation, so a ~660px disc was masked
    // and re-composited sixty times a second. That is the stutter, and it was mine, not the Shield's.
    //
    // With the clip inside a RepaintBoundary and the rotation outside it, the mask is rasterised
    // ONCE into a layer and each frame only moves a transform.
    final spinningDisc = RotationTransition(
      turns: _spin,
      child: RepaintBoundary(
        child: ClipPath(
          clipper: const _DiscClipper(),
          child: Image.memory(disc,
              width: s * .92,
              height: s * .92,
              fit: BoxFit.cover,
              // This one rotates sixty times a second. Decoding it at 1200px to spin it inside a
              // 600px circle is the most expensive picture in the app.
              cacheWidth: decodeWidth(s * .92)),
        ),
      ),
    );

    return SizedBox(
      width: s + travel,
      height: s,
      child: Stack(
        clipBehavior: Clip.none,
        children: [
          // Behind the sleeve, and drawn first so it stays there.
          Positioned(
            left: 0,
            top: s * .04,
            // The disc's own clip is cached below; this boundary is about everything ABOVE it.
            // RenderTransform is not a repaint boundary, so a moving disc marked the nearest one
            // above — the route — and the whole screen was re-recorded every frame, including the
            // full-bleed cover behind it and its 44-blur shadow. Now the frame stops here.
            child: RepaintBoundary(
                child: AnimatedBuilder(
              animation: _slide,
              // Translate rather than reposition: a Positioned inside a builder would relayout the
              // Stack every frame, where a transform only moves an already-painted layer.
              // A resting sliver, always. Standing still the disc used to sit entirely behind the
              // sleeve, so an album page you were not playing showed no disc at all — and somebody
              // who had just chosen a disc scan had no way to look at it without pressing play.
              // The reveal is still the reveal: it comes the rest of the way out and starts turning.
              builder: (context, child) => Transform.translate(
                offset: Offset(
                  (_discRest + (1 - _discRest) * Curves.easeOutCubic.transform(_slide.value)) *
                      travel,
                  0,
                ),
                child: child,
              ),
              child: spinningDisc,
            )),
          ),
          // Never rebuilt: it is outside the builder entirely, and it never changes while a record
          // plays.
          Positioned(left: 0, top: 0, child: sleeve),
        ],
      ),
    );
  }
}

/// Pick which pressing describes an album — showing, before you choose, what each one carries.
///
/// The metadata editor could already pin a release, but it listed them as bare names and said
/// nothing about their artwork. Choosing blind meant finding out afterwards that a pressing had no
/// disc scan, and the animation had nothing to spin.
class ReleaseGallery extends StatefulWidget {
  final Album album;
  const ReleaseGallery(this.album, {super.key});

  @override
  State<ReleaseGallery> createState() => _ReleaseGalleryState();
}

/// The three things a scan can be, and what to call each on screen.
///
/// One list, read by the gallery and by the assign dialog: two copies would drift, and the role
/// KEYS are what album_art_roles.json stores — a label changed in one place and not the other would
/// write a role nothing reads.
const artRoles = [('front', 'hoes'), ('back', 'achter'), ('disc', 'cd')];

class _ReleaseGalleryState extends State<ReleaseGallery> {
  static const _roles = artRoles;

  List<ReleaseChoice>? _choices;
  String? _error;

  /// Which source has reported in. Discogs takes far longer, so the list is live before it lands
  /// and the footer has to be able to say so.
  bool _mbDone = false, _dgDone = false, _dgFailed = false;
  bool _busy = false;

  /// Which formats to show. Everything Discogs has is fetched; this only narrows what is listed,
  /// so switching filters never costs another request.
  String _filter = 'Alles';

  /// Het veld waarin een Discogs-nummer of -link geplakt kan worden.
  final _nummerCtl = TextEditingController();
  bool _zoeken = false;

  /// Wat er misging bij het opvragen, ONDER het veld en niet als zwevende melding.
  ///
  /// Een SnackBar hoort bij de Scaffold, en die ligt achter deze dialoog: de enige terugkoppeling
  /// op een verkeerd getypt nummer zou dan achter het grijze scherm gebeuren. Onder het veld staat
  /// hij waar je kijkt, en blijft hij staan tot je het opnieuw probeert.
  String? _nummerFout;

  /// Hoeveel uitgaves Discogs zegt te hebben, en of er meer zijn dan hier staan.
  int _dgTotaal = 0;
  bool _dgMeer = false;

  /// Hoeveel gelijknamige albums op Discogs er niet doorlopen zijn.
  int _andereMasters = 0;

  /// De sleutel van de vastgezette uitgave, als er één is.
  ///
  /// Nodig in [_merge], want juist die ene rij mag nooit sneuvelen op het ontdubbelen: kent
  /// MusicBrainz dezelfde persing, dan zou je eigen keuze uit de lijst met keuzes verdwijnen.
  String? _pinSleutel;

  /// De rij die zojuist op nummer is opgehaald, zodat je hem terugvindt tussen tweehonderd andere.
  String? _gemarkeerd;

  /// Nodig om na zo'n opvraging naar boven te springen: de rij komt bovenaan te staan, en dat helpt
  /// niet als je op dat moment halverwege de lijst staat te kijken.
  final _scroll = ScrollController();

  @override
  void dispose() {
    _nummerCtl.dispose();
    _scroll.dispose();
    super.dispose();
  }

  /// role → the scan picked for it, possibly from a DIFFERENT pressing than the others.
  ///
  /// A record you own rarely matches one catalogue entry exactly: the sleeve is best photographed on
  /// the digital release, the tray inlay only exists on the CD, and the disc scan on a third. Held
  /// here until Save so a half-made choice never reaches the album, and so "cancel" means cancel.
  final Map<String, ChoiceImage> _staged = {};
  bool _saving = false;

  /// Bij welke uitgave elke klaargezette scan hoort.
  ///
  /// Nodig omdat een rij die nog niet is uitgevraagd alleen een miniatuur heeft; [_save] haalt daar
  /// de volle scan bij op, en dat kan alleen met de rij in de hand.
  final Map<String, ReleaseChoice> _stagedRij = {};

  void _stage(String role, ChoiceImage img, ReleaseChoice rij) {
    setState(() {
      // Tapping the same one again takes it back, which is the only way to undo without cancelling
      // the whole dialog.
      if (_staged[role]?.uri == img.uri) {
        _staged.remove(role);
        _stagedRij.remove(role);
      } else {
        _staged[role] = img;
        _stagedRij[role] = rij;
      }
    });
  }

  /// De volle scan achter een klaargezette keuze, of hem ongewijzigd als hij al vol is.
  ///
  /// **Waarom dit bestaat.** De zoeklijst van Discogs geeft per rij een miniatuur van 150×150 en
  /// verder niets; de volle scan komt pas met de detail-lookup, die lui gebeurt zodra een rij in
  /// beeld staat. Tik je sneller dan die lookup, dan legde de app dat miniatuur vast als je hoes —
  /// permanent, want `correctedCover` wint van elke andere bron en wordt bij elke start teruggeladen.
  ///
  /// Mislukt de lookup, dan gaat de keuze van de gebruiker vóór de resolutie: liever zijn hoes klein
  /// dan zijn hoes niet. Maar dan is het wél geprobeerd.
  Future<ChoiceImage> _volleScan(String rol, ChoiceImage img, AppSettings settings) async {
    if (!img.alleenMiniatuur) return img;
    final rij = _stagedRij[rol];
    if (rij == null || rij.releaseId <= 0) return img;
    try {
      final vol = await DiscogsService(settings).detailOf(rij);
      final beter = switch (rol) {
        'back' => vol?.back,
        'disc' => vol?.disc,
        _ => vol?.front,
      };
      if (beter != null && !beter.alleenMiniatuur && beter.uri.isNotEmpty) return beter;
    } catch (_) {/* de keuze van de gebruiker gaat voor; klein is beter dan weg */}
    return img;
  }

  /// Write the picked scans and have every screen show them in the same frame.
  ///
  /// Two different writes, on purpose:
  ///   - back and disc are ROLES: a url per role, which releaseArt reads and which its cache key
  ///     already includes, so the album page re-fetches by itself.
  ///   - the front is also fetched and pinned as the album's cover, because the grid, the player bar
  ///     and the Tracks list read Album.cover and would otherwise keep the old sleeve until
  ///     something happened to re-enrich them. That is the difference between "instant on this page"
  ///     and "instant everywhere", which is what was asked for.
  Future<void> _save() async {
    if (_staged.isEmpty || _saving) return;
    setState(() => _saving = true);
    final lib = context.read<LibraryStore>();
    final settings = context.read<AppSettings>();
    final mbSvc = context.read<MusicBrainzService>();
    try {
      // Eerst opwaarderen, dan pas vastleggen: een miniatuur van 150 pixels mag nooit de hoes van
      // dit album worden. Zie [_volleScan].
      final teBewaren = <String, ChoiceImage>{};
      for (final e in _staged.entries) {
        teBewaren[e.key] = await _volleScan(e.key, e.value, settings);
      }
      for (final e in teBewaren.entries) {
        await lib.setAlbumArtRole(widget.album.artist, widget.album.title, e.key, e.value.uri);
      }
      final front = teBewaren['front'];
      if (front != null) {
        // Each catalogue serves its own images, and Discogs wants its token on the request.
        final bytes = front.uri.contains('coverartarchive.org')
            ? await mbSvc.fetchImage(front.uri)
            : await DiscogsService(settings).fetchImage(front.uri);
        if (bytes != null && bytes.isNotEmpty) {
          await lib.setAlbumCover(widget.album, settings, bytes);
        }
      }
      if (mounted) Navigator.of(context).pop(true);
    } catch (e) {
      if (!mounted) return;
      setState(() => _saving = false);
      _srcToast(context, 'Kon de keuze niet opslaan: $e');
    }
  }

  @override
  void initState() {
    super.initState();
    _load();
  }

  /// MusicBrainz first, Discogs appended — which is the order the user asked for and also the
  /// order the two can deliver in. One release-group browse names every pressing at once, so the
  /// dialog fills in about two seconds; Discogs needs a request per pressing and takes fifteen.
  ///
  /// So the list is shown as soon as MusicBrainz answers rather than waiting for both. A user
  /// staring at a spinner while a source they did not ask about finishes is the thing to avoid.
  Future<void> _load() async {
    final lib = context.read<LibraryStore>();
    final settings = context.read<AppSettings>();
    final pinnedMb = lib.pinnedMbid(widget.album);
    final pinnedDg = lib.pinnedRelease(widget.album);
    _pinSleutel = pinnedMb != null
        ? 'mb:$pinnedMb'
        : (pinnedDg != null ? 'dg:$pinnedDg' : null);

    try {
      // Shown as it fills in: the pressings the moment they are named, then their scans as each
      // arrives. Waiting for the whole answer is what made this dialog feel broken — the rows were
      // ready seconds before the artwork the spinner was actually waiting for.
      final mb = await context.read<MusicBrainzService>().editionChoices(
          widget.album.artist, widget.album.title,
          pinnedMbid: pinnedMb, onPartial: _merge);
      if (!mounted) return;
      _merge(mb);
      setState(() => _mbDone = true);
    } catch (_) {
      if (mounted) setState(() => _mbDone = true);
    }

    // Discogs supplements: it has scans for pressings the archive has never seen. Its failures are
    // reported separately, because "Discogs is unreachable" and "this record has no pressings" are
    // very different things to be told.
    // Kapotte verbindingen TELLEN, want ze gooien niet. `_get` maakt van een time-out, een 429 en
    // een 5xx dezelfde `null` als van "bestaat niet", dus de `catch` hieronder ving in de praktijk
    // nooit iets — en Discogs die plat lag las als "deze plaat heeft geen uitgaves". Het verschil
    // tussen die twee is precies wat de gebruiker moet horen.
    final foutenVoor = DiscogsService.transportErrors;
    try {
      // The rows appear as soon as the versions listing lands — one request for a whole master.
      // Their scans are fetched per row, as each is scrolled into view: see _wantDetail.
      await DiscogsService(settings).releaseChoices(
        widget.album.artist,
        widget.album.title,
        pinned: pinnedDg,
        onPartial: _merge,
        // De dialoog is dicht. Doorgaan kost requests op een baan van zestig per minuut voor een
        // venster dat er niet meer is — en die requests gaan af van wat de rest van de app krijgt.
        gestopt: () => !mounted,
        // Opgeteld en niet overschreven, net als bij het nummerveld. Vraag je een master op terwijl
        // de gewone lijst nog binnenkomt, dan zou dit anders "niet alles staat hier" weer uitzetten
        // op grond van een lijst die daar niets over te zeggen heeft.
        onEinde: (totaal, meer, andereMasters) {
          if (!mounted) return;
          setState(() {
            if (totaal > _dgTotaal) _dgTotaal = totaal;
            _dgMeer = _dgMeer || meer;
            _andereMasters = andereMasters;
          });
        },
      );
    } catch (_) {
      _dgFailed = true;
    }
    if (!mounted) return;
    // De teller is van de hele app, dus hij kan ook de mislukking van de achtergrondwarmer
    // opvangen. Dat is bewust de goede kant om ernaast te zitten: hoogstens zegt de dialoog dat de
    // lijst onvolledig KAN zijn terwijl hij compleet is. Andersom — stilzwijgend een halve lijst
    // tonen als het hele antwoord — is de fout waar deze wijziging over gaat.
    setState(() {
      _dgDone = true;
      _dgFailed = _dgFailed || DiscogsService.transportErrors > foutenVoor;
    });
    if (_choices?.isEmpty ?? true) {
      // Over de ontbrekende sleutel staat hier niets: die regel staat altijd onder de lijst, ook
      // als er wél rijen zijn. Hem hier herhalen zou hetzelfde twee keer op één scherm zetten.
      setState(() => _error = _dgFailed
          ? 'Geen uitgaves gevonden. Discogs was niet bereikbaar, dus de aanvulling ontbreekt.'
          : 'Geen uitgaves gevonden.');
    }
  }

  /// Nieuwe rijen erbij, zonder ooit iets weg te gooien wat er al staat.
  ///
  /// **Waarom toevoegen en niet opnieuw opbouwen.** Hier stond een functie die `_choices` elke keer
  /// hersamenstelde uit "alles van MusicBrainz" plus de Discogs-lijst. Dat kon toen alles van
  /// Discogs in één klap binnenkwam. Nu niet meer, en wel om drie redenen tegelijk: Discogs levert
  /// pagina voor pagina, elke rij krijgt onderweg zijn scans ingevuld, en de gebruiker kan er zelf
  /// een uitgave bij zetten met een nummer. Opnieuw opbouwen zou die twee laatste dingen bij elke
  /// binnenkomende pagina wissen — de scans terug naar een molentje, de opgevraagde rij weg.
  ///
  /// Beide catalogussen lopen door deze ene weg. Wie het eerst is wint, en dat is MusicBrainz (twee
  /// seconden tegen vijftien) — dezelfde uitkomst als de oude volgorde, maar nu als gevolg van één
  /// regel in plaats van twee die het eens moesten blijven.
  /// Geeft terug hoeveel rijen er in het BLOK op [opIndex] terecht kwamen — nul als er niets
  /// veranderde. Het nummerveld leest dat getal, want "de dienst gaf een uitgave terug" en "er staat
  /// nu een rij op het scherm" zijn twee verschillende dingen, en alleen het tweede telt.
  int _merge(List<ReleaseChoice> nieuw, {int? opIndex, bool ontdubbel = true}) {
    if (!mounted || nieuw.isEmpty) return 0;
    final huidig = [...?_choices];
    final plaats = <String, int>{};
    for (var i = 0; i < huidig.length; i++) {
      plaats[huidig[i].key] = i;
    }
    final zelfde = {for (final c in huidig) c.dedupeKey};
    final gepland = <String, int>{}; // sleutel → plek in [erbij]

    final erbij = <ReleaseChoice>[];
    var iets = false;
    for (final c in nieuw) {
      final g = gepland[c.key];
      if (g != null) {
        // Twee keer dezelfde sleutel in één lading. Komt vandaag niet voor, en als het ooit gebeurt
        // hoort de rijkste te winnen — niet degene die toevallig eerst kwam.
        if (rijkdom(c) > rijkdom(erbij[g])) erbij[g] = c;
        continue;
      }
      final i = plaats[c.key];
      if (i != null) {
        // Dezelfde rij, opnieuw aangeboden. Alleen overnemen als hij RIJKER is — zie [rijkdom].
        if (rijkdom(c) > rijkdom(huidig[i])) {
          huidig[i] = c;
          // De vervanger kan een ANDERE dedupeKey dragen (een uitgave die op nummer is opgehaald
          // heeft een streepjescode waar de versielijst er geen gaf). Zonder deze regel blijft de
          // oude sleutel in de verzameling staan en de nieuwe eruit.
          zelfde.add(c.dedupeKey);
          iets = true;
        }
        continue;
      }
      // `dedupeKey` houdt dezelfde PERSING uit de andere catalogus tegen — maar nooit een rij waar
      // met zoveel woorden om gevraagd is, en nooit de vastgezette uitgave. Precies díe twee mogen
      // niet stilletjes wegvallen omdat een andere catalogus dezelfde persing ook kent: dan drukt
      // de gebruiker op Toon en gebeurt er niets, wat de fout is waar dit veld voor bestaat.
      if (ontdubbel && c.key != _pinSleutel && !zelfde.add(c.dedupeKey)) continue;
      zelfde.add(c.dedupeKey);
      gepland[c.key] = erbij.length;
      erbij.add(c);
      iets = true;
    }
    if (opIndex == null) {
      if (!iets && _choices != null) return 0;
      setState(() => _choices = [...huidig, ...erbij]);
      return erbij.length;
    }
    // Op een plek gevraagd: ook een rij die er AL stond schuift daarheen. Zonder dat zou het
    // nummerveld, uitgerekend voor een uitgave die de lijst al bevatte, zeggen "hier is hij" en je
    // vervolgens naar regel één sturen terwijl hij op regel tweehonderd staat.
    final wil = {for (final c in nieuw) c.key};
    final naarVoren = [for (final c in huidig) if (wil.contains(c.key)) c];
    if (!iets && naarVoren.isEmpty) return 0;
    // [opIndex] is hoeveel rijen deze zelfde opvraging er al bovenaan zette. Alles op nul zetten zou
    // pagina twee bóven pagina één plakken, en Discogs levert op datum — dan staat de oorspronkelijke
    // persing onderaan het blok in plaats van bovenaan.
    final rest = [for (final c in huidig) if (!wil.contains(c.key)) c];
    final k = opIndex.clamp(0, rest.length);
    setState(() => _choices = [
          ...rest.take(k),
          ...erbij,
          ...naarVoren,
          ...rest.skip(k),
        ]);
    return erbij.length + naarVoren.length;
  }


  /// De rijen die nog op hun scans wachten, als STAPEL en niet als rij.
  ///
  /// De lijst telt sinds de paginering geen veertig regels meer maar soms tweehonderd, en elke
  /// lookup kost een request op een baan van zestig per minuut. Wie doorscrolt naar regel honderd
  /// zet er onderweg tientallen in de wacht; op volgorde van binnenkomst zou hij daar dan minuten
  /// naar een molentje zitten kijken terwijl de app rijen ophaalt die allang van het scherm zijn.
  ///
  /// De laatst gevraagde rij is de rij waar je nú naar kijkt. Dus die eerst.
  final _stapel = <ReleaseChoice>[];
  bool _detailBezig = false;

  /// De uitgave waar nu een lookup voor loopt, zodat hij er niet nog een keer bij komt.
  int _bezigMet = 0;

  /// This row is on screen, so now it is worth knowing what it holds.
  ///
  /// Called from the builder, which Flutter only runs for visible rows — that is the whole saving.
  /// Deferred by a frame because a builder must not setState while it is building.
  ///
  /// **Elke keer opnieuw bovenop, en niet één keer en dan nooit meer.** Hier stond een verzameling
  /// `_asked` die een rij precies één keer in de wacht zette. Dat was genoeg toen de lijst veertig
  /// regels telde, maar met tweehonderd betekende het: scroll je langs een rij naar beneden en weer
  /// terug, dan staat die rij nog steeds achteraan de wacht — achter honderd rijen die allang van
  /// het scherm zijn, op een baan van zestig requests per minuut. Je zit dan minuten naar een
  /// molentje te kijken van een rij die de app al lang geleden had kunnen ophalen.
  ///
  /// Herhalen kan niet blijven duren: een lookup die niets oplevert zet de rij alsnog op
  /// `detailed`, en dan valt hij op de eerste regel hieronder af.
  void _wantDetail(ReleaseChoice c) {
    if (c.isMb || c.detailed || c.releaseId <= 0 || c.releaseId == _bezigMet) return;
    _stapel.removeWhere((x) => x.releaseId == c.releaseId);
    _stapel.add(c);
    if (_detailBezig) return;
    _detailBezig = true;
    WidgetsBinding.instance.addPostFrameCallback((_) => _werkStapelAf());
  }

  Future<void> _werkStapelAf() async {
    if (!mounted) {
      _detailBezig = false;
      return;
    }
    final settings = context.read<AppSettings>();
    while (mounted && _stapel.isNotEmpty) {
      final gevraagd = _stapel.removeLast();
      // De rij zoals hij NU in de lijst staat, en niet zoals hij was toen de bouwer hem aanwees.
      // Daartussen kan het nummerveld dezelfde uitgave opnieuw hebben opgehaald, met meer erin;
      // doorwerken op het oude exemplaar zou dat weer overschrijven.
      final voor = _choices;
      final j = voor == null ? -1 : voor.indexWhere((x) => x.key == gevraagd.key);
      final c = j >= 0 ? voor![j] : gevraagd;
      if (c.detailed) continue;
      _bezigMet = c.releaseId;
      final filled = await DiscogsService(settings).detailOf(c).catchError((_) => null);
      _bezigMet = 0;
      if (!mounted) break;
      final list = _choices;
      if (list == null) continue;
      final i = list.indexWhere((x) => x.key == c.key);
      if (i < 0) continue;
      // A failed lookup still ANSWERS the question. Returning here left the row saying "scans
      // ophalen…" with its little spinner for as long as the dialog stayed open. The row promised
      // something that was no longer coming. Marked as looked-up instead: the three slots then read
      // "asked, and there was nothing", which is true and is what the crosses are for.
      setState(() => _choices = [...list]..[i] = filled ?? list[i].withArt());
    }
    _detailBezig = false;
  }

  /// Haal precies de uitgave op die in het veld staat — of elke uitgave van dat master.
  ///
  /// **Waarom dit veld er is.** Het zoeken op naam komt uit bij een master, en soms bij het
  /// verkeerde: van "Te Quiero" bestaan er meerdere, en de persing met de cd-scan hing onder een
  /// master dat het zoeken nooit koos. Dan is er geen zoekterm die je kunt bedenken om er alsnog te
  /// komen — maar het nummer staat gewoon op de pagina waar je naar kijkt. Dit is de deur die
  /// daarvoor open moet staan.
  Future<void> _haalNummer() async {
    // Een leeg veld is geen fout maar een onafgemaakte handeling, en "dat lijkt geen Discogs-nummer"
    // is daar een raar antwoord op: er stond niets om op te lijken. Dit is wat je krijgt als je op
    // Toon drukt om te kijken wat de knop doet — dan hoort er te staan wat je moet invullen.
    if (_nummerCtl.text.trim().isEmpty) {
      setState(() => _nummerFout =
          'Vul eerst een nummer of een link in. Het nummer van een uitgave (7738290) geeft die ene '
          'uitgave; een masternummer ([m1938390]) geeft alle persingen van dat album.');
      return;
    }
    final verwijzing = DiscogsVerwijzing.ontleed(_nummerCtl.text);
    if (verwijzing == null) {
      setState(() => _nummerFout =
          'Dat lijkt geen Discogs-nummer. Plak het nummer van de uitgave (7738290), de vorm met '
          'de letter ([r7738290] of [m1938390]) of gewoon de link.');
      return;
    }
    final settings = context.read<AppSettings>();
    final dg = DiscogsService(settings);
    // Zonder sleutel komt er nooit een antwoord, en "Discogs kent deze uitgave niet" zou dan een
    // leugen zijn over iets wat de app zelf weet.
    if (!dg.available) {
      setState(() => _nummerFout =
          'Er is geen Discogs-sleutel ingesteld. Zet die eerst bij Instellingen → Discogs.');
      return;
    }
    setState(() {
      _zoeken = true;
      _nummerFout = null;
    });

    // Bovenaan erbij, zodra er iets is. Dezelfde weg als de gewone lijst, dus een rij die al
    // stond en al zijn scans had houdt ze — zie [rijkdom].
    var gezien = 0;
    var geplaatst = 0;
    void binnen(List<ReleaseChoice> rijen) {
      if (!mounted || rijen.length <= gezien) return;
      final verse = rijen.sublist(gezien);
      gezien = rijen.length;
      // `ontdubbel: false`: hier is met zoveel woorden om deze uitgave gevraagd. De gewone
      // samenvoeging laat een Discogs-persing vallen zodra MusicBrainz dezelfde kent, en dan zou
      // Toon indrukken precies niets doen — de fout waar dit veld voor gemaakt is.
      //
      // `opIndex` telt op, zodat pagina twee ONDER pagina één komt. Discogs levert op datum: op nul
      // zetten zou de oorspronkelijke persing onderaan het blok zetten in plaats van bovenaan.
      final n = _merge(verse, opIndex: geplaatst, ontdubbel: false);
      if (n == 0) return;
      final eerste = geplaatst == 0;
      geplaatst += n;
      // Anders kan de rij die je zojuist opvroeg achter een formaatknop verstopt zitten, of blijft
      // "Geen uitgaves gevonden" over een lijst staan die er nu wél is.
      setState(() {
        _filter = 'Alles';
        _error = null;
        _gemarkeerd ??= verse.first.key;
      });
      // Alleen bij de eerste lading. Een master van zes pagina's zou de lijst anders zes keer onder
      // je vinger vandaan naar boven trekken terwijl je zit te lezen.
      if (eerste && _scroll.hasClients) _scroll.jumpTo(0);
    }

    setState(() => _gemarkeerd = null);
    try {
      if (verwijzing.isMaster) {
        await dg.keuzesVanMaster(
          verwijzing.id,
          onPartial: binnen,
          gestopt: () => !mounted,
          // Ook deze weg heeft een plafond (vierhonderd rijen, zes pagina's), en een plafond dat
          // niets zegt is de fout waar deze hele wijziging over gaat.
          onEinde: (totaal, meer) {
            if (!mounted) return;
            setState(() {
              if (totaal > _dgTotaal) _dgTotaal = totaal;
              _dgMeer = _dgMeer || meer;
            });
          },
        );
      } else {
        final een = await dg.keuzeVanRelease(verwijzing.id);
        if (een != null) binnen([een]);
      }
    } catch (_) {
      // Geplaatst is dan nul, en de regel hieronder zegt het.
    }
    if (!mounted) return;
    setState(() {
      _zoeken = false;
      if (geplaatst == 0) {
        // Geteld wordt wat er OP HET SCHERM kwam, niet wat de dienst teruggaf. Dat verschil is een
        // gebruiker die op Toon drukt en niets ziet gebeuren, zonder een woord waarom.
        _nummerFout = verwijzing.isMaster
            ? 'Discogs kent master ${verwijzing.id} niet, of was niet bereikbaar.'
            : 'Discogs kent uitgave ${verwijzing.id} niet, of was niet bereikbaar.';
      }
    });
  }

  /// Open the assign panel for one pressing, fetching its scans first if that hasn't happened.
  /// Rollen die de gebruiker in DEZE dialoog met de hand heeft toegewezen.
  ///
  /// Zie [_choose]: het kiezen van een uitgave wist met opzet alle rollen, want anders blijft de
  /// hoes van de digitale uitgave staan boven de cd die je net koos. Maar dat wist óók wat je een
  /// tel eerder in dit venster zelf aanwees, en dat is de enige weg die er is als de app de
  /// schijf-scan in het verkeerde vak zet. Deze worden na het wissen teruggezet.
  final Map<String, String> _eigenRollen = {};

  /// Wat je per rij zelf hebt aangewezen: rijsleutel → rol → scan.
  ///
  /// Een laagje óver de drie vakjes van een rij heen, zodat je meteen ziet wat je koos zonder dat
  /// de rij zelf herschreven hoeft te worden. Weggehaalde rollen staan er niet in, en dan komt de
  /// gok van de app er vanzelf weer onderuit.
  final Map<String, Map<String, ChoiceImage>> _rolOverride = {};

  Future<void> _assign(ReleaseChoice c) async {
    if (!mounted) return;
    final lib = context.read<LibraryStore>();
    Map<String, String> lees() =>
        {...lib.albumArtRoles(widget.album.artist, widget.album.title)};
    final voor = lees();
    final gekozen = await showDialog<Map<String, ChoiceImage>>(
        context: context, builder: (_) => AssignScansDialog(album: widget.album, choice: c));
    if (!mounted) return;
    // Alleen wat hier veranderde. Rollen die al op schijf stonden horen wél weg te vallen bij het
    // kiezen van een andere uitgave — dat is juist waar dat wissen voor is.
    //
    // Beide RICHTINGEN, en dat is niet vanzelfsprekend: in het venster hiernaast haal je een rol
    // weg door hem nog een keer aan te tikken, en "Alles weer laten raden" wist ze allemaal. Keek
    // dit alleen naar wat erbij kwam, dan zou [_choose] straks netjes terugzetten wat je zojuist
    // met opzet had weggehaald — en een handmatige rol wint van de uitgave die je kiest, dus je
    // zou hem er niet meer af krijgen.
    final na = lees();
    for (final sleutel in {...voor.keys, ...na.keys}) {
      final nu = na[sleutel];
      if (nu == voor[sleutel]) continue;
      if (nu == null) {
        _eigenRollen.remove(sleutel);
      } else {
        _eigenRollen[sleutel] = nu;
      }
    }
    // En de rij laten zien wat je gekozen hebt.
    //
    // Zonder dit sluit het venster en staat de rij er precies zo bij als ervoor: de scan die je net
    // als cd aanwees zit nog in het vak "achter", want die drie vakjes tonen wat DISCOGS ervan
    // dacht. Dan heb je iets opgeslagen en zie je er niets van.
    //
    // NAAST de rij en niet erin. De verleiding is om de rij zelf te herschrijven met `withArt`,
    // maar die zet `detailed` onvoorwaardelijk op waar — en dan beweert een rij die nog nooit is
    // opgezocht dat hij geen achterkant en geen cd-scan heeft, en wordt hij ook nooit meer
    // opgezocht. Precies de leugen waar de rest van dit scherm van af moest. Bovendien is een los
    // laagje omkeerbaar: haal je een rol weer weg, dan valt de gok van de app er vanzelf onder
    // vandaan, waar een overschreven rij hem kwijt was.
    if (gekozen == null) return;
    setState(() => _rolOverride[c.key] = gekozen);
  }

  Future<void> _choose(ReleaseChoice c) async {
    if (_busy) return;
    setState(() => _busy = true);
    final lib = context.read<LibraryStore>();
    final settings = context.read<AppSettings>();
    final mbSvc = context.read<MusicBrainzService>();
    try {
      Uint8List? front;
      if (c.front != null) {
        // Each catalogue serves its own images; Discogs wants its token on the request.
        front = c.isMb
            ? await mbSvc.fetchImage(c.front!.uri)
            : await DiscogsService(settings).fetchImage(c.front!.uri);
      }
      if (!mounted) return;
      // Choosing an EDITION means using its scans — all three of them. Any single scan picked
      // earlier is an override that outranks the pressing, so leaving those in place made this
      // button look like it did nothing: you chose the CD and kept the digital sleeve.
      await lib.clearAlbumArtRoles(widget.album.artist, widget.album.title);
      // Behalve wat je in ditzelfde venster net zelf hebt aangewezen. Anders is "zoek de scan op,
      // wijs hem toe, kies dan deze uitgave" een handeling die zichzelf ongedaan maakt — en dat is
      // precies de weg die openstaat als de app de schijf-scan in het verkeerde vak zette.
      for (final e in _eigenRollen.entries) {
        await lib.setAlbumArtRole(widget.album.artist, widget.album.title, e.key, e.value);
      }
      await lib.applyCorrection(widget.album, settings,
          coverBytes: front,
          discogsRelease: c.isMb ? null : c.releaseId,
          mbid: c.isMb ? c.mbid : null);
      if (mounted) Navigator.of(context).pop(true);
    } catch (_) {
      // The pin may already be on disk; saying nothing would leave the dialog dead and the button
      // spinning, which is how a failure here used to present.
      if (mounted) {
        setState(() => _busy = false);
        _srcToast(context, 'Kon deze uitgave niet toepassen.');
      }
    }
  }

  /// Take this pressing's numbering for the library's own files.
  ///
  /// Separate from choosing it, because they are different decisions: one describes the record,
  /// the other rewrites what the tracklist says. A user with correct tags wants only the first.
  Future<void> _renumber(ReleaseChoice c) async {
    final lib = context.read<LibraryStore>();
    final mbSvc = context.read<MusicBrainzService>();
    var list = c.tracklist;
    // A row arrives without a tracklist until something looks it up — the picker lists a whole
    // master off one request and fills the rest in as rows come into view. So ask, per catalogue,
    // rather than telling the user a pressing has no numbering when only nobody had asked yet.
    if (list.isEmpty && c.isMb && c.mbid != null) {
      final full = await mbSvc.release(c.mbid!);
      if (full != null) list = await mbSvc.tracklistOf(full);
    } else if (list.isEmpty && !c.isMb && c.releaseId > 0) {
      final full = await DiscogsService(context.read<AppSettings>()).release(c.releaseId);
      if (full != null) {
        list = [for (final t in full.tracklist) ChoiceTrack(t.position, t.title, t.seconds)];
      }
    }
    if (!mounted || list.isEmpty) {
      if (mounted) _srcToast(context, 'Deze uitgave geeft geen nummering.');
      return;
    }
    final plan = lib.planRenumber(widget.album, list);
    if (!mounted) return;
    final done = await showDialog<bool>(
        context: context, builder: (_) => RenumberDialog(album: widget.album, plan: plan));
    if (done == true && mounted) Navigator.of(context).pop(true);
  }

  @override
  Widget build(BuildContext context) {
    // `select` en geen `watch`: dit venster heeft van de hele bibliotheek maar één ding nodig — welke
    // uitgave vastgezet is. Met `watch` werd de kiezer opnieuw opgebouwd bij élke melding van de
    // bibliotheek, en die meldt tijdens het verrijken aan één stuk door. Zo hertekent hij alleen nog
    // als de vastgezette uitgave werkelijk verandert.
    //
    // Beide sleutels, want een album dat op een MusicBrainz-persing is vastgezet markeerde eerder
    // geen enkele rij: de kiezer vroeg alleen naar de Discogs-speld.
    final pinnedKey = context.select<LibraryStore, String?>((lib) {
      final mb = lib.pinnedMbid(widget.album);
      if (mb != null) return 'mb:$mb';
      final dg = lib.pinnedRelease(widget.album);
      return dg != null ? 'dg:$dg' : null;
    });
    return Dialog(
      backgroundColor: _panel,
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
      child: SizedBox(
        width: dialogWidth(context, 820),
        height: dialogHeight(context, 660),
        child: Padding(
          padding: const EdgeInsets.all(20),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Row(children: [
                const Text('Uitgave kiezen', style: TextStyle(fontSize: 18, fontWeight: FontWeight.w700)),
                const Spacer(),
                IconButton(icon: const Icon(Icons.close_rounded), onPressed: () => Navigator.of(context).pop(false)),
              ]),
              Text(
                  '${widget.album.artist} — ${widget.album.title}'
                  // Hoeveel er staan, want sinds de lijst compleet is kan hij lang zijn — en dan is
                  // "hoeveel zijn er eigenlijk?" een echte vraag. Tijdens het aanvullen loopt het
                  // getal op, wat meteen laat zien dat er nog iets binnenkomt.
                  //
                  // Geteld wordt wat er ZICHTBAAR is. Het aantal van de hele lijst boven een lijst
                  // die op CD gefilterd staat, is een getal dat de rijen eronder tegenspreekt.
                  '${_telRegel()}',
                  style: const TextStyle(color: _muted, fontSize: 12.5)),
              const SizedBox(height: 10),
              _nummerVeld(),
              const SizedBox(height: 10),
              // Filters over what was fetched, not another trip to Discogs.
              Row(children: [
                for (final f in const ['Alles', 'CD', 'Vinyl', 'Digitaal'])
                  Padding(
                    padding: const EdgeInsets.only(right: 6),
                    child: InkWell(
                      onTap: () => setState(() => _filter = f),
                      borderRadius: BorderRadius.circular(999),
                      child: Container(
                        padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 5),
                        decoration: BoxDecoration(
                          color: _filter == f ? _accent : Colors.white.withValues(alpha: .06),
                          borderRadius: BorderRadius.circular(999),
                        ),
                        child: Text(f,
                            style: TextStyle(
                                fontSize: 12,
                                color: _filter == f ? Colors.white : _muted,
                                fontWeight: _filter == f ? FontWeight.w600 : FontWeight.w400)),
                      ),
                    ),
                  ),
              ]),
              const SizedBox(height: 12),
              Expanded(child: _body(pinnedKey)),
              // MusicBrainz answers in about two seconds and Discogs in fifteen, so the list is
              // usable long before it is finished. Say which, rather than let a short list look
              // like the whole answer.
              if (_mbDone && !_dgDone)
                const Padding(
                  padding: EdgeInsets.only(top: 8),
                  child: Row(children: [
                    SizedBox(
                        width: 11,
                        height: 11,
                        child: CircularProgressIndicator(strokeWidth: 1.6, color: _muted)),
                    SizedBox(width: 8),
                    Text('Discogs vult nog aan…', style: TextStyle(color: _muted, fontSize: 11.5)),
                  ]),
                ),
              // "Zes? Meer niet?" — en niets op het scherm dat die vraag beantwoordt.
              //
              // Een korte lijst en een AFGEKAPTE lijst zien er precies hetzelfde uit, en de app wist
              // het verschil wel maar zei het alleen in het tweede geval. Dan blijft er twijfel
              // hangen over een lijst die gewoon compleet is. Deze regel is het spiegelbeeld van de
              // oranje hieronder: die zegt dat er meer is, deze dat er niet meer is.
              //
              // Over het OPHALEN en niet over de lijst: onder deze zes kunnen twee persingen samen
              // op één regel staan (zelfde catalogusnummer en land), en cassettes vallen weg. Wat
              // hier wél waar is: Discogs had er niet meer.
              //
              // `_dgTotaal > 0` is de voorwaarde die het waar HOUDT, en die is niet vanzelfsprekend.
              // Er staan Discogs-rijen is niet hetzelfde als: we hebben Discogs afgezocht. Vindt het
              // zoeken geen enkel master, dan komt er via de vastgezette uitgave — of via een nummer
              // dat je zelf intypt — tóch een Discogs-rij op het scherm, terwijl er nooit een
              // versielijst is gelezen. Zonder deze voorwaarde staat er dan "meer heeft Discogs er
              // niet" onder precies het bewijs dat Discogs de plaat wél kent. Dit getal komt uit het
              // pagineringsblok van een echt gelezen pagina, en is dus alleen gevuld als er ook echt
              // iets is afgezocht.
              if (_dgDone &&
                  !_dgMeer &&
                  !_dgFailed &&
                  _dgTotaal > 0 &&
                  (_choices ?? const <ReleaseChoice>[]).any((c) => !c.isMb))
                const Padding(
                  padding: EdgeInsets.only(top: 8),
                  child: Text('Alles opgehaald — meer heeft Discogs er niet onder dit album.',
                      style: TextStyle(color: _muted, fontSize: 11.5)),
                ),
              if (_dgDone && _dgFailed)
                Padding(
                  padding: const EdgeInsets.only(top: 8),
                  child: Text(
                      // Twee verschillende dingen, en de oude regel zei altijd het eerste. Kwam er
                      // wél iets van Discogs binnen, dan is "dit zijn alleen de MusicBrainz-uitgaves"
                      // aantoonbaar onwaar terwijl de Discogs-rijen op het scherm staan.
                      (_choices ?? const <ReleaseChoice>[]).any((c) => !c.isMb)
                          ? 'Een deel van Discogs kwam niet door; deze lijst kan onvolledig zijn.'
                          : 'Discogs was niet bereikbaar — dit zijn alleen de MusicBrainz-uitgaves.',
                      style: const TextStyle(color: _muted, fontSize: 11.5)),
                ),
              // De enige eerlijke regel over een afgekapte lijst. Precies dit — een lijst die
              // ophoudt zonder het te zeggen — is wat deze hele wijziging kwam repareren, dus een
              // nieuw plafond mag niet opnieuw stil zijn.
              // Zonder sleutel is de halve catalogus nooit gevraagd, en dat mag niet als "dit is
              // wat er is" doorgaan. Los van de lege-lijst-melding: juist mét MusicBrainz-rijen
              // erop lijkt de lijst compleet.
              if (!DiscogsService(context.read<AppSettings>()).available)
                const Padding(
                  padding: EdgeInsets.only(top: 8),
                  child: Text(
                      'Er is geen Discogs-sleutel ingesteld — dit zijn alleen de '
                      'MusicBrainz-uitgaves.',
                      style: TextStyle(color: _muted, fontSize: 11.5)),
                ),
              // Niet achter `_dgDone`: het nummerveld kan dit óók zetten, en dan zou de melding
              // wachten op een lijst waar je niet op zit te wachten.
              if (_dgMeer)
                Padding(
                  padding: const EdgeInsets.only(top: 8),
                  child: Text(
                      // "Niet alles staat hier" is de zin die bedoeld werd; er stond iets wat als
                      // "er staan er niet meer dan dit in de lijst" te lezen was, en dat is een
                      // mededeling over de lijst in plaats van over wat eruit gebleven is.
                      //
                      // "Minstens", want het getal is het grootste dat één master noemde — een
                      // ondergrens die waar is, waar een optelsom over masters dat niet zou zijn.
                      _dgTotaal > 0
                          ? 'Niet alles staat hier: Discogs kent er minstens $_dgTotaal.'
                          : 'Niet alles staat hier — er zijn er meer dan er nu in de lijst passen.',
                      style: const TextStyle(color: Color(0xFFE0A33A), fontSize: 11.5)),
                ),
              // Het stilste plafond van allemaal, en uitgerekend degene waar een gezochte persing
              // zich het makkelijkst achter verstopt: het zoeken kiest op naam, loopt de drie
              // best scorende albums af, en de promo hangt net onder de vierde. Grijs en niet
              // oranje — het is geen waarschuwing dat er iets misging, het is waar de volgende
              // stap ligt.
              if (_dgDone && _andereMasters > 0)
                Padding(
                  padding: const EdgeInsets.only(top: 8),
                  child: Text(
                      'Discogs heeft nog $_andereMasters ${_andereMasters == 1 ? 'ander album' : 'andere albums'} '
                      'met deze naam. Staat je uitgave er niet bij, plak dan hierboven het '
                      'masternummer van het juiste album.',
                      style: const TextStyle(color: _muted, fontSize: 11.5)),
                ),
              // Only once something is picked: an empty bar at the bottom of every gallery would be
              // a control that does nothing, most of the time.
              if (_staged.isNotEmpty) ...[
                const Divider(height: 18),
                Row(children: [
                  Expanded(
                    child: Text(
                      // Names what will change, in the words the thumbnails use, so pressing Save is
                      // not a leap of faith.
                      'Overnemen: ${[
                        for (final r in _roles)
                          if (_staged.containsKey(r.$1)) r.$2
                      ].join(', ')}',
                      style: const TextStyle(color: _muted, fontSize: 12),
                    ),
                  ),
                  TextButton(
                    onPressed: _saving ? null : () => setState(_staged.clear),
                    child: const Text('Ongedaan maken'),
                  ),
                  const SizedBox(width: 6),
                  FilledButton.icon(
                    style: FilledButton.styleFrom(backgroundColor: _accent),
                    onPressed: _saving ? null : _save,
                    icon: _saving
                        ? const SizedBox(
                            width: 14,
                            height: 14,
                            child: CircularProgressIndicator(strokeWidth: 2, color: Colors.white))
                        : const Icon(Icons.check_rounded, size: 18),
                    label: Text(_saving ? 'Opslaan…' : 'Opslaan'),
                  ),
                ]),
              ],
            ],
          ),
        ),
      ),
    );
  }

  /// Wat het formaatfilter overlaat, en de vastgezette uitgave bovenaan.
  ///
  /// Eén functie, gelezen door de teller in de kop én door de lijst eronder — twee tellingen die
  /// het oneens kunnen worden is precies hoe een kop "312 uitgaves" boven veertig rijen komt te
  /// staan.
  ///
  /// De vastgezette rij vooraan zetten gebeurt HIER en niet bij het binnenhalen, en dat is met
  /// opzet: hij komt als laatste binnen (hij wordt pas opgehaald als hij onder geen enkel master
  /// bleek te hangen), dus op volgorde van binnenkomst staat je eigen keuze onderaan een lijst van
  /// driehonderd. Waar hij hoort te staan hangt niet af van wanneer hij aankwam.
  List<ReleaseChoice> _zichtbaar(List<ReleaseChoice> alle, String? pinnedKey) {
    // 'File' is what Discogs calls a digital release; nobody looking for one thinks of it that way.
    // Through the shared bucketing, not substring matching: MusicBrainz says `12" Vinyl`,
    // `Digital Media` and `Enhanced CD` where Discogs says `Vinyl` and `File`, and one rule has
    // to cover both or the filters silently hide half the list.
    final uit = _filter == 'Alles'
        ? [...alle]
        : alle.where((c) {
            final m = majorFormat(c.format);
            if (_filter == 'CD') return m == 'CD' || m == 'CDr';
            if (_filter == 'Vinyl') return m == 'Vinyl';
            return m == 'File';
          }).toList();
    if (pinnedKey != null) {
      final i = uit.indexWhere((c) => c.key == pinnedKey);
      if (i > 0) uit.insert(0, uit.removeAt(i));
    }
    return uit;
  }

  String _telRegel() {
    final alle = _choices;
    if (alle == null || alle.isEmpty) return '';
    final n = _zichtbaar(alle, null).length;
    return n == alle.length ? ' · $n uitgaves' : ' · $n van ${alle.length} uitgaves';
  }

  /// "Plak hier het nummer van de uitgave die je wél bedoelt."
  ///
  /// Eén regel, met de knop ernaast, want op een telefoon is de dialoog 340 punten breed en past er
  /// niets naast een veld dat ook nog leesbaar moet zijn. De aanwijzing staat in de hint en niet in
  /// een regel eronder: dat scheelt hoogte in een venster waar de lijst de hoofdzaak is.
  Widget _nummerVeld() => Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        _nummerRegel(),
        if (_nummerFout != null)
          Padding(
            padding: const EdgeInsets.only(top: 6, left: 2),
            child: Text(_nummerFout!,
                style: const TextStyle(color: Color(0xFFE0A33A), fontSize: 11.5)),
          ),
      ]);

  Widget _nummerRegel() => Row(children: [
        Expanded(
          child: TextField(
            controller: _nummerCtl,
            style: const TextStyle(fontSize: 13),
            textInputAction: TextInputAction.search,
            // Enter doet hetzelfde als de knop. Wie een nummer typt drukt daarna op enter.
            onSubmitted: (_) => _zoeken ? null : _haalNummer(),
            decoration: InputDecoration(
              isDense: true,
              contentPadding: const EdgeInsets.symmetric(horizontal: 12, vertical: 10),
              hintText: 'Discogs-nummer of link — bv. 7738290, [r7738290] of [m1938390]',
              hintStyle: const TextStyle(color: _muted, fontSize: 12),
              prefixIcon: const Icon(Icons.tag_rounded, size: 17, color: _muted),
              prefixIconConstraints: const BoxConstraints(minWidth: 34, minHeight: 34),
              filled: true,
              fillColor: Colors.white.withValues(alpha: .05),
              border: OutlineInputBorder(
                borderRadius: BorderRadius.circular(10),
                borderSide: BorderSide.none,
              ),
            ),
          ),
        ),
        const SizedBox(width: 8),
        FilledButton(
          style: FilledButton.styleFrom(
            backgroundColor: _accent,
            padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 14),
          ),
          onPressed: _zoeken ? null : _haalNummer,
          child: _zoeken
              ? const SizedBox(
                  width: 14,
                  height: 14,
                  child: CircularProgressIndicator(strokeWidth: 2, color: Colors.white))
              : const Text('Toon'),
        ),
      ]);

  Widget _body(String? pinnedKey) {
    if (_error != null) return Center(child: Text(_error!, style: const TextStyle(color: _muted)));
    final list = _choices;
    if (list == null) {
      return const Center(
        child: Column(mainAxisSize: MainAxisSize.min, children: [
          CircularProgressIndicator(strokeWidth: 2, color: _accent),
          SizedBox(height: 14),
          // Honest about the wait: this is several Discogs calls plus their images, and Discogs
          // allows sixty a minute.
          Text('Uitgaves en scans ophalen…', style: TextStyle(color: _muted, fontSize: 12.5)),
        ]),
      );
    }
    if (list.isEmpty) return const Center(child: Text('Geen uitgaves gevonden.', style: TextStyle(color: _muted)));
    final shown = _zichtbaar(list, pinnedKey);
    if (shown.isEmpty) {
      return const Center(child: Text('Geen uitgaves in dit formaat.', style: TextStyle(color: _muted)));
    }
    return ListView.separated(
      controller: _scroll,
      itemCount: shown.length,
      separatorBuilder: (_, __) => const SizedBox(height: 10),
      itemBuilder: (_, i) {
        final c = shown[i];
        // Only rows that are actually built get looked up — that is what makes this cheap.
        _wantDetail(c);
        final isPinned = pinnedKey != null && pinnedKey == c.key;
        // De rij die zojuist op nummer is opgehaald. Een andere kleur dan de vastgezette rij, want
        // het zijn twee verschillende dingen: "dit is je keuze" tegenover "dit is wat je opvroeg".
        final gevraagd = !isPinned && _gemarkeerd != null && _gemarkeerd == c.key;
        return UitgaveRij(
          uitgave: c,
          vastgezet: isPinned,
          opgevraagd: gevraagd,
          eigenScans: _rolOverride[c.key],
          klaargezet: _staged,
          onKiezen: () => _choose(c),
          onScans: () => _assign(c),
          onNummering: () => _renumber(c),
          onKlaarzetten: _stage,
        );
      },
    );
  }

}

/// Eén uitgave als rij in de uitgavekiezer.
///
/// **Los van de dialoog, en dat is de reden dat deze er staat.** De kiezer zelf leunt op veertien
/// providers, op het netwerk en op een libmpv die in een toetsrun niet bestaat; hij is hier niet te
/// bouwen en dus ook niet op te meten. Deze rij krijgt alleen feiten en terugroepen, en is daarmee
/// wél te pompen op precies de breedte van een telefoon — zie test/uitgave_rij_test.dart.
///
/// Dat is geen luxe achteraf. Deze ene rij is vier keer op rij op dezelfde manier misgegaan: er
/// stonden dingen naast elkaar die niet naast elkaar pasten, en Flutter meldt dat niet — het duwt
/// wat er niet bij kan buiten de rij, waar het te zien is noch aan te tikken. Elke keer was een
/// schermafbeelding van het toestel nodig om het te merken. Een toets die de rij bouwt en omvalt
/// bij overloop had elk van die vier keren meteen gevonden.
class UitgaveRij extends StatelessWidget {
  const UitgaveRij({
    super.key,
    required this.uitgave,
    required this.onKiezen,
    required this.onScans,
    required this.onNummering,
    required this.onKlaarzetten,
    this.vastgezet = false,
    this.opgevraagd = false,
    this.eigenScans,
    this.klaargezet = const {},
  });

  final ReleaseChoice uitgave;

  /// De uitgave waar dit album aan vastzit, en de uitgave die zojuist op nummer is opgehaald.
  /// Twee verschillende dingen, dus twee kleuren: "dit is je keuze" tegenover "dit is wat je vroeg".
  final bool vastgezet, opgevraagd;

  /// Wat de gebruiker voor DEZE uitgave zelf aanwees: rol → scan. Gaat voor op de gok van de app.
  final Map<String, ChoiceImage>? eigenScans;

  /// Wat er in de kiezer klaarstaat om overgenomen te worden: rol → scan. Alleen om de rand om het
  /// gekozen plaatje te tekenen.
  final Map<String, ChoiceImage> klaargezet;

  final VoidCallback onKiezen, onScans, onNummering;
  /// De RIJ hoort erbij, niet alleen de scan. Een rij die nog niet `detailed` is levert alleen een
  /// miniatuur van 150 pixels, en het opslaan moet dan eerst de volle scan kunnen ophalen — daar is
  /// de rij voor nodig. Zie [ChoiceImage.alleenMiniatuur].
  final void Function(String rol, ChoiceImage scan, ReleaseChoice rij) onKlaarzetten;

  @override
  Widget build(BuildContext context) => InkWell(
        onTap: onKiezen,
        borderRadius: BorderRadius.circular(10),
        child: Container(
          padding: const EdgeInsets.all(10),
          decoration: BoxDecoration(
            color: vastgezet
                ? _accent.withValues(alpha: .16)
                : opgevraagd
                    ? _accent2.withValues(alpha: .10)
                    : _panel2,
            borderRadius: BorderRadius.circular(10),
            border: Border.all(
                color: vastgezet
                    ? _accent
                    : opgevraagd
                        ? _accent2
                        : Colors.transparent),
          ),
          child: _binnenkant(context),
        ),
      );

  /// Eén uitgave als rij — op een breed scherm op één regel, op een telefoon op twee.
  ///
  /// **Waarom twee vormen.** Alles op één regel is 300 punten breed op een staande telefoon: drie
  /// scans van 58 plus hun randen is al 204, en wat er overblijft moet de tekst én twee knoppen én
  /// het vinkje dragen. Dat past niet, en Flutter lost dat niet op — het duwt de laatste dingen
  /// gewoon buiten de rij, waar ze te zien zijn noch aan te tikken. Precies wat er gebeurde toen de
  /// scan-knop erbij kwam: de nummering-knop viel eraf.
  ///
  /// Op een telefoon staat daarom álles onder elkaar: de drie scans, dan de beschrijving over de
  /// volle breedte, dan de knoppen rechts. De eerste poging zette alleen de knoppen op een eigen
  /// regel en liet de tekst naast de scans staan — dat maakte de knoppen bereikbaar en de rest
  /// niet: er bleven vijfentachtig punten over voor een titel, een label en vier bordjes, dus de
  /// titel was na drie letters op en elk bordje viel afzonderlijk over de rand. Naast elkaar zetten
  /// wat allebei de volle breedte nodig heeft, is het probleem — niet hoe het wordt afgekapt.
  ///
  /// In liggende stand blijft het één regel, want daar is die breedte er wel.
  Widget _binnenkant(BuildContext context) {
    final c = uitgave;
    // The three scans side by side, so what you get is visible rather than described.
    // Clicking one opens every scan this pressing has, to say which is which — the roles
    // below are inferred, and inference on a catalogue that never labels its images gets
    // the back and the disc the wrong way round often enough to need an answer.
    // Wat de gebruiker zelf aanwees gaat vóór de gok van de app — zie [eigenScans].
    final eigen = eigenScans;
    final scans = <Widget>[
      _thumb(eigen?['front'] ?? c.front, 'hoes',
          role: 'front', row: c, onLongPress: onScans),
      const SizedBox(width: 8),
      _thumb(eigen?['back'] ?? c.back, 'achter',
          role: 'back', row: c, onLongPress: onScans),
      const SizedBox(width: 8),
      _thumb(eigen?['disc'] ?? c.disc, 'cd',
          role: 'disc', row: c, onLongPress: onScans),
    ];
    final knoppen = <Widget>[
      // Alle scans van deze uitgave, als KNOP.
      //
      // Dit zat alleen op lang indrukken van een van de drie plaatjes, en dat is op een
      // telefoon onvindbaar: je drukt lang op de RIJ (waar die handeling niet op zit), er
      // gebeurt niets, en je concludeert dat het niet kan. En juist deze weg is de enige
      // die werkt als de app een scan in het verkeerde vak zet — wat bij een wit cd-label
      // op een witte achtergrond gebeurt, want daar valt aan helderheid niets te meten.
      // Een uitweg die je moet raden is geen uitweg.
      TvLabelled(
        label: 'Alle scans van deze uitgave',
        child: IconButton(
          icon: const Icon(Icons.photo_library_outlined, size: 18),
          tooltip: 'Alle scans van deze uitgave — zelf kiezen wat de hoes, de achterkant '
              'en de cd is',
          constraints: const BoxConstraints(minWidth: 34, minHeight: 34),
          onPressed: onScans,
        ),
      ),
      TvLabelled(
        label: 'Nummering van deze uitgave overnemen',
        child: IconButton(
          icon: const Icon(Icons.format_list_numbered_rounded, size: 19),
          tooltip: 'Nummering van deze uitgave overnemen',
          constraints: const BoxConstraints(minWidth: 34, minHeight: 34),
          onPressed: onNummering,
        ),
      ),
      if (vastgezet) const Icon(Icons.check_circle_rounded, color: _accent, size: 20),
    ];
    final tekst = _tekst(c);

    if (isCompact(context)) {
      return Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        Row(children: scans),
        const SizedBox(height: 8),
        tekst,
        Row(mainAxisAlignment: MainAxisAlignment.end, children: knoppen),
      ]);
    }
    return Row(children: [
      ...scans,
      const SizedBox(width: 14),
      Expanded(child: tekst),
      ...knoppen,
    ]);
  }

  Widget _tekst(ReleaseChoice c) => Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                  Text(c.line, maxLines: 1, overflow: TextOverflow.ellipsis,
                      style: const TextStyle(fontWeight: FontWeight.w600, fontSize: 13.5)),
                  if ((c.label ?? '').isNotEmpty)
                    Text(c.label!, maxLines: 1, overflow: TextOverflow.ellipsis,
                        style: const TextStyle(color: _muted, fontSize: 12)),
                  const SizedBox(height: 6),
                  // `Wrap` en geen `Row`, en dat is geen opmaakvoorkeur. Deze vier plaatjes zijn
                  // samen ruim tweehonderd punten breed en op een staande telefoon houdt de tekst
                  // er nog geen negentig over. Een Row buigt daar niet voor: hij tekent door en
                  // laat Flutter er gele strepen overheen zetten, met het laatste bordje half
                  // buiten beeld. Wrap zet ze op een tweede regeltje en klaar.
                  Wrap(
                    spacing: 6,
                    runSpacing: 4,
                    crossAxisAlignment: WrapCrossAlignment.center,
                    children: [
                      // Which catalogue this row came from. The user asked to choose the source, so
                      // it has to be visible rather than inferred from the row's shape.
                      _source(c.isMb),
                      // Het nummer van deze uitgave, zichtbaar. Dit is de tegenhanger van het veld
                      // bovenaan: daar type je een nummer in, hier lees je hem af — zo kun je een
                      // rij die je hier vindt terugzoeken op Discogs zelf, en andersom.
                      if (!c.isMb && c.releaseId > 0)
                        Text('r${c.releaseId}',
                            style: const TextStyle(color: _muted, fontSize: 10.5)),
                      // Until this pressing has been looked up we do not know whether it has a back
                      // or a disc, and saying "–" would be a claim we have not earned. A row you can
                      // see is always on its way now — being visible is what starts the lookup — so
                      // the spinner is always honest here.
                      if (!c.detailed)
                        // Het molentje en zijn tekst horen bij elkaar; los in de Wrap zouden ze op
                        // twee regels kunnen belanden.
                        const Row(mainAxisSize: MainAxisSize.min, children: [
                          SizedBox(
                              width: 10,
                              height: 10,
                              child: CircularProgressIndicator(strokeWidth: 1.4, color: _muted)),
                          SizedBox(width: 6),
                          // `Flexible`, want deze twee zitten expres in een eigen Row en juist
                          // daardoor beschermt de Wrap eromheen ze niet: een Row geeft zijn vaste
                          // kinderen geen breedtegrens, dus de tekst neemt zijn volle 78 punten en
                          // loopt op een smalle telefoon een paar punten over de rand. Zo krimpt hij
                          // met puntjes in plaats van eroverheen te tekenen.
                          Flexible(
                            child: Text('scans ophalen…',
                                maxLines: 1,
                                overflow: TextOverflow.ellipsis,
                                style: TextStyle(color: _muted, fontSize: 10.5)),
                          ),
                        ])
                      else ...[
                        _tag('achterkant', c.hasBack),
                        _tag('cd-scan', c.hasDisc),
                      ],
                    ],
                  ),
                ]);

  /// One scan of one pressing, and a way to say "this one, for this role".
  ///
  /// Tap picks it for [role] on the RECORD — the sleeve of the digital edition beside the disc of
  /// the CD, which is the thing a record collector's own copy actually looks like. Long-press still
  /// opens every scan this pressing has, for the case where the roles within one pressing are simply
  /// swapped.
  Widget _thumb(ChoiceImage? img, String label,
      {required String role, required ReleaseChoice row, VoidCallback? onLongPress}) {
    final staged = klaargezet[role];
    final chosen = img != null && staged != null && staged.uri == img.uri;
    // Nothing here yet, and nobody has looked — as opposed to looked and found none.
    final waiting = img == null && !row.detailed;
    return InkWell(
      onTap: img == null ? null : () => onKlaarzetten(role, img, row),
      onLongPress: onLongPress,
      borderRadius: BorderRadius.circular(6),
      child: Tooltip(
        message: img != null
            ? 'Klik: neem deze $label over · Lang indrukken: alle scans van deze uitgave'
            // "Has none" and "nobody has asked yet" are different statements, and the row now
            // appears before its scans do — so for a second or two the cross was claiming the
            // first while the second was true. The badges beside it already made that distinction;
            // the thumbnails were still saying it flatly.
            : waiting
                ? 'De scans van deze uitgave worden opgehaald…'
                : 'Deze uitgave heeft geen $label',
        child: Column(children: [
          // Een randje van twee punten om een plaatje van 58 was het enige dat "deze heb ik gekozen"
          // zei, en op een scherm vol miniaturen is dat te weinig. Gemeld op 27-08-2026: *"waardoor
          // ik soms twijfel of hij het wel heeft aangepast"*. Het vinkje eroverheen laat geen twijfel;
          // het ligt IN het vakje, dus de rij wordt er geen punt breder van.
          Stack(children: [
            Container(
              decoration: BoxDecoration(
                borderRadius: BorderRadius.circular(8),
                border: Border.all(
                  color: chosen ? _accent : Colors.transparent,
                  width: 2,
                ),
              ),
              padding: const EdgeInsets.all(1),
              child: ClipRRect(
                borderRadius: BorderRadius.circular(6),
                child: img != null
                    ? _netCover(img.thumb, size: 58, radius: 6)
                    : Container(
                        width: 58,
                        height: 58,
                        color: Colors.white.withValues(alpha: .04),
                        // Nothing at all while we wait: an empty frame reads as "not yet", where any
                        // mark at this size reads as an answer.
                        child: waiting
                            ? null
                            : const Icon(Icons.close_rounded, size: 16, color: _muted)),
              ),
            ),
            if (chosen)
              Positioned(
                right: 0,
                bottom: 0,
                // Een sleutel en niet "zoek het vinkje": op deze rij staan al vinkjes van dezelfde
                // soort — de bordjes "achterkant" en "cd-scan" gebruiken hetzelfde icoon. Een toets
                // die op het icoon zoekt vindt die van de bordjes en zegt niets over dit vinkje.
                child: Container(
                  key: const Key('scan-klaargezet'),
                  decoration: const BoxDecoration(color: _accent, shape: BoxShape.circle),
                  padding: const EdgeInsets.all(2),
                  child: const Icon(Icons.check_rounded, size: 13, color: Colors.white),
                ),
              ),
          ]),
          const SizedBox(height: 3),
          // Het bijschrift mag het vakje niet BREDER maken dan het plaatje.
          //
          // Zonder deze breedte bepaalt het woord de kolom: zet iemand de systeemletters op 150%,
          // dan wordt "achter" breder dan de 58 van de scan erboven, en dan passen drie vakjes niet
          // meer naast elkaar op een smal toestel. De toets ving dat op 360 punten — achttien
          // pixels eroverheen — en op het toestel is dat precies weer een rij die stilletjes
          // buiten zijn kader tekent.
          SizedBox(
            width: 58,
            child: Text(label,
                maxLines: 1,
                overflow: TextOverflow.ellipsis,
                textAlign: TextAlign.center,
                style: TextStyle(
                    color: chosen ? _accent : _muted,
                    fontSize: 10,
                    fontWeight: chosen ? FontWeight.w700 : FontWeight.w400)),
          ),
        ]),
      ),
    );
  }

  /// Which catalogue found this pressing. The user asked to be able to choose the source, so the
  /// source has to be readable on the row rather than inferred from what the row happens to carry.
  Widget _source(bool isMb) => Container(
        padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 3),
        decoration: BoxDecoration(
          color: (isMb ? _accent : _accent2).withValues(alpha: .18),
          borderRadius: BorderRadius.circular(999),
        ),
        child: Text(isMb ? 'MusicBrainz' : 'Discogs',
            style: TextStyle(
                fontSize: 10.5, fontWeight: FontWeight.w600, color: isMb ? _accent : _accent2)),
      );

  /// Present or absent, stated rather than implied — the reason this dialog exists.
  Widget _tag(String text, bool on) => Container(
        padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 3),
        decoration: BoxDecoration(
          color: on ? _accent2.withValues(alpha: .16) : Colors.white.withValues(alpha: .05),
          borderRadius: BorderRadius.circular(999),
        ),
        child: Row(mainAxisSize: MainAxisSize.min, children: [
          Icon(on ? Icons.check_rounded : Icons.remove_rounded, size: 11, color: on ? _accent2 : _muted),
          const SizedBox(width: 4),
          Text(text, style: TextStyle(color: on ? _accent2 : _muted, fontSize: 10.5)),
        ]),
      );
}

/// Say which scan is the sleeve, which is the back, and which is the disc.
///
/// Discogs marks one image "primary" and calls the rest "secondary" — it never states what a
/// picture SHOWS. So the app infers: primary is the front, wider-than-tall is the rear inlay, and a
/// punched hole in the middle means a disc. Measured on Random Access Memories, eight of its
/// fourteen scans are wider than tall, so the back-cover rule picks whichever booklet spread comes
/// first. This is where you say otherwise, and your answer outranks every guess afterwards.
class AssignScansDialog extends StatefulWidget {
  final Album album;
  final ReleaseChoice choice;
  const AssignScansDialog({super.key, required this.album, required this.choice});

  @override
  State<AssignScansDialog> createState() => _AssignScansDialogState();
}

class _AssignScansDialogState extends State<AssignScansDialog> {
  List<ChoiceImage>? _images;
  String? _error;

  static const _roles = artRoles;

  /// De keuze zoals hij HIER staat, nog niet op schijf.
  ///
  /// **Waarom dit niet meer meteen wegschrijft.** Elke tik ging rechtstreeks naar de bibliotheek.
  /// Dat werkt, maar er is niets aan te zien: geen knop die indrukt, geen melding, en de rij
  /// eronder verandert pas als je het venster sluit. "Ik weet nooit of het iets gedaan heeft" is
  /// dan een terechte klacht en niet een kwestie van beter kijken.
  ///
  /// Nu is het een keuze die je maakt en dan opslaat: je ziet bovenaan meteen wat het wordt, de
  /// opslaanknop kleurt op zodra er iets te bewaren valt, en sluiten zonder opslaan laat alles
  /// zoals het was.
  final Map<String, String> _rollen = {};

  /// Wat er op schijf stond toen dit venster openging — om te weten of er iets veranderd is.
  Map<String, String> _begin = const {};
  bool _opslaan = false;

  bool get _gewijzigd {
    if (_rollen.length != _begin.length) return true;
    for (final e in _rollen.entries) {
      if (_begin[e.key] != e.value) return true;
    }
    return false;
  }

  @override
  void initState() {
    super.initState();
    final lib = context.read<LibraryStore>();
    _begin = {...lib.albumArtRoles(widget.album.artist, widget.album.title)};
    _rollen.addAll(_begin);
    _load();
  }

  /// Schrijft de keuze weg en geeft hem terug aan de kiezer, zodat de rij daar meteen meeverandert.
  Future<void> _bewaar() async {
    if (_opslaan) return;
    setState(() => _opslaan = true);
    final lib = context.read<LibraryStore>();
    try {
      // Wissen en opnieuw zetten: wat hier staat IS de keuze, inclusief wat je weghaalde.
      await lib.clearAlbumArtRoles(widget.album.artist, widget.album.title);
      for (final e in _rollen.entries) {
        await lib.setAlbumArtRole(widget.album.artist, widget.album.title, e.key, e.value);
      }
    } catch (e) {
      if (!mounted) return;
      setState(() => _opslaan = false);
      // MÉT de reden. Die was er — `RemoteClient.edit` gooit een leesbare zin, en de pc stuurt zelfs
      // zijn eigen tekst mee — en `catch (_)` gooide hem weg. "Kon de keuze niet opslaan." is dan
      // alles wat je hebt, en daar valt niets mee te beginnen: staat de pc uit, weigert hij de
      // sleutel, of kent hij deze bewerking niet? Drie heel verschillende problemen, één zin.
      _srcToast(context, 'Kon de keuze niet opslaan: $e');
      return;
    }
    if (!mounted) return;
    final beelden = <String, ChoiceImage>{};
    for (final e in _rollen.entries) {
      for (final i in _images ?? const <ChoiceImage>[]) {
        if (i.uri == e.value) {
          beelden[e.key] = i;
          break;
        }
      }
    }
    Navigator.of(context).pop(beelden);
  }

  Future<void> _load() async {
    // Both read before the first await: after it this State may be gone, and reaching back into
    // context then is exactly what use_build_context_synchronously is warning about.
    final mb = context.read<MusicBrainzService>();
    final settings = context.read<AppSettings>();
    try {
      final c = widget.choice;
      final list = c.isMb
          ? [for (final i in await mb.art(c.mbid ?? '')) ChoiceImage(i.full, i.thumb)]
          : await DiscogsService(settings).allImages(c.releaseId);
      if (!mounted) return;
      setState(() {
        _images = list;
        if (list.isEmpty) _error = 'Deze uitgave heeft geen scans.';
      });
    } catch (_) {
      if (mounted) setState(() => _error = 'Kon de scans niet ophalen.');
    }
  }

  @override
  Widget build(BuildContext context) {
    final roles = _rollen;
    final images = _images;
    return Dialog(
      backgroundColor: _panel,
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
      child: SizedBox(
        width: dialogWidth(context, 760),
        height: dialogHeight(context, 620),
        child: Padding(
          padding: const EdgeInsets.all(20),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Row(children: [
                const Text('Scans toewijzen',
                    style: TextStyle(fontSize: 18, fontWeight: FontWeight.w700)),
                const Spacer(),
                IconButton(
                    icon: const Icon(Icons.close_rounded),
                    onPressed: () => Navigator.of(context).pop()),
              ]),
              const Text('Klik onder een scan om te zeggen wat het is. Jouw keuze wint van wat de app zelf denkt.',
                  style: TextStyle(color: _muted, fontSize: 12.5)),
              const SizedBox(height: 10),
              // Wat het WORDT, boven de keuze zelf.
              //
              // Zonder dit is toewijzen blind: je tikt een chipje aan onder een plaatje ergens in
              // een raster, en nergens staat wat de hoes nu eigenlijk is. Deze drie vakjes zijn het
              // antwoord, en ze veranderen onder je vinger mee.
              _voorbeeld(roles),
              const SizedBox(height: 12),
              Expanded(
                child: _error != null
                    ? Center(child: Text(_error!, style: const TextStyle(color: _muted)))
                    : images == null
                        ? const Center(child: CircularProgressIndicator())
                        : GridView.builder(
                            gridDelegate: const SliverGridDelegateWithMaxCrossAxisExtent(
                                maxCrossAxisExtent: 170,
                                mainAxisSpacing: 14,
                                crossAxisSpacing: 14,
                                childAspectRatio: .78),
                            itemCount: images.length,
                            itemBuilder: (_, i) {
                              final img = images[i];
                              return Column(children: [
                                Expanded(child: _netCover(img.thumb, size: 150, radius: 8)),
                                const SizedBox(height: 6),
                                Row(
                                  mainAxisAlignment: MainAxisAlignment.center,
                                  children: [
                                    for (final (role, label) in _roles)
                                      Padding(
                                        padding: const EdgeInsets.symmetric(horizontal: 2),
                                        child: _roleChip(
                                          label,
                                          on: roles[role] == img.uri,
                                          onTap: () => setState(() {
                                            // Nog een keer op dezelfde rol tikken haalt hem weg, zodat
                                            // een verkeerde toewijzing terug te draaien is zonder het
                                            // hele venster te resetten.
                                            if (roles[role] == img.uri) {
                                              roles.remove(role);
                                            } else {
                                              roles[role] = img.uri;
                                            }
                                          }),
                                        ),
                                      ),
                                  ],
                                ),
                              ]);
                            },
                          ),
              ),
              Padding(
                padding: const EdgeInsets.only(top: 8),
                child: Row(children: [
                  if (roles.isNotEmpty)
                    TextButton(
                      onPressed: _opslaan ? null : () => setState(roles.clear),
                      child: const Text('Alles weer laten raden',
                          style: TextStyle(color: _muted, fontSize: 12)),
                    ),
                  const Spacer(),
                  // De knop die er niet was. Hij zegt ook of er iets te bewaren valt: staat hij uit,
                  // dan is er niets veranderd — en dat is een antwoord op "heeft het iets gedaan?"
                  // nog vóór je hem indrukt.
                  FilledButton.icon(
                    style: FilledButton.styleFrom(backgroundColor: _accent),
                    onPressed: !_gewijzigd || _opslaan ? null : _bewaar,
                    icon: _opslaan
                        ? const SizedBox(
                            width: 14,
                            height: 14,
                            child: CircularProgressIndicator(strokeWidth: 2, color: Colors.white))
                        : const Icon(Icons.check_rounded, size: 18),
                    label: Text(_opslaan
                        ? 'Opslaan…'
                        : _gewijzigd
                            ? 'Opslaan'
                            : 'Niets gewijzigd'),
                  ),
                ]),
              ),
            ],
          ),
        ),
      ),
    );
  }

  /// De drie rollen zoals ze er NU voor staan, met het gekozen plaatje erin.
  Widget _voorbeeld(Map<String, String> roles) => Row(
        children: [
          for (final (role, label) in _roles)
            Padding(
              padding: const EdgeInsets.only(right: 10),
              child: Column(children: [
                ClipRRect(
                  borderRadius: BorderRadius.circular(6),
                  child: roles[role] == null
                      ? Container(
                          width: 52,
                          height: 52,
                          color: Colors.white.withValues(alpha: .04),
                          child: const Icon(Icons.close_rounded, size: 15, color: _muted),
                        )
                      : _netCover(roles[role]!, size: 52, radius: 6),
                ),
                const SizedBox(height: 3),
                Text(label,
                    style: TextStyle(
                        color: roles[role] == null ? _muted : _accent,
                        fontSize: 10,
                        fontWeight: roles[role] == null ? FontWeight.w400 : FontWeight.w700)),
              ]),
            ),
          const Expanded(
            child: Text(
              'Zo komt deze plaat eruit te zien. Een leeg vak betekent: de app mag het zelf blijven '
              'raden.',
              style: TextStyle(color: _muted, fontSize: 11.5),
            ),
          ),
        ],
      );

  Widget _roleChip(String text, {required bool on, required VoidCallback onTap}) => InkWell(
        onTap: onTap,
        borderRadius: BorderRadius.circular(999),
        child: Container(
          padding: const EdgeInsets.symmetric(horizontal: 9, vertical: 4),
          decoration: BoxDecoration(
            color: on ? _accent : Colors.white.withValues(alpha: .06),
            borderRadius: BorderRadius.circular(999),
          ),
          child: Text(text,
              style: TextStyle(
                  fontSize: 10.5,
                  color: on ? Colors.white : _muted,
                  fontWeight: on ? FontWeight.w600 : FontWeight.w400)),
        ),
      );
}

/// Elke plaat die onder één artiestnaam staat, in één keer onder een andere naam zetten.
///
/// Groeperen gaat op de naam. Eén album waarvan de tags "Enrique" zeggen terwijl de rest "Enrique
/// Iglesias" zegt, is daarmee een tweede artiest: twee tegels, twee pagina's, en op elke pagina de
/// helft van een catalogus. De metadata-editor kon dat al rechtzetten, maar per album — en dezelfde
/// correctie een keer per plaat typen is geen oplossing, dat is werk.
///
/// Hernoemen naar een naam die al in je bibliotheek staat is niet een randgeval maar de bedoeling:
/// beide helften komen onder één naam, en groeperen voegt ze daarna vanzelf samen.
class ArtistRenameDialog extends StatefulWidget {
  const ArtistRenameDialog(this.name, {super.key});

  final String name;

  @override
  State<ArtistRenameDialog> createState() => _ArtistRenameDialogState();
}

class _ArtistRenameDialogState extends State<ArtistRenameDialog> {
  late final TextEditingController _naar = TextEditingController(text: widget.name);
  bool _bezig = false;

  @override
  void dispose() {
    _naar.dispose();
    super.dispose();
  }

  Future<void> _toepassen() async {
    final doel = _naar.text.trim();
    if (doel.isEmpty || doel == widget.name) return;
    setState(() => _bezig = true);
    final lib = context.read<LibraryStore>();
    final settings = context.read<AppSettings>();
    // Titels, geen Album-objecten. Elke correctie hergroepeert de bibliotheek en levert nieuwe
    // Album-objecten voor dezelfde platen op — en op een telefoon wordt het id waarmee een
    // correctie naar de pc gaat op objectidentiteit opgezocht. Een vooraf verzamelde lijst zou na
    // de eerste plaat stil niets meer versturen.
    final titels = [for (final a in lib.albums) if (a.artist == widget.name) a.title];
    var geschreven = 0;
    final mislukt = <String>[];
    try {
      for (final titel in titels) {
        Album? album;
        for (final a in lib.albums) {
          if (a.artist == widget.name && a.title == titel) {
            album = a;
            break;
          }
        }
        if (album == null) continue;
        final r = await lib.applyCorrection(album, settings, artist: doel);
        geschreven += r.written;
        mislukt.addAll(r.failed);
      }
    } catch (e) {
      if (!mounted) return;
      setState(() => _bezig = false);
      _srcToast(context, 'Hernoemen mislukte: $e');
      return;
    }
    if (!mounted) return;
    Navigator.pop(context, (naam: doel, geschreven: geschreven, mislukt: mislukt.length));
  }

  @override
  Widget build(BuildContext context) {
    final lib = context.watch<LibraryStore>();
    final aantal = lib.albums.where((a) => a.artist == widget.name).length;
    // Namen die al in de bibliotheek staan en waar deze in zit, of die in deze zitten — precies de
    // vorm die een afgekapte tag heeft. "Enrique" biedt zo "Enrique Iglesias" aan, en dan is de
    // correctie een tik in plaats van iets om foutloos over te typen.
    final ik = widget.name.toLowerCase();
    final buren = <String>{
      for (final a in lib.albums)
        if (a.artist != widget.name &&
            (a.artist.toLowerCase().contains(ik) || ik.contains(a.artist.toLowerCase())))
          a.artist,
    }.toList()
      ..sort((a, b) => a.length.compareTo(b.length));

    return AlertDialog(
      backgroundColor: _panel,
      title: const Text('Artiestnaam corrigeren'),
      // Scrollbaar, en dat is geen franje: een AlertDialog scrolt zijn inhoud niet uit zichzelf.
      // Met het toetsenbord open vallen de suggesties onder de onderrand — en wat buiten de doos
      // van zijn ouder getekend wordt, tekent wel maar vangt geen tik.
      content: SizedBox(
        width: dialogWidth(context, 460),
        child: SingleChildScrollView(
          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Text(
                '$aantal ${aantal == 1 ? 'plaat staat' : 'platen staan'} onder “${widget.name}”. '
                'Ze gaan allemaal over naar de naam die je hier zet. Staat die naam al in je '
                'bibliotheek, dan worden de twee één artiest.',
                style: const TextStyle(color: _muted, fontSize: 13, height: 1.35),
              ),
              const SizedBox(height: 16),
              TextField(
                controller: _naar,
                // Geen autofocus: het toetsenbord zou over de suggesties heen komen, en daar een
                // van aantikken is juist de bedoeling.
                enabled: !_bezig,
                textInputAction: TextInputAction.done,
                onSubmitted: (_) => _toepassen(),
                onChanged: (_) => setState(() {}),
                decoration: const InputDecoration(labelText: 'Nieuwe naam'),
              ),
              if (buren.isNotEmpty) ...[
                const SizedBox(height: 16),
                const Text('Staat al in je bibliotheek',
                    style: TextStyle(color: _muted, fontSize: 11.5, fontWeight: FontWeight.w700)),
                const SizedBox(height: 8),
                Wrap(
                  spacing: 8,
                  runSpacing: 8,
                  children: [
                    for (final n in buren)
                      ActionChip(
                        label: Text(n),
                        backgroundColor: _panel2,
                        side: const BorderSide(color: _line),
                        onPressed: _bezig
                            ? null
                            : () => setState(() {
                                  _naar.text = n;
                                  _naar.selection = TextSelection.collapsed(offset: n.length);
                                }),
                      ),
                  ],
                ),
              ],
            ],
          ),
        ),
      ),
      actions: [
        TextButton(
          // Waar de highlight begint op een televisie: dit verandert de tags van elk bestand van
          // een artiest, en dat is niet iets om per ongeluk met OK te bevestigen.
          autofocus: isTv,
          onPressed: _bezig ? null : () => Navigator.pop(context),
          child: const Text('Annuleren'),
        ),
        FilledButton(
          style: FilledButton.styleFrom(backgroundColor: _accent),
          onPressed: _bezig || _naar.text.trim().isEmpty || _naar.text.trim() == widget.name
              ? null
              : _toepassen,
          child: _bezig
              ? const SizedBox(
                  width: 16,
                  height: 16,
                  child: CircularProgressIndicator(strokeWidth: 2.2, color: Colors.white))
              : const Text('Hernoemen'),
        ),
      ],
    );
  }
}

/// Choose an artist's portrait and the backdrop behind their page.
///
/// Discogs holds dozens of photos per act (twenty-nine for Daft Punk) and TheAudioDB adds its own
/// fanart and thumbs, but neither labels what a picture is FOR. The app guesses by shape — squarish
/// reads as a portrait, wide as a backdrop — and a guess is exactly the thing worth overruling.
class ArtistArtGallery extends StatefulWidget {
  final String artist;
  const ArtistArtGallery(this.artist, {super.key});

  @override
  State<ArtistArtGallery> createState() => _ArtistArtGalleryState();
}

class _ArtistArtGalleryState extends State<ArtistArtGallery> {
  List<DiscogsImage>? _images;
  String? _error;

  @override
  void initState() {
    super.initState();
    _load();
  }

  Future<void> _load() async {
    final settings = context.read<AppSettings>();
    try {
      final a = await DiscogsService(settings).artist(widget.artist);
      final extra = <DiscogsImage>[];
      // TheAudioDB's fanart is the widest thing either source has, and is usually the better
      // backdrop; Discogs almost never has anything that shape.
      final tadb = await CoverEnricher(settings).artistArt(widget.artist);
      for (final url in [tadb?.backdrop, tadb?.thumb]) {
        if (url != null && url.isNotEmpty) extra.add(DiscogsImage(url, url, 0, 0, false));
      }
      if (!mounted) return;
      setState(() => _images = [...a?.images ?? const <DiscogsImage>[], ...extra]);
    } catch (_) {
      if (mounted) setState(() => _error = 'Kon de foto\'s niet ophalen.');
    }
  }

  @override
  Widget build(BuildContext context) {
    final lib = context.watch<LibraryStore>();
    final portrait = lib.chosenArtistArt(widget.artist, 'portrait');
    final backdrop = lib.chosenArtistArt(widget.artist, 'backdrop');
    return Dialog(
      backgroundColor: _panel,
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
      child: SizedBox(
        width: dialogWidth(context, 860),
        height: dialogHeight(context, 680),
        child: Padding(
          padding: const EdgeInsets.all(20),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Row(children: [
                const Text('Foto kiezen', style: TextStyle(fontSize: 18, fontWeight: FontWeight.w700)),
                const Spacer(),
                IconButton(icon: const Icon(Icons.close_rounded), onPressed: () => Navigator.of(context).pop()),
              ]),
              Text(widget.artist, style: const TextStyle(color: _muted, fontSize: 12.5)),
              const SizedBox(height: 4),
              const Text('Klik een foto voor het portret · rechtsklik voor de achtergrond',
                  style: TextStyle(color: _muted, fontSize: 11.5)),
              const SizedBox(height: 14),
              Expanded(child: _body(portrait, backdrop)),
            ],
          ),
        ),
      ),
    );
  }

  Widget _body(String? portrait, String? backdrop) {
    if (_error != null) return Center(child: Text(_error!, style: const TextStyle(color: _muted)));
    final list = _images;
    if (list == null) {
      return const Center(child: CircularProgressIndicator(strokeWidth: 2, color: _accent));
    }
    if (list.isEmpty) return const Center(child: Text('Geen foto\'s gevonden.', style: TextStyle(color: _muted)));
    return GridView.builder(
      gridDelegate: const SliverGridDelegateWithMaxCrossAxisExtent(
          maxCrossAxisExtent: 160, mainAxisSpacing: 10, crossAxisSpacing: 10, childAspectRatio: .82),
      itemCount: list.length,
      itemBuilder: (_, i) {
        final img = list[i];
        final isPortrait = portrait == img.uri;
        final isBackdrop = backdrop == img.uri;
        final lib = context.read<LibraryStore>();
        return Pressable(
          onPressed: () => lib.setArtistArt(widget.artist, 'portrait', img.uri),
          // Right-click sets the backdrop, and a remote has no right button — so on a television
          // holding OK does the same thing. Both, not one instead of the other: choosing a backdrop
          // was something you simply could not do from the sofa, and nothing on screen said why.
          //
          // Gated, because on a phone or an iPad a long press on a photo is not "set as backdrop"
          // to anybody, and it would fire where a drag or a context menu was meant.
          onSecondaryTap: (_) => lib.setArtistArt(widget.artist, 'backdrop', img.uri),
          onLongPress:
              isTv ? () => lib.setArtistArt(widget.artist, 'backdrop', img.uri) : null,
          borderRadius: BorderRadius.circular(10),
          child: Container(
            decoration: BoxDecoration(
              borderRadius: BorderRadius.circular(8),
              border: Border.all(
                  color: isPortrait
                      ? _accent
                      : isBackdrop
                          ? _accent2
                          : Colors.transparent,
                  width: 2),
            ),
            child: Column(children: [
              Expanded(
                child: ClipRRect(
                  borderRadius: BorderRadius.circular(6),
                  child: _netCover(img.thumb, size: 150, radius: 6),
                ),
              ),
              if (isPortrait || isBackdrop)
                Padding(
                  padding: const EdgeInsets.only(top: 3),
                  child: Text(isPortrait ? 'portret' : 'achtergrond',
                      style: TextStyle(fontSize: 10, color: isPortrait ? _accent : _accent2)),
                ),
            ]),
          ),
        );
      },
    );
  }
}

/// Move a track into another album — showing, before anything is touched, what happens on disk.
///
/// The one operation here that rewrites the folder tree, so it states its plan first. A file that
/// can't be moved still gets regrouped: the tags are what decide where a track lives, and leaving
/// it correct-but-in-place beats refusing the whole thing.
class MoveTrackDialog extends StatefulWidget {
  final Track track;

  /// The album the track is leaving, when it has one. Null for a track that no album page shows:
  /// a rip with no album tag sits in its own single, and a copy that lost a title collision is on
  /// no page at all. Those are precisely the tracks that need moving, so the dialog must open
  /// without a source — it only ever used this to keep the current album out of the target list.
  final Album? from;
  const MoveTrackDialog({super.key, required this.track, this.from});

  @override
  State<MoveTrackDialog> createState() => _MoveTrackDialogState();
}

class _MoveTrackDialogState extends State<MoveTrackDialog> {
  final _query = TextEditingController();
  Album? _target;
  bool _moveFiles = true;
  bool _busy = false;

  /// What the chosen target would do on disk. Fetched rather than computed: on a Mac or an iPad
  /// the PC is the only one that knows the folders, so this arrives a moment after the target is
  /// picked instead of being there in the same frame.
  List<MovePlan> _plan = const [];
  bool _planning = false;

  Future<void> _pick(Album album) async {
    setState(() {
      _target = album;
      _plan = const [];
      _planning = true;
    });
    try {
      final result = await context.read<LibraryStore>().planMoveAsync([widget.track], album);
      if (!mounted || _target != album) return; // a different album was picked meanwhile
      setState(() {
        _plan = result.items;
        _planning = false;
      });
    } catch (_) {
      if (!mounted) return;
      setState(() => _planning = false);
    }
  }

  @override
  void dispose() {
    _query.dispose();
    super.dispose();
  }

  Future<void> _go() async {
    final target = _target;
    if (target == null) return;
    setState(() => _busy = true);
    final moved = await context
        .read<LibraryStore>()
        .moveTracksToAlbum([widget.track], target, context.read<AppSettings>(),
            moveFiles: _moveFiles, plan: _plan);
    if (!mounted) return;
    _srcToast(context, moved > 0 ? 'Verplaatst — $moved bestand mee verhuisd' : 'Verplaatst — bestand bleef staan');
    Navigator.of(context).pop(true);
  }

  @override
  Widget build(BuildContext context) {
    final lib = context.watch<LibraryStore>();
    final q = normKey(_query.text);
    final options = lib.albums
        .where((a) => !a.isSingle && a != widget.from)
        .where((a) => q.isEmpty || normKey('${a.artist} ${a.title}').contains(q))
        .take(40)
        .toList();
    final plan = _plan;

    return Dialog(
      backgroundColor: _panel,
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
      child: SizedBox(
        width: dialogWidth(context, 640),
        height: dialogHeight(context, 600),
        child: Padding(
          padding: const EdgeInsets.all(20),
          child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
            const Text('Nummer verplaatsen', style: TextStyle(fontSize: 18, fontWeight: FontWeight.w700)),
            const SizedBox(height: 2),
            Text(widget.track.title, style: const TextStyle(color: _muted, fontSize: 12.5)),
            const SizedBox(height: 14),
            TextField(
              controller: _query,
              onChanged: (_) => setState(() {}),
              decoration: const InputDecoration(labelText: 'Zoek een album…', isDense: true),
            ),
            const SizedBox(height: 10),
            Expanded(
              child: ListView.builder(
                itemCount: options.length,
                itemBuilder: (_, i) {
                  final a = options[i];
                  final sel = identical(_target, a);
                  return InkWell(
                    onTap: () => _pick(a),
                    borderRadius: BorderRadius.circular(8),
                    child: Container(
                      margin: const EdgeInsets.only(bottom: 5),
                      padding: const EdgeInsets.all(7),
                      decoration: BoxDecoration(
                        color: sel ? _accent.withValues(alpha: .18) : _panel2,
                        borderRadius: BorderRadius.circular(8),
                        border: Border.all(color: sel ? _accent : Colors.transparent),
                      ),
                      child: Row(children: [
                        cover(a.cover, size: 34, radius: 5),
                        const SizedBox(width: 9),
                        Expanded(
                          child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                            Text(a.title,
                                maxLines: 1,
                                overflow: TextOverflow.ellipsis,
                                style: const TextStyle(fontWeight: FontWeight.w600, fontSize: 13)),
                            Text('${a.artist} · ${a.tracks.length} nummers',
                                maxLines: 1,
                                overflow: TextOverflow.ellipsis,
                                style: const TextStyle(color: _muted, fontSize: 11.5)),
                          ]),
                        ),
                      ]),
                    ),
                  );
                },
              ),
            ),
            const SizedBox(height: 10),
            CheckboxListTile(
              value: _moveFiles,
              onChanged: (v) => setState(() => _moveFiles = v ?? true),
              dense: true,
              contentPadding: EdgeInsets.zero,
              controlAffinity: ListTileControlAffinity.leading,
              title: const Text('Bestand mee verplaatsen', style: TextStyle(fontSize: 13)),
              subtitle: Text(
                // The plan, in words, before the button is pressed.
                plan.isEmpty
                    ? 'Kies eerst een album.'
                    : plan.first.movesFile
                        ? 'Naar: ${File(plan.first.to!).parent.path}'
                        : 'Doelmap onbekend — alleen de indeling verandert.',
                style: const TextStyle(color: _muted, fontSize: 11.5),
              ),
            ),
            const SizedBox(height: 6),
            Row(mainAxisAlignment: MainAxisAlignment.end, children: [
              TextButton(
                  autofocus: isTv,
                  onPressed: () => Navigator.of(context).pop(false),
                  child: const Text('Annuleren')),
              const SizedBox(width: 8),
              FilledButton(
                style: FilledButton.styleFrom(backgroundColor: _accent),
                onPressed: (_target == null || _busy || _planning) ? null : _go,
                child: _busy
                    ? const SizedBox(
                        width: 16, height: 16, child: CircularProgressIndicator(strokeWidth: 2, color: Colors.white))
                    : const Text('Verplaatsen'),
              ),
            ]),
          ]),
        ),
      ),
    );
  }
}

/// Take an official pressing's numbering for a mistagged album — showing every change first.
///
/// Rippers get this wrong constantly: one album here arrived with two number sixes, two number
/// tens and a track with no number at all, so its tracklist could not be read or played in order.
/// The pressing knows; the tags do not. But rewriting what a user's library says about their own
/// files is not something to do silently, so the whole list is shown and collisions are refused.
/// Read the whole plan before a single byte is written.
///
/// This is the one dialog in the app that changes files the user already owns, so it says exactly
/// what it will do — per file, old beside new — and names what it will NOT touch instead of quietly
/// leaving it out.
class NormaliseTagsDialog extends StatefulWidget {
  final Album album;
  final NormalisePlan plan;
  const NormaliseTagsDialog({super.key, required this.album, required this.plan});

  @override
  State<NormaliseTagsDialog> createState() => _NormaliseTagsDialogState();
}

String _fileName(String path) => File(path).uri.pathSegments.last;

class _NormaliseTagsDialogState extends State<NormaliseTagsDialog> {
  bool _busy = false;

  /// Files the write could not reach, and how many did land. Empty until a write has run.
  List<String> _failed = const [];
  int _written = 0;

  /// Same-recording pairs in this record, worked out once when the dialog opens. A title collision
  /// is nearly always one of these, and the pairs are what turns the refusal into something to do.
  List<SameRecordingPair> _dupes = const [];

  @override
  void initState() {
    super.initState();
    // The title rule first, so the dialog has an answer immediately, and then the audio — which
    // takes a second or two the first time and can both ADD a pair the titles missed and take one
    // away that the titles got wrong.
    final lib = context.read<LibraryStore>();
    _dupes = lib.duplicateRecordings(widget.album);
    lib.duplicateRecordingsHeard(widget.album).then((gehoord) {
      if (mounted) setState(() => _dupes = gehoord);
    });
  }

  Future<void> _parkDupes() async {
    setState(() => _busy = true);
    final n = await context.read<LibraryStore>().parkDuplicates(_dupes);
    if (!mounted) return;
    _srcToast(
        context,
        n == 0
            ? 'Kon de kopie niet verplaatsen — staat hij open in de speler?'
            : '$n opzij gezet in $dupeFolder · niets gewist');
    Navigator.of(context).pop(n > 0);
  }

  Future<void> _go() async {
    setState(() => _busy = true);
    final r = await context.read<LibraryStore>().applyNormalise(widget.plan);
    if (!mounted) return;
    // Name what did not land. A bare count reads as success even when a file was missed, and the
    // one that gets missed is usually the track you are listening to — the player holds it open.
    if (r.failed.isNotEmpty) {
      setState(() {
        _busy = false;
        _failed = r.failed;
        _written = r.written;
      });
      return;
    }
    _srcToast(context,
        r.written == 0 ? 'Er is niets geschreven.' : '${r.written} bestanden gelijkgetrokken');
    Navigator.of(context).pop(r.written > 0);
  }

  @override
  Widget build(BuildContext context) {
    final plan = widget.plan;
    final album = widget.album;
    final blocked = plan.collides || plan.titleCollides;
    final totals = plan.totalsNow.toList()..sort();
    return Dialog(
      backgroundColor: _panel,
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
      child: SizedBox(
        width: dialogWidth(context, 720),
        height: dialogHeight(context, 640),
        child: Padding(
          padding: const EdgeInsets.all(20),
          child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
            const Text('Tags gelijktrekken', style: TextStyle(fontSize: 18, fontWeight: FontWeight.w700)),
            const SizedBox(height: 4),
            Text('${widget.album.artist} — ${widget.album.title}',
                style: const TextStyle(color: _muted, fontSize: 12.5)),
            const SizedBox(height: 12),
            // What is actually wrong today, in numbers. "Your files disagree" means nothing; "four
            // different totals" is the reason there are four tiles.
            if (totals.length > 1 || plan.albumsNow.length > 1 || plan.steps.length > album.tracks.length)
              Container(
                width: double.infinity,
                padding: const EdgeInsets.all(10),
                decoration: BoxDecoration(
                    color: _panel2, borderRadius: BorderRadius.circular(8)),
                child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                  if (totals.length > 1)
                    Text(
                        'De bestanden zeggen nu ${totals.length} verschillende aantallen: '
                        '${totals.map((t) => t == 0 ? "geen" : "$t").join(", ")}. '
                        'Daarom staat deze plaat in ${totals.length} tegels.',
                        style: const TextStyle(fontSize: 12.5)),
                  if (plan.albumsNow.length > 1) ...[
                    const SizedBox(height: 4),
                    Text('En ${plan.albumsNow.length} schrijfwijzen van de albumtitel.',
                        style: const TextStyle(fontSize: 12.5, color: _muted)),
                  ],
                  // The tile you opened holds only part of the record. Say so, or the file count
                  // below reads as a mistake.
                  if (plan.steps.length > album.tracks.length) ...[
                    const SizedBox(height: 4),
                    Text(
                        'Dit gaat over alle ${plan.steps.length} bestanden van deze plaat, '
                        'niet alleen de ${album.tracks.length} in deze tegel.',
                        style: const TextStyle(fontSize: 12.5, color: _muted)),
                  ],
                ]),
              ),
            const SizedBox(height: 12),
            Text('Wordt: album "${plan.album}" · ${plan.total} nummers'
                '${plan.year != null ? " · ${plan.year}" : ""}',
                style: const TextStyle(fontSize: 13, fontWeight: FontWeight.w600)),
            const SizedBox(height: 10),
            Expanded(
              child: ListView(children: [
                for (final s in plan.renamed)
                  Padding(
                    padding: const EdgeInsets.symmetric(vertical: 5),
                    child: Row(children: [
                      SizedBox(
                          width: 46,
                          child: Text(
                              s.trackNo == s.track.trackNo
                                  ? '${s.trackNo}'
                                  : '${s.track.trackNo} → ${s.trackNo}',
                              style: TextStyle(
                                  fontSize: 12.5,
                                  color: s.trackNo == s.track.trackNo ? _muted : _accent2))),
                      Expanded(
                          child: Text(s.title ?? s.track.title,
                              maxLines: 1,
                              overflow: TextOverflow.ellipsis,
                              style: const TextStyle(fontSize: 13))),
                      Text('${s.track.trackTotal == 0 ? "geen" : s.track.trackTotal} → ${plan.total}',
                          style: const TextStyle(fontSize: 11.5, color: _muted)),
                    ]),
                  ),
                if (plan.albumOnly.isNotEmpty) ...[
                  const Divider(height: 22),
                  const Text('Alleen album en aantal — titel en nummer blijven',
                      style: TextStyle(fontSize: 12, fontWeight: FontWeight.w700, color: _muted)),
                  const SizedBox(height: 6),
                  for (final s in plan.albumOnly)
                    Padding(
                      padding: const EdgeInsets.symmetric(vertical: 4),
                      child: Row(children: [
                        SizedBox(
                            width: 46,
                            child: Text('${s.track.trackNo}',
                                style: const TextStyle(fontSize: 12.5, color: _muted))),
                        Expanded(
                            child: Text(s.track.title,
                                maxLines: 1,
                                overflow: TextOverflow.ellipsis,
                                style: const TextStyle(fontSize: 13, color: _muted))),
                        Text('${s.track.trackTotal == 0 ? "geen" : s.track.trackTotal} → ${plan.total}',
                            style: const TextStyle(fontSize: 11.5, color: _muted)),
                      ]),
                    ),
                ],
                if (plan.skipped.isNotEmpty) ...[
                  const Divider(height: 22),
                  const Text('Blijft ongemoeid',
                      style: TextStyle(fontSize: 12, fontWeight: FontWeight.w700, color: _muted)),
                  const SizedBox(height: 6),
                  for (final s in plan.skipped)
                    Padding(
                      padding: const EdgeInsets.symmetric(vertical: 3),
                      child: Text('${s.name} — ${s.skipped}',
                          style: const TextStyle(fontSize: 12, color: _muted)),
                    ),
                ],
              ]),
            ),
            if (_failed.isNotEmpty)
              Padding(
                padding: const EdgeInsets.only(top: 8),
                child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                  Text(
                      '$_written van de ${plan.writing.length} geschreven. '
                      'Deze konden niet — een bestand dat de speler open heeft, kan niet vervangen worden:',
                      style: const TextStyle(color: Colors.orangeAccent, fontSize: 12.5)),
                  for (final f in _failed)
                    Padding(
                      padding: const EdgeInsets.only(top: 2, left: 8),
                      child: Text(f,
                          maxLines: 1,
                          overflow: TextOverflow.ellipsis,
                          style: const TextStyle(color: Colors.orangeAccent, fontSize: 11.5)),
                    ),
                  const Padding(
                    padding: EdgeInsets.only(top: 2),
                    child: Text('Stop het afspelen en klik opnieuw — de rest is al klaar.',
                        style: TextStyle(color: _muted, fontSize: 11.5)),
                  ),
                ]),
              ),
            if (blocked)
              Padding(
                padding: const EdgeInsets.only(top: 8),
                child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                  const Text(
                      'Dit wordt niet geschreven — deze bestanden zouden op elkaar uitkomen:',
                      style: TextStyle(color: Colors.orangeAccent, fontSize: 12.5)),
                  for (final c in plan.clashes)
                    Padding(
                      padding: const EdgeInsets.only(top: 2, left: 8),
                      child: Text(c,
                          maxLines: 2,
                          overflow: TextOverflow.ellipsis,
                          style: const TextStyle(color: Colors.orangeAccent, fontSize: 11.5)),
                    ),
                  // Almost always the same cause: two rips of one song that landed under different
                  // names. Saying so is not enough — the way out belongs here too.
                  if (_dupes.isEmpty)
                    const Padding(
                      padding: EdgeInsets.only(top: 2),
                      child: Text('Kies een uitgave die bij deze bestanden past.',
                          style: TextStyle(color: _muted, fontSize: 11.5)),
                    )
                  else ...[
                    const SizedBox(height: 6),
                    for (final d in _dupes)
                      Padding(
                        padding: const EdgeInsets.only(left: 8, top: 2),
                        child: Text('Zelfde nummer, twee bestanden: ${d.drop.title} — '
                            'behouden ${_fileName(d.keep.path)} (${d.why})',
                            maxLines: 2,
                            overflow: TextOverflow.ellipsis,
                            style: const TextStyle(color: _muted, fontSize: 11.5)),
                      ),
                    const SizedBox(height: 6),
                    Align(
                      alignment: Alignment.centerLeft,
                      child: OutlinedButton.icon(
                        onPressed: _busy ? null : _parkDupes,
                        icon: const Icon(Icons.inbox_rounded, size: 16),
                        label: Text(_dupes.length == 1
                            ? 'Mindere kopie opzij zetten'
                            : '${_dupes.length} mindere kopieën opzij zetten'),
                      ),
                    ),
                  ],
                ]),
              ),
            const SizedBox(height: 12),
            Row(children: [
              const Expanded(
                child: Text('De hoes, de ReplayGain-waarden en al het andere in het bestand blijven staan.',
                    style: TextStyle(color: _muted, fontSize: 11.5)),
              ),
              TextButton(
                  onPressed: _busy ? null : () => Navigator.of(context).pop(false),
                  child: const Text('Annuleren')),
              const SizedBox(width: 6),
              FilledButton.icon(
                style: FilledButton.styleFrom(backgroundColor: _accent),
                onPressed: (_busy || blocked || !plan.safe) ? null : _go,
                icon: _busy
                    ? const SizedBox(
                        width: 14,
                        height: 14,
                        child: CircularProgressIndicator(strokeWidth: 2, color: Colors.white))
                    : const Icon(Icons.check_rounded, size: 18),
                label: Text(_busy ? 'Schrijven…' : 'Schrijf ${plan.writing.length} bestanden'),
              ),
            ]),
          ]),
        ),
      ),
    );
  }
}

class RenumberDialog extends StatefulWidget {
  final Album album;
  final RenumberPlan plan;
  const RenumberDialog({super.key, required this.album, required this.plan});

  @override
  State<RenumberDialog> createState() => _RenumberDialogState();
}

class _RenumberDialogState extends State<RenumberDialog> {
  bool _busy = false;

  Future<void> _go() async {
    setState(() => _busy = true);
    await context.read<LibraryStore>().applyRenumber(widget.plan);
    if (!mounted) return;
    _srcToast(context, 'Nummering overgenomen');
    Navigator.of(context).pop(true);
  }

  @override
  Widget build(BuildContext context) {
    final plan = widget.plan;
    final blocked = plan.collides || plan.titleCollides;
    return Dialog(
      backgroundColor: _panel,
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
      child: SizedBox(
        width: dialogWidth(context, 700),
        height: dialogHeight(context, 620),
        child: Padding(
          padding: const EdgeInsets.all(20),
          child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
            const Text('Nummering overnemen',
                style: TextStyle(fontSize: 18, fontWeight: FontWeight.w700)),
            const SizedBox(height: 2),
            Text('${widget.album.artist} · ${widget.album.title}',
                style: const TextStyle(color: _muted, fontSize: 12.5)),
            const SizedBox(height: 14),
            Container(
              width: double.infinity,
              padding: const EdgeInsets.all(11),
              decoration: BoxDecoration(
                color: blocked ? Colors.red.withValues(alpha: .12) : _panel2,
                borderRadius: BorderRadius.circular(9),
              ),
              child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                Text(
                  plan.collides
                      ? 'Geweigerd: twee nummers zouden hetzelfde nummer krijgen.'
                      : plan.titleCollides
                          ? 'Geweigerd: twee nummers zouden dezelfde titel krijgen — dan verdwijnt er één uit de lijst.'
                          : plan.changing.isEmpty
                              ? 'De nummering klopt al.'
                              : '${plan.changing.length} van de ${plan.steps.length} worden aangepast · ${plan.total} nummers',
                  style: const TextStyle(fontSize: 13.5, fontWeight: FontWeight.w600),
                ),
                if (plan.unmatched.isNotEmpty) ...[
                  const SizedBox(height: 3),
                  Text(
                      '${plan.unmatched.length} niet herkend op deze uitgave — die houden hun eigen tags.',
                      style: const TextStyle(color: _muted, fontSize: 11.5)),
                ],
              ]),
            ),
            const SizedBox(height: 12),
            Expanded(
              child: ListView.builder(
                itemCount: plan.steps.length,
                itemBuilder: (_, i) {
                  final st = plan.steps[i];
                  final was = st.track.trackNo > 0 ? '${st.track.trackNo}' : '—';
                  return Padding(
                    padding: const EdgeInsets.only(bottom: 6),
                    child: Row(children: [
                      SizedBox(
                        width: 62,
                        child: Text(st.unmatched ? '$was  ·' : '$was → ${st.newNo}',
                            style: TextStyle(
                                fontSize: 12,
                                fontWeight: st.changes ? FontWeight.w700 : FontWeight.w400,
                                color: st.unmatched
                                    ? _muted
                                    : st.changes
                                        ? _accent
                                        : _muted)),
                      ),
                      Expanded(
                        child: Text(
                          // De titel die er ECHT uit komt, niet die van de persing. Zie
                          // [RenumberStep.nieuweTitel]: een persing mag geen versiemerk van jouw
                          // kopie afhalen, en dan hoort dit venster ook geen pijl te tonen.
                          st.nieuweTitel != st.track.title
                              ? '${st.track.title}  →  ${st.nieuweTitel}'
                              : st.track.title,
                          maxLines: 1,
                          overflow: TextOverflow.ellipsis,
                          style: TextStyle(
                              fontSize: 12.5, color: st.unmatched ? _muted : Colors.white),
                        ),
                      ),
                    ]),
                  );
                },
              ),
            ),
            const SizedBox(height: 8),
            Row(mainAxisAlignment: MainAxisAlignment.end, children: [
              TextButton(
                  autofocus: isTv,
                  onPressed: () => Navigator.of(context).pop(false), child: const Text('Annuleren')),
              const SizedBox(width: 8),
              FilledButton(
                style: FilledButton.styleFrom(backgroundColor: _accent),
                onPressed: (_busy || blocked || plan.changing.isEmpty) ? null : _go,
                child: _busy
                    ? const SizedBox(
                        width: 16,
                        height: 16,
                        child: CircularProgressIndicator(strokeWidth: 2, color: Colors.white))
                    : const Text('Overnemen'),
              ),
            ]),
          ]),
        ),
      ),
    );
  }
}

/// Pick one album out of the library. Pops the chosen [Album], or null.
class PickAlbumDialog extends StatefulWidget {
  /// The album doing the asking — never offered as an answer to itself.
  final Album exclude;
  const PickAlbumDialog({super.key, required this.exclude});

  @override
  State<PickAlbumDialog> createState() => _PickAlbumDialogState();
}

class _PickAlbumDialogState extends State<PickAlbumDialog> {
  final _query = TextEditingController();

  @override
  void dispose() {
    _query.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final lib = context.watch<LibraryStore>();
    final q = normKey(_query.text);
    final options = lib.albums
        .where((a) => !a.isSingle && a != widget.exclude)
        .where((a) => q.isEmpty || normKey('${a.artist} ${a.title}').contains(q))
        .take(60)
        .toList();

    return Dialog(
      backgroundColor: _panel,
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
      child: SizedBox(
        width: dialogWidth(context, 620),
        height: dialogHeight(context, 560),
        child: Padding(
          padding: const EdgeInsets.all(20),
          child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
            const Text('Welk album samenvoegen?',
                style: TextStyle(fontSize: 18, fontWeight: FontWeight.w700)),
            const SizedBox(height: 2),
            Text('Dit album gaat op in “${widget.exclude.title}”.',
                style: const TextStyle(color: _muted, fontSize: 12.5)),
            const SizedBox(height: 14),
            TextField(
              controller: _query,
              autofocus: !isTv,
              onChanged: (_) => setState(() {}),
              decoration: const InputDecoration(labelText: 'Zoek een album…', isDense: true),
            ),
            const SizedBox(height: 10),
            Expanded(
              child: ListView.builder(
                itemCount: options.length,
                itemBuilder: (_, i) {
                  final a = options[i];
                  return InkWell(
                    onTap: () => Navigator.of(context).pop(a),
                    borderRadius: BorderRadius.circular(8),
                    child: Container(
                      margin: const EdgeInsets.only(bottom: 5),
                      padding: const EdgeInsets.all(7),
                      decoration: BoxDecoration(color: _panel2, borderRadius: BorderRadius.circular(8)),
                      child: Row(children: [
                        cover(a.cover, size: 34, radius: 5),
                        const SizedBox(width: 9),
                        Expanded(
                          child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                            Text(a.title,
                                maxLines: 1,
                                overflow: TextOverflow.ellipsis,
                                style: const TextStyle(fontWeight: FontWeight.w600, fontSize: 13)),
                            Text('${a.artist} · ${a.tracks.length} nummers',
                                maxLines: 1,
                                overflow: TextOverflow.ellipsis,
                                style: const TextStyle(color: _muted, fontSize: 11.5)),
                          ]),
                        ),
                      ]),
                    ),
                  );
                },
              ),
            ),
            const SizedBox(height: 6),
            Align(
              alignment: Alignment.centerRight,
              child: TextButton(
                  autofocus: isTv,
                  onPressed: () => Navigator.of(context).pop(), child: const Text('Annuleren')),
            ),
          ]),
        ),
      ),
    );
  }
}

/// What the AUDIO says each file is, next to what its tags claim — before anything is written.
///
/// For a loose file this is the only question worth asking. `13 - Various Artists - Jij Bent Zo
/// Mooi.mp3` cannot be identified by its album, because "Various Artists" names nobody and the
/// album is a compilation no catalogue can find. The fingerprint answers in one line: Petra, "Jij
/// bent zo mooi", 0.99.
///
/// Only ARTIST and TITLE, and only where the two disagree with the file. AcoustID knows which
/// RECORDING this is; it says nothing about which pressing this copy came from, so the album, the
/// number and the year are left exactly as they are.
class RecogniseTracksDialog extends StatefulWidget {
  final Album album;

  /// track → what the audio said, best match first. Only files with an answer are in here.
  final Map<Track, AcoustIdMatch> found;

  /// What the FILE's own tags say right now, by path.
  ///
  /// Not [Track.artist], and that distinction is the whole reason this map exists. Measured on
  /// "Jij Bent Zo Mooi": the file's ARTIST already read "Petra", while the Track carried
  /// "Various Artists" — which is the ALBUM artist, and a perfectly correct value for a
  /// compilation. Comparing against the Track made a confirmation screen state the current value
  /// wrongly and offer a repair that was not one. A screen that asks "shall I change this to that"
  /// has to be right about "this".
  final Map<String, ({String artist, String title})> current;

  /// Files that were asked about and came back unknown, by name, so the screen can say so instead
  /// of quietly listing fewer rows than there are files.
  final List<String> unknown;

  /// Waarom er niets terugkwam, als er iets MIS ging in plaats van dat het antwoord nee was.
  ///
  /// Dit veld bestaat omdat het scherm die twee jarenlang door elkaar haalde. Een geweigerde
  /// sleutel, een tijdslimiet, een pc zonder net en een plaat die AcoustID werkelijk niet kent
  /// gaven allemaal "Geen van deze nummers is herkend" — ook bij wereldberoemde platen waar de
  /// dienst honderdduizend vingerafdrukken van heeft. Er viel niets aan te onderzoeken.
  final String? fout;

  const RecogniseTracksDialog(
      {super.key,
      required this.album,
      required this.found,
      required this.current,
      required this.unknown,
      this.fout});

  @override
  State<RecogniseTracksDialog> createState() => _RecogniseTracksDialogState();
}

class _RecogniseTracksDialogState extends State<RecogniseTracksDialog> {
  bool _busy = false;
  List<String> _failed = const [];

  /// Rows where the audio actually disagrees with the file. A match that confirms what the tags
  /// already say is reassuring and completely pointless to write.
  late final List<MapEntry<Track, AcoustIdMatch>> _changes = [
    for (final e in widget.found.entries)
      if (_differs(e.key, e.value)) e,
  ];

  late final Set<String> _chosen = {for (final e in _changes) e.key.path};

  /// What the file says now — falling back to the Track only when the tags could not be read.
  ({String artist, String title}) _nu(Track t) =>
      widget.current[t.path] ?? (artist: t.artist, title: t.title);

  bool _differs(Track t, AcoustIdMatch m) {
    final nu = _nu(t);
    return (m.artist.isNotEmpty && normKey(m.artist) != normKey(nu.artist)) ||
        (m.title.isNotEmpty && normKey(m.title) != normKey(nu.title));
  }

  Future<void> _go() async {
    setState(() => _busy = true);
    final lib = context.read<LibraryStore>();
    final r = await lib.applyRecognised({
      for (final e in _changes)
        if (_chosen.contains(e.key.path))
          e.key: (artist: e.value.artist, title: e.value.title),
    });
    if (!mounted) return;
    if (r.failed.isEmpty) {
      _srcToast(context, '${r.written} bijgewerkt · ongedaan maken kan met de terugknop');
      Navigator.of(context).pop(true);
      return;
    }
    // Named, not counted. "3 written" reads like success when four were asked for, and the one that
    // did not land is nearly always the track playing at that moment.
    setState(() {
      _busy = false;
      _failed = r.failed;
    });
  }

  @override
  Widget build(BuildContext context) {
    return Dialog(
      backgroundColor: _panel,
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
      child: SizedBox(
        width: dialogWidth(context, 760),
        height: dialogHeight(context, 620),
        child: Padding(
          padding: const EdgeInsets.all(20),
          child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
            const Text('Wat zegt de audio?',
                style: TextStyle(fontSize: 18, fontWeight: FontWeight.w700)),
            const SizedBox(height: 2),
            Text(
              _changes.isEmpty
                  ? widget.found.isEmpty
                      ? widget.fout == null
                          ? 'Gevraagd aan AcoustID, en het antwoord is: onbekend.'
                          : 'Er is niet gevraagd wat deze nummers zijn — er ging iets mis.'
                      : 'Alles herkend, en de tags kloppen al — er valt niets te wijzigen.'
                  : '${_changes.length} ${_changes.length == 1 ? 'nummer wijkt' : 'nummers wijken'} af '
                      '· alleen artiest en titel worden geschreven, album en nummering blijven',
              style: const TextStyle(color: _muted, fontSize: 12.5),
            ),
            // De reden, als er een is. Bovenaan en niet weggestopt: dit is het enige wat je verder
            // helpt, en het onderscheid tussen "AcoustID kent dit niet" en "AcoustID heeft de vraag
            // nooit gekregen" is precies wat hier vroeger ontbrak.
            if (widget.fout != null) ...[
              const SizedBox(height: 10),
              Container(
                width: double.infinity,
                padding: const EdgeInsets.all(11),
                decoration: BoxDecoration(
                  color: _panel2,
                  borderRadius: BorderRadius.circular(9),
                  border: Border.all(color: _accent2.withValues(alpha: .45)),
                ),
                child: Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
                  const Icon(Icons.report_gmailerrorred_rounded, size: 17, color: _accent2),
                  const SizedBox(width: 9),
                  Expanded(
                    child: SelectableText(widget.fout!,
                        style: const TextStyle(fontSize: 12.5, height: 1.35)),
                  ),
                ]),
              ),
            ],
            const SizedBox(height: 12),
            Expanded(
              child: ListView(children: [
                for (final e in _changes)
                  Container(
                    margin: const EdgeInsets.only(bottom: 10),
                    padding: const EdgeInsets.all(11),
                    decoration:
                        BoxDecoration(color: _panel2, borderRadius: BorderRadius.circular(9)),
                    child: Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
                      Checkbox(
                        value: _chosen.contains(e.key.path),
                        activeColor: _accent,
                        onChanged: _busy
                            ? null
                            : (v) => setState(() => v == true
                                ? _chosen.add(e.key.path)
                                : _chosen.remove(e.key.path)),
                      ),
                      const SizedBox(width: 4),
                      Expanded(
                        child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                          Text('${_nu(e.key).artist} — ${_nu(e.key).title}',
                              maxLines: 1,
                              overflow: TextOverflow.ellipsis,
                              style: const TextStyle(color: _muted, fontSize: 12.5)),
                          const SizedBox(height: 3),
                          Row(children: [
                            const Icon(Icons.arrow_forward_rounded, size: 14, color: _accent),
                            const SizedBox(width: 7),
                            Expanded(
                              child: Text('${e.value.artist} — ${e.value.title}',
                                  maxLines: 2,
                                  style: const TextStyle(
                                      fontSize: 13.5, fontWeight: FontWeight.w600)),
                            ),
                            Text('${(e.value.score * 100).round()}%',
                                style: const TextStyle(color: _accent2, fontSize: 11.5)),
                          ]),
                        ]),
                      ),
                    ]),
                  ),
                if (widget.unknown.isNotEmpty) ...[
                  const SizedBox(height: 4),
                  Text('Niet herkend (${widget.unknown.length})',
                      style: const TextStyle(fontSize: 12.5, fontWeight: FontWeight.w600)),
                  const SizedBox(height: 4),
                  for (final n in widget.unknown)
                    Padding(
                      padding: const EdgeInsets.only(top: 2),
                      child: Text(n,
                          maxLines: 1,
                          overflow: TextOverflow.ellipsis,
                          style: const TextStyle(color: _muted, fontSize: 11.5)),
                    ),
                ],
                if (_failed.isNotEmpty) ...[
                  const SizedBox(height: 10),
                  const Text('Niet gelukt',
                      style: TextStyle(fontSize: 12.5, fontWeight: FontWeight.w600)),
                  for (final f in _failed)
                    Padding(
                      padding: const EdgeInsets.only(top: 2),
                      child: Text(f, style: const TextStyle(color: _accent2, fontSize: 11.5)),
                    ),
                ],
              ]),
            ),
            const SizedBox(height: 8),
            Row(mainAxisAlignment: MainAxisAlignment.end, children: [
              TextButton(
                  autofocus: isTv,
                  onPressed: () => Navigator.of(context).pop(_failed.isNotEmpty),
                  child: Text(_changes.isEmpty ? 'Sluiten' : 'Annuleren')),
              if (_changes.isNotEmpty) ...[
                const SizedBox(width: 8),
                FilledButton(
                  style: FilledButton.styleFrom(backgroundColor: _accent),
                  onPressed: _busy || _chosen.isEmpty ? null : _go,
                  child: _busy
                      ? const SizedBox(
                          width: 16,
                          height: 16,
                          child: CircularProgressIndicator(strokeWidth: 2, color: Colors.white))
                      : Text('${_chosen.length} in de bestanden schrijven'),
                ),
              ],
            ]),
          ]),
        ),
      ),
    );
  }
}

/// The same recording, twice, anywhere in the library — found by LISTENING, not by reading names.
///
/// Deliberately its own screen rather than a line on an album page: the expensive duplicates do not
/// share a record. Measured over 389 files, the five it finds are a track sitting loose in the root
/// as well as filed under its album, the same recording downloaded into two different Soulseek
/// folders, one compilation track held as both .flac and .m4a, a FLAC beside an MP3 of the same
/// song, and a 242 MB rip beside an 87 MB one. Not one of those is visible from inside a record.
///
/// Nothing is deleted here either. The lesser copy of each pair goes to `_dubbel` beside the music,
/// which the scan skips — so the library stops holding the song twice while the file is still there
/// if the judgement was wrong.
class SoundDuplicatesDialog extends StatefulWidget {
  final List<SameRecordingPair> pairs;
  const SoundDuplicatesDialog({super.key, required this.pairs});

  @override
  State<SoundDuplicatesDialog> createState() => _SoundDuplicatesDialogState();
}

class _SoundDuplicatesDialogState extends State<SoundDuplicatesDialog> {
  bool _busy = false;

  /// Which pairs the user still wants acted on. Everything is ticked to begin with, because every
  /// pair here cleared the strict threshold — but the choice has to be per pair, since "the better
  /// copy" is a judgement about a file the app has never heard the user's opinion on.
  late final Set<String> _chosen = {for (final p in widget.pairs) p.drop.path};

  Future<void> _go() async {
    setState(() => _busy = true);
    final lib = context.read<LibraryStore>();
    final n = await lib
        .parkDuplicates([for (final p in widget.pairs) if (_chosen.contains(p.drop.path)) p]);
    if (!mounted) return;
    _srcToast(
        context,
        n == 0
            ? 'Kon niets verplaatsen — staat er een bestand open in de speler?'
            : '$n opzij gezet in $dupeFolder · niets gewist');
    Navigator.of(context).pop(true);
  }

  String _kort(String pad) {
    final d = pad.split(RegExp(r'[\\/]'));
    return d.length < 3 ? pad : d.sublist(d.length - 2).join('/');
  }

  @override
  Widget build(BuildContext context) {
    final ps = widget.pairs;
    return Dialog(
      backgroundColor: _panel,
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
      child: SizedBox(
        width: dialogWidth(context, 780),
        height: dialogHeight(context, 640),
        child: Padding(
          padding: const EdgeInsets.all(20),
          child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
            const Text('Dezelfde opname, twee keer',
                style: TextStyle(fontSize: 18, fontWeight: FontWeight.w700)),
            const SizedBox(height: 2),
            Text(
              ps.isEmpty
                  ? 'Niets gevonden — geen enkel bestand klinkt hetzelfde als een ander.'
                  : '${ps.length} ${ps.length == 1 ? 'paar' : 'paren'} · herkend aan de audio, niet aan de naam · '
                      'de mindere gaat naar $dupeFolder, er wordt niets gewist',
              style: const TextStyle(color: _muted, fontSize: 12.5),
            ),
            const SizedBox(height: 12),
            Expanded(
              child: ListView.builder(
                itemCount: ps.length,
                itemBuilder: (_, i) {
                  final p = ps[i];
                  final aan = _chosen.contains(p.drop.path);
                  return Container(
                    margin: const EdgeInsets.only(bottom: 10),
                    padding: const EdgeInsets.all(11),
                    decoration:
                        BoxDecoration(color: _panel2, borderRadius: BorderRadius.circular(9)),
                    child: Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
                      Checkbox(
                        value: aan,
                        activeColor: _accent,
                        onChanged: _busy
                            ? null
                            : (v) => setState(() => v == true
                                ? _chosen.add(p.drop.path)
                                : _chosen.remove(p.drop.path)),
                      ),
                      const SizedBox(width: 4),
                      Expanded(
                        child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                          Text(p.keep.title.isEmpty ? _kort(p.keep.path) : p.keep.title,
                              style: const TextStyle(fontWeight: FontWeight.w600, fontSize: 13.5)),
                          const SizedBox(height: 4),
                          Row(children: [
                            const Icon(Icons.check_circle_rounded, size: 14, color: _accent2),
                            const SizedBox(width: 7),
                            Expanded(
                              child: Text('blijft: ${_kort(p.keep.path)}',
                                  maxLines: 1,
                                  overflow: TextOverflow.ellipsis,
                                  style: const TextStyle(fontSize: 11.5)),
                            ),
                          ]),
                          const SizedBox(height: 2),
                          Row(children: [
                            const Icon(Icons.subdirectory_arrow_right_rounded,
                                size: 14, color: _muted),
                            const SizedBox(width: 7),
                            Expanded(
                              child: Text('naar $dupeFolder: ${_kort(p.drop.path)}',
                                  maxLines: 1,
                                  overflow: TextOverflow.ellipsis,
                                  style: const TextStyle(color: _muted, fontSize: 11.5)),
                            ),
                          ]),
                          if (p.why.isNotEmpty) ...[
                            const SizedBox(height: 3),
                            Text(p.why, style: const TextStyle(color: _muted, fontSize: 11)),
                          ],
                        ]),
                      ),
                    ]),
                  );
                },
              ),
            ),
            const SizedBox(height: 8),
            Row(mainAxisAlignment: MainAxisAlignment.end, children: [
              TextButton(
                  autofocus: isTv,
                  onPressed: () => Navigator.of(context).pop(false),
                  child: Text(ps.isEmpty ? 'Sluiten' : 'Annuleren')),
              if (ps.isNotEmpty) ...[
                const SizedBox(width: 8),
                FilledButton(
                  style: FilledButton.styleFrom(backgroundColor: _accent),
                  onPressed: _busy || _chosen.isEmpty ? null : _go,
                  child: _busy
                      ? const SizedBox(
                          width: 16,
                          height: 16,
                          child: CircularProgressIndicator(strokeWidth: 2, color: Colors.white))
                      : Text('${_chosen.length} opzij zetten'),
                ),
              ],
            ]),
          ]),
        ),
      ),
    );
  }
}

/// Clean up albums that are wholly duplicates of one you already own — the dry-run before it acts.
///
/// The stale fragments and junk singles the library found on its own: a "Special Edition" holding
/// three tracks that are all in the real album, an unknown-artist WAV that is really track two.
/// Nothing moves until Opruimen — and even then the loser of each pair goes to _dubbel, never the
/// bin, because the better copy is sometimes the one in the fragment.
class RedundantCleanupDialog extends StatefulWidget {
  final List<RedundantAlbum> found;
  const RedundantCleanupDialog({super.key, required this.found});

  @override
  State<RedundantCleanupDialog> createState() => _RedundantCleanupDialogState();
}

class _RedundantCleanupDialogState extends State<RedundantCleanupDialog> {
  bool _busy = false;

  Future<void> _go() async {
    setState(() => _busy = true);
    final lib = context.read<LibraryStore>();
    for (final r in widget.found) {
      await lib.consolidate(r);
    }
    if (!mounted) return;
    _srcToast(context, 'Dubbele albums opgeruimd');
    Navigator.of(context).pop(true);
  }

  @override
  Widget build(BuildContext context) {
    final found = widget.found;
    final totalTracks = found.fold<int>(0, (n, r) => n + r.pairs.length);
    return Dialog(
      backgroundColor: _panel,
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
      child: SizedBox(
        width: dialogWidth(context, 760),
        height: dialogHeight(context, 640),
        child: Padding(
          padding: const EdgeInsets.all(20),
          child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
            const Text('Dubbele albums opruimen',
                style: TextStyle(fontSize: 18, fontWeight: FontWeight.w700)),
            const SizedBox(height: 2),
            Text(
              '${found.length} ${found.length == 1 ? 'album gaat' : 'albums gaan'} op in een album dat je al hebt · '
              '$totalTracks ${totalTracks == 1 ? 'nummer' : 'nummers'}',
              style: const TextStyle(color: _muted, fontSize: 12.5),
            ),
            const SizedBox(height: 12),
            Expanded(
              child: ListView.builder(
                itemCount: found.length,
                itemBuilder: (_, i) {
                  final r = found[i];
                  return Container(
                    margin: const EdgeInsets.only(bottom: 12),
                    padding: const EdgeInsets.all(11),
                    decoration:
                        BoxDecoration(color: _panel2, borderRadius: BorderRadius.circular(9)),
                    child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                      Text('${r.source.title}  →  ${r.target.title}',
                          style: const TextStyle(fontWeight: FontWeight.w600, fontSize: 13.5)),
                      const SizedBox(height: 2),
                      Text(
                        r.upgrades > 0
                            ? '${r.upgrades} van de ${r.pairs.length} ${r.upgrades == 1 ? 'is' : 'zijn'} beter en vervangt wat je hebt · de rest naar _dubbel'
                            : 'alle ${r.pairs.length} zijn dubbel · naar _dubbel',
                        style: const TextStyle(color: _muted, fontSize: 11.5),
                      ),
                      const SizedBox(height: 6),
                      for (final p in r.pairs)
                        Padding(
                          padding: const EdgeInsets.only(top: 3),
                          child: Row(children: [
                            Icon(p.dupWins ? Icons.upgrade_rounded : Icons.content_copy_rounded,
                                size: 14, color: p.dupWins ? _accent : _accent2),
                            const SizedBox(width: 7),
                            Expanded(
                              child: Text(
                                p.dupWins
                                    ? '${p.owned.trackNo}. ${p.owned.title} — betere kopie behouden, oude naar _dubbel'
                                    : '${p.owned.trackNo}. ${p.owned.title} — dubbel naar _dubbel',
                                maxLines: 1,
                                overflow: TextOverflow.ellipsis,
                                style: const TextStyle(fontSize: 11.5),
                              ),
                            ),
                          ]),
                        ),
                    ]),
                  );
                },
              ),
            ),
            const SizedBox(height: 8),
            Row(mainAxisAlignment: MainAxisAlignment.end, children: [
              TextButton(
                  autofocus: isTv,
                  onPressed: () => Navigator.of(context).pop(false), child: const Text('Annuleren')),
              const SizedBox(width: 8),
              FilledButton(
                style: FilledButton.styleFrom(backgroundColor: _accent),
                onPressed: _busy ? null : _go,
                child: _busy
                    ? const SizedBox(
                        width: 16,
                        height: 16,
                        child: CircularProgressIndicator(strokeWidth: 2, color: Colors.white))
                    : const Text('Opruimen'),
              ),
            ]),
          ]),
        ),
      ),
    );
  }
