/// De pc bijwerken zonder erbij te staan.
///
/// **Waarom dit bestaat.** Gevraagd op 28-08-2026: *"wel ambetant dat ik de pc niet kan updaten van
/// op afstand, pc staat aan."* Bij een koppeling doet de pc het zoeken, het downloaden en — sinds
/// deze week — het omzetten van de stroom. Loopt hij achter, dan loopt de hele app achter, en dat
/// merk je op een toestel dat helemaal bij is.
///
/// **Peilt alleen als er iets te peilen valt.** Eén vraag bij het openen, en daarna een klok van
/// twee seconden die uitsluitend loopt terwijl de pc werkelijk bezig is. Zie `pc_bijwerker.dart`
/// voor de andere helft van die afspraak: die kijkt hoogstens eens per tien minuten bij GitHub, hoe
/// vaak dit ook vraagt.
class PcBijwerkenKnop extends StatefulWidget {
  const PcBijwerkenKnop({super.key, required this.session});

  final ClientSession session;

  @override
  State<PcBijwerkenKnop> createState() => _PcBijwerkenKnopState();
}

class _PcBijwerkenKnopState extends State<PcBijwerkenKnop> {
  Map<String, dynamic>? _stand;
  Timer? _klok;
  bool _wacht = true;

  /// De pc antwoordt niet. Dat betekent iets anders nadat je op bijwerken hebt gedrukt.
  bool _stil = false;

  /// Deze pc kent de weg `/api/update` niet — hij is te oud. Een 404 en geen storing.
  bool _teOud = false;

  /// Er is hier op bijwerken gedrukt. Vanaf dan is een pc die zwijgt geen fout maar het verwachte
  /// beeld: de installer sluit de app af en start hem daarna weer op.
  bool _gestart = false;

  @override
  void initState() {
    super.initState();
    unawaited(_peil());
  }

  @override
  void dispose() {
    _klok?.cancel();
    _klok = null;
    super.dispose();
  }

  Bijwerkbeeld get _beeld => bijwerkbeeldVan(_stand ?? const <String, dynamic>{});

  bool get _bezig {
    // Wegen en niet casten, om dezelfde reden als in `bijwerkstand.dart`: dit veld komt van een
    // andere machine met mogelijk een andere versie erop.
    final v = _stand?['fase'];
    final fase = faseUitNaam(v is String ? v : null);
    return fase == Bijwerkfase.halen || fase == Bijwerkfase.installeren;
  }

  /// Er loopt al een vraag. Zonder dit stapelen de klok van twee seconden en het antwoord op
  /// `start` — dat tot twintig seconden mag duren — over elkaar heen, en dan zet een status van
  /// vóór het starten de fase weer terug op stil.
  bool _vraagtAl = false;

  void _planKlok() {
    // De klok loopt terwijl er iets gebeurt, en terwijl we wachten tot de pc na het installeren
    // terugkomt. Verder niet: dan is er niets te zien dat verandert.
    final nodig = _bezig || (_gestart && _stil);
    if (!nodig) {
      _klok?.cancel();
      _klok = null;
      return;
    }
    _klok ??= Timer.periodic(const Duration(seconds: 2), (_) => unawaited(_peil()));
  }

  Future<void> _peil({bool start = false}) async {
    final ep = widget.session.endpoint;
    // De grendel geldt NIET voor `start`. Anders valt precies de druk op de knop weg zodra er
    // toevallig een peiling onderweg is, en dan doet hij niets — één keer, zonder uitleg.
    if (ep == null || (_vraagtAl && !start)) return;
    _vraagtAl = true;
    // Ruimer dan de standaard: `start` kijkt eerst bij GitHub wat er klaarstaat, en dat is een
    // verzoek over het internet bovenop het verzoek over het netwerk.
    final client = RemoteClient(ep, timeout: const Duration(seconds: 20));
    try {
      final j = await client.ask('/api/update', {'op': start ? 'start' : 'status'});
      if (!mounted) return;
      setState(() {
        _stand = j;
        _wacht = false;
        _stil = false;
        _teOud = false;
      });
    } on RemoteException catch (e) {
      if (!mounted) return;
      setState(() {
        _wacht = false;
        // 404 is geen storing maar een antwoord: deze pc is van vóór deze voorziening.
        if (e.statusCode == 404) _teOud = true;
        _stil = e.statusCode != 404;
      });
    } catch (_) {
      if (!mounted) return;
      setState(() {
        _wacht = false;
        _stil = true;
      });
    } finally {
      _vraagtAl = false;
      client.close();
      if (mounted) _planKlok();
    }
  }

  Future<void> _start() async {
    setState(() {
      _gestart = true;
      // Meteen iets laten zien. Het antwoord op `start` komt pas terug als de pc bij GitHub is
      // langsgeweest, en een knop die seconden lang niets doet is een knop waar nog eens op gedrukt
      // wordt.
      _stand = {...?_stand, 'fase': 'halen', 'voortgang': 0.0, 'fout': ''};
    });
    _planKlok();
    await _peil(start: true);
  }

  @override
  Widget build(BuildContext context) {
    if (_wacht) return const SizedBox.shrink();

    // De pc is te oud voor deze weg: zeggen wat er aan de hand is, want dit is precies het geval
    // waarin iemand zich afvraagt waarom de knop er niet is.
    if (_teOud) {
      // Zeggen wat je eraan doet, niet alleen dat het niet kan. De pc kijkt bij het opstarten zelf
      // of er iets klaarstaat en biedt het dan aan — die weg bestaat al sinds 3.9.74. Vandaar
      // "meestal": wie daar ooit op "overslaan" tikte krijgt juist die uitgave niet meer aangeboden.
      return const Text(
        'Deze pc is te oud om zichzelf op afstand bij te werken — die knop komt vanaf 3.9.237. '
        'Eén keer aan de pc zelf dus; meestal biedt hij het aan zodra je hem opnieuw opstart.',
        style: TextStyle(color: _muted, fontSize: 11.5, height: 1.4),
      );
    }

    // Zwijgt hij nadat je op bijwerken drukte, dan is dat het verwachte beeld en geen storing.
    if (_stil && _gestart) {
      return const Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        LinearProgressIndicator(minHeight: 3),
        SizedBox(height: 8),
        Text('De pc installeert en start opnieuw op. Even geduld.',
            style: TextStyle(color: _muted, fontSize: 11.5, height: 1.4)),
      ]);
    }
    if (_stil && _stand == null) return const SizedBox.shrink();

    final beeld = _beeld;
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        if (beeld.balk != null) ...[
          LinearProgressIndicator(minHeight: 3, value: beeld.balkOnbepaald ? null : beeld.balk),
          const SizedBox(height: 8),
        ],
        Text(
          beeld.regel,
          style: TextStyle(
            color: beeld.fout ? Colors.orangeAccent : _muted,
            fontSize: 11.5,
            height: 1.4,
          ),
        ),
        if (beeld.knop != null) ...[
          const SizedBox(height: 10),
          OutlinedButton.icon(
            onPressed: () => unawaited(_start()),
            icon: const Icon(Icons.system_update_alt_rounded, size: 18),
            label: Text(beeld.knop!),
          ),
        ],
      ],
    );
  }
}

/// Hoeveel je pc over de lijn stuurt als dit toestel van hem afspeelt.
///
/// **Waarom dit alleen op een gekoppeld toestel staat.** Het paneel waar hij in hangt wordt bereikt
/// via `if (!session.owner)` — op de pc zelf kan hij per constructie niet verschijnen, en dat klopt:
/// de pc stuurt niets naar zichzelf. En het is bewust géén gesynchroniseerde instelling: een iPad
/// die altijd op wifi zit en een telefoon op een databundel willen hier een ander antwoord.
///
/// **De adaptieve schakelaar en de tweede rij chips staan alleen op telefoon en tablet.** Een Mac
/// heeft geen mobiele data, dus daar is "onderweg" een keuze zonder betekenis.
class StroomkwaliteitKeuze extends StatelessWidget {
  const StroomkwaliteitKeuze({super.key});

  Widget _chips(
    BuildContext context, {
    required Stroomstand huidig,
    required ValueChanged<Stroomstand> kies,
  }) =>
      Wrap(
        spacing: 8,
        runSpacing: 4,
        children: [
          for (final s in Stroomstand.values)
            ChoiceChip(
              label: Text(labelVan(s)),
              selected: huidig == s,
              onSelected: (aan) {
                if (!aan) return;
                kies(s);
              },
            ),
        ],
      );

  @override
  Widget build(BuildContext context) {
    final settings = context.watch<AppSettings>();
    final netStore = context.watch<NetsoortStore>();

    // De verdedigende terugval hoort hier en niet alleen in het bestand: een instellingenbestand van
    // een oudere of nieuwere uitgave is een voorkeur, geen contract.
    final thuis = standUitNaam(settings.stroomThuis);
    final onderweg = standUitNaam(settings.stroomOnderweg, terugval: Stroomstand.cd);

    // Elke aanraking is een verandering waar de gebruiker bij was, dus de noodgrendel gaat los.
    Future<void> bewaar() async {
      netStore.grendelLos();
      await settings.save();
    }

    final geldend = netStore.geldendeStand(settings);

    return Padding(
      padding: const EdgeInsets.only(bottom: 4),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          const Text('Streamkwaliteit',
              style: TextStyle(fontSize: 14, fontWeight: FontWeight.w700)),
          const SizedBox(height: 10),
          Text(_isTouch ? 'Op wifi' : 'Kwaliteit',
              style: const TextStyle(fontSize: 12.5, fontWeight: FontWeight.w600)),
          const SizedBox(height: 6),
          _chips(context, huidig: thuis, kies: (s) {
            settings.stroomThuis = naamVan(s);
            unawaited(bewaar());
          }),
          if (_isTouch) ...[
            const SizedBox(height: 4),
            SwitchListTile(
              contentPadding: EdgeInsets.zero,
              dense: true,
              value: settings.stroomAdaptief,
              onChanged: (aan) {
                settings.stroomAdaptief = aan;
                unawaited(bewaar());
              },
              title: const Text('Onderweg minder gebruiken',
                  style: TextStyle(fontSize: 12.5, fontWeight: FontWeight.w600)),
              subtitle: const Text('Schakelt om zodra je op mobiele data zit.',
                  style: TextStyle(color: _muted, fontSize: 11.5)),
            ),
            if (settings.stroomAdaptief) ...[
              const SizedBox(height: 2),
              const Text('Op mobiele data',
                  style: TextStyle(fontSize: 12.5, fontWeight: FontWeight.w600)),
              const SizedBox(height: 6),
              _chips(context, huidig: onderweg, kies: (s) {
                settings.stroomOnderweg = naamVan(s);
                unawaited(bewaar());
              }),
            ],
          ],
          const SizedBox(height: 8),
          Text(
            // De getallen zijn het hele argument. Zonder hen is dit drie namen zonder betekenis.
            'Alles blijft lossless — er komt geen mp3 aan te pas. Alleen de frequentie en de '
            'bitdiepte gaan omlaag, en wat al lager staat blijft onaangeroerd.\n'
            '· ${labelVan(Stroomstand.max)} — het bestand zoals het is, ${tempoVan(Stroomstand.max)}.\n'
            '· ${labelVan(Stroomstand.hoog)} — ${tempoVan(Stroomstand.hoog)}.\n'
            '· ${labelVan(Stroomstand.cd)} — ${tempoVan(Stroomstand.cd)}, en nog altijd bit-voor-bit cd.\n'
            'Nu geldt: ${labelVan(geldend)}${netStore.noodstand ? ' (verlaagd omdat het haperde)' : ''}. '
            'Een wijziging geldt vanaf het volgende nummer.',
            style: const TextStyle(color: _muted, fontSize: 11.5, height: 1.4),
          ),
        ],
      ),
    );
  }
}

/// Het koekje uit je eigen browser overnemen, omdat de app zelf niet langs Cloudflare komt.
///
/// **Waarom dit scherm bestaat.** Gemeten op 23-08-2026: élk verzoek aan rutracker.org strandt in
/// een Cloudflare-uitdaging (403, `Cf-Mitigated: challenge`, "Just a moment..."), ook een kale GET
/// van de inlogpagina zonder gegevens. Headers nabootsen helpt niet — uitgeprobeerd met en zonder
/// User-Agent en met een volledige Chrome inclusief `sec-ch-ua` en `Sec-Fetch-*`, allemaal 403.
/// Zolang er geen ingebouwde webview is, is dit de enige eerlijke weg: jouw browser lost de
/// uitdaging op, en de app leent het koekje dat daaruit komt.
/// Hoe lang de app blijft terugdelen na een download van een besloten tracker.
///
/// **Waarom dit zichtbaar moet zijn.** Op Redacted wordt bijgehouden wat je haalt en wat je
/// teruggeeft. Binnenhalen en meteen stoppen heet daar hit-and-run en kost je je account — dat is
/// niet iets om stilletjes voor iemand te beslissen. Andersom kost seeden bandbreedte en tijdelijk
/// dubbele schijfruimte, want aria2 kan alleen uitdelen wat in zijn eigen map ligt.
class SeedKeuze extends StatelessWidget {
  const SeedKeuze({super.key});

  static const _keuzes = [(0, 'Niet delen'), (24, '24 uur'), (72, '72 uur'), (168, 'Een week')];

  @override
  Widget build(BuildContext context) {
    final settings = context.watch<AppSettings>();
    return Padding(
      padding: const EdgeInsets.only(top: 10, bottom: 4),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          const Text('Terugdelen na een download van een besloten tracker',
              style: TextStyle(fontSize: 12.5, fontWeight: FontWeight.w600)),
          const SizedBox(height: 6),
          Wrap(
            spacing: 8,
            children: [
              for (final (uren, naam) in _keuzes)
                ChoiceChip(
                  label: Text(naam),
                  selected: settings.seedUren == uren,
                  onSelected: (aan) async {
                    if (!aan) return;
                    settings.seedUren = uren;
                    await settings.save();
                  },
                ),
            ],
          ),
          const SizedBox(height: 6),
          Text(
            settings.seedUren == 0
                ? 'Uit. Op Redacted heet dat hit-and-run, en daar kun je je account mee kwijtraken.'
                : 'Zolang de app deelt blijft het bestand ook in de werkmap staan — die ruimte komt '
                    'daarna vanzelf vrij. Bij Pirate Bay, Knaben en RuTracker verandert er niets.',
            style: const TextStyle(color: _muted, fontSize: 11.5, height: 1.35),
          ),
        ],
      ),
    );
  }
}

/// Wie de torrent binnenhaalt: TorBox, deze pc, of de app die kiest.
///
/// **Waarom dit op het scherm staat en niet alleen in een bestand.** Het is de enige instelling die
/// bepaalt of jouw IP-adres in de zwerm terechtkomt. Dat is geen technisch detail dat je stilletjes
/// voor iemand invult — dat is precies het verschil waarvoor mensen een debrid-dienst nemen.
class TorrentmotorKeuze extends StatelessWidget {
  const TorrentmotorKeuze({super.key});

  static const _keuzes = [
    ('auto', 'Automatisch'),
    ('torbox', 'Altijd TorBox'),
    ('lokaal', 'Altijd deze pc'),
  ];

  @override
  Widget build(BuildContext context) {
    final settings = context.watch<AppSettings>();
    final motor = context.read<OnlineService>().aria2;
    final huidig = _keuzes.any((k) => k.$1 == settings.torrentMotor) ? settings.torrentMotor : 'auto';

    return Padding(
      padding: const EdgeInsets.only(bottom: 12),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          const Text('Torrents ophalen via',
              style: TextStyle(fontSize: 12.5, fontWeight: FontWeight.w600)),
          const SizedBox(height: 6),
          Wrap(
            spacing: 8,
            children: [
              for (final (waarde, naam) in _keuzes)
                ChoiceChip(
                  label: Text(naam),
                  selected: huidig == waarde,
                  onSelected: (aan) async {
                    if (!aan) return;
                    settings.torrentMotor = waarde;
                    await settings.save();
                  },
                ),
            ],
          ),
          const SizedBox(height: 6),
          Text(
            motor.beschikbaar
                ? 'Automatisch: wat TorBox al klaar heeft komt daarvandaan (meteen klaar, en jouw '
                    'IP blijft erbuiten). De rest haalt deze pc zelf op — dat is waar TorBox de hele '
                    'torrent nog moet ophalen en dus traag is. Daarbij zit je eigen IP wél in de zwerm.'
                : 'Deze pc kan zelf geen torrents halen: aria2c.exe staat niet naast de app. Alles '
                    'gaat via TorBox.',
            style: const TextStyle(color: _muted, fontSize: 11.5, height: 1.35),
          ),
        ],
      ),
    );
  }
}

class RuTrackerKoekjeDialoog extends StatefulWidget {
  const RuTrackerKoekjeDialoog({super.key});

  @override
  State<RuTrackerKoekjeDialoog> createState() => _RuTrackerKoekjeDialoogState();
}

class _RuTrackerKoekjeDialoogState extends State<RuTrackerKoekjeDialoog> {
  final _plaksel = TextEditingController();
  bool _bezig = false;
  String? _melding;
  bool _gelukt = false;

  @override
  void dispose() {
    _plaksel.dispose();
    super.dispose();
  }

  Future<void> _gebruik() async {
    setState(() {
      _bezig = true;
      _melding = null;
    });
    final rt = context.read<OnlineService>().rutracker;
    final uitkomst = await rt.gebruikPlaksel(_plaksel.text);
    if (!mounted) return;
    setState(() {
      _bezig = false;
      _gelukt = uitkomst.ok;
      _melding = uitkomst.ok
          ? 'Gelukt — RuTracker antwoordt weer. Zoeken werkt tot Cloudflare het koekje intrekt.'
          : (uitkomst.error ?? 'Het lukte niet.');
    });
  }

  @override
  Widget build(BuildContext context) {
    return Dialog(
      backgroundColor: _panel,
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
      child: SizedBox(
        width: dialogWidth(context, 620),
        child: Padding(
          padding: const EdgeInsets.all(22),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              const Text('Koekje uit je browser',
                  style: TextStyle(fontSize: 19, fontWeight: FontWeight.w800)),
              const SizedBox(height: 8),
              const Text(
                  'RuTracker staat achter Cloudflare. Die uitdaging kan alleen een echte browser '
                  'oplossen — dus doet jouw browser dat, en gebruikt de app het resultaat.',
                  style: TextStyle(color: _muted, fontSize: 12.5, height: 1.4)),
              const SizedBox(height: 14),
              const Text('1.  Open rutracker.org in je browser en log daar in.\n'
                  '2.  Druk op F12, ga naar het tabblad Netwerk en ververs de pagina.\n'
                  '3.  Rechtsklik op het bovenste verzoek → Kopiëren → Kopieer als cURL.\n'
                  '4.  Plak dat hieronder.',
                  style: TextStyle(fontSize: 12.5, height: 1.6)),
              const SizedBox(height: 10),
              // Waarom niet gewoon document.cookie: cf_clearance is HttpOnly en staat daar dus niet
              // in. Via "Kopieer als cURL" komt hij wél mee — samen met het browserkenmerk, en dat
              // is nodig omdat Cloudflare het koekje aan die twee bindt.
              const Text(
                  'Kopieer als cURL neemt ook je browserkenmerk mee. Dat is nodig: het koekje hoort '
                  'bij dat kenmerk én bij je IP-adres, dus na een netwerkwissel plak je het opnieuw.',
                  style: TextStyle(color: _muted, fontSize: 11.5, height: 1.4)),
              const SizedBox(height: 14),
              TextField(
                controller: _plaksel,
                maxLines: 6,
                minLines: 4,
                style: const TextStyle(fontSize: 12),
                decoration: InputDecoration(
                  hintText: "curl 'https://rutracker.org/forum/index.php' -H 'cookie: …'",
                  hintStyle: const TextStyle(color: _muted, fontSize: 11.5),
                  filled: true,
                  fillColor: _panel2,
                  border: OutlineInputBorder(borderRadius: BorderRadius.circular(10)),
                ),
              ),
              if (_melding != null) ...[
                const SizedBox(height: 12),
                Row(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Icon(_gelukt ? Icons.check_circle_rounded : Icons.error_outline_rounded,
                        size: 17, color: _gelukt ? _accent2 : Colors.redAccent),
                    const SizedBox(width: 8),
                    Expanded(
                      child: Text(_melding!,
                          style: TextStyle(
                              fontSize: 12.5,
                              height: 1.4,
                              color: _gelukt ? _accent2 : Colors.red.shade300)),
                    ),
                  ],
                ),
              ],
              const SizedBox(height: 16),
              Row(
                mainAxisAlignment: MainAxisAlignment.end,
                children: [
                  TextButton(
                      onPressed: () => Navigator.pop(context),
                      child: Text(_gelukt ? 'Klaar' : 'Annuleren')),
                  const SizedBox(width: 8),
                  FilledButton(
                    style: FilledButton.styleFrom(backgroundColor: _accent),
                    onPressed: _bezig ? null : _gebruik,
                    child: _bezig
                        ? const SizedBox(
                            width: 16,
                            height: 16,
                            child: CircularProgressIndicator(strokeWidth: 2, color: Colors.white))
                        : const Text('Gebruik dit'),
                  ),
                ],
              ),
            ],
          ),
        ),
      ),
    );
  }
}
